window.AUZEF_DATA={"examDate":"2026-11-07","examEnd":"2026-11-08","generated":"2026-09-25","courses":{"bat":{"name":"Bilimsel Araştırma Teknikleri","code":"AIKY1003","file":"Ders _ BİLİMSEL ARAŞTIRMA TEKNİKLERİ - eKitap.txt","color":"#7c3aed","units":["Bilim Felsefesi ve Bilimsel Araştırma","Bilimsel Araştırma Süreci ve Hipotez Geliştirme","Araştırma Tasarımları: Keşfedici, Tanımlayıcı ve Nedensel Araştırmalar","Veri Türleri ve Kaynak Taraması","Kalitatif (Nitel) Araştırma","Kantitatif (Nicel) Araştırma","Örnekleme Süreci ve Yöntemleri","Ölçekleme ve Ölçek Türleri","Anket Formu Tasarımı","Bilimsel Araştırmalarda Hata ve Güvenirlik","Bilimsel Araştırmalarda Geçerlik","Veri Hazırlama ve Veri Analizi","Bilimsel Araştırma Raporunun Hazırlanması","Bilimsel Araştırma Etiği"],"unitData":[{"title":"Bilim Felsefesi ve Bilimsel Araştırma","cards":["Bu bölümde bilimin ve bilimsel yöntemin ne olduğu, araştırma ile ilişkisi tartışılmış ve bilimsel araştırmanın önemi ve kapsamı incelenmiştir. Bu\nkapsamda araştırma türlerinin neler olduğu ve tümevarım ve tümdengelim araştırmaların özellikleri üzerinde durulmuştur.","Bu bölümde ayrıca, bilimsel araştırmaların karar almadaki önemli fonksiyonu açıklanmaya çalışılmış ve buna bağlı olarak araştırmalarda izlenen süreçler\naçıklanmıştır. Tüm bunlara ek olarak araştırma sürecinde kalite olgusu üzerinde durularak bir bilimsel araştırmada bulunması gereken özellikler üzerine\ndetaylı bilgilendirmeler yapılmıştır. Son olarak kalitatif (nitel) ve kantitatif araştımalarda takip edilecek sürece yönelik aşamalar hakkında\nbilgilendirmelerde bulunulmuştur."],"questions":[{"q":"Varolan bilgilere yenilerini katma amacını taşıyan bilimsel araştırma aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Temel araştırma"},{"key":"B","text":"Uygulamalı araştırma"},{"key":"C","text":"Nicel araştırma"},{"key":"D","text":"Nitel araştırma"},{"key":"E","text":"Tümleşik araştırma"}],"answerText":"Temel araştırma","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bilimsel yöntemde takip edilmesi gereken basamaklardan değildir?","options":[{"key":"A","text":"Hata ve önyargıları en aza indirmeye çalışmak"},{"key":"B","text":"Araştırılması gereken problemi ortaya koyup tanımlamak"},{"key":"C","text":"Veri toplamak ve verilerin analizini yapmak"},{"key":"D","text":"Araştırmanın anakütlesini belirlemek ve örneklemi seçmek"},{"key":"E","text":"Araştırma raporunu yazmak"}],"answerText":"Hata ve önyargıları en aza indirmeye çalışmak","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırmanın özelliklerinden değildir?","options":[{"key":"A","text":"Araştırma ampiriktir."},{"key":"B","text":"Araştırma sistemli ve kontrollü bir veri toplama yöntemidir."},{"key":"C","text":"Araştırma öznel sorun çözme yoludur."},{"key":"D","text":"Araştırma kendini düzelticidir."},{"key":"E","text":"Araştırma doğruyu elde etmede en başarılı yoldur"}],"answerText":"Araştırma öznel sorun çözme yoludur.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki cümleler bilimsel yöntemin aşamalarını rastgele vermektedir. Doğru sıralamayı işaretleyiniz.\n• Araştırmanın planlanması\n• Hipotezin belirlenmesi\n• Araştırma probleminin ortaya konması\n• Araştırmadan elde edilen bulguların yorumlanması\n• Araştırmanın yapılması","options":[{"key":"A","text":"1-2-3-4-5"},{"key":"B","text":"3-2-1-5-4"},{"key":"C","text":"1-3-2-5-4"},{"key":"D","text":"2-3-1-5-4"},{"key":"E","text":"3-1-2-5-4"}],"answerText":"3-2-1-5-4","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıda bilimsel yöntemle ilgili verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Bilimsel yöntem sorunlara doğru çözüm bulmak için yapılan bir etkinliktir."},{"key":"B","text":"Bilimsel yöntem hem tümevarıma dayalı hem de tümdengelime dayalı akıl yürütme yolunu kullanır."},{"key":"C","text":"Bilimsel yöntemler günlük hayatta karşılaşılan sorunların çözümünde kullanılmaz."},{"key":"D","text":"Bilimsel yöntem bir konuda dünyadaki tüm olguların incelenmesini gerektirmez."},{"key":"E","text":"Bilimsel yöntem başkalarının da sınayıp yürütebilecekleri bir nesnellik içermelidir."}],"answerText":"Bilimsel yöntemler günlük hayatta karşılaşılan sorunların çözümünde kullanılmaz.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Günlük sorunlara pratik çözümle bulmak, kamuoyunu aydınlatmak, ekonomik, sosyal ve siyasal konularda tahminlerde bulunmak vb. gibi\namaçlara yönelik yapılmakta olan araştırmalar ne tür araştırmalardır?","options":[{"key":"A","text":"Nitel araştırma"},{"key":"B","text":"Uygulamalı araştırma"},{"key":"C","text":"Tümleşik araştırma"},{"key":"D","text":"Temel araştırma"},{"key":"E","text":"Nicel araştırma"}],"answerText":"Uygulamalı araştırma","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel, sistematik, objektif, geçerli ve güvenilir olan; problemlere güvenilir çözümler aramak, bilinmeyen ya da tartışmalı olan bir konuya\naçıklık getirmek amacıyla yapılan sistematik ve objektif bir veri toplama ve değerlendirme süreçlerine ne ad verilmektedir?","options":[{"key":"A","text":"İstatistik"},{"key":"B","text":"Bilim"},{"key":"C","text":"Araştırma"},{"key":"D","text":"Yöntem"},{"key":"E","text":"Teknik"}],"answerText":"Araştırma","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bilimsel araştırma sürecini başlatan, geliştiren ve sonuçlandıran sorulardan biri değildir?","options":[{"key":"A","text":"Bu araştırmayı neden yapmalıyız?"},{"key":"B","text":"Hangi araştırmalar yapılmalı?"},{"key":"C","text":"Yapılan bu araştırma harcanacak zaman ve paraya değecek mi?"},{"key":"D","text":"Araştırmada önceki bulguları doğrulamak için nasıl bir araştırma uygulamalıyız?"},{"key":"E","text":"Bu araştırmanın sonuçlarıyla ne/neler yapacağız?"}],"answerText":"Araştırmada önceki bulguları doğrulamak için nasıl bir araştırma uygulamalıyız?","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıda belirtilen özelliklerden hangisini taşıyan bir bilimsel araştırmanın orijinalliğinden söz edilemez?","options":[{"key":"A","text":"Yeni bilgi üretme"},{"key":"B","text":"Yeni bir araştırma alanına uygulama"},{"key":"C","text":"Mevcut veriden yeni sonuçlara ulaşma"},{"key":"D","text":"Mevcut bulguları tekrar etme"},{"key":"E","text":"Daha önceki çalışmaları eleştirel olarak değerlendirme yapma"}],"answerText":"Mevcut bulguları tekrar etme","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel araştırma, bilimin araçlarına ve ölçütlerine uygun olarak aşağıdakilerden hangisini yapmamalıdır?","options":[{"key":"A","text":"Güvenilir çözümleri hedeflemelidir."},{"key":"B","text":"Önceki çalışmaların sonuçlarını mutlaka teyit etmelidir."},{"key":"C","text":"Verileri sistemli ve planlı toplamalıdır."},{"key":"D","text":"Bulguları değerlendirip ve yorumlamalıdır."},{"key":"E","text":"Toplanan verilerin analizlerini yapmalıdır."}],"answerText":"Önceki çalışmaların sonuçlarını mutlaka teyit etmelidir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilim felsefesi nedir?","options":[{"key":"A","text":"Bilgi türlerini sınıflandıran disiplin"},{"key":"B","text":"Günlük sorunlara pratik çözümler bulan yöntem"},{"key":"C","text":"Bilgi edinme yollarını araştıran yöntem"},{"key":"D","text":"Bilimsel bilgiyi diğer bilgi türlerinden ayıran özellikleri inceleyen alan"},{"key":"E","text":"Bilimsel yöntemleri sınıflandıran disiplin"}],"answerText":"Bilimsel bilgiyi diğer bilgi türlerinden ayıran özellikleri inceleyen alan","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel bilgiyi diğer bilgi türlerinden ayıran en önemli ölçüt nedir?","options":[{"key":"A","text":"Bilginin felsefi bir temele dayanması"},{"key":"B","text":"Bilginin nesnel (ampirik) gerçeklik olması"},{"key":"C","text":"Bilginin tarihi gelişimi"},{"key":"D","text":"Bilginin sosyal kabulü"},{"key":"E","text":"Bilginin sanatla ilişkisi"}],"answerText":"Bilginin nesnel (ampirik) gerçeklik olması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Bilimsel Araştırma Süreci ve Hipotez Geliştirme","cards":["Bu bölümde, araştırma planlamasının kapsamı ve dikkate alınması gerereken noktalar üzerinde durulmuştur. Araştırma konusunun belirlenmesi ve\nproblemin seçiminin bir araştırmadaki önemine yer verilmiştir.","Araştırma modelinin nasıl oluşturulduğu ve buna bağlı olarak değişkenlerin ve hipotezlerin nasıl tanımlandığı açıklanmıştır.","Araştırmanın bundan sonraki sürecinin temel yapı taşlarını oluşturan planlama aşamasının tüm süreçleri hassas noktalarıyla birlikte detaylı olarak ortaya\nkonulmuştur."],"questions":[{"q":"Aşağıdakilerden hangisi problem seçiminde göz önünde bulundurulan genel ölçütlerden biri değildir?","options":[{"key":"A","text":"Alanda yeterlilik"},{"key":"B","text":"Önemlilik"},{"key":"C","text":"Yenilik"},{"key":"D","text":"Etik kurallara uygunluk"},{"key":"E","text":"Çözülebilirlik"}],"answerText":"Alanda yeterlilik","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İyi bir hipotezde aşağıdaki özelliklerden hangisi yer almaz?","options":[{"key":"A","text":"Kesin yargı belirtmeli"},{"key":"B","text":"Sınanabilir olmalı"},{"key":"C","text":"Açık ve öz bir şekilde açıklanmalı"},{"key":"D","text":"Mantıklı olmalı"},{"key":"E","text":"Daha önce yapılmış çalışmaların sonuçlarıyla tutarlı olmalı"}],"answerText":"Daha önce yapılmış çalışmaların sonuçlarıyla tutarlı olmalı","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki ifadelerden hangisi hipotez kavramını en iyi açıklamaktadır?","options":[{"key":"A","text":"Hipotez araştırılmadan doğruluğuna inanılan ifadelerdir."},{"key":"B","text":"Hipotez doğruluğu hakkında kanıt toplanacak ifadelerdir."},{"key":"C","text":"Hipotez araştırma probleminin açık ve sınırlandırılmış ifadesidir."},{"key":"D","text":"Hipotez araştırma sonunda ulaşılan sonuçtur."},{"key":"E","text":"Hipotez olup olmadığı araştırmada test edilecek ifadelerdir."}],"answerText":"Hipotez doğruluğu hakkında kanıt toplanacak ifadelerdir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi yokluk hipotezine bir örnek olabilir (H0)?","options":[{"key":"A","text":"Kadın ve erkeklerin ortalama ömrü birbirine eşittir."},{"key":"B","text":"Eğitim düzeyi arttıkça gelir miktarı da artar."},{"key":"C","text":"Egzersiz ile şişmanlık arasında bir ilişki vardır."},{"key":"D","text":"Eğitim düzeyi yükseldikçe aile içi şiddet oranı azalır."},{"key":"E","text":"Hiçbiri"}],"answerText":"Kadın ve erkeklerin ortalama ömrü birbirine eşittir.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırma planlamasında kullanılan modeller arasında değildir?","options":[{"key":"A","text":"Sözel model"},{"key":"B","text":"Grafiksel model"},{"key":"C","text":"Analitik model"},{"key":"D","text":"Matematiksel model"},{"key":"E","text":"Varsayımsal model"}],"answerText":"Varsayımsal model","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Nedensel araştırmalarda hipotezlere yer verilirken, mevcut durumun ortaya konulması amacıyla yapılan ___________________araştırmalarda\nhipotez kurulmamaktadır.” İfadesinde boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?","options":[{"key":"A","text":"Tanımlayıcı"},{"key":"B","text":"Kantitatif"},{"key":"C","text":"Deneysel"},{"key":"D","text":"Nicel"},{"key":"E","text":"İlişkisel"}],"answerText":"Tanımlayıcı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi hipotezlerin taşıması gereken özelliklerden biri değildir?","options":[{"key":"A","text":"Amaçlarla tutarlı olmalı"},{"key":"B","text":"Test edilebilir olmalı"},{"key":"C","text":"Ölçülebilir olmalı"},{"key":"D","text":"Bir araştırmada yalnızca bir hipotez olmalı"},{"key":"E","text":"Analizde kullanılacak tüm değişkenleri içermeli"}],"answerText":"Bir araştırmada yalnızca bir hipotez olmalı","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir araştırmada en fazla kaç tane hipotez olabilir?","options":[{"key":"A","text":"En fazla 1"},{"key":"B","text":"En fazla 2"},{"key":"C","text":"En fazla 3"},{"key":"D","text":"En fazla 4"},{"key":"E","text":"Birden fazla ve modele göre üst sınır değişebilir"}],"answerText":"Birden fazla ve modele göre üst sınır değişebilir","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırmacının varsayımını ifade eden hipoteze verilen isimdir?","options":[{"key":"A","text":"Sıfır hipotezi"},{"key":"B","text":"Alternatif hipotez"},{"key":"C","text":"Null hipotez"},{"key":"D","text":"Başlangıç hipotezi"},{"key":"E","text":"Yokluk hipotezi"}],"answerText":"Alternatif hipotez","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi, araştırmacının varsayımının gerçekleşmemesi durumunu ifade hipoteze verilen isimdir?","options":[{"key":"A","text":"Alternatif hipotez"},{"key":"B","text":"Son hipotez"},{"key":"C","text":"Yokluk (null) hipotezi"},{"key":"D","text":"Başlangıç hipotezi"},{"key":"E","text":"İlk hipotez"}],"answerText":"Yokluk (null) hipotezi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel araştırma sürecinin ilk aşaması nedir?","options":[{"key":"A","text":"Veri toplama"},{"key":"B","text":"Araştırma probleminin tanımlanması"},{"key":"C","text":"Hipotez oluşturma"},{"key":"D","text":"Analiz yapma"},{"key":"E","text":"Bulguları raporlama"}],"answerText":"Araştırma probleminin tanımlanması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hipotez nedir?","options":[{"key":"A","text":"Bilimsel bir teoriyi açıklayan genel ilke"},{"key":"B","text":"Bilimsel araştırmanın sonuçları"},{"key":"C","text":"Veri toplama yöntemi"},{"key":"D","text":"Araştırma modeli"},{"key":"E","text":"Doğruluğu kanıtlanması gereken önerme"}],"answerText":"Doğruluğu kanıtlanması gereken önerme","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Araştırma Tasarımları: Keşfedici, Tanımlayıcı ve Nedensel Araştırmalar","cards":["Bu bölümde, araştırma tasarımının ne olduğu ve kapsamı açıklanmıştır. İyi bir tasarımda bulunması gereken özellikler üzerinde durulmuştur.","Araştırmalarında kullanılan araştırma tasarım türlerinin sınıflandırılması yapılmış ve her bir türün özellikleri detaylıca açıklanmıştır.","Araştırmada model oluşturmanın önemi ve model türleri üzerinde durulmuştur. Keşfedici, Tanımlayıcı ve Nedensel araştırma tasarımlarının\nbirbirlerinden üstünlükleri ve zayıflıkları vurgulanarak hangi amaçla kullanılabilecekleri tartışılmıştır."],"questions":[{"q":"Araştırma tasarımı ile ilgili aşağıdakilerden hangisi yanlıştır?","options":[{"key":"A","text":"Araştırma probleminin tespiti ile başlar."},{"key":"B","text":"Bir araştırma projesinin temeli veya genel planıdır."},{"key":"C","text":"Bir araştırmayı yürütmek için oluşturulan çatıdır."},{"key":"D","text":"Araştırma problemini çözmek veya şekillendirmek için önemlidir."},{"key":"E","text":"Araştırma için gerekli bilgiyi sağlama amacını güder."}],"answerText":"Araştırma probleminin tespiti ile başlar.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırma tasarımını adımları arasında yer almaz?","options":[{"key":"A","text":"İkincil veri analizi"},{"key":"B","text":"Araştırma türüne karar verilmesi"},{"key":"C","text":"Bilgi ihtiyacının tanımlanması"},{"key":"D","text":"Ölçme ve ölçekleme prosedürlerinin belirlenmesi"},{"key":"E","text":"Araştırma amaçların tanımlanması"}],"answerText":"Araştırma amaçların tanımlanması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi temel araştırma tasarımları arasında yer almaz?","options":[{"key":"A","text":"Keşfedici Araştırma"},{"key":"B","text":"Tanımlayıcı Araştırma"},{"key":"C","text":"Sonuçlandırıcı Araştırma"},{"key":"D","text":"Uzman Araştırma"},{"key":"E","text":"Nedensel Araştırma"}],"answerText":"Uzman Araştırma","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"\"Ortalıkta apaçık bulunmayan, henüz ortaya çıkmamış veya gelecekte olabilecek problemleri tanımlamaya yardımcı olan\" araştırma türü\nhangisidir?","options":[{"key":"A","text":"Keşfedici Araştırma"},{"key":"B","text":"Tanımlayıcı Araştırma"},{"key":"C","text":"Sonuçlandırıcı Araştırma"},{"key":"D","text":"Uzman Araştırma"},{"key":"E","text":"Nedensel Araştırma"}],"answerText":"Keşfedici Araştırma","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tanımlayıcı araştırmaların kullanılma amaçları arasında yer almaz?","options":[{"key":"A","text":"İlgili grupların özelliklerini tanımlamak"},{"key":"B","text":"Anakütle içinde belli bir davranışı sergileyen grupların yüzdesini tahminlemek"},{"key":"C","text":"Algılamaları belirlemek"},{"key":"D","text":"İlişkilendirilen değişkenleri belirlemek"},{"key":"E","text":"Bağımlı-bağımsız değişkenler arasındaki etkiyi belirlemek"}],"answerText":"Bağımlı-bağımsız değişkenler arasındaki etkiyi belirlemek","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sebep sonuç ilişkisini ortaya çıkaracak ipuçları bulmak için yapılan ve ilişkilerin hipotezlerini test etmek için yapılan araştırmalara ne ad\nverilmektedir?","options":[{"key":"A","text":"Tanımlayıcı araştırma"},{"key":"B","text":"Keşfedici araştırma"},{"key":"C","text":"Neden-Sonuç (nedensel) araştırmaları"},{"key":"D","text":"Uzman araştırma"},{"key":"E","text":"Grafiksel araştırma"}],"answerText":"Neden-Sonuç (nedensel) araştırmaları","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Nedensel araştırmalarda Bağımlı değişkeni (Y) etkileyen değişkenlere ne isim verilmektedir.","options":[{"key":"A","text":"İlişkili değişken"},{"key":"B","text":"Sıfır değişken"},{"key":"C","text":"Son değişken"},{"key":"D","text":"İlk değişken"},{"key":"E","text":"Bağımsız değişken"}],"answerText":"Bağımsız değişken","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi nedensel araştırmalar için bağımsız değişkenin (X) bağımlı değişkene (Y) neden olduğunu söyleyebilmek için gerek ve\nyeter koşullardan biri değildir?","options":[{"key":"A","text":"X’deki değişme Y’deki değişmeden zaman içinde daha sonra meydana gelmeli."},{"key":"B","text":"X ve Y’deki değişmeler arasında bir ilgi olmalı."},{"key":"C","text":"X’deki değişme Y’deki değişmeden zaman içinde daha önce meydana gelmeli."},{"key":"D","text":"Y’ye etki etmesi olası diğer faktörlerin tümü serimden elimine edilmeli."},{"key":"E","text":"X’in Y’ye etki ettiğini saptayan ilgili bir teori bulunmalıdır."}],"answerText":"X’deki değişme Y’deki değişmeden zaman içinde daha sonra meydana gelmeli.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"I.Sebep olan ile sonuç olan değişkenleri bulabilmek için (Ne sebep oluyor, ne sonucu doğuruyor şeklinde).\nII.Sebep olan değişkenler ile tahmin edilmesi gereken sonuçlar arasındaki ilişkiyi ve etkileri bulmak için\nIII.Hipotezin test edilmesi için\nYukarıdaki ifadelerden hangileri nedensel araştırmanın kullanılma amaçları arasında yer alır.","options":[{"key":"A","text":"I"},{"key":"B","text":"II"},{"key":"C","text":"III"},{"key":"D","text":"I-II"},{"key":"E","text":"I-II-III"}],"answerText":"I-II-III","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Keşfedici araştırmalarda temel bilgilerin analizi __________ olarak gerçekleştirilirken, sonuçlandırıcı araştırmalarda veri analizi\n____________ olarak gerçekleştirilir.” ifadesinde boş bırakılan kısımlara aşağıdaki kavramlardan hangileri getirilmelidir?","options":[{"key":"A","text":"kantitatif /kalitatif"},{"key":"B","text":"kalitatif / kantitatif"},{"key":"C","text":"sayısal / sözel"},{"key":"D","text":"nicel / nitel"},{"key":"E","text":"ordinal / nominal"}],"answerText":"kalitatif / kantitatif","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Keşfedici araştırmanın temel amaçlarından biri hangisidir?","options":[{"key":"A","text":"Hipotezleri test etmek"},{"key":"B","text":"Veri toplama sürecini planlamak"},{"key":"C","text":"Araştırma modelini tasarlamak"},{"key":"D","text":"Verileri analiz etmek"},{"key":"E","text":"Problemleri yapılandırmak ve daha kesin tanımlamak"}],"answerText":"Problemleri yapılandırmak ve daha kesin tanımlamak","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Keşfedici araştırmanın kullanıldığı durumlardan biri aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Önceden belirlenmiş hipotezlerin doğrulanması"},{"key":"B","text":"Daha az bilinen veya yeni konuların araştırılması"},{"key":"C","text":"Büyük örneklem gruplarının analizi"},{"key":"D","text":"Deneysel veri toplama"},{"key":"E","text":"Veri madenciliği"}],"answerText":"Daha az bilinen veya yeni konuların araştırılması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Veri Türleri ve Kaynak Taraması","cards":["Bu bölümde, araştırmalarda veri ve verinin önemi ile veri türleri kavramları karşılaştırmalı olarak tartışılmıştır. İkincil verilerin elde edilmesi ve literatür\ntarama konusu üzerinde ayrıntılı olarak durulmuştur.","İkincil verilerin bilimsel araştırma sürecindeki önemi ve kullanımı açıklanmıştır.","Literatür taramasının ne olduğu, nasıl ve nerelerden yapılabileceği ve kapsamı açıklanarak araştırma açısından önemi vurgulanmıştır. Literatür\ntaramasında kullanılan kaynaklar kısaca açıklanmış ve bu kaynakların içeriği ve nasıl ulaşılabileceği hakkında bazı değerlendirmelerde de bulunulmuştur."],"questions":[{"q":"İkincil veriler ile ilgili aşağıdakiler hangisi yanlıştır?","options":[{"key":"A","text":"Toplama amacı diğer problemler içindir."},{"key":"B","text":"Toplama süreci hızlı ve kolaydır."},{"key":"C","text":"Toplama maliyeti yüksektir."},{"key":"D","text":"Toplama süresi kısadır."},{"key":"E","text":"Daha önce toplanmıştır."}],"answerText":"Toplama maliyeti yüksektir.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi İkinci el verilerin sağladığı avantajlar arasında yer almaz?","options":[{"key":"A","text":"Araştırmacının sürece katılımı yoğundur."},{"key":"B","text":"Çok çabuk elde edilirler."},{"key":"C","text":"Yetenekli araştırmacılara ihtiyaç sınırlıdır."},{"key":"D","text":"Daha az emekle elde edilebilirler."},{"key":"E","text":"Zaman ve maliyetten tasarruf sağlar."}],"answerText":"Araştırmacının sürece katılımı yoğundur.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırmalarda literatür kavramı tam olarak neyi ifade etmektedir?","options":[{"key":"A","text":"Benzer araştırmaları anlatan makaleleri"},{"key":"B","text":"İlgili alanda yapılmış bilimsel tezleri"},{"key":"C","text":"Araştırılan konu üzerine yazılan kitapları"},{"key":"D","text":"Araştırmacının yararlandığı kaynakları"},{"key":"E","text":"Bir konu hakkında üretilmiş tüm eserleri"}],"answerText":"Bir konu hakkında üretilmiş tüm eserleri","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Literatür taramasında aşağıdaki sorulardan hangisine yanıt aranmaz?","options":[{"key":"A","text":"Alandaki yetersiz araştırmalar nelerdir?"},{"key":"B","text":"Alandaki önemli kaynaklar nelerdir?"},{"key":"C","text":"Konu hakkındaki temel tartışmalar nelerdir?"},{"key":"D","text":"Önemli kuramlar, görüşler ve kavramlar nelerdir?"},{"key":"E","text":"Bugüne değin araştırılmamış sorunlar nelerdir?"}],"answerText":"Bugüne değin araştırılmamış sorunlar nelerdir?","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisinin literatür taramasında yapılması zorunlu değildir?","options":[{"key":"A","text":"Mevcut araştırmaların incelenmesi"},{"key":"B","text":"Belirlenen araştırma problemine bağlı kalınması"},{"key":"C","text":"Özgün bulguların ortaya konulması"},{"key":"D","text":"Var olan sonuçların sentezlenmesi"},{"key":"E","text":"Yeni araştırma gereksinimlerinin belirginleştirilmesi"}],"answerText":"Özgün bulguların ortaya konulması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Birincil verinin toplanma maliyeti ________, toplama süresi _______; ikincil verinin ise toplanma maliyeti _________, toplanma süresi\n_________ dır/dur.” İfadesinde boş bırakılan yerlere aşağıdakilerden hangisi getirilmelidir?","options":[{"key":"A","text":"yüksek, uzun / düşük, kısa"},{"key":"B","text":"yüksek, kısa / düşük, uzun"},{"key":"C","text":"düşük, uzun / yüksek, kısa"},{"key":"D","text":"yüksek, kısa / düşük, kısa"},{"key":"E","text":"yüksek, uzun / düşük, uzun"}],"answerText":"yüksek, uzun / düşük, kısa","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi İkincil verilerin elde edildiği kaynaklardan biri değildir?","options":[{"key":"A","text":"Kütüphaneler"},{"key":"B","text":"Resmi Kayıtlar"},{"key":"C","text":"Diğer finansal kaynaklar"},{"key":"D","text":"Anketler"},{"key":"E","text":"Bölgesel yayınlar"}],"answerText":"Anketler","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bir literatür taramasında bulunması gereken özelliklerden değildir?","options":[{"key":"A","text":"Araştırma problemiyle doğrudan ilgili olmalıdır."},{"key":"B","text":"Kaynakların magazinler, dergiler, gazeteler gibi akademik olmayan belgelerden değil, akademik yayınlardan oluşması gerekir."},{"key":"C","text":"İlgili literatürdeki (ihtilaflı) üzerinde uzlaşılmayan alanları göstermemelidir."},{"key":"D","text":"Konuyla ilgili daha fazla araştırma gerektiren soruları ortaya koyabilme"},{"key":"E","text":"Konuyla ilgili bilinen ve bilinmeyen şeylerin neler olduğunu özetleyen bir sentez oluşturabilmeli,"}],"answerText":"İlgili literatürdeki (ihtilaflı) üzerinde uzlaşılmayan alanları göstermemelidir.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bilimsel bir araştırma için literatür araştırmasına, araştırma problemi ile ilgili ________________ seçilmesi ile başlanır.” İfadesinde boş\nbırakılan yere ne getirilmelidir?","options":[{"key":"A","text":"Giriş kısmının"},{"key":"B","text":"Anahtar kelimelerin"},{"key":"C","text":"İsmin"},{"key":"D","text":"Başlığın"},{"key":"E","text":"Özetin"}],"answerText":"Anahtar kelimelerin","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Türkiye’de yayımlanan akademik dergilere merkezi bir sistemle ulaşılmasına imkân veren TUBİTAK bilgi ağı hangisidir?","options":[{"key":"A","text":"ULAKBİM"},{"key":"B","text":"Ulusal Tez Arşivi"},{"key":"C","text":"Scopus"},{"key":"D","text":"Ebscohost"},{"key":"E","text":"Science Direct"}],"answerText":"ULAKBİM","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi birincil verilerin temel özellikleri arasında yer alır?","options":[{"key":"A","text":"Hızlı ve maliyetsiz toplanması"},{"key":"B","text":"Özgün ve araştırmacı tarafından toplanması"},{"key":"C","text":"Kolay bulunabilir olması"},{"key":"D","text":"İkincil kaynaklardan elde edilmesi"},{"key":"E","text":"Eski ve hatalı olma olasılığı"}],"answerText":"Özgün ve araştırmacı tarafından toplanması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Literatür taraması hangi amaçla yapılır?","options":[{"key":"A","text":"Yeni teoriler geliştirmek"},{"key":"B","text":"Deneysel veri toplamak"},{"key":"C","text":"Mevcut bilgileri gözden geçirmek"},{"key":"D","text":"Anket sonuçlarını analiz etmek"},{"key":"E","text":"Verilerin doğruluğunu test etmek"}],"answerText":"Mevcut bilgileri gözden geçirmek","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Kalitatif (Nitel) Araştırma","cards":["Bu bölümde kalitatif araştırma türü ve bu araştırma türünde kullanılan veri toplama yöntemleri detaylıca incelenmiştir.","Kalitatif araştırmanın kantitatif araştırmadan farklılıkları açıklanmıştır.","Kalitatif araştırmalarda kullanılan veri toplama teknikleri birbirleriyle kıyaslamalı olarak detaylıca irdelenmiştir."],"questions":[{"q":"Aşağıdaki kalitatif (nitel) ve kantitatif (nicel) araştırma yöntemlerinin karşılaştırıldığı ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Nicel araştırmalarda genelleme yapılırken, nitel araştırmalarda derinlemesine betimleme yapılır"},{"key":"B","text":"Nicel araştırmalarda araştırmacı öznel değerlendirme yapabilirken nitel araştırmalarda araştırmacı nesnel değerlendirme yapar"},{"key":"C","text":"Nicel araştırmalar kuram ve denence ile başlarken nitel araştırmalar kuram ve denence ile son bulur"},{"key":"D","text":"Nicel araştırmalarda araştırmacı olay ve olgulara dışardan bakarken nitel araştırmalarda katılımcı bir tavır geliştirir"},{"key":"E","text":"Nicel araştırmalarda tahmin yapılabilirken nitel araştırmalarda yorumlamaya gidilir"}],"answerText":"Nicel araştırmalarda araştırmacı öznel değerlendirme yapabilirken nitel araştırmalarda araştırmacı nesnel değerlendirme yapar","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"-A Değişkenler kesin sınırlarıyla saptanabilir ve bu değişkenler arasındaki ilişkiler ölçülebilir\n-B Araştırmacı olay ve olguları yakından izler, katılımcı bir tavır geliştirir\nYukarıda açıklamaları verilen araştırma yöntemleri sırasıyla hangi seçenekte doğru olarak verilmiştir?","options":[{"key":"A","text":"Nitel Araştırma - Nicel Araştırma"},{"key":"B","text":"Nitel Araştırma - Nitel Araştırma"},{"key":"C","text":"Nicel Araştırma - Nicel Araştırma"},{"key":"D","text":"Nicel Araştırma - Nitel Araştırma"},{"key":"E","text":"Karma Araştırma - Nitel Araştırma"}],"answerText":"Nicel Araştırma - Nitel Araştırma","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kalitatif (nitel) veri toplama yöntemleri arasında değildir?","options":[{"key":"A","text":"Derinlemesine görüşme"},{"key":"B","text":"Odak grup"},{"key":"C","text":"Deney"},{"key":"D","text":"Yansıtma teknikleri"},{"key":"E","text":"Gözlem"}],"answerText":"Deney","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Derinlemesine görüşmede, mülakatçı ile ilgili aşağıdakilerden hangisi yanlıştır?","options":[{"key":"A","text":"Olumlu bir hava yaratabilmeli"},{"key":"B","text":"Soruları o an aklına geldiği gibi sormalı"},{"key":"C","text":"Uygun tepki elde etmeli"},{"key":"D","text":"Yanlılıklardan kaçınmalı"},{"key":"E","text":"Cevaplayıcının önceliklerini dikkate almalı"}],"answerText":"Soruları o an aklına geldiği gibi sormalı","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hanisi gözlem yönteminde kullanılan katılımcılarla direkt temasa gerek olmayan araçlar arasında yer almaz?","options":[{"key":"A","text":"AC Nielsen odyometresi"},{"key":"B","text":"Binaya giren ve çıkanların kaydını tutan turnikeler"},{"key":"C","text":"Gizlenmiş göz kamerası"},{"key":"D","text":"Saha kameraları"},{"key":"E","text":"Psikogalvanometre"}],"answerText":"Psikogalvanometre","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Derinlemesine görüşme türü araştırma tekniklerinden, görüşme öncesinde hazırlanmış sadece standart soruların sorulduğu teknik hangisidir.","options":[{"key":"A","text":"Sınırlandırılmamış (Yönlendirilmemiş) Görüşme"},{"key":"B","text":"Standart açık-uçlu görüşme"},{"key":"C","text":"Yüz yüze sınırsız görüşme"},{"key":"D","text":"Sınırsız görüşme"},{"key":"E","text":"Yarı Yapılandırılmış veya Odaklanmış (Yönlendirilmiş) Bireysel Görüşme"}],"answerText":"Standart açık-uçlu görüşme","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi odak grup türü araştırma tekniklerinin avantajları arasında yer almaz?","options":[{"key":"A","text":"Yeni fikirler meydana çıkması"},{"key":"B","text":"Gruptaki hareketlere bakarak kişileri gözlemlemeyebilmek"},{"key":"C","text":"Genel çok yönlülük"},{"key":"D","text":"Özel deneklerle çalışma imkânı"},{"key":"E","text":"Katılımcı başına maliyetin çok düşük olması"}],"answerText":"Katılımcı başına maliyetin çok düşük olması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Odak grup türü araştırmalarda grup üyelerinden etkilenme ___________ iken, derinlemesine görüşme de diğer grup üyelerinden etkilenme\nihtimali ____________.” İfadesinde boş bırakılan yere hangileri getirilmelidir?","options":[{"key":"A","text":"yok / vardır."},{"key":"B","text":"yok / yoktur."},{"key":"C","text":"var /çoktur."},{"key":"D","text":"var / yoktur."},{"key":"E","text":"var/ yüksektir."}],"answerText":"var / yoktur.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Kalitatif araştırma tekniklerinden gözlem yöntemi eleştiriye çok açık bir yöntemdir, çünkü _____________.” İfadesinde boş bırakılan yere\nhangisi getirilmelidir?","options":[{"key":"A","text":"subjektiftir."},{"key":"B","text":"objektiftir."},{"key":"C","text":"bağımsızdır."},{"key":"D","text":"nesneldir."},{"key":"E","text":"hatasızdır."}],"answerText":"subjektiftir.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırmalarında sık başvurulan gözlem yöntemlerinden değildir?","options":[{"key":"A","text":"Kişisel gözlem"},{"key":"B","text":"Mekanik gözlem"},{"key":"C","text":"Anket"},{"key":"D","text":"Denetim"},{"key":"E","text":"İçerik analizi"}],"answerText":"Anket","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kalitatif araştırmanın temel amacı nedir?","options":[{"key":"A","text":"Sayısal veriler toplamak"},{"key":"B","text":"Olguları derinlemesine anlamak"},{"key":"C","text":"Hipotezleri test etmek"},{"key":"D","text":"Genelleme yapmak"},{"key":"E","text":"Verileri sayılara indirgemek"}],"answerText":"Olguları derinlemesine anlamak","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kalitatif araştırmaların temel özelliklerinden biridir?","options":[{"key":"A","text":"Nesnel ve standart verilere odaklanır"},{"key":"B","text":"Yalnızca laboratuvar ortamında yapılır"},{"key":"C","text":"Hipotezleri test etmek için kullanılır"},{"key":"D","text":"Gerçek ortamlarda veri toplar"},{"key":"E","text":"Verileri sayılara dönüştürür"}],"answerText":"Gerçek ortamlarda veri toplar","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Kantitatif (Nicel) Araştırma","cards":["Bu bölümde kantitatif araştırma hakkında kapsamlı açıklamalara yer verilmiştir. Kantitatif araştırmanın kapsamı, özellikleri ve iyi bir kantitatif araştırma\ntasarımında dikkat edilmesi gereken hususlar incelenmiştir.","Kantitatif araştırma yöntemlerinde en sık kullanılan veri toplama yöntemi olan anket yöntemi ve deneysel tasarım yöntemleri detaylı olarak incelenmiştir.","Anket yöntemi olarak internet anketinin geleneksel yöntemlere göre üstünlük ve zayıflıkları tartışılmıştır. Ayrıca Anket uygulamasında kullanılacak\nyöntemler ve bu yöntemlerin avantaj ve dezavantajları anlatılmıştır.","Son olarak Kantitatif araştırmalarda kullanılan deneysel tasarımlar hakkında detaylı bilgilere yer verilmiş, araştırmacının deneysel tasarımları nerede,\nnasıl ve hangi amaçla kullanabileceği, değişik deneysel tasarım yöntemleri ışığında anlatılmıştır."],"questions":[{"q":"Aşağıdakilerden hangisi kantitatif metotların, kalitatif metotlara göre önemli avantajları arasında yer almaz?","options":[{"key":"A","text":"Standartlaştırma"},{"key":"B","text":"Yönetim Kolaylığı"},{"key":"C","text":"Tablolaştırma ve İstatistiksel Analizlere Uygunluk"},{"key":"D","text":"Alt Grup Farklılıklarına Duyarlılık"},{"key":"E","text":"Keşfedici araştırma tasarımına uygunluk"}],"answerText":"Keşfedici araştırma tasarımına uygunluk","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iyi tasarlanmış bir nicel araştırmanın özellikleri arasında değildir?","options":[{"key":"A","text":"Yanılgılardan arınmış olma"},{"key":"B","text":"Karışıklıktan arınmış olma"},{"key":"C","text":"Dış değişkenlerin kontrol altında tutulması"},{"key":"D","text":"Kalitatif araştırma ile desteklenmiş olma"},{"key":"E","text":"Hipotezlerin sınanmasında istatistikî kesinlik"}],"answerText":"Kalitatif araştırma ile desteklenmiş olma","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Belli bir amaç ve plana göre düzenlenmiş soru listesine ne ad verilir?","options":[{"key":"A","text":"Ölçek"},{"key":"B","text":"Anket"},{"key":"C","text":"Kontrol listesi"},{"key":"D","text":"Gözlem"},{"key":"E","text":"Görüşme"}],"answerText":"Anket","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi en yaygın olarak kullanılan anket yöntemleri arasında yer almaz?","options":[{"key":"A","text":"Yüz-yüze anket"},{"key":"B","text":"Posta anketi"},{"key":"C","text":"Uzman anketi"},{"key":"D","text":"Telefon anketi"},{"key":"E","text":"İnternet anketi"}],"answerText":"Uzman anketi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Internet anketi ile ilgili aşağıdaki yargılardan hangisi doğrudur?","options":[{"key":"A","text":"Veri toplamada esnekliği düşüktür."},{"key":"B","text":"Veri toplama ortamının kontrolü yüksektir."},{"key":"C","text":"Veri miktarı düşüktür."},{"key":"D","text":"Cevaplama oranı düşüktür."},{"key":"E","text":"Uygulama hızı çok yüksektir"}],"answerText":"Uygulama hızı çok yüksektir","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Önceden belirlenmiş hipotezlerin kontrol ve deney grubu seçilerek dış faktörlerin kontrol altına ve amacın, belirli sonuçların sadece bağımsız\ndeğişkenin etkisiyle meydana geldiğini ve bu bağımsız değişkenin etkisi ortadan kaldırıldığında aynı sonuçların ortaya çıkmadığını göstermeye\nyönelik araştırma tekniğidir.\nYukarıda sözü edilen araştırma yöntemi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Anket"},{"key":"B","text":"Odak grup"},{"key":"C","text":"Derinlemesine Görüşme"},{"key":"D","text":"Katılımlı gözlem"},{"key":"E","text":"Deney"}],"answerText":"Deney","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırmalarda değişimin beklendiği araştırma konusu olan değişkenlerin genel adı nedir?","options":[{"key":"A","text":"Bağımlı değişken"},{"key":"B","text":"Bağımsız değişken"},{"key":"C","text":"Sanal değişken"},{"key":"D","text":"Karar değişkeni"},{"key":"E","text":"Model değişken"}],"answerText":"Bağımlı değişken","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İnternet kullanmanın öğrencilerin ders başarısına etkileri” konulu araştırmanın bağımlı değişkeni hangisidir?","options":[{"key":"A","text":"Ders başarısı"},{"key":"B","text":"İnternet kullanma"},{"key":"C","text":"Öğrenciler"},{"key":"D","text":"Etkiler"},{"key":"E","text":"İnternet ile eğitim"}],"answerText":"Ders başarısı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"O1XO2\nYukarıda simgesel görünümü verilen araştırma modeli aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Tek gruplu öntest-sontest model"},{"key":"B","text":"Sontest kontrol gruplu model"},{"key":"C","text":"Tek gruplu sontest model"},{"key":"D","text":"Zaman dizisi modeli"},{"key":"E","text":"Öntest-sontest kontrol gruplu model"}],"answerText":"Tek gruplu öntest-sontest model","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Deney öncesi ve sonrası ölçmelerin yapıldığı yansız atama ile oluşturulmuş, deney ve kontrol grubu olmak üzere iki grubu bulunan araştırma\nmodeli aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Eşit zaman örneklemli model"},{"key":"B","text":"Tek gruplu sontest model"},{"key":"C","text":"Sontest kontrol gruplu model"},{"key":"D","text":"Öntest-sontest kontrol gruplu model"},{"key":"E","text":"Karşılaştırılmalı eşitlenmemiş grup sontest modeli"}],"answerText":"Öntest-sontest kontrol gruplu model","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kantitatif araştırmalarda yaygın olarak kullanılan veri toplama yöntemi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Derinlemesine görüşme"},{"key":"B","text":"Gözlem"},{"key":"C","text":"Anket"},{"key":"D","text":"Odak grup"},{"key":"E","text":"Yansıtma teknikleri"}],"answerText":"Anket","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kantitatif araştırmanın başlıca özelliklerinden biridir?","options":[{"key":"A","text":"Veri toplama araçlarının yapılandırılmamış olması"},{"key":"B","text":"Sayısal değerlere indirgenmiş veriler kullanması"},{"key":"C","text":"Katılımcılarla kişisel etkileşimin yüksek olması"},{"key":"D","text":"Küçük örneklem gruplarıyla çalışması"},{"key":"E","text":"Hipotez geliştirmeye odaklanması"}],"answerText":"Sayısal değerlere indirgenmiş veriler kullanması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Örnekleme Süreci ve Yöntemleri","cards":["Bu bölümde örnekleme, parametre, tamsayım, anakütle kavramlarının ne olduğu, bu kavramların araştırma açısından önemi detaylıca incelenmiştir.","Örnekleme yöntemlerinin neler olduğu, hangi durumda hangi örnekleme yönteminin kullanımının daha uygun olduğu açıklanmıştır. Tüm örnekleme\nyöntemleri karşılaştırmalı olarak anlatılmıştır. Örnekleme süreci detaylı olarak anlatılmıştır.","Son olarak, örneklem büyüklüğü belirlemesinde kullanılacak yöntemlere kısaca yer verilerek örnekler üzerinden bazı hesaplamalar yapılmıştır. Bu\nçerçevede, hata payı, güven aralığı, varyans, standart sapma gibi bazı kavramlara değinilmiştir."],"questions":[{"q":"Bir araştırmada tanım çerçevesinde yer alan tüm birimlerin oluşturduğu kümeye ne ad verilir?","options":[{"key":"A","text":"Parametre"},{"key":"B","text":"Gözlem birimi"},{"key":"C","text":"Anakütle"},{"key":"D","text":"Örneklem"},{"key":"E","text":"Yan Grup"}],"answerText":"Anakütle","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tesadüfi olmayan örnekleme yöntemlerinden birisi değildir?","options":[{"key":"A","text":"Kolayda örnekleme"},{"key":"B","text":"Küme örneklemesi"},{"key":"C","text":"Kartopu örneklemesi"},{"key":"D","text":"Kota örneklemesi"},{"key":"E","text":"Yargısal örnekleme"}],"answerText":"Küme örneklemesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi olasılığa dayalı örnekleme tekniklerinden birisi değildir?","options":[{"key":"A","text":"Sistematik örnekleme"},{"key":"B","text":"Tabakalı örnekleme"},{"key":"C","text":"Küme örneklemesi"},{"key":"D","text":"Kartopu örnekleme"},{"key":"E","text":"Basit tesadüfi örnekleme"}],"answerText":"Kartopu örnekleme","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Belli bir örneklem büyüklüğüne ulaşmada, anakütledeki her birimin örnekleme girebilme olasılığının belli, bağımsız ve birbirine eşit olması\ndurumuna ne ad verilir?","options":[{"key":"A","text":"Birim"},{"key":"B","text":"Örneklem"},{"key":"C","text":"Gözlem birimi"},{"key":"D","text":"Yansızlık"},{"key":"E","text":"Tam sayım"}],"answerText":"Yansızlık","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Örneklem büyüklüğüyle örneklem hatası arasında ne tür bir ilişki vardır?","options":[{"key":"A","text":"İlişki yoktur"},{"key":"B","text":"Örneklem küçükse örneklem hatası da küçüktür"},{"key":"C","text":"Örneklem büyükse örneklem hatası da büyüktür"},{"key":"D","text":"Örneklem büyüklüğü arttıkça örneklem hatası da artar"},{"key":"E","text":"Örneklem büyüklüğü arttıkça örneklem hatası da azalır"}],"answerText":"Örneklem büyüklüğü arttıkça örneklem hatası da azalır","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi örneklemenin yararlarından biri değildir?","options":[{"key":"A","text":"Tam ve kesin bilgiye ulaşmada karşılaşılan zorluklar"},{"key":"B","text":"Maliyetlerin azalması"},{"key":"C","text":"Sürenin kısalması"},{"key":"D","text":"Fazla işgücü gerektirmemesi"},{"key":"E","text":"Derleme ve değerlendirme kolaylığı sağlaması"}],"answerText":"Tam ve kesin bilgiye ulaşmada karşılaşılan zorluklar","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi örnekleme yapılırken dikkat edilmesi gerekenlerden biri değildir?","options":[{"key":"A","text":"İçinden örnek seçilecek anakütle hakkında bazı özel bilgilere ihtiyaç vardır."},{"key":"B","text":"Örneklem seçiminde önyargıya yer verilebilir."},{"key":"C","text":"Seçme işlemi ilgilenilen özellikten veya değişkenden bağımsız olmalıdır"},{"key":"D","text":"Örnekleme alınan birimlerden her biri diğerinden bağımsız olmalıdır."},{"key":"E","text":"Örnekleme alınacak verilerin hepsine aynı koşullar uygulanmalıdır."}],"answerText":"Örneklem seçiminde önyargıya yer verilebilir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Anakütleyi oluşturan birimlerin örneğe girme şansları eşit olmadığı örnekleme tipine _______________________; anakütlenin her biriminin\nörneğe seçilme şansının eşit olduğu örnekleme tipine ise _________________________denir.” İfadesinde boş bırakılan yerleri doldurunuz.","options":[{"key":"A","text":"Sistematik örnekleme / Kolayda örnekleme"},{"key":"B","text":"Tesadüfi örnekleme / Tesadüfi olmayan örnekleme"},{"key":"C","text":"Tesadüfi olmayan örnekleme / Tesadüfi örnekleme"},{"key":"D","text":"Zümrelere göre örnekleme / Kasıtlı örnekleme"},{"key":"E","text":"Kümelere göre örnekleme / Kota örnekleme"}],"answerText":"Tesadüfi olmayan örnekleme / Tesadüfi örnekleme","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıda küme örneklemesi ile ilgili kullanılan ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Kümeler arasında homojenlik vardır."},{"key":"B","text":"Kümeler içinde heterojenlik vardır."},{"key":"C","text":"Saha çalışmasında kişilere ulaşmak zor olduğunda kullanılır."},{"key":"D","text":"Küme örneklemesi ile tabakalı örnekleme aynıdır."},{"key":"E","text":"Uygulaması kolay ve maliyeti düşüktür."}],"answerText":"Küme örneklemesi ile tabakalı örnekleme aynıdır.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Uygun elemanlardan örnekleme oluşturmaya çalışılan, örnekleme biriminin seçimini öncelikli olarak veri toplayıcıya bırakan, genellikle doğru\nzamanda, doğru yerde bulunanların seçildiği örnekleme yöntemine ne ad verilmektedir?","options":[{"key":"A","text":"Sistematik örnekleme"},{"key":"B","text":"Kasıtlı örnekleme"},{"key":"C","text":"Kota örnekleme"},{"key":"D","text":"Zümrelere göre örnekleme"},{"key":"E","text":"Kolayda örnekleme"}],"answerText":"Kolayda örnekleme","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Örnekleme sürecinin ilk adımı nedir?","options":[{"key":"A","text":"Örnekleme büyüklüğünü belirlemek"},{"key":"B","text":"Anakütleyi tanımlamak"},{"key":"C","text":"Örnekleme yöntemini seçmek"},{"key":"D","text":"Verileri analiz etmek"},{"key":"E","text":"Örnekleme çerçevesini belirlemek"}],"answerText":"Anakütleyi tanımlamak","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Örnekleme neden kullanılır?","options":[{"key":"A","text":"Anakütlenin tamamını incelemek maliyetli ve zaman alıcı olduğu için"},{"key":"B","text":"Daha fazla veri toplamak için"},{"key":"C","text":"Sadece belirli bir grubu incelemek için"},{"key":"D","text":"Tüm bireylerin katılımını sağlamak için"},{"key":"E","text":"Yalnızca küçük örneklemlerle çalışmak için"}],"answerText":"Anakütlenin tamamını incelemek maliyetli ve zaman alıcı olduğu için","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Ölçekleme ve Ölçek Türleri","cards":["Bu bölümde araştırmalarında ölçme ve ölçekleme kavramlarının ne olduğu açıklanmıştır. Ölçmenin önemine vurgu yapılarak, temel ölçüm seviyelerinin\naçıklamalarına yer verilmiştir.","Ölçek türleri detaylı olarak anlatılmış, sürekli ölçek, tekli ölçek ve çoklu ölçek başlıklarıyla detaylandırılmıştır. Araştırmalarda sıkça kullanılan Likert tipi\nölçek ile Semantik farklılıklar ölçekleri karşılaştırmalı olarak ele alınmıştır."],"questions":[{"q":"“Objelere ya da bireylere herhangi bir özelliğe sahip oluş miktarlarını belirtmek amacıyla sayı veya sembolle değer verme işlemidir”\nYukarıda tanımlanan kavram, aşağıdaki seçeneklerden hangisinde doğru olarak verilmiştir?","options":[{"key":"A","text":"Ölçme"},{"key":"B","text":"Ağırlıklandırma"},{"key":"C","text":"Değerlendirme"},{"key":"D","text":"Ölçme ve değerlendirme"},{"key":"E","text":"Ölçüt"}],"answerText":"Ölçme","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ölçmenin fonksiyonlarından değildir?","options":[{"key":"A","text":"Daha duyarlı olmayı sağlar"},{"key":"B","text":"Daha kesin veriler oluşturur."},{"key":"C","text":"Değerlendirmeye olanak sağlar."},{"key":"D","text":"Ölçme aracını denemeyi sağlar."},{"key":"E","text":"Performansı sayısallaştırır"}],"answerText":"Ölçme aracını denemeyi sağlar.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Mutlak sıfır noktasının bulunduğu ölçek türü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Sınıflama"},{"key":"B","text":"Oran"},{"key":"C","text":"Aralık"},{"key":"D","text":"Sıralama"},{"key":"E","text":"Dereceleme"}],"answerText":"Oran","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi, bir sınıflama ölçeği verisi değildir?","options":[{"key":"A","text":"Eğitim durumu"},{"key":"B","text":"Kişinin çalışıp çalışmaması"},{"key":"C","text":"Alışveriş yapılan mağaza türü"},{"key":"D","text":"Cinsiyet"},{"key":"E","text":"Medeni durum"}],"answerText":"Eğitim durumu","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Çalışma yılınız? [ ] 1-5 [ ] 6-10 [ ] 11-15 [ ] 16-20 [ ] 21 ve üzeri\nYukarıdaki soru aşağıdaki anket sorusu türlerinden hangisine bir örnektir?","options":[{"key":"A","text":"Liste"},{"key":"B","text":"Kategori"},{"key":"C","text":"Sıralama"},{"key":"D","text":"Nicelik"},{"key":"E","text":"Oranlama"}],"answerText":"Kategori","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki verilerden hangisi oran ölçeği ile ölçülebilir?","options":[{"key":"A","text":"Cinsiyet"},{"key":"B","text":"Meslek"},{"key":"C","text":"Öğrenim durumu"},{"key":"D","text":"Sıcaklık"},{"key":"E","text":"Aylık gelir"}],"answerText":"Aylık gelir","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki verilerden hangisi sıralama ölçeği ile ölçülebilir?","options":[{"key":"A","text":"Cinsiyet"},{"key":"B","text":"Önem seviyesi"},{"key":"C","text":"Meslek"},{"key":"D","text":"Sıcaklık"},{"key":"E","text":"Başarı puanı"}],"answerText":"Önem seviyesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi çoklu ölçek türlerinden biridir?","options":[{"key":"A","text":"Sabit-toplam"},{"key":"B","text":"Grafiksel"},{"key":"C","text":"Karşılaştırmalı"},{"key":"D","text":"Semantik farklılıklar"},{"key":"E","text":"Sıralama"}],"answerText":"Semantik farklılıklar","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sosyal araştırmalarda en çok kullanılan ölçek türü hangisidir?","options":[{"key":"A","text":"Likert tipi"},{"key":"B","text":"Semantik farklılıklar"},{"key":"C","text":"Karşılaştırmalı"},{"key":"D","text":"Sıralama"},{"key":"E","text":"Grafiksel"}],"answerText":"Likert tipi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"I-Kategori sayısı\nII-Ölçeklerde denge\nIII-Tek veya çift sayıda kategori\nIV-Kategorilerin yapısı ve yazılı gösterimi\nV-Ölçeğin fiziksel formu\nYukarıda verilenlerden hangileri ölçeklerde dikkat edilmesi gereken hususlardandır?","options":[{"key":"A","text":"I"},{"key":"B","text":"II"},{"key":"C","text":"III"},{"key":"D","text":"IV"},{"key":"E","text":"Hepsi"}],"answerText":"Hepsi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ölçekleme sürecinde kullanılan temel ölçüm seviyeleri kaç türe ayrılır?","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"4"},{"key":"E","text":"6"}],"answerText":"4","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Nominal ölçeği tanımlayan ana özellik aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Nesneleri sıralama yöntemi"},{"key":"B","text":"Nesneleri oransal olarak karşılaştırma yöntemi"},{"key":"C","text":"Nesneleri sınıflandırma yöntemi"},{"key":"D","text":"Eşit aralıklarla ölçüm yapma yöntemi"},{"key":"E","text":"Sürekli ölçek kullanma yöntemi"}],"answerText":"Nesneleri sınıflandırma yöntemi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Anket Formu Tasarımı","cards":["Bu bölümde bir araştırmanın geçerli olmasında büyük bir öneme sahip olan anket formunun özellikleri, genel yapısı, anket formu oluşturma süreci\nincelenmiştir. Tasarım aşamasında yer alan tüm aşamalar detaylandırılmıştır. Bu bağlamda araştırma için birinci kaynaktan anket yolu ile verilerin elde\nedilmesi kararlaştırılmış ise bu anketlerin nasıl tasarlanacağı ve nasıl oluşturulacağı bu bölümde detaylı olarak incelenmiştir."],"questions":[{"q":"Anket tasarımında sorunun içeriğine ilişkin aşağıdaki sorulardan hangisine gerek yoktur?","options":[{"key":"A","text":"Soru gerekli mi?"},{"key":"B","text":"Cevaplayıcı soruyu anlıyor mu?"},{"key":"C","text":"Soru talep edilen bilgiyi ortaya çıkarmada yeterli olacak mı?"},{"key":"D","text":"Soruyu cevaplamak çok zaman alır mı?"},{"key":"E","text":"Cevaplayıcının sorulara cevap vermek için yeterli bilgisi var mı?"}],"answerText":"Soruyu cevaplamak çok zaman alır mı?","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anket tasarımına ilişkin aşağıdakilerden hangisi yanlıştır?","options":[{"key":"A","text":"Cümleleri kısa tutmak her zaman için soruların daha rahat anlaşılmasını sağlar."},{"key":"B","text":"Negatif tasarımlı sorulardan olabildiğince yararlanılmalıdır."},{"key":"C","text":"Cevap seçenekleri kapsamlı ve birbiriyle çakışmayacak şekilde düzenlenmelidir."},{"key":"D","text":"Soruların tümü genelden özele gitmelidir."},{"key":"E","text":"Cevaplayıcıların kişisel ve demografik özellikleri ile ilgili sorular anketin sonunda yer almalıdır."}],"answerText":"Negatif tasarımlı sorulardan olabildiğince yararlanılmalıdır.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi anket sorularını geliştirirken dikkat edilmesi gereken ilkelerden biri değildir?","options":[{"key":"A","text":"Olumsuz tümcelere ağırlık verilmeli"},{"key":"B","text":"Sorular basit ve anlaşılır olmalı"},{"key":"C","text":"Yönlendirme içeren ifadelerden kaçınılmalı"},{"key":"D","text":"Yanıtlaması kolay sorular sorulmalı"},{"key":"E","text":"Gerçekdışı varsayımlara dayanan sorular sorulmamalı"}],"answerText":"Olumsuz tümcelere ağırlık verilmeli","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi anket tasarımı ve oluşumu aşamaları arasında yer almaz?","options":[{"key":"A","text":"Soru İçeriği"},{"key":"B","text":"Soru Düzeni"},{"key":"C","text":"Soru Yerleşimi"},{"key":"D","text":"Anketin Öntesti"},{"key":"E","text":"Veri Girişi"}],"answerText":"Veri Girişi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anketin tasarımında kullanılan dil ve üslup ile ilgili aşağıdakilerden hangisi doğrudur?","options":[{"key":"A","text":"Soru cümlelerin olabildiğince detaylı olması gerekir."},{"key":"B","text":"Önyargılı kelimeler hataya neden olur."},{"key":"C","text":"Yönlendirici sorular etkin cevap almayı sağlar."},{"key":"D","text":"“ebilir-abilir” ekleri cevaplayıcının daha rahat yanıt vermesini sağlar."},{"key":"E","text":"Tahminleme soruları cevaplayıcının arka plandaki düşüncelerini alma olanağı sağlar."}],"answerText":"Önyargılı kelimeler hataya neden olur.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ankette yer alan soruların düzeni ile alakalı aşağıda verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Beklenen cevaplara yönelik ipuçları verilmedir."},{"key":"B","text":"Sorular ilgi uyandıran bir nitelikte olmalıdır."},{"key":"C","text":"Sorular mantıklı bir sıra izlemelidir."},{"key":"D","text":"Yaş ve maaş gibi tanımlayıcı bilgiler anketin sonunda istenmelidir."},{"key":"E","text":"Mahcup edici, can sıkıcı sorulara anketin sonunda yer verilmelidir."}],"answerText":"Beklenen cevaplara yönelik ipuçları verilmedir.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anket sorularının sıralanması ile alakalı aşağıda verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Cevaplayıcıların kişisel ve demografik özellikleri ile ilgili sorular anketin sonunda yer almalıdır."},{"key":"B","text":"Sorular herhangi bir düzene göre değil tamamen rastgele yerleştirilmelidir."},{"key":"C","text":"Eğer anket, birçok başlığa işaret ediyorsa, aynı başlıklara odaklanan soruları bir araya toplamak önerilmektedir."},{"key":"D","text":"Bir başlık içerisinde soruların genelden özele doğru sıralanmasıdır."},{"key":"E","text":"Bazı anketlerde cevaplayıcıların tüm soruları cevaplaması gerekmemektedir. Bu durumda bazı sorular atlanabilir olmalıdır."}],"answerText":"Sorular herhangi bir düzene göre değil tamamen rastgele yerleştirilmelidir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anketin sınırlı sayıda potansiyel cevaplayıcıya ve anketin eksikliklerini görebilecek kişilere uygulanmasına ne ad verilmektedir?","options":[{"key":"A","text":"Analiz"},{"key":"B","text":"Araştırma"},{"key":"C","text":"Anket öntesti"},{"key":"D","text":"Anket metodu"},{"key":"E","text":"Anket tasarımı"}],"answerText":"Anket öntesti","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anketin öntesti yapılırken aşağıdakilerden hangisi dikkat edilmesi gereken durumlar arasında yer almaz?","options":[{"key":"A","text":"Öntestteki cevaplayıcılar hedef anakütlenin temsilcileri olmamalı farklı bir anakütleden alınmalıdır."},{"key":"B","text":"Öntestteki cevaplayıcılar hedef anakütlenin temsilcileri olmalıdır."},{"key":"C","text":"Anket ile ilgili yerleşme, soru akışı, kelime anlamı, soru zorluğu, dallanma talimatları gibi her konuya dikkat edilmelidir."},{"key":"D","text":"Öntest araştırmada kullanılacakla benzer bir çevrede yürütülmelidir."},{"key":"E","text":"Öntest görüşmelerinin büyük çoğunluğu benzer karakteristiklere, davranışlara ve fikirlere sahip olmalı ve konuyla alakalı olmalıdırlar."}],"answerText":"Öntestteki cevaplayıcılar hedef anakütlenin temsilcileri olmamalı farklı bir anakütleden alınmalıdır.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"I-Anketör kendilerini tanıtmalıdırlar.\nII-Katılımcıların onayını almalıdırlar.\nIII-Anketin amacıyla ilgili bilgilendirme yapmalıdırlar.\nYukarıda verilen anketin sunumunda yapılması gerekenlerin uygun sıralaması aşağıdaki şıkların hangisinde doğru olarak verilmiştir?","options":[{"key":"A","text":"I-II-III"},{"key":"B","text":"II-I-III"},{"key":"C","text":"II-III-I"},{"key":"D","text":"I-III-II"},{"key":"E","text":"III-II-I"}],"answerText":"I-III-II","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Anketin temel amacı nedir?","options":[{"key":"A","text":"Görüş ve düşünceleri toplamak"},{"key":"B","text":"Sayısal veriler toplamak"},{"key":"C","text":"Katılımcıların demografik bilgilerini öğrenmek"},{"key":"D","text":"Deneysel veriler toplamak"},{"key":"E","text":"Anketörün görüşlerini belirtmek"}],"answerText":"Görüş ve düşünceleri toplamak","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Öntest nedir?","options":[{"key":"A","text":"Anketi ilk yanıtlandıranların analiz edilmesi"},{"key":"B","text":"Anketin anakütle yerine örnekleme uygulanması"},{"key":"C","text":"Anket sonuçlarının değerlendirilmesi"},{"key":"D","text":"Anketin sınırlı sayıda potansiyel cevaplayıcıya uygulanması"},{"key":"E","text":"Anket sorularının belirlenmesi"}],"answerText":"Anketin sınırlı sayıda potansiyel cevaplayıcıya uygulanması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Bilimsel Araştırmalarda Hata ve Güvenirlik","cards":["Bu bölümde araştırmada hata kavramı, hata türleri, hata minimize yolları detaylıca incelenmiştir. Özellikle güvenilirlik kavramının üzerinde durulmuş,\ngüvenirlik ölçme yöntemleri detaylıca incelenmiştir. Son olarak bir araştırmanın güvenirliğini artırmak amacıyla izlenecek yollar açıklanmıştır."],"questions":[{"q":"Aşağıdakilerden hangisi güvenirlik türlerinden biri değildir?","options":[{"key":"A","text":"Test-tekrar test"},{"key":"B","text":"Bağımsız gözlemciler arası uyum"},{"key":"C","text":"Uyum-benzer ölçekler"},{"key":"D","text":"İç tutarlılık"},{"key":"E","text":"Eş değer (paralel) formlar"}],"answerText":"Uyum-benzer ölçekler","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İki ya da daha çok puanlayıcının, farklı bireylere, durumlara ya da nesnelere ilişkin yaptıkları puanlamalar arasındaki tutarlık derecesi\naşağıdakilerden hangisidir?","options":[{"key":"A","text":"Cronbach alfa güvenirliği"},{"key":"B","text":"Puanlayıcı güvenirliği"},{"key":"C","text":"Bölünmüş yarılar güvenirliği"},{"key":"D","text":"Paralel formlar güvenirliği"},{"key":"E","text":"Test-tekrar test güvenirliği"}],"answerText":"Paralel formlar güvenirliği","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Örnek bireylerinin değerlerindeki değişmelerin neden olduğu, aynı anakütleden alınacak değişik örnek değerlerinden elde edilecek tahminler\narasındaki farkların esas alınarak ölçüldüğü hata türlerine ne ad verilir?","options":[{"key":"A","text":"Sabit hata"},{"key":"B","text":"Sistematik hata"},{"key":"C","text":"Tesadüfi hata"},{"key":"D","text":"Tahmini hata"},{"key":"E","text":"Muhtemel hata"}],"answerText":"Tesadüfi hata","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıda belirtilenlerden hangisi hataların önlenmesine/indirgenmesine yardımcı olmaz?","options":[{"key":"A","text":"Araştırmanın başında amaçlar doğru belirlenmelidir."},{"key":"B","text":"Problemler ve hipotezler, değişken ve ölçekler rastgele belirlenmelidir."},{"key":"C","text":"Örneklem seçilirken anakütlenin sınırları tam olarak belirlenmeli, anakütlenin yapısına uygun örneklem seçim yöntemi kullanılmalıdır."},{"key":"D","text":"Araştırmanın uygulama aşamasında literatürden yardım alınmalıdır."},{"key":"E","text":"İstatistiksel teknikler hakkında temel düzeyde bilgi edinilmelidir. Araştırmanın uygulama aşamasında bir uygulamalı istatistik uzmanından yardım alınmalıdır."}],"answerText":"Problemler ve hipotezler, değişken ve ölçekler rastgele belirlenmelidir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir özelliğin değişik zamanlarda aynı koşullar altında ve aynı bireyler üzerinde aynı araçla ölçülmesi halinde aynı sonuçların elde edilebilmesi\ndurumunu ifade eden kavrama ne ad verilmektedir?","options":[{"key":"A","text":"Geçerlik"},{"key":"B","text":"Ölçüm"},{"key":"C","text":"Değişken"},{"key":"D","text":"Kararlılık"},{"key":"E","text":"Güvenirlik"}],"answerText":"Güvenirlik","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Ölçme sonucunda hata miktarı düştükçe güvenirlik _________. Hata miktarı arttıkça güvenirlik de ___________.”İfadesinde boş bırakılan\nyerlere aşağıdakilerden hangisi getirilmelidir?","options":[{"key":"A","text":"düşer/ artar"},{"key":"B","text":"azalır/yükselir"},{"key":"C","text":"sabit kalır/yükselir"},{"key":"D","text":"artar/düşer"},{"key":"E","text":"azalır/sabit kalır"}],"answerText":"artar/düşer","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi güvenirlik bileşenlerinden biri değildir?","options":[{"key":"A","text":"Öznellik"},{"key":"B","text":"İç tutarlılık"},{"key":"C","text":"İstikrarlılık"},{"key":"D","text":"Temsil edicilik"},{"key":"E","text":"Nesnellik"}],"answerText":"Öznellik","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Sosyal bilimlerde en çok kullanılan yöntem ___________________ ve genellikle ___________ ile hesaplanır.”İfadesinde boş bırakılan yerlere\naşağıdakilerden hangisi getirilmelidir?","options":[{"key":"A","text":"Temsil edicilik / Korelasyon katsayısı"},{"key":"B","text":"Nesnellik / Eşdeğerlik katsayısı"},{"key":"C","text":"İçsel tutarlılık / Cronbach’s alpha"},{"key":"D","text":"İstikrarlılık / Kararlılık katsayısı"},{"key":"E","text":"Eş değerlilik / Korelasyon katsayısı"}],"answerText":"İçsel tutarlılık / Cronbach’s alpha","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Cronbach Alpha (a) Katsayısının yorumlanması ile ilgili aşağıda verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"0 < α < 0.40 ise Ölçek Güvenilir Değil."},{"key":"B","text":"α < 0 ise ölçek güvenilirdir, negatif bir ilişki vardır."},{"key":"C","text":"0.40 < α < 0.60 ise Ölçek Düşük Güvenilirlikte"},{"key":"D","text":"0.60 < α < 0.80 ise Ölçek Oldukça Güvenilir"},{"key":"E","text":"0.80 <α< 1.00 ise Ölçek Yüksek Güvenirlikte"}],"answerText":"α < 0 ise ölçek güvenilirdir, negatif bir ilişki vardır.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırmada yapılan ölçümün ve elde edilen sonuçların güvenirliliğinin artırılması için aşağıda verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Ölçekte kullanılan soruların/maddelerin sayısı arttıkça güvenirlik artar."},{"key":"B","text":"Örneklem büyüklüğü arttıkça güvenirlik artar."},{"key":"C","text":"Uygulanacak ölçme yönteminin içeriği, katılımcı kişilerin bilgi ve algılama seviyesine uygunsa güvenirlik artar."},{"key":"D","text":"Sorular açık ve anlaşılır ise güvenirlik artar."},{"key":"E","text":"Örneklem büyüklüğü azaldıkça güvenirlik artar."}],"answerText":"Örneklem büyüklüğü azaldıkça güvenirlik artar.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hata türlerinden biri olan sabit hata nedir?","options":[{"key":"A","text":"Her ölçümde aynı miktarda olan hata"},{"key":"B","text":"Değişkenlik gösteren hata"},{"key":"C","text":"Örneklem seçimiyle ilgili hata"},{"key":"D","text":"Yanlış veri girişi kaynaklı hata"},{"key":"E","text":"Anket sorularının yanlış olması kaynaklı hata"}],"answerText":"Her ölçümde aynı miktarda olan hata","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sistematik hatanın temel özelliği nedir?","options":[{"key":"A","text":"Araştırma problemi kaynaklı olarak meydana gelmesi"},{"key":"B","text":"Her ölçümde aynı miktarda olması"},{"key":"C","text":"Geri dönüşünün mümkün olmaması"},{"key":"D","text":"Tesadüfi olarak meydana gelmesi"},{"key":"E","text":"Verilerin yanlış kodlanması"}],"answerText":"Geri dönüşünün mümkün olmaması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Bilimsel Araştırmalarda Geçerlik","cards":["Araştırmada bulunması gereken en önemli niteliklerden olan geçerlik ve güvenirlik kavramları detaylı olarak açıklanmıştır. Geçerlik türleri kapsamlı\nolarak ele alınmıştır. Son olarak araştırmayı geçersiz kılan faktörlere değinilmiştir."],"questions":[{"q":"‘Geçerlik’ ile ilgili olarak aşağıda yer alan ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Uyum geçerliği analizinde, aynı amaca yönelik iki ölçü aracı birbiriyle karşılaştırılır."},{"key":"B","text":"İçerik geçerliği analizinde, bilgi ölçen bir ölçü aracının, ilişkili olduğu alandaki içeriği yansıtma düzeyi belirlenir."},{"key":"C","text":"Geçerlik, istatistiksel analizlerle yüzde olarak hesaplanır."},{"key":"D","text":"Yapı geçerliği, gözlenemeyen değişkenleri ölçmeyi hedefleyen ölçü araçları için söz konusudur."},{"key":"E","text":"İçerik geçerliği analizinde, uzman görüşüne başvurulabilir."}],"answerText":"Geçerlik, istatistiksel analizlerle yüzde olarak hesaplanır.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir ölçme aracının ölçmeyi amaçladığı özelliği, başka herhangi bir özellikle karıştırmadan doğru olarak ölçebilme derecesine ne ad verilir?","options":[{"key":"A","text":"Kullanışlılık"},{"key":"B","text":"Güvenirlik"},{"key":"C","text":"Nesnellik"},{"key":"D","text":"Önemlilik"},{"key":"E","text":"Geçerlik"}],"answerText":"Geçerlik","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi geçerlik türlerinden biri değildir?","options":[{"key":"A","text":"Kapsam"},{"key":"B","text":"Kriter"},{"key":"C","text":"Yapı"},{"key":"D","text":"Eş değer (paralel)"},{"key":"E","text":"Görünüş"}],"answerText":"Eş değer (paralel)","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Testin ölçmek istediği özellikleri ve davranışları ne derecede kapsaması ile ilgili olan ve bir bütün olarak ölçeğin her bir maddesinin amaca ne\nderece hizmet ettiğini ifade eden geçerlik türü hangisidir?","options":[{"key":"A","text":"Kriter geçerliliği"},{"key":"B","text":"Yapı geçerliliği"},{"key":"C","text":"Görünüş geçerliliği"},{"key":"D","text":"Kapsam geçerliği"},{"key":"E","text":"Uyum geçerliliği"}],"answerText":"Kapsam geçerliği","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir teoriye dayalı olarak geliştirilmiş bir ölçeğin (özellikle, psikoloji alanında) o teoride yer alan yapıları ne derecede ölçebildiğini geçerlik türü\nhangisidir?","options":[{"key":"A","text":"Kriter geçerliliği"},{"key":"B","text":"Uyum geçerliliği"},{"key":"C","text":"Görünüş geçerliliği"},{"key":"D","text":"Kapsam geçerliği"},{"key":"E","text":"Yapı geçerliliği"}],"answerText":"Yapı geçerliliği","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yapı geçerliliğinin değerlendirilmesi ile ilgili aşağıdaki ifadelerden hangisi doğru değildir?","options":[{"key":"A","text":"Alan uzmanları tarafından sorular incelenebilir."},{"key":"B","text":"Aynı yapıyı ölçtüğü bilinen başka bir test ile elde edilen sonuçlar arasındaki korelasyon hesaplanabilir (korelasyonun yüksek çıkması beklenir)."},{"key":"C","text":"Aynı yapıyı ölçtüğü bilinen başka bir test ile elde edilen sonuçlar arasındaki korelasyon hesaplamasına gerek yoktur (korelasyonun düşük çıkması\nbeklenir)."},{"key":"D","text":"Ölçülecek yapı açısından birbirinden farklı olduğu bilinen iki gruba ölçek uygulanarak sonuçlar karşılaştırılabilir (gruplar arası farkın anlamlı olması"},{"key":"E","text":"beklenir). Testin ölçtüğü yapı veya yapıları ortaya çıkaran faktör analizi de yapılabilir (teori ile örtüşen yapıların ortaya çıkması beklenir)."}],"answerText":"Aynı yapıyı ölçtüğü bilinen başka bir test ile elde edilen sonuçlar arasındaki korelasyon hesaplamasına gerek yoktur (korelasyonun düşük çıkması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir ölçekte yer alan maddelerdeki ifadelerin her okuyucu ve araştırmacı tarafından aynı şekilde anlaşılmasına imkân veren, ölçme aracının neyi\nölçtüğünü değil de neyi ölçer göründüğünü belirtmekte olan geçerlik türü hangisidir?","options":[{"key":"A","text":"Kriter geçerliliği"},{"key":"B","text":"Görünüş geçerliliği"},{"key":"C","text":"Uyum geçerliliği"},{"key":"D","text":"Kapsam geçerliği"},{"key":"E","text":"Yapı geçerliliği"}],"answerText":"Görünüş geçerliliği","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir ölçme işleminde geçerlik “_______ ölçülecek?” güvenirlik ise “_______ölçülecek?” sorusunun cevabını inceler.” İfadesinde boş bırakılan\nyerleri doldurunuz.","options":[{"key":"A","text":"ne / niye"},{"key":"B","text":"niye / ne"},{"key":"C","text":"niye / nasıl"},{"key":"D","text":"ne / nasıl"},{"key":"E","text":"nerede / ne zaman"}],"answerText":"ne / nasıl","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırmayı geçersiz kılan faktörlerden biri değildir?","options":[{"key":"A","text":"Gelecek etkisi"},{"key":"B","text":"Geçmişin etkisi"},{"key":"C","text":"Olgunlaşma etkisi"},{"key":"D","text":"Test etkisi"},{"key":"E","text":"Araç etkisi"}],"answerText":"Gelecek etkisi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırmaya katılan bireylerin tutum ve/veya davranışlarının gözlendiğini veya ölçüldüğünü bilmeleri sonucunda koşullanarak gerçek dışı\ndavranmaları sonucunda ortaya çıkan bir geçersizlik kaynağı hangisidir?","options":[{"key":"A","text":"Seçim etkisi"},{"key":"B","text":"Geçmişin etkisi"},{"key":"C","text":"Test etkisi"},{"key":"D","text":"Olgunlaşma etkisi"},{"key":"E","text":"Araç etkisi"}],"answerText":"Test etkisi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Geçerlik nedir?","options":[{"key":"A","text":"Ölçme aracının amaca hizmet etme derecesidir"},{"key":"B","text":"Ölçme aracının tutarlılığı"},{"key":"C","text":"Ölçme aracının kullanılabilirliği"},{"key":"D","text":"Ölçme aracının doğruluğu"},{"key":"E","text":"Ölçme aracının istatistiksel anlamlılığı"}],"answerText":"Ölçme aracının amaca hizmet etme derecesidir","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kapsam geçerliği nedir?","options":[{"key":"A","text":"Ölçme aracının görsel olarak kabul edilebilirliği"},{"key":"B","text":"Ölçme aracının ölçmek istediği özellikleri ne derece kapsadığı"},{"key":"C","text":"Ölçme aracının kullanıcılar tarafından anlaşılırlığı"},{"key":"D","text":"Ölçme aracının tüm soruları içermesi"},{"key":"E","text":"Ölçme aracının soruları arasındaki ilişki derecesi"}],"answerText":"Ölçme aracının ölçmek istediği özellikleri ne derece kapsadığı","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Veri Hazırlama ve Veri Analizi","cards":["Bu bölümde veri hazırlama aşamasının araştırma sürecindeki yeri ve önemi kısaca açıklanmıştır. Veri hazırlama sürecinde bulunan alt basamakların\nkapsamları incelenmiştir.","İşletme araştırmalarında kullanılan tek ve çok değişkenli istatistiksel analizlere yer verilerek en uygun testine seçiminde dikkat edilmesi gereken noktalar\ntartışılmıştır."],"questions":[{"q":"Aşağıdakilerden hangisi veri hazırlama aşamaları arasında değildir?","options":[{"key":"A","text":"Veri Düzenleme"},{"key":"B","text":"Kodlama"},{"key":"C","text":"Veri Girişi"},{"key":"D","text":"Veri Analizi"},{"key":"E","text":"Kayıp Gözlemleri Düzenleme"}],"answerText":"Veri Analizi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tanımlayıcı (betimsel) istatistikler ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Tek bir madde ya da değişken hakkındaki sayısal veriler özetlenir."},{"key":"B","text":"Bir değişken içerisinde her bir değerin kaç kez tekrar ettiği belirtilebilir."},{"key":"C","text":"Değerlerin merkez nokta etrafında nasıl dağıldığına bakılabilir."},{"key":"D","text":"Bulgular frekans tabloları, sütun grafiği ya da histogramla özetlenebilir."},{"key":"E","text":"Değişkenler arası ilişkilere odaklanılır."}],"answerText":"Değişkenler arası ilişkilere odaklanılır.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangi merkezi eğilim ölçüsü dağılımı iki eşit parçaya böler?","options":[{"key":"A","text":"Aritmetik ortalama"},{"key":"B","text":"Geometrik Ortalama"},{"key":"C","text":"Mod"},{"key":"D","text":"Medyan"},{"key":"E","text":"Varyans"}],"answerText":"Medyan","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aralıklı ve oranlı düzeyde ölçülmüş iki değişken arasında ilişki olup olmadığını, varsa yönünü ve gücünü göstermek amacıyla kullanılan analiz\ntürü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"t testi"},{"key":"B","text":"Korelasyon"},{"key":"C","text":"Ki kare"},{"key":"D","text":"Varyans analizi"},{"key":"E","text":"Z testi"}],"answerText":"Korelasyon","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi çok değişkenli istatistiksel analizler arasında yer almaz?","options":[{"key":"A","text":"Faktör Analizi"},{"key":"B","text":"Kümeleme Analizi"},{"key":"C","text":"MANOVA"},{"key":"D","text":"Ayırma Analizi"},{"key":"E","text":"Ki-kare analizi"}],"answerText":"Ki-kare analizi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Değişken bir niteliği belirtiyorsa _______, bir nicelik belirtiyorsa _____________ değişkendir. Nicel değişkenler, herhangi bir aralıktaki bir\ndeğere sahip olabiliyorsa (ondalıklı değer alıyorsa) __________, tam sayı değer alıyorsa __________ değişkendir.” İfadesindeki boş bırakılan\nyerleri doldurunuz.","options":[{"key":"A","text":"nitel / nicel / sürekli / kesikli"},{"key":"B","text":"nitel / nicel / kesikli / sürekli"},{"key":"C","text":"kesikli / nicel / sürekli / nitel"},{"key":"D","text":"nitel / kesikli / sürekli / nicel"},{"key":"E","text":"nitel / sürekli / nicel / kesikli"}],"answerText":"nitel / nicel / sürekli / kesikli","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tanımlayıcı istatistiklerden biri değildir?","options":[{"key":"A","text":"Frekans ve yüzde"},{"key":"B","text":"Aritmetik ortalama"},{"key":"C","text":"Mod"},{"key":"D","text":"Medyan"},{"key":"E","text":"Regresyon analizi"}],"answerText":"Regresyon analizi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Fazla sayıdaki değişkenler arasında içsel ilişkileri analiz etmeyi ve bu değişkenlerin temelinde yatan ortak boyutları açıklayan, birbiriyle ilişkili\nçok sayıda değişkeni bir araya getirerek az sayıda kavramsal olarak anlamlı yeni değişkenler (faktörler) bulmak ve keşfetmek istendiğinde\nkullanılan istatistiksel analiz hangisidir?","options":[{"key":"A","text":"Kümeleme analizi"},{"key":"B","text":"Çoklu varyans analizi"},{"key":"C","text":"Faktör analizi"},{"key":"D","text":"Çoklu regresyon analizi"},{"key":"E","text":"Conjoint analizi"}],"answerText":"Faktör analizi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Gruplaşmamış verileri benzerliklerine göre sınıflandırmak ve uygun, işe yarar, özetleyici bilgiler elde etmek istendiğinde kullanılan ve verileri\nbenzerliklere bağlı özel alt gruplar halinde sınıflandıran istatistiksel analiz nedir?","options":[{"key":"A","text":"Faktör analizi"},{"key":"B","text":"Kümeleme analizi"},{"key":"C","text":"Çoklu regresyon analizi"},{"key":"D","text":"Kanonik korelasyon analizi"},{"key":"E","text":"Çoklu varyans analizi"}],"answerText":"Kümeleme analizi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tek bir bağımlı değişkenin bir veya daha fazla bağımsız değişken ile ilişkisinin incelenmesinde kullanılan ve bağımsız değişkenlerdeki\ndeğişmelere yanıt olarak bağımlı değişkendeki değişmeleri tahmin eden istatistiksel analiz nedir?","options":[{"key":"A","text":"Conjoint analizi"},{"key":"B","text":"Kümeleme analizi"},{"key":"C","text":"Kanonik korelasyon analizi"},{"key":"D","text":"Çoklu regresyon analizi"},{"key":"E","text":"Faktör analizi"}],"answerText":"Çoklu regresyon analizi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Veri hazırlama sürecinin ilk aşaması nedir?","options":[{"key":"A","text":"Düzenleme"},{"key":"B","text":"Veri girişi"},{"key":"C","text":"Veri analizi"},{"key":"D","text":"Kodlama"},{"key":"E","text":"Kayıp gözlemleri düzenleme"}],"answerText":"Düzenleme","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kodlama işlemini en iyi tanımlar?","options":[{"key":"A","text":"Verilerin bilgisayara aktarılması"},{"key":"B","text":"Verilerin sınıflandırılması ve belirli kodlarla işaretlenmesi"},{"key":"C","text":"Verilerin düzenlenmesi"},{"key":"D","text":"Anket sorularının yanıtlandırılması"},{"key":"E","text":"Kayıp verilerin belirlenmesi"}],"answerText":"Verilerin sınıflandırılması ve belirli kodlarla işaretlenmesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Bilimsel Araştırma Raporunun Hazırlanması","cards":["Bu bölümde araştırma yöntemlerinde elde edilen bulguların nasıl yorumlanacağı ve dikkat edilmesi gereken unsurlar belirtilmiştir.","Elde edilen bulgular ve yorumlardan sonra bir bütün olarak araştırma raporunun sunulması gerekmektedir. Bu raporun hazırlanması süreci detaylı olarak\nincelenmiştir.","Araştırma sürecinde ve yazımında kaynak ve kaynak göstermenin önemi üzerinde durulmuştur."],"questions":[{"q":"Araştırmadan elde edilen verilerin işlenmesi ve çözümlenmesinden sonra elde edilen bilgiye ne ad verilir?","options":[{"key":"A","text":"Bulgu"},{"key":"B","text":"Veri"},{"key":"C","text":"Hipotez"},{"key":"D","text":"Yargı"},{"key":"E","text":"Varsayım"}],"answerText":"Bulgu","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi rapor yazımında dikkat edilmesi gereken hususlardan değildir?","options":[{"key":"A","text":"Açık ve anlaşılır bir dille yazılmalı"},{"key":"B","text":"Subjektif yargılardan kaçınılmalı"},{"key":"C","text":"Araştırmacının duygularını da içermeli"},{"key":"D","text":"Metin içinde üslup birliği sağlanmalı"},{"key":"E","text":"İlgi çekici ve akıcı bir üslupla yazılmalı"}],"answerText":"Araştırmacının duygularını da içermeli","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırmayı kısaca tanıtmak üzere hazırlanan özet sayfasına ne ad verilir?","options":[{"key":"A","text":"Kapak sayfası"},{"key":"B","text":"Bulgular"},{"key":"C","text":"Tartışma"},{"key":"D","text":"Öz"},{"key":"E","text":"Ekler"}],"answerText":"Öz","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel bir rapor yazımında, bir kaynaktan yapılan doğrudan alıntı, aşağıdaki durumların hangisinde doğrudur?","options":[{"key":"A","text":"Araştırmacı kendi görüşlerini belirtiyorsa"},{"key":"B","text":"Araştırmacı bir başka yazarın görüşlerini kendi cümleleriyle belirtiyorsa"},{"key":"C","text":"Araştırmacı konuyla ilgili bir örnek veriyorsa"},{"key":"D","text":"Araştırmacı elindeki istatistiki bilgileri yorumluyorsa"},{"key":"E","text":"Araştırmacı bir ifade, tanım veya kavramı bir kaynaktan olduğu gibi alıp, çalışmasında kullanıyorsa"}],"answerText":"Araştırmacı bir ifade, tanım veya kavramı bir kaynaktan olduğu gibi alıp, çalışmasında kullanıyorsa","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel rapor hazırlamada uluslararası kabul gören iki yazım tekniğinden biri aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Word"},{"key":"B","text":"Excel"},{"key":"C","text":"APA"},{"key":"D","text":"SSCI"},{"key":"E","text":"Scopus"}],"answerText":"APA","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Raporlarda kaynak gösterme ile ilgili aşağıda verilen ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Genel bilgilerin dışında kalan ve başkaları tarafından ifade edilmiş görüşler aktarılırken mutlak kaynak gösterilmelidir."},{"key":"B","text":"Başka kaynaklardan edinilen fikir ya da düşünceler aktarılırken mutlak kaynak gösterilmelidir."},{"key":"C","text":"Makalelerden yapılan atıflar dışında diğer alıntılar için kaynak göstermeye gerek yoktur."},{"key":"D","text":"Tablo ya da çizelgenin alındığı kaynaklar mutlaka gösterilmelidir."},{"key":"E","text":"Kaynaklar metin içerisinde de gösterilebildiği gibi, dipnotlar halinde de gösterilebilir."}],"answerText":"Makalelerden yapılan atıflar dışında diğer alıntılar için kaynak göstermeye gerek yoktur.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıda verilenlerden hangisi kaynak gösterme türleri arasında yer almaz?","options":[{"key":"A","text":"Başlangıç sayfasında dipnot"},{"key":"B","text":"APA (American Psychological Association)"},{"key":"C","text":"MLA (Modern Language Association)"},{"key":"D","text":"Sayfa sonunda dipnot"},{"key":"E","text":"Bölüm sonunda dipnot"}],"answerText":"Başlangıç sayfasında dipnot","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi alıntı yapıldığının belirtilmesi gerekmeyen durumlardan biri değildir?","options":[{"key":"A","text":"Herkesçe bilinen, herkesçe tekrarlanan terimler."},{"key":"B","text":"Sözlük, ansiklopedi, el kitabı bilgilerindeki anonim yazılar."},{"key":"C","text":"Orijinalliği olmayan gözlem ve fikirler."},{"key":"D","text":"Atasözleri, deyişler"},{"key":"E","text":"Yayımlanmasının üzerinden 20 yıl geçmiş makaleler"}],"answerText":"Yayımlanmasının üzerinden 20 yıl geçmiş makaleler","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisinde kaynak gösterirken uyulması gereken kural yanlış olarak verilmiştir?","options":[{"key":"A","text":"Her bilimsel çalışmada, yararlanılan kaynakların listelendiği bir kaynakça bölümü bulunmalıdır."},{"key":"B","text":"Kaynakçada her kaynak yalnız bir kez yazılmamalı, atıf yapıldığı sayı kadar tekrar etmelidir."},{"key":"C","text":"Metin içinde gönderme yapılan her kaynak kaynakçada yer almalı, kaynakçada yer verilen her kaynağa da metin içinde gönderme yapılmalıdır."},{"key":"D","text":"Kaynakçaya alınacak yapıtlar, yazarın bizzat okuyup yararlandığı yapıtlar olmalıdır."},{"key":"E","text":"Kaynakçada, ilgili yayının künyesi kurallara uygun olarak verilmeli, künye içindeki bilgi öğeleri tam ve doğru olmalıdır."}],"answerText":"Kaynakçada her kaynak yalnız bir kez yazılmamalı, atıf yapıldığı sayı kadar tekrar etmelidir.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kaynakçada, yararlanılan kaynağa erişimi sağlayacak ölçüde bilgiye yer verilmesi gerekmektedir. Bu durumda aşağıdaki bilgilerden hangisinin\nkaynakçada yer almasına gerek yoktur?","options":[{"key":"A","text":"Yazar adı"},{"key":"B","text":"Yayın yılı"},{"key":"C","text":"Yapıt adı"},{"key":"D","text":"Yazarın çalışma alanları"},{"key":"E","text":"Yayın yeri"}],"answerText":"Yazarın çalışma alanları","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilimsel araştırma raporunun ilk kısmında hangi bilgiler yer alır?","options":[{"key":"A","text":"Verilerin analizi"},{"key":"B","text":"Sonuçların tartışılması"},{"key":"C","text":"Araştırma yöntemleri"},{"key":"D","text":"Kapak sayfası ve özet"},{"key":"E","text":"Hipotezler"}],"answerText":"Kapak sayfası ve özet","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Rapor yazımında dil ve üslup nasıl olmalıdır?","options":[{"key":"A","text":"Teknik ve karmaşık"},{"key":"B","text":"Günlük dilde"},{"key":"C","text":"Şiirsel ve edebi"},{"key":"D","text":"Kısa ve öz"},{"key":"E","text":"Akademik ve anlaşılır"}],"answerText":"Akademik ve anlaşılır","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Bilimsel Araştırma Etiği","cards":["Bu bölümde, bilim ve etik kavramları açıklanmış ve araştırma etiğinin kapsamı, etik dışı davranışların neler olduğu detaylı olarak incelenmiştir.","Kamuoyu açısından, araştırmaya katılan cevaplayıcı açısından ve araştırmacı-kurum açısından karşılaşılan etik dışı davranışların oluşma süreci\nincelenmiş ve buna yönelik çözüm önerileri sunulmuştur. Son olarak, intihal, intihal yolları, intihale başvurma nedenleri açıklanmış, intihali belirleme\nyöntemleri üzerinde durulmuş ve telif hakları ve intihal kavramı arasındaki ilişki üzerinde durulmuştur."],"questions":[{"q":"Aşağıdakilerden hangisi bilimsel araştırma etiği açısından uygun bir tutum değildir?","options":[{"key":"A","text":"Kanıtların dikkatli bir şekilde toplanması ve kullanılması"},{"key":"B","text":"Fikirlerin ve başkalarının eserlerinin dikkatli kullanılması"},{"key":"C","text":"Söylemde nezaket ve ikna yolunun tercih edilmesi"},{"key":"D","text":"Üretilen bilginin, mutlak doğruyu gösterdiğinin iddia edilmesi"},{"key":"E","text":"Bilgi edinme sürecinde cevaplayıcılara zarar verilmemesi"}],"answerText":"Üretilen bilginin, mutlak doğruyu gösterdiğinin iddia edilmesi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bilim insanlarının etik sorumlulukları arasında ver almaz?","options":[{"key":"A","text":"Kendi düşüncelerini doğrulamaya çalışmaktan kaçınma"},{"key":"B","text":"Oluşturdukları kuramlara gerçeğin değişmez bilgisi olarak bakmama"},{"key":"C","text":"Araştırma tasarımı ve yürütülmesinde temel ilkelere bağlı kalma"},{"key":"D","text":"Toplumu ve doğayı ilgilendiren her türlü olgu ve değerle uğraşma"},{"key":"E","text":"Dürüst davranma"}],"answerText":"Toplumu ve doğayı ilgilendiren her türlü olgu ve değerle uğraşma","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İntihal” sözcüğünün anlamı aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Kopyalama"},{"key":"B","text":"Aşırma"},{"key":"C","text":"Akademik hırsızlık"},{"key":"D","text":"Başkasının eserini kendine mal etme"},{"key":"E","text":"Hepsi"}],"answerText":"Hepsi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir araştırmanın saydamlığını, güvenirliğini, geçerliğini ve değerini olumsuz etkileyen hatalı, disiplinsiz, kasıtlı ya da özensiz tüm girişimler”\nifadesi hangi kavramı tanımlamaktadır?","options":[{"key":"A","text":"Bilimsel yanıltma"},{"key":"B","text":"Bilimsel ihmal"},{"key":"C","text":"Disiplinsiz araştırma"},{"key":"D","text":"Kasıtlı sahtekârlık"},{"key":"E","text":"Bilimsel saptırma"}],"answerText":"Bilimsel yanıltma","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi araştırmalarında etik dışı davranışların tarafları arasında yer almaz?","options":[{"key":"A","text":"Kamuoyu"},{"key":"B","text":"Araştırmacı"},{"key":"C","text":"İşletme"},{"key":"D","text":"Rakipler"},{"key":"E","text":"Cevaplayıcı"}],"answerText":"Rakipler","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletmelerin uyguladıkları yasal araştırmalarda bile kasıtlı olarak cevaplayıcıların hakları çiğnenebilmektedir. Aşağıdakilerden hangisi bu\ndurumlardan biri değildir?","options":[{"key":"A","text":"Özel bir ölçümün amacının gizlenmesi,"},{"key":"B","text":"İşbirliği sağlamak için yalan sunuş,"},{"key":"C","text":"Bir görüşme daha yapılacağının cevaplayıcıya söylenmemesi,"},{"key":"D","text":"Anketin amacının, tüm aşamalarının ve detaylarının cevaplayıcıya aktarılması,"},{"key":"E","text":"Görüşmeye devam edebilmek için görüşmecinin cevaplayıcıya yalan söylemesi,"}],"answerText":"Anketin amacının, tüm aşamalarının ve detaylarının cevaplayıcıya aktarılması,","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Eser sahibi ürününün kullanılmasından haberdar olması ve üçüncü kişilerin aldatılmasına yardım etmesi anlamına gelen aldatma türüne ne ad\nverilir?","options":[{"key":"A","text":"Muvazaa"},{"key":"B","text":"İntihal"},{"key":"C","text":"Alıntı yapma"},{"key":"D","text":"Kopyalama"},{"key":"E","text":"Benzetme"}],"answerText":"Muvazaa","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kaynak göstermeden, yazarın adını belirtmeden bir eserden parçalar alma, kendininmiş gibi gösterme veya bir eserin bütününü kendine mal\netme gibi aldatma işlemlerine ne ad verilir?","options":[{"key":"A","text":"Muvazaa"},{"key":"B","text":"Alıntı"},{"key":"C","text":"İntihal"},{"key":"D","text":"Benzetme"},{"key":"E","text":"Tekrarlama"}],"answerText":"İntihal","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kişileri intihale başvurmaya sevk eden nedenlerden biri değildir?","options":[{"key":"A","text":"İntihalin kolayca yapılabiliyor olması,"},{"key":"B","text":"Çok iyi bir zaman yönetimi yapılması,"},{"key":"C","text":"Tembellik,"},{"key":"D","text":"Beklentiler,"},{"key":"E","text":"Çalışmanın önemli bulunmaması veya ilgi çekmemesi,"}],"answerText":"Çok iyi bir zaman yönetimi yapılması,","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi intihali tespit etmeye yönelik program veya internet sitelerinden biri değildir?","options":[{"key":"A","text":"iThenticate"},{"key":"B","text":"Turnitin"},{"key":"C","text":"Intihal.net"},{"key":"D","text":"PlagScan"},{"key":"E","text":"ULAKBİM"}],"answerText":"ULAKBİM","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Disiplinsiz araştırma nedir?","options":[{"key":"A","text":"Araştırmacının araştırmanın yöntemini ya da sonuçlarını kasıtlı olarak saptırması"},{"key":"B","text":"Başka bir kişinin eserini, kaynağını belirtmeden kullanma"},{"key":"C","text":"Veri toplama sürecinde katılımcı onayının alınmaması"},{"key":"D","text":"Araştırma yapmayı bilmeyen bir araştırmacının yanlış sonuçlar üretmesi"},{"key":"E","text":"Araştırma hipotezlerinin analiz edilememesi"}],"answerText":"Araştırma yapmayı bilmeyen bir araştırmacının yanlış sonuçlar üretmesi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırma etiği neden önemlidir?","options":[{"key":"A","text":"Verilerin gizliliğini sağlamak için"},{"key":"B","text":"Yeni hipotezler geliştirmek için"},{"key":"C","text":"Araştırmanın güvenilirliğini ve doğruluğunu artırmak için"},{"key":"D","text":"Araştırma sonuçlarını genelleştirebilmek için"},{"key":"E","text":"Veri analizini kolaylaştırmak için"}],"answerText":"Araştırmanın güvenilirliğini ve doğruluğunu artırmak için","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]}]},"sos":{"name":"Çalışma Sosyolojisi","code":"AIKY1004","file":"Ders _ ÇALIŞMA SOSYOLOJİSİ - eKitap.txt","color":"#0f766e","units":["Sosyoloji ve Sosyolojik Düşünme","Sanayi Devriminin Sosyal Sonuçları","İşin Tarihsel Dönüşümü","Çalışma Sosyolojisinde Teorik Yaklaşımlar","Modern Yaklaşımlar","Teknoloji, İş ve Yabancılaşma","Yeni Teknoloji, Emek Süreci ve İstihdam","İşin Yeniden Tasarımı ve Alternatif İş Organizasyonu","Fordist Kitle Üretiminin Yükselişi ve Çöküşü","Üretimin Yeniden Yapılanması ve Post-Fordizm","Esneklik ve Esnek Çalışma","Üretimin Küreselleşmesi ve Çokuluslu Şirketler","İş-Yaşam Dengesi ve AB’de İş-Yaşam Dengesi Politikaları","Refah Devleti ve Vatandaşlık"],"unitData":[{"title":"Sosyoloji ve Sosyolojik Düşünme","cards":["Bir bilim dalı olarak sosyolojinin gelişiminin büyük ölçüde 200 yıl önce gerçekleşen Fransız Devrimi ve Sanayi","Devrimine bağlıdır. Bu her iki Devrim binlerce yıl süren feodal ekonomik ve sosyal düzenin çökmesiyle sonuçlanmıştır.","Akademik bir disiplin olarak sosyoloji, Avrupa’da birkaç asırda meydana gelen sayısız sosyal ve kültürel dönüşüme bir\ntepki olarak 19. yüzyılda ortaya çıkmıştır. Sosyolojinin ortaya çıkışından birkaç asır önce, Avrupalı toplumları bir arada\ntutan ve onlara istikrar sağlayan dinsel ve geleneksel temelleri zayıflamaya başlamıştı. Reformlar Katolik Kilisesi’nin\notoritesini sarsmış, Protestanlık bireyi ön plana çıkarmıştı. Rönesans ile birlikte din ve eşitsizlik, mülkiyet ve krallık gibi\nkurumlar akılcı ve eleştirel bir incelenmeye tabi tutulmuştu. Tüm bu kurumlar Sanayi Devrimi ve Fransız ihtilaliyle\nsarsılmış ve pek çoğu da çökmüştür.","Sosyoloji, büyük değişim ve dönüşüm sürecin ve etkilerini anlamanın bir yolu\nolarak ortaya çıkmıştır.","Bizler 19. ve 20. Yüzyılın sosyologlarını rahatsız eden, dehşete düşüren ilk kez gördükleri bir toplum ve ekonomi içinde\nyaşıyoruz. Onları ürküten pek çok olguyu ne sorguluyor ne de tartışıyoruz. Ancak ilk sosyologlar sanayi toplumunun ilk\nyıllarını görmekle birlikte sanayi öncesi toplum pek çok kurumunun ve uygulamasının da varlığını sürdürdüğü bir\ndöneme bu değişime tanık olmuşlardı. Dolayısı ile her iki toplumun kurum ve değerlerine vakıftılar. Bu nedenle\nsosyoloji biliminin kurucularının fikirlerine, kavrayışlarına, teorilerine ihtiyaç hissetmekte ve eleştirel yaklaşımlarını\ngüncel bir analiz için başlangıç noktası olarak görmekteyiz. 20.","Yüzyılın son çeyreğinden itibaren kapitalizminde bir dizi yeni dönüşüm ve değişime yaşamaktadır. Gerçekte Sanayi","Devrimi sonrası şartları anımsatan yeni durum söz konusudur. Bu şartlar, üretim süreci, işin niteliği, çalışma yaşamı, iş-\n yaşam dengesi ve cinsiyet ilişikleri açısından bir dönüşüm sürecine işaret etmektedir. Bu dönüşümün anlaşılması ve\nanalizi sosyolojik açıdan önem arz etmektedir. Sosyologlar faklı olguları incelemek için beş temel yaklaşım\nkullanmaktadır. Bunlar demografik, sosyal psikolojik, kolektif veya kurumsal ve sosyolojik yaklaşımdır. Sosyolojinin\nbilimsel bir disiplindir ve sosyolojik bir açıklama ciddi bir araştırma gerektirmektedir.","Sosyolojik analiz toplumsal yapı,\nkalıp ve süreçler araştırılmakta ve sosyal dünyayla ilgili genelleştirme yapmaktadır. [1]Deliller öylesi bir yöntemle toplanır, açıklanır ve yorumlanır ki diğer insanlar bu delileri inceleyebilir ve sunulan\ngenelleştirmeyle ilgili kendi kararlarını verebilirler."],"questions":[{"q":"Toplumsal düzeni derinden etkileyen ve sosyolojik çalışmalara yön veren olgulardan hangi ikili doğru olarak verilmiştir?","options":[{"key":"A","text":"Sanayi Devrimi - Fransız Devrimi"},{"key":"B","text":"Reform - Rönesans"},{"key":"C","text":"Rönesans - Fransız Devrimi"},{"key":"D","text":"Tarım Devrimi - Fransız Devrimi"},{"key":"E","text":"Sanayi Devrimi-Rönesans"}],"answerText":"Sanayi Devrimi - Fransız Devrimi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bilmek, tahmin etmek ve kontrol etmek” diyerek bilimlerinin kullandıkları metotlarının toplumu incelemek amacıyla\nkullanılması ile bu değişimin daha iyi anlaşılacağı ve toplumun iyileştirilmesinin mümkün olacağına inanan sosyolog\nkimdir?","options":[{"key":"A","text":"Emil Durkheim"},{"key":"B","text":"Giddens"},{"key":"C","text":"Weber"},{"key":"D","text":"August Comte"},{"key":"E","text":"Marx"}],"answerText":"August Comte","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Sanayi Devrimi ve Fransız ihtilaliyle sarsılmaya başlayan kurumlar, …………. Katolik Kilisesi’nin merkezi otoritesinin\nsorgulanmasını sağlarken, Protestanlığın yükselişi bireyi ön plana çıkarmıştı. ……………ile birlikte din, eşitsizlik,\nakrabalık, mülkiyet ve krallık gibi kurumlar akılcı ve eleştirel bir incelenmeye tabi tutulmuştu.” Boşluklara hangi ikili\nuygundur?","options":[{"key":"A","text":"Reform - Rönesans"},{"key":"B","text":"Rönesans- Sosyolojik Değişim"},{"key":"C","text":"Reform - Evrim Teorisi"},{"key":"D","text":"Rönesans - Reform"},{"key":"E","text":"Sanayi-Fransız Devrimi"}],"answerText":"Reform - Rönesans","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki bilimlerden hangisi sosyolojinin bağlantılı olduğu bilim dallarından birisi değildir?","options":[{"key":"A","text":"Tarih"},{"key":"B","text":"Antropoloji"},{"key":"C","text":"Hukuk"},{"key":"D","text":"Felsefe"},{"key":"E","text":"Sosyal Psikoloji"}],"answerText":"Felsefe","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerinden hangisi ilk sosyologların özelliklerinden değildir?","options":[{"key":"A","text":"Bilim İnsanları"},{"key":"B","text":"Muhafazakâr Kimseler"},{"key":"C","text":"Devrimci Kişiler"},{"key":"D","text":"Kilise Görevlileri"},{"key":"E","text":"İş Adamları"}],"answerText":"Devrimci Kişiler","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Niçin sosyoloji hala kurucu babalarının fikirlerine muhtaçtır?","options":[{"key":"A","text":"Çok zeki insanlar oldukları için"},{"key":"B","text":"İlk sosyolojik çalışmaları yaptıkları için"},{"key":"C","text":"Fransız Devrimine katıldıkları için"},{"key":"D","text":"Kilisenin baskılarına karı çıktıkları için"},{"key":"E","text":"Sanayi kapitalist toplumun oluşuma alternatif düşüncelerin ışığında bakabildikleri için."}],"answerText":"Sanayi kapitalist toplumun oluşuma alternatif düşüncelerin ışığında bakabildikleri için.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi sosyolojinin sosyal olguları incelemek niçin farklı yaklaşımlar kullanmasının sebebidir?","options":[{"key":"A","text":"Sosyal olguların nedenlerinin farklı olması"},{"key":"B","text":"Farklı sosyologların farklı bakış açılarını tercihe etmeleri"},{"key":"C","text":"Tek bir olgunun çok sayıda farklı bilimsel disiplinin alanına girebilmesi"},{"key":"D","text":"Sosyolojik yaklaşımın yeterince gelişmiş olmaması"},{"key":"E","text":"Çok sayıda farklı bakış açısının bulunması"}],"answerText":"Tek bir olgunun çok sayıda farklı bilimsel disiplinin alanına girebilmesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sosyolojik bir açıklamadır?","options":[{"key":"A","text":"Kız çocuklarının bebekle oynamayı tercih etmesi onların biyolojileri ile ilgilidir."},{"key":"B","text":"İnsanların yoksul olması büyük ölçüde kendi tembelliklerinden kaynaklanmadır."},{"key":"C","text":"Endüstriyel eylemin sebebi sendikanın kışkırtmasıdır"},{"key":"D","text":"Daha çok iradesi zayıf ve zihinsel sorunları olan insanlar intihar eder."},{"key":"E","text":"Fakirlik, sınıflı toplumlarda mevcut olan sosyal ve ekonomik eşitsizliklerden kaynaklanır."}],"answerText":"Fakirlik, sınıflı toplumlarda mevcut olan sosyal ve ekonomik eşitsizliklerden kaynaklanır.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sosyolojinin kurucusu olarak kabul edilen kişi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Karl Marx"},{"key":"B","text":"August Comte"},{"key":"C","text":"Emil Durkheim"},{"key":"D","text":"Max Weber"},{"key":"E","text":"Herbert Spencer"}],"answerText":"August Comte","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sosyoloji biliminin gelişiminde hangi olaylar etkili olmuştur?","options":[{"key":"A","text":"Amerikan Bağımsızlık Savaşı ve Fransız Devrimi"},{"key":"B","text":"Birinci Dünya Savaşı ve İkinci Dünya Savaşı"},{"key":"C","text":"Fransız Devrimi ve Sanayi Devrimi"},{"key":"D","text":"İkinci Dünya Savaşı"},{"key":"E","text":"Rönesans ve Reform"}],"answerText":"Fransız Devrimi ve Sanayi Devrimi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi'nin sosyoloji üzerindeki etkisi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Siyasi sistemleri değiştirmesi"},{"key":"B","text":"Toplumsal yapıyı alt üst etmesi"},{"key":"C","text":"Ekonomik sistemleri dönüştürmesi"},{"key":"D","text":"Kültürel değerleri yok etmesi"},{"key":"E","text":"Dinî inançları değiştirmesi"}],"answerText":"Toplumsal yapıyı alt üst etmesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi sosyolojik analizde kullanılan yaklaşımlardan biridir?","options":[{"key":"A","text":"Psikolojik yaklaşım"},{"key":"B","text":"Biyolojik yaklaşım"},{"key":"C","text":"Felsefi yaklaşım"},{"key":"D","text":"Edebi yaklaşım"},{"key":"E","text":"Demografik yaklaşım"}],"answerText":"Demografik yaklaşım","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Sanayi Devriminin Sosyal Sonuçları","cards":["1780-1830 yıllar arasında gerçekleşen Sanayi Devrimi insanlık tarihinin karşılaştığı en büyük ve en önemli dönüşüm\nsürecidir. Bu dönemde meyanda gelen ekonomik politik ve sosyal dönüşümler öylesine büyüktür devrim dışında bir\nkavramla anlatmak mümkün değdir. Buhar motorunun icadının tetiklediği devrim ilk önce İngiltere'de gerçekleşmiş ve\nkısa zaman içerisinde önce Kıta Avrupa'sına ve daha sonra tüm dünyaya yayılmıştır. Sanayi Devrimi ile birlikte üretim,\nilk defa insan kası ve diğer kaynaklar yerine buhar motor gibi dışsal enerji kaynağı kullanan makinelerde yapılır\nolmuştur.","Bu süreç tekstil sektöründe başlamış ve diğer sektörlere yayılmıştır. Sanayi Devriminin yol açtığı sosyo-\nekonomik dönüşümler sonuçları itibariyle son derece radikaldir ve aileden, kent yaşamına, çalışma hayatından toplumsal\ncinsiyet rollerine kadar birçok alanda değişimlere neden olmuştur.","Sanayi Devrimi ilk başladığı dönemde işçiler açısından son derece olumsuz bir durum yaratmış, altyapısı yetersiz\nkentlerde son derece kötü yaşam koşullarına ve kadın ve çocuklar gibi güçsüz kesimler için sömürücü çalışma şartlarına\nneden olmuştur. Hükümetlerin kanunlarla çalışma şartlarını düzenlemeye başlamaları, işletmeler arasındaki rekabeti\n teknoloji ve verimlilik artışına yönlendirmiş bu durum sanayileşmenin teknolojik gelişimle beraber pekişmesini\nsağlamıştır. Nihayet Sanayi Devrimi işçi sınıfı ve orta sınıf gibi iki yeni sınıfın ortay çıkmasına yol açmıştır."],"questions":[{"q":"Sanayi Devrimi, aşağıdakilerden hangilerinde köklü bir değişime sebep olmamıştır?","options":[{"key":"A","text":"Teknolojide"},{"key":"B","text":"Emek Sürecinde"},{"key":"C","text":"Kültürel İlişkilerde"},{"key":"D","text":"Coğrafi Sınırlarda"},{"key":"E","text":"Çalışma ilişkilerinde"}],"answerText":"Kültürel İlişkilerde","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi öncesi Avrupa'da genellikle tarımsal üretime ek olarak, her aile evini üretim mekânı olarak\nkullanmaktaydı. Bu sistemin adı nedir?","options":[{"key":"A","text":"Putting-Out"},{"key":"B","text":"Check - Off"},{"key":"C","text":"Atölye"},{"key":"D","text":"Büro"},{"key":"E","text":"Fabrika"}],"answerText":"Putting-Out","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi toplumunda hangi kavram, ekonomide resmi bir istihdam olarak yeniden tanımlanmaktadır?","options":[{"key":"A","text":"Ücretsiz ev işleri"},{"key":"B","text":"Gönüllü yapılan işler"},{"key":"C","text":"Aile veya arkadaş için yapılan işler"},{"key":"D","text":"Ücretli iş"},{"key":"E","text":"Zorla çalıştırma"}],"answerText":"Ücretli iş","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sanayileşme ile birlikte kentlere doğru olan göç akımları dolayısıyla kentlerde meydana gelen\nolumsuzluklardan biri değildir?","options":[{"key":"A","text":"Kanalizasyon sorunları ve alt yapı yetersizliği"},{"key":"B","text":"Çarpık kentleşme"},{"key":"C","text":"Merkez - Çevre bağlarının güçlenmesi"},{"key":"D","text":"Kolera, tifo ve tüberküloz gibi hastalıkların yaygınlaşması"},{"key":"E","text":"Erken yaşta ölmek"}],"answerText":"Merkez - Çevre bağlarının güçlenmesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Protestan Ahlakına göre çalışmanın tanrı tarafından emir olarak verildiğine inanan toplum hangisidir?","options":[{"key":"A","text":"Sanayi Toplumu"},{"key":"B","text":"Tarım Toplumu"},{"key":"C","text":"Post-Modern Toplum"},{"key":"D","text":"Avcı-Toplayıcı Toplum"},{"key":"E","text":"Antik toplum"}],"answerText":"Tarım Toplumu","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşverenlerin, işçilerin sadakatini artırmak ve direnişlerini azaltmak için kendilerini baba ve işçileri de çocukları olarak\nvarsayan politika uygulamalarına ne ad verilir?","options":[{"key":"A","text":"Merkantilizm"},{"key":"B","text":"Modernizm"},{"key":"C","text":"Paternalizm"},{"key":"D","text":"Liberalizm"},{"key":"E","text":"Evanjelizm"}],"answerText":"Paternalizm","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sanayi Devrimi öncesi aile bakımından doğru değildir?","options":[{"key":"A","text":"Aile ekonomik bir birimdir."},{"key":"B","text":"Aile büyük baskındır"},{"key":"C","text":"Aile çekirdek baskındır"},{"key":"D","text":"Aile evde üretim yapmaktadır"},{"key":"E","text":"Aile sosyal bir birimdir."}],"answerText":"Aile çekirdek baskındır","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi modern kentlerle ilgili olarak söylenemez?","options":[{"key":"A","text":"Modern kentler aşırı stres ve gerilim yaratmaktadır"},{"key":"B","text":"Modern kentler insanların hayata tutunmalarını teşvik etmektedir"},{"key":"C","text":"Modern kentler herkes için yeni fırsatlar sunmaktadır"},{"key":"D","text":"Modern kentler insanoğlunun tüm potansiyelini açığa çıkarmaktadır"},{"key":"E","text":"Modern kentler insanların hayata karşı vurdumduymaz ve sorumsuz davranmaya zorlamaktadır."}],"answerText":"Modern kentler insanların hayata tutunmalarını teşvik etmektedir","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sanayi Devrimi sonrası iş ritmi ile ilgili söylenemez?","options":[{"key":"A","text":"Mevsimlik ve Düzensizdir."},{"key":"B","text":"Makine hızına bağlıdır"},{"key":"C","text":"Düzenlidir"},{"key":"D","text":"24 saat devem eder"},{"key":"E","text":"Tabiat olaylarına bağlıdır."}],"answerText":"Mevsimlik ve Düzensizdir.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi aşağıdaki ülkelerin hangisinde gerçekleşmiştir?","options":[{"key":"A","text":"Fransa"},{"key":"B","text":"Almanya"},{"key":"C","text":"İtalya"},{"key":"D","text":"İngiltere"},{"key":"E","text":"Amerika"}],"answerText":"İngiltere","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi'nin tarım toplumlarına etkisi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Tarım toplumlarını endüstriyel topluma dönüştürmüştür"},{"key":"B","text":"Hiçbir etkisi olmamıştır"},{"key":"C","text":"Tarım üretimini artırmıştır"},{"key":"D","text":"Tarım toplumlarının daha fazla bağımsızlık kazanmasını sağlamıştır"},{"key":"E","text":"Tarım teknolojilerini geliştirmiştir"}],"answerText":"Tarım toplumlarını endüstriyel topluma dönüştürmüştür","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi'nin işçi sınıfı üzerindeki etkisi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"İşsizlik oranının düşmesi"},{"key":"B","text":"Tarım işçilerinin çoğalması"},{"key":"C","text":"Köylü sınıfının güçlenmesi"},{"key":"D","text":"Aristokrasinin zayıflaması"},{"key":"E","text":"Yeni işçi sınıfının ortaya çıkması"}],"answerText":"Yeni işçi sınıfının ortaya çıkması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşin Tarihsel Dönüşümü","cards":["Bu bölümde insanoğlunun var olduğu günden beri işin ve iş bölümünün farklı toplum yapılarda nasıl dönüştüğünü\ngördük. İnsanoğlu yerleşik hayat geçmeden önce binlerce yıl avcı ve toplayıcılıkla hayatını sürdüren göçebe topluluklar\nhalinde yaşadığını ve bunun insan türünün toplumsal yaşamının nerdeyse % 97’sini oluşturduğunu gördük. Bu\ntoplumlarda iş bölümü son derce basittir, yaşa ve cinsiyete göre belirlenmektedir. İnsanoğlu 10.000 önce toprağı ekip\nbiçmeye başlayarak yerleşik hayat geçmiş ve bunun sonucu olarak nüfus artmış ve ekonomik faaliyetler de çeşitlenmiştir.","Tarım imparatorlukların yükselişi, işin dönüşümü açısından önemli bir dönüm noktasıdır. Güçlü toplumların daha zayıf\ntoplumları tahakküm altıdan alarak onların üretimlerine el koydukları gibi insanlarını da köleleştirmiştir. Bu dönemde\nçevrecindeki kırsal bölgelerin sağaldığı gıda ile varlığını sürdüren büyük şehirlerin ortaya çıkması, yerleşik sınıflara\nhizmet veren zanaatkâr işletmelerin ve loncaların doğumuna yol açmıştır. Feodal toplum yükselişi ile birlikte artık değer\nelde etmenin şekli değişmiştir. Ancak tarımsal artık değerin elde edilme biçimi değişmişti.","Feodal toplumda ise toprak\nsahipleri hem köylülerin mahsullerinden pay olarak hem de topraklarında çalışmanın bir karşılığı artı değere el\nkoymaktaydı.","Ortaçağda çalışmanın değişimine bakıldığında en önemli gelişme yeni bir üretici sınıf olarak serbest çalışan\nzanaatkârların ortaya çıkmasıdır. Zanaatkârlar fırıncılık, dericilik ve dokumacılık gibi meslekleri icra etmekteydi.","Zanaatkâr ustalar karşılıklı çıkarlarını korumak için lonca ismi verilen meslek kuruluşlarında örgütlenmekteydi. Ticari\nkapitalizm, Protestan Reformları olarak isimlendirilen yeni dinsel inancaların gelişimine yol açmıştır. Bu bakış açısı, bir\nkişinin mesleğini başarılı bir şeklîde icra etmesine ruhani bir nitelik atfetmekteydi. İngiltere’de 18. ve 19. Yüzyıllar\nboyunca feodal ve Merkantilist dönemin üretim sistemleri 1780’lerde Sanayi Devrimi ile sonuçlanan radikal bir\ndönüşüm geçirmiştir. 19. Yüzyılda fabrika sisteminin gelişmesiyle birlikte toplumsal yapıda önemli değişiklikler\nmeydana gelmiştir.","Tarımda, el zanaatlarında ve ev işletmelerinde çalışan çok sayıda bağımsız üretici işçileşerek\nkapitalistlerin kontrolü altına girerken üretim, hızla büyük ölçekte ve merkezi yapılarda örgütlenmeye başlamış ve iş\nevden fabrikaya kaymıştı. Sanayi Devrimi ile birlikte üretimin ölçeği de artmaya başlamıştı. 19.yüzyılın ikinci yarısından\nitibaren tekstil ve çelik fabrikaları, ayakkabı fabrikaları çatıları altında yüzlerce işçi çalıştırmaya başlamıştı. Sanayi","Devrimi geçmiş ile tam bir kırılma ifade etmemekle birlikte, teknoloji, iş organizasyonu ve ekonomik ilişkilerde kayda\ndeğer değişikliklere neden olmuştur."],"questions":[{"q":"Avcı ve toplayıcı toplumlarda nasıl bir işbölümü mevcuttur?","options":[{"key":"A","text":"Hayvan avlama alanında uzmanlığa dayalı bir iş bölümü"},{"key":"B","text":"Son derce karmaşık bir işbölümü"},{"key":"C","text":"Bitki toplayıcılığına dayalı basit bir işbölümü"},{"key":"D","text":"Yaşa ve cinsiyete dayalı bir iş bölümü"},{"key":"E","text":"İş birliğine bağlı"}],"answerText":"Yaşa ve cinsiyete dayalı bir iş bölümü","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bahçıvan toplumlar niçin yerleşik hayata geçmek zorundaydı?","options":[{"key":"A","text":"Daha çok hayvan avlamak için"},{"key":"B","text":"Daha sağlıklı barınak sahibi olmak için"},{"key":"C","text":"Hasatlarını korumak için"},{"key":"D","text":"Düşmanlarından korunmak için"},{"key":"E","text":"Yönetici sınıfa vergi vermek için"}],"answerText":"Hasatlarını korumak için","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kentlerde zanaatkâr işletmeler hangi dönemde ortaya çıkmıştır?","options":[{"key":"A","text":"Avcı ve Toplayıcı toplumlarda"},{"key":"B","text":"Bahçeci toplularda"},{"key":"C","text":"Tarım imparatorluklarında"},{"key":"D","text":"Roma imparatorluğunda"},{"key":"E","text":"Sanayi Devriminden sonra"}],"answerText":"Roma imparatorluğunda","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Erken tarım toplumları açısından aşağıdakilerden hangis doğrudur?","options":[{"key":"A","text":"Erkek savaşçıların baskın olduğu bir tabakalaşma mevcut değildir."},{"key":"B","text":"Karasaban ve çapa kullanımıyla yapılan tarımsal üretim baskındır."},{"key":"C","text":"İnsanlar hayatlarını idame ettiremek için ticari amaçlı üretim yaparlar."},{"key":"D","text":"Politika, din ve savaş konusunda uzmanlaşmış erkelerin oluşturduğu bir aristokrasi mevuttur"},{"key":"E","text":"Tarım ve hayvancılık yeterince gelişmiştir."}],"answerText":"Politika, din ve savaş konusunda uzmanlaşmış erkelerin oluşturduğu bir aristokrasi mevuttur","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Roma imparatorluğunda loncalar için aşağıdakilerden hangisi söylenemez?","options":[{"key":"A","text":"Köle emeği istihdam edildiği için teknolojik gelişme mümkün olmamıştır"},{"key":"B","text":"Kölelilerin işte yaratıcı olması için ne fırsat ne de motivasyon vardır,"},{"key":"C","text":"Loncalar üyeleri için dinsel ve sosyal hizmetler sunmuştur"},{"key":"D","text":"Loncalardan ayrılmak yasaklanmıştır"},{"key":"E","text":"Çocuğun babasının mesleğini sürdürmesi şart değildir."}],"answerText":"Çocuğun babasının mesleğini sürdürmesi şart değildir.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Feodal toplumla ilgili olarak aşağıdakilerden hangisi yanlıştır?","options":[{"key":"A","text":"İnsanların büyük bir çoğunluğu geleneksel bir şekilde toprağa bağlanmıştır."},{"key":"B","text":"Köylüler ürünlerin bir kısmı vergi olarak vermek zorundadır."},{"key":"C","text":"Köylülerin angarya yükümlülüğü yoktur."},{"key":"D","text":"Üç farklı ürünün nöbetleşe ekilmesi tarımda verimliliği arıtmıştır."},{"key":"E","text":"Tarım dışı üretim loncalarda örgütlenmiştir."}],"answerText":"Köylülerin angarya yükümlülüğü yoktur.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ticari kapitalizmin yükselişine yol açan faktörlerden değildir?","options":[{"key":"A","text":"Eve iş verme sisteminin gelişmesi."},{"key":"B","text":"Yenidünyanın keşfi ve Asya yeni ticaret yollarının bulunması."},{"key":"C","text":"Tüccarların tarım ürünleri ve imalat malları üretiminde kentler arası ticarette tekel konumu elde etmeleri."},{"key":"D","text":"Vasıflı işleri işyeri olmayan kalfalar yapılması."},{"key":"E","text":"Zanaatkâr İşletmelerin tüccarlar işbirliği yapması."}],"answerText":"Zanaatkâr İşletmelerin tüccarlar işbirliği yapması.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Protestan ahlakı aşağıdakilerden hangisini içermez?","options":[{"key":"A","text":"Başarısız bireylere sempati ile bakılır."},{"key":"B","text":"Çalışmaya ruhani bir nitelik atfedilmesi."},{"key":"C","text":"Tasarruf etme teşvik edilmektedir."},{"key":"D","text":"Mütevazı ve sofi yaşam özendirilmektedir."},{"key":"E","text":"Zaman bir çeşit paradır."}],"answerText":"Başarısız bireylere sempati ile bakılır.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Modern toplumun yükselişi hangi olaya bağlı değildir?","options":[{"key":"A","text":"Köylülerin topraklarından sürülmesi."},{"key":"B","text":"Çıraklık müessesini tesis edilmesi."},{"key":"C","text":"Aylaklar ve yoksulluk kanunun çıkarılması."},{"key":"D","text":"Eve iş verme sisteminin sonun gelmesi."},{"key":"E","text":"İşin evden fabrikaya kayması."}],"answerText":"Çıraklık müessesini tesis edilmesi.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi modern fabrika sistemin özellikleri arasında bulunmaz?","options":[{"key":"A","text":"Yüksek vasılı işgücünün istihdam edilmesi"},{"key":"B","text":"İç taşeronluk sistemi"},{"key":"C","text":"İşçilerin daha yakından kontrol edilebilesi ve denetlenebilmesi"},{"key":"D","text":"Görevlerin işçilere tahsisi ve üretimin kesin olarak ölçülebilmesi"},{"key":"E","text":"Ceza sistemi, denetim, işbaşı saati ve teşvik sistemi gibi yönetim pratiklerinin kolayca uygulanabilmesi"}],"answerText":"Yüksek vasılı işgücünün istihdam edilmesi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Feodal toplumda işin organizasyonu nasıl yapılırdı?","options":[{"key":"A","text":"Loncalar"},{"key":"B","text":"Serbest piyasa"},{"key":"C","text":"Devlet"},{"key":"D","text":"Özel şirketler"},{"key":"E","text":"Sendikalar"}],"answerText":"Loncalar","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Zanaatkâr işletmeler hangi toplum dönemine aittir?","options":[{"key":"A","text":"Sanayi toplumu"},{"key":"B","text":"Post-modern toplum"},{"key":"C","text":"Bilgi toplumu"},{"key":"D","text":"Feodal toplum"},{"key":"E","text":"Avcı-toplayıcı toplum"}],"answerText":"Feodal toplum","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Çalışma Sosyolojisinde Teorik Yaklaşımlar","cards":["Bu bölümde Endüstri Devrimi, 10 bin yıl önce gerçekleştiği varsayılan Tarım Devriminde sonra insanlık tarihin\nkaydettiği ve insan toplumlarının geçirdiği en önemli dönüşüm olarak değerlendirilmektedir. Bu dönüşüm sosyoloji\nbiliminin doğumundan itibaren en önemli konularından birini oluşturmaktadır. Farklı yazarlar, Endüstri Devrimi ve\nmodern kapitalizmin yükselişini farklı değişkenlere bağlı olarak açıklamaktadır.","Auguste Comte, moden toplumun yükselişini sosyal evrim ile entelektüel evrimin eseridir. Comte pozitif bilimlerin\nsosayl düzeni anlamak ve ilerletmek için kullanılması gerektiğini söylemektedir. Herbert Spencer endüstri toplumu ile\nsavaşçı toplumları karşılaştır. Sosyal evrim düşüncesine inanan Spencer, toplumu “ayrı parçaların karşılıklı ve işlevsel\nbir bağımlılık kazandığı karmaşık ve farklılaşmış yapılara doğru evrim geçiren bir şey” olarak tanımlamış ve toplumu\nkarakterize eden en önemli yapısallık olarak da “parçalar” ile “bütün” arasındaki uzlaşıya vurgu yapmıştır.","Marx, toplumların ardıl ve doğrusal olarak gelişen birkaç evrimsel aşamadan geçtiklerini ve bu evrimde mülkiyet\nilişkilerinin ve kalıplarının son derece önemli bir rol oynadığını iddia etmektedir. Üretim tarzında meydana gelen\ndeğişmeler üretim ilişkilerinde dönüşümlere yol açmakta ve çalışanların üretim teknolojisine eklemlenme biçimini\nbelirlemektedir.","Weber, “Protestan Ahlakı “ isimli meşhur eserinde kapitalizmin yükselişinin temelinde Batı Avrupa’da 16 Yüzyıl sonrası,","Protestanlığın yayılmasının harekete geçirdiği zihinsel bir dönüşümün yattığını savunmaktadır. Weber, kapitalist ruhun\ngelişmesini büyük ölçüde rasyonalizmin gelişmesine bağlamaktadır. Kapitalizmin ruhu, insanların para kazanma ve\nservet edinme düşüncesi ile fazlaca meşgul oldukları ve mal biriktirmenin yaşamın nihai hedefi haline geldiği bir\ndurumun ifade etmektedir.","Durkheim, Batı’nın 19. yüzyıldaki gelişim seyri sırasında görülen toplumsal mücadeleler ile çatışmalar, yeni ve sınıflı bir\ntoplum biçiminin (yani sınai kapitalizmin) ortaya çıkışına işaret etmediğini aksine bunların, mekanik dayanışmadan\norganik dayanışmaya geçişin yarattığı gerilimler olduğunu ileri sürmektedir. Ona göre, yaşanan sınıf çatışmaları,\ngelişmekte olan sanayi düzenindeki organik dayanışmacı yapının tam olarak kavranamadığını göstermektedir."],"questions":[{"q":"Sosyal evrimin, entelektüel evrim ile birlikte beşeri düşüncenin gelişiminin ve sürekli rasyonelleşmesinin bir ürünü\nolduğunu söyleyen yazar aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Herbert Spencer"},{"key":"B","text":"Auguste Comte"},{"key":"C","text":"Karl Marks"},{"key":"D","text":"Max Weber"},{"key":"E","text":"Emil Durkheim"}],"answerText":"Auguste Comte","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Auguste Comte’un düşüncelerinden biri değildir?","options":[{"key":"A","text":"Teolojik evrede doğaüstü güçlere referansla tüm doğal ve sosyal olgular açıklanmaktadır."},{"key":"B","text":"Sanayi toplumu bütün insanlığın toplumu haline gelecektir."},{"key":"C","text":"Sosyal evrim söz konusu değildir."},{"key":"D","text":"Mükemmel topluma sosyolojinin “adam gibi uygulanması” sonucu ulaşılacaktır"},{"key":"E","text":"Pozitivist evre tarihsel olarak büyük ölçüde modern periyoda tesadüf etmektedir."}],"answerText":"Sosyal evrim söz konusu değildir.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Herbert Spencer’in görüşlerini yansıtmamaktadır?","options":[{"key":"A","text":"Toplumsal seleksiyon (ayıklanma) kuramına inanmaktadır"},{"key":"B","text":"Toplumların gerçek olan bütün güçleri sanayide toplanmaktadır"},{"key":"C","text":"Endüstri Devriminin özü ve temeli ilerlemedir."},{"key":"D","text":"Biyolojik evrim yasaları topluma da uygulanabilir"},{"key":"E","text":"Toplum, tarihsel açıdan karmaşık sanayi yapılara doğru evrim geçiren dinamik bir sistemdir."}],"answerText":"Toplumların gerçek olan bütün güçleri sanayide toplanmaktadır","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Herbert Spencer’la ilgili olarak doğru değildir?","options":[{"key":"A","text":"En uygun olanların hayatta kalması” ilkesinin uygulanması en mükemmel toplumu ortaya çıkartacaktır"},{"key":"B","text":"Sencer’in düşünceleri, radikal bireyciliğin de temelini oluştur."},{"key":"C","text":"Spencer, toplumsal yapılar ile kurumların evrimsel süreç içindeki gelişimlerini inceler."},{"key":"D","text":"Bireylere kendi çıkarlarının peşinden koşturmalarına izin verilirse, toplum yeterince düzenlenmiş olacaktır"},{"key":"E","text":"Toplumsal hayatta bireyler özel çıkarlarına ulaşmaya çalışırlarken etkili olan “görünmez bir düzen” mevcut değildir."}],"answerText":"Toplumsal hayatta bireyler özel çıkarlarına ulaşmaya çalışırlarken etkili olan “görünmez bir düzen” mevcut değildir.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Marx’ın düşüncelerini yansıtmamaktadır?","options":[{"key":"A","text":"Toplumsal yapıyı belirleyen asli unsur ekonomik boyut değildir"},{"key":"B","text":"Üretim ilişkileri sosyal tabakalaşmanın ve sosyal sınıfların temelini oluşturur"},{"key":"C","text":"Toplumlar evrimsel aşamalardan geçmektedir ve bu evrimde mülkiyet ilişkileri ve kalıpları büyük ölçüde\nbelirleyicidir."},{"key":"D","text":"Antik toplum, sınıfsal ayrışmanın ve özel mülkiyetin gözlemlendiği ilk toplumdur"},{"key":"E","text":"Kapitalizmle birlikte üretim araçlarının mülkiyetine sahip olan burjuvazi egemen sınıf haline gelirken serfler de mülksüzleştirilerek ücretli işçilere dönüşmüştür."}],"answerText":"Toplumsal yapıyı belirleyen asli unsur ekonomik boyut değildir","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Marx’ın düşüncelerini yansıtmamaktadır?","options":[{"key":"A","text":"Marx, modern kapitalizmin yükselişini ekonomik faktörler ve sınıf çatışmasıyla açıklamaktadır"},{"key":"B","text":"Modern kapitalizmin kökenlerini feodal dönemde bulmak mümkündür."},{"key":"C","text":"Sanayi Devrimiyle birlikte kapitalizmin yükselişi aristokrasinin egemenliğine son vermiştir."},{"key":"D","text":"Bürokratik yapılarda, görev ve sorumluluklar gibi, yetkiler de hiyerarşik olarak sıralanır"},{"key":"E","text":"Bu yeni üretim tarzı, eski feodal üretim ilişkilerinin değişmesini gerekli kılmaktaydı."}],"answerText":"Bürokratik yapılarda, görev ve sorumluluklar gibi, yetkiler de hiyerarşik olarak sıralanır","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi Marx’a göre sosyal gelişmenin geleceğini ifade etmektedir?","options":[{"key":"A","text":"Komünist aşamadan sonra sosyal evrim son bulacaktır"},{"key":"B","text":"Komünist toplumlarda sosyal evrim devam edecektir"},{"key":"C","text":"Kapitalizm yıkıldığında sosyal evrim son bulacaktır"},{"key":"D","text":"Sosyal evrim önlenebilir bir süreçtir."},{"key":"E","text":"Sosyal evrim sonsuza kadar devam edecektir."}],"answerText":"Komünist aşamadan sonra sosyal evrim son bulacaktır","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Weber ’in görüşü değildir?","options":[{"key":"A","text":"Modern toplumda sınıf çatışması oldukça önemlidir."},{"key":"B","text":"Modern kapitalizm ile sanayi toplumunun gelişmesi, rasyonelleşme yönündeki genel eğilimlerin sonucudur."},{"key":"C","text":"Sanayi toplumu ile modern kapitalizmin belirleyici karakteristiği, bürokratik rasyonalizmdir"},{"key":"D","text":"Sanayi toplumlarına özgü rasyonalizm, en karakteristik biçimiyle büyük ölçekli organizasyonlar/örgütlerin"},{"key":"E","text":"yayılmasıdır. Köylülerin kitleler halinde tarım topraklarından sürülmesi ihtiyaç duyulan serbest emeğin oluşmasına zemin hazırlamıştır."}],"answerText":"Modern toplumda sınıf çatışması oldukça önemlidir.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Weber ‘in düşüncelerini yansıtmaktadır?","options":[{"key":"A","text":"Kapitalizm toplumun burjuvazi ve proletarya şeklinde kutuplaşmasına yol açmıştır"},{"key":"B","text":"Evrensel doğal yasalar düşüncesinin mantıksal uzantısı, olarak denetimsiz bir laissez-faire anlayışıdır."},{"key":"C","text":"Rasyonellik, ‘modern çağın ruhu’ arayışı içinde, sanayi toplumlarını geçmişteki toplumlardan ayıran en temel\ndinamiktir."},{"key":"D","text":"Toplum, rasyonel bir bencillikten ziyade ortak bir ahlaki düzene dayanması gerekmektedir."},{"key":"E","text":"Batı liberal demokrasisinin insanlığın nihai yönetim biçimi olacaktır."}],"answerText":"Evrensel doğal yasalar düşüncesinin mantıksal uzantısı, olarak denetimsiz bir laissez-faire anlayışıdır.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Durkehim’in düşüncelerini yansıtmamaktadır?","options":[{"key":"A","text":"Sanayi toplumunda baş gösteren “hastalık”, belirli bir sınıftan kaynaklanan bir durum değil, tersine “bütün toplumu\nkapsayan genel bir durum” olarak ortaya çıkmıştır."},{"key":"B","text":"Protestanlık, rasyonelleştirici edimler üzerine fayda temelli bir dünya tasavvurudur"},{"key":"C","text":"Endüstri toplumunun yaşadığı kriz, “toplumun ahlaki yapısını yeniden şekillendirme” sorunudur."},{"key":"D","text":"Sınıf çatışması, geleneksel toplumdan modern topluma geçişten kaynaklanan yapısal bir olgudur."},{"key":"E","text":"İşbölümü, toplumsal dayanışmanın temelinde yaşanan değişimlerle bağlantılıdır."}],"answerText":"Protestanlık, rasyonelleştirici edimler üzerine fayda temelli bir dünya tasavvurudur","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Evrimci Teoriler’in kurucusu kimdir?","options":[{"key":"A","text":"Max Weber"},{"key":"B","text":"Karl Marx"},{"key":"C","text":"Emile Durkheim"},{"key":"D","text":"August Comte"},{"key":"E","text":"Herbert Spencer"}],"answerText":"August Comte","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Karl Marx’a göre aşağıdakilerden hangisi kapitalizmin temel özelliklerinden biridir?","options":[{"key":"A","text":"Sosyal dayanışma"},{"key":"B","text":"Bürokrasi"},{"key":"C","text":"Sınıf çatışması"},{"key":"D","text":"Mekanik dayanışma"},{"key":"E","text":"Anomi Doğru cevap: b) Sınıf çatışması"}],"answerText":"Sınıf çatışması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Modern Yaklaşımlar","cards":["Yakınsama teorisi, 1950 ve 1960’larda çağdaş Marxizmi eleştiren bir grup liberal sosyal bilimci tarafından\ngeliştirilmiştir. Bu yazarlar kapitalist toplumun uzun dönem dinamiklerini ve eğilimlerini açıklayabilecek Marxist teori\nkarakterinde, fakat kapsam ve açıklama gücü açısından Marxist teorinin ötesine giden bir teori geliştirmek ve sanayi\ntoplumlarını bu teori temelinde incelemek amacında olduğunu gördük. Bu yaklaşım da klasik yaklaşımlar gibi evrimci\nbir niteliktedir. Bu yaklaşımın temel iddiası, milletler arasındaki temel farklılıkların, bunların ekonomik gelişmenin farklı\naşamalarında bulunmalarından kaynaklandığı şeklindedir.","Teknolojik ve ekonomik açıdan gelişmiş olan tüm toplumlar, (kapitalist veya komünist) benzer olan yapılar, süreçler ve\nözellikler sergilemekte ve bütün dünyada kültürel ve politik yaşamın ortak kalıpları oluşmaktadır. Yazarlar bu gelişmeyi\nbüyük ölçüde sanayileşme teknolojisinin gereksinimi ve sonucuna atfetmektedirler. Teknoloji determinist olmakla\nsuçlanan bu yaklaşımın yoğun bir şeklide eleştirilmektedir","Öte yandan, yine evrimci bir perspektifle bakan bir grup yazarın 1950’li yıllardan itibaren gelişmiş kapitalist toplumların\nekonomik ve sosyal yapılarında meydana gelen üretim eksenli değişim ve dönüşümü “sanayi-ötesi toplum” olarak\ntanımladıklarını gördük. Bu çerçevede Bell, Gorz ve Toffler isimli üç farklı yazar inceledik. Bu yazarlardan Bell ve","Toffler son derece iyimserdir. Gorz oldukça kötümser bir yaklaşıma sahiptir. [1]1970’li yıllarda meydana gelen olayların ilki, gelişmekte olan ülkelerde ayırıcı özelliği komünist deneyimden belirgin\nbir biçimde farklı olan sosyalizmin yeni bir biçiminin yükselmesidir. Üçüncü dünya ülkelerinde sosyalist sanayileşme\nileri sanayi toplumlarının pek çok değerine başkaldırmaktaydı. İkincisi, İran da yaşanan İslam Devrimi, Batı dünyasının\ndeğerlerine ve arzularına karşı diğer bir farklı trendi oluşturmaktaydı.","İslami kaynaklara dönüş ve İslam devlet,\nsanayileşmenin alternatif bir şeklini oluşturmakta ve sanayi medeniyetin etosuna karşı olan dinsel hareketlerin çağrısını\nön plana çıkarmaktadır. Üçüncüsü Sovyetler birliğinde ve komünist blok da yeni gelişmeleri mevcuttu. Kısa bir\nliberalleşme periyodundan sonra Sovyetler Birliğinde Brejnev neo-Stalinist politikalar uygulamaya başladı ve diğer\nkomünist ülkelerde baskılar arttı. Dördüncüsü, ileri düzeyde politik huzursuzluklara eşlik eden ekonomik kriz, Batı\nülkelerin 1950 yıllarda sahip oldukları özgüveni kaybetmelerine yol açan bir güvensizlik duygusu gelişmiştir.","Bu yıllarda\ndemokratik kurumların yönettiği ve genel konsesusa dayalı refah toplumu ile eş anlamlı olan sanayi toplumu kavramı bir\nartık pek açık görülmemektedir."],"questions":[{"q":"Aşağıdakilerden hangisi yakınsama teorisinin varsayımı değildir?","options":[{"key":"A","text":"Uzun dönem sosyal değişmenin temel dinamiği hâkim teknolojik ve ekonomik yapının evrensel gereksinimleridir."},{"key":"B","text":"Modern dünyada sosyal düzenler farklı ve çeşitlidir ve farklı sanayileşme kalıpları mevcuttur"},{"key":"C","text":"Politik karakterine bakılmaksızın sanayileşmeye başlayan toplumların tamamı çoğulcu sanayileşmeye ya da liberal\ndemokratik toplum düzenine ulaşacaktır."},{"key":"D","text":"Nüfusun önemli bir kesiminin kentlerde yaşaması nedeniyle sanayi toplumları zorunlu olarak kentsel toplumlardır."},{"key":"E","text":"Sanayi toplumunun oluşumu için demir, kara, deniz ve hava yollarıyla birlikte medya ve elektronik iletişim\naltyapılarının gelişmesi gerekmez."}],"answerText":"Sanayi toplumunun oluşumu için demir, kara, deniz ve hava yollarıyla birlikte medya ve elektronik iletişim altyapılarının","answerKey":null,"source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Bell’e göre sanayi ötesi toplumun bir özelliğidir?","options":[{"key":"A","text":"Mavi yakalı sanayi işçilerin sayısının ve öneminin artması"},{"key":"B","text":"İmalat sektörünün ekonomik açıdan öneminin artması"},{"key":"C","text":"Sendikaların öneminin artması"},{"key":"D","text":"Beyaz yakalı işçilerin sayısının ve öneminin artması"},{"key":"E","text":"Hizmet Sektörünün ön plana çıkması"}],"answerText":"Beyaz yakalı işçilerin sayısının ve öneminin artması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Bell a göre sanayi-ötesi toplumu geçişte meydana gelen değişimlerden değildir?","options":[{"key":"A","text":"Sanayi-ötesi toplumun dinamik gücü bilgidir."},{"key":"B","text":"Mal üreten bir ekonomiden hizmet üreten bir ekonomiye geçilmektedir."},{"key":"C","text":"Mesleki yapı değişmektedir"},{"key":"D","text":"İşin niteliği değişmektedir."},{"key":"E","text":"Bilim adamı ve mühendislerin önemi azalmaktadır."}],"answerText":"Bilim adamı ve mühendislerin önemi azalmaktadır.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Gorz’a göre sanayi toplumlarını maruz kaldığı krizle ilişikli değildir?","options":[{"key":"A","text":"Sosyal maliyetlerin yükselmesi ve üretimin sürdürülemez hale gelmesi"},{"key":"B","text":"Endüstriyelizme” dayalı sosyoekonomik gelişmenin artık yapısal ve fiziksel sınırlarına yaklaşmasıdır."},{"key":"C","text":"Sosyalizmin çökmesi ve neo-libral politikaların yükselişi"},{"key":"D","text":"Mevcut teknoloji düzeyde tabiat üzerinde kontrol kurulmasının ve sürdürülmesinin giderek imkânsızlaşması"},{"key":"E","text":"Piyasaların doyması, kar marjlarının azalması."}],"answerText":"Sosyalizmin çökmesi ve neo-libral politikaların yükselişi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Gorz’un sanayi ötesi toplum yaklaşımına ilişkin kullandığı kavramdır?","options":[{"key":"A","text":"Piyasasızlaşma"},{"key":"B","text":"Teknokrasi"},{"key":"C","text":"Yeni sanayi işçisi"},{"key":"D","text":"İşçi olmayan sınıfsız yeni proletarya"},{"key":"E","text":"Esnek üretim"}],"answerText":"İşçi olmayan sınıfsız yeni proletarya","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Gorz nasıl bir sanayi ötesi toplum önermektedir?","options":[{"key":"A","text":"Teknokratik bir toplum"},{"key":"B","text":"Sanayi ötesi kapitalist bir toplum"},{"key":"C","text":"Programlanmış bir toplum"},{"key":"D","text":"Özgürleştirilmiş bir toplum"},{"key":"E","text":"Sosyalist bir toplum"}],"answerText":"Özgürleştirilmiş bir toplum","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Alvin Tofler’e göre sanayi toplumun çökmesi ne ifade etmektedir?","options":[{"key":"A","text":"Süper sanayi toplumunun oluşması"},{"key":"B","text":"Sanayi ötesi bir dönüşümün başlaması"},{"key":"C","text":"Kapitalizm çökmesi"},{"key":"D","text":"Yeni bir medeniyetinin dalgasının"},{"key":"E","text":"Bilgi işçisinin yükselişi"}],"answerText":"Yeni bir medeniyetinin dalgasının","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Toffler’e göre sanayi toplumlarının krizinin nedeni değildir?","options":[{"key":"A","text":"Doğal çevrenin tahribatı"},{"key":"B","text":"Enerji ve hammadde kaynakların tükenmeye yüz tutması"},{"key":"C","text":"Yeni enerji kaynaklarının bulunması"},{"key":"D","text":"Kentsel yaşamın yarattığı stres ve gerilim,"},{"key":"E","text":"Uluslararası mali sistemin krizi ve ulus devletin çökme eğilimine girmesi"}],"answerText":"Yeni enerji kaynaklarının bulunması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Toffler’e göre üçüncü dalga medeniyetinin özelliği değildir?","options":[{"key":"A","text":"Esneklik, çeşitlilik, ölçeğin küçülmesi ve ademi merkezileşme"},{"key":"B","text":"Elektronik evin gelişmesi önemli bir yer işgal etmektedir"},{"key":"C","text":"Emperyalizm sonrası dünyada yarı-özerk ekonomilerin doğması"},{"key":"D","text":"Piyasalaşma sürecinin sona ermesi,"},{"key":"E","text":"Kentleşme sürecinin ve kentsel yaşamın ivme kazanması"}],"answerText":"Kentleşme sürecinin ve kentsel yaşamın ivme kazanması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerinden hangisi sanayi ötesi topluma yönelik bir eleştiri değildir?","options":[{"key":"A","text":"Bilgi teknolojisine gereğinden fazla bir güç atfetmektedirler"},{"key":"B","text":"Küreselleşme sürecini dikkate almamaktadırlar"},{"key":"C","text":"Sanayi toplumunun özelliklerini yeniymiş gibi sunmaktadır"},{"key":"D","text":"Klasik sosyologların sanayi toplumuna özgü varsayımlarını tekrarlamaktadırlar"},{"key":"E","text":"Sanayi ötesi toplumun geçmişle bir kırılma oluşturmamaktadır."}],"answerText":"Sanayi ötesi toplumun geçmişle bir kırılma oluşturmamaktadır.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Ötesi Toplum Teorisi'ni geliştiren bilim insanı kimdir?","options":[{"key":"A","text":"Karl Marx"},{"key":"B","text":"Max Weber"},{"key":"C","text":"Emile Durkheim\nHerbert Spencer\nDoğru cevap: a"},{"key":"E","text":"Daniel Bell"}],"answerText":"Daniel Bell","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yakınsama Teorisi'ne göre, hangi süreç sanayi toplumlarını birbirine benzer hale getirir?","options":[{"key":"A","text":"Endüstrileşme"},{"key":"B","text":"Modernleşme"},{"key":"C","text":"Küreselleşme"},{"key":"D","text":"Kapitalizm"},{"key":"E","text":"Sosyalleşme Doğru cevap: a"}],"answerText":"Endüstrileşme","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Teknoloji, İş ve Yabancılaşma","cards":["Teknoloji iş ve çalışma arasında yakın bir ilişki mevcuttur. Teknoloji iş bölümünü, işin niteliğini, içeriğini ve ritmini\netkilemektedir. Kitle üretiminin yükselişi ve Taylorizmle birlikte iş basit, rutin, monoton ve sıkıcı ve gayr-ı insani bir\nniteliğe bürünmüştür. İşin vasıfsızlaştırılması, rutin, monoton ve gayr-ı insani hale gelmesi en açık ifadesini\nyabancılaşma teorilerinde bulmaktadır. Yabancılaşmaya yönelik çok sayıda farklı teorik yaklaşım mevcuttur. Bu\nyaklaşımlardan biri Marx'ın yabancılaşma yaklaşımıdır. Marx yabancılaşmayı daha çok kapitalist üretim tarzına ve bu\nsistemde teknolojinin kullanım biçimine bağlamaktadır.","Blauner ise yabancılaşmanın teknolojiden kaynakladığını ileri\nsürmektedir. Yabancılaşma düzeyini üretim sürecinde çalışanlara verilen karar-alma ve inisiyatif kullanma gibi\nimkânlarının belirlediği söylemektedir. Teknolojinin işçilerin tutum ve davranışlarını belirlediği düşüncesine karşı çıkan","Goldhorpe ve Lookwood ise yabancılaşma yerine işe yönelim kavramını kullanmaktadır. İşe yönelimin teknoloji gibi\nnesnel faktörlerden çok işçilerin iş dışında şekillenen kendi öznel hissiyatlarının ve beklentilerinin belirlediğini ileri\nsürmektedirler."],"questions":[{"q":"Aşağıdakilerden hangisi yabancılaşmanın bir sebebi değildir?","options":[{"key":"A","text":"Emek sürecinin artan bir şeklide otomasyona maruz kalması."},{"key":"B","text":"İşçinin makinenin bir parçası haline getirilmesi."},{"key":"C","text":"İşin parçalanması, standartlaşması ve basitleştirilmesi."},{"key":"D","text":"İnsan emeğinin değersizleştirilmesi ve vasıfsızlaştırılması."},{"key":"E","text":"Ücretlerin büyük ölçüde düşmesi"}],"answerText":"Ücretlerin büyük ölçüde düşmesi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Marx’a göre yabancılaşmanın orijinini oluşturmaktadır?","options":[{"key":"A","text":"Modern fabrika sisteminin gelişmesi"},{"key":"B","text":"Sosyalist Sistemin kurulması"},{"key":"C","text":"Eve iş verme sistemin ortaya çıkması"},{"key":"D","text":"Takasa dayalı bir ekonominin ortaya çıkması"},{"key":"E","text":"Lonca sisteminin çökmesi"}],"answerText":"Takasa dayalı bir ekonominin ortaya çıkması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Marks’a göre yabancılaşma boyutunu oluşturmaz?","options":[{"key":"A","text":"İnsanın kendi ürününe yabancılaşması"},{"key":"B","text":"İnsanın kendi üretken faaliyetinde yabancılaşması"},{"key":"C","text":"İnsanın bir tür olarak yabancılaşması"},{"key":"D","text":"İnsanın diğer insanlara yabancılaşması"},{"key":"E","text":"İnsanın kendi kendine yabancılaşması"}],"answerText":"İnsanın kendi kendine yabancılaşması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Marx’göre yabancılaşman sonunu getirecektir?","options":[{"key":"A","text":"Kapitalizmin çökmesi"},{"key":"B","text":"Zanaat sistemine dönülmesi"},{"key":"C","text":"İşin lağvedilmesi"},{"key":"D","text":"Komünist topluma geçilmesi"},{"key":"E","text":"İşçi sınıfının güç kazanması"}],"answerText":"Komünist topluma geçilmesi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Blauner’e göre yabancılaşmanın boyutları arasında değildir?","options":[{"key":"A","text":"Bir şahısın şahsi olmayan bir sistem tarafından kontrol ve maniple edilen bir nesne olması"},{"key":"B","text":"İşin küçük alt-görevlere ayırması nedeniyle işçilerin genel amaçlarını görememesi"},{"key":"C","text":"Bir işyerinde yeteneklerini, potansiyellerini ve kişiliğini ifade etmek için çok çalışmak"},{"key":"D","text":"Mesleki bir temelde bir toplumla ve bir firma ile kimliklenememesi"},{"key":"E","text":"İşçinin bir sosyal cemiyete veya topluluğa ait hissetmemesi"}],"answerText":"Bir işyerinde yeteneklerini, potansiyellerini ve kişiliğini ifade etmek için çok çalışmak","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Blauner’in yabancılaşmanın sektörel incelemesinde en yüksek yabancılaşma hangi sektörde görülmüştür?","options":[{"key":"A","text":"Tekstil"},{"key":"B","text":"Petro-Kimya"},{"key":"C","text":"Matbaa"},{"key":"D","text":"Otomotiv"},{"key":"E","text":"Madencilik"}],"answerText":"Otomotiv","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Blauner’e göre yabancılaşanın nedeni değildir?","options":[{"key":"A","text":"Kapitalist toplumun üretim ilişikleri"},{"key":"B","text":"İş bölümünün artması nedeniyle işçilerin genel amaçlarını görememeleri ve nihai ürüne katkılarının ne olduğunu\nanlayamamalarıdır."},{"key":"C","text":"Bir meslek örgütü ile veya bir firma ile kimliklenememeleridir."},{"key":"D","text":"Bireyin kendi iş ortamı üzerinde kontrol sahibi olamaması nedeniyle çalıştığı işletmenin amaçlarını benimsememesi"},{"key":"E","text":"Üretim araçlarının mülkiyeti"}],"answerText":"Kapitalist toplumun üretim ilişikleri","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işe yönelim yaklaşımının varsayımını ifade etmektedir?","options":[{"key":"A","text":"İşçilerin işe yabancılaşmalarının sebebi fabrika teknolojisidir."},{"key":"B","text":"İşçilerin işe araçsal yönelimi onların yabancılaşmaya bir tepkisidir."},{"key":"C","text":"İşçiler işyerine arkadaş edinmek için de gitmektedir"},{"key":"D","text":"İşçilerin sendikaya eylem yapmak için katılmaları araçsal yönelimdir."},{"key":"E","text":"İşçilerin iş tutum ve davranışlar, iş dışındaki sosyal şartlar ve kişisel deneyimleri tarafından belirlenir"}],"answerText":"İşçilerin iş tutum ve davranışlar, iş dışındaki sosyal şartlar ve kişisel deneyimleri tarafından belirlenir","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işe yönelim yaklaşımı için söylenemez?","options":[{"key":"A","text":"İşe yönelim yaklaşımını, yabancılaşma yaklaşımlarına bir alternatif olarak geliştirilmiştir."},{"key":"B","text":"Yabancılaşma yaklaşımı, işçilerin işlerinden beklentilerini ve işlerine yönelik tutumlarını açıklamakta yetersiz\nkalmaktadır."},{"key":"C","text":"İşçilerin bazı tutum ve davranışlarının öznel faktörlere ve sosyal şartlarla açıklanabilir."},{"key":"D","text":"İşi, iş organizasyonu ve işçilerin işyerindeki tutum ve davranışlarını belirleyen en önemli değişken teknolojidir."},{"key":"E","text":"İşe yönelim yaklaşımı sosyal deterministtir."}],"answerText":"İşi, iş organizasyonu ve işçilerin işyerindeki tutum ve davranışlarını belirleyen en önemli değişken teknolojidir.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Galile’nin İngiltere’de ve Fransa’da iki ayrı petrol rafinerisinde araştırma yaptığı araştırmanın\nsonucunu yansıtmamaktadır?","options":[{"key":"A","text":"İki rafineride çalışan işçilerin tutum ve davranışlarının farklı olmasını teknolojik faktörlere atfen açıklamaktadır."},{"key":"B","text":"Fransız rafineri işçilerinin İngilizlerden daha fazla militan olması teknoloji ile değil, endüstrideki güç yapısı, sendika\nve yönetim stratejileriyle ilişiklidir."},{"key":"C","text":"Fransız işçileri yönetimin kendilerini sömürdüğünü düşünürken İngiliz işçileri yönetimi teknik uzman olarak\ngörmektedir."},{"key":"D","text":"Fransız yönetiminin daha otoriter yaklaşımına ve toplu pazarlığın Fransa’da daha merkezi olmasına bağlamaktadır."},{"key":"E","text":"Sosyal değişkenlerin Fransa ve İngiltere rafineri işçilerinin davranış farklılığını açıklamada daha mühim olduğunu ileri sürmektedir."}],"answerText":"İki rafineride çalışan işçilerin tutum ve davranışlarının farklı olmasını teknolojik faktörlere atfen açıklamaktadır.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Teknolojinin hangi yönü işçilerin yabancılaşmasına katkıda bulunur?","options":[{"key":"A","text":"İş yükünü azaltması"},{"key":"B","text":"İşin monotonlaşması"},{"key":"C","text":"İşçilerin üretkenliğini artırması"},{"key":"D","text":"Çalışma koşullarının iyileşmesi"},{"key":"E","text":"İşçilerin işini kolaylaştırması"}],"answerText":"İşin monotonlaşması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yabancılaşmayı açıklayan teori aşağıdakilerden hangisidir?","options":[{"key":"A","text":"İşlevselci teori"},{"key":"B","text":"Rasyonel seçim teorisi"},{"key":"C","text":"Sosyal etkileşimcilik"},{"key":"D","text":"Marksist teori"},{"key":"E","text":"Evrimsel teori"}],"answerText":"Marksist teori","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Yeni Teknoloji, Emek Süreci ve İstihdam","cards":["Bu bölümde bilgi teknolojilerinin emek süreci iş ve istihdam üzerindeki etkilerini değerlendirdik. Bilgi teknolojisi,\nmikro-işlemci, yeni bir teknolojidir. Kökenleri savaş sonrası döneme dayanmakla birlikte asıl gelişimini, 1970’lerde\nsilikonun elektrik devrelerinde kullanılmasından sonra göstermiştir. 1970’den günümüze kadar olan süre içinde bilgi\nteknolojisinin hem kapasitesi ve boyutu muazzam değişime uğramış, boyutu binlerce kat küçülürken işleme kapasitesi de\nmilyonlarca kat artmıştır. Bilgi teknolojisi gerek üretimde ve gerekse ürünlerde yoğun bir şekilde kullanılmaktadır.","Öyle\nki uçaktan, füzeye, çaydanlıktan, otomobilde yakıt kontrolüne, saatten, mutfak robotuna ve makine-takımlara kadar son\nderce geniş kullanım alanına sahiptir.","Bilgi teknolojisinin üretim sürecinde kullanılması istihdamı ve işçilerin işlerini, sahip oldukları vasıflarını ve meslekleri\nderinden etkilemektedir. Zira bilgi teknolojisinin kullanımı nedeniyle özellikle imalat sektöründe ve bürolarda\nmilyonlarca iş ve istihdam yok olurken sayısız meslek ve vasıf da ortadan kalkmıştır. Ancak bunun yanında bilgi\nteknolojisinin in bizzat kendi milyonlarca yeni iş ve istihdamla birlikte çok sayıda vasıf ve meslek yaratmıştır. Nitekim\nbugün internetle ve cep telefonlarıyla alakalı mesleklerin büyük bir kısma 20 yıl önce yoktu.","Dolayısı ile bilgi\nteknolojilerini iş ve istihdama etkileri açısından değerlendirirken iş ve vasıf yok etmek kadar yaratma etkisinin de\ndikkate alınması gerekmektedir. Nitekim imalat sektöründe robot kullanımının son yıllarda süratle artırttığı dikkat\nçekmekte ve veriler 10.000 işçi başına robot kullanımı 69’a ulaştığını göstermektedir. Bu ilk bakışta, 20 milyona yakın\nişçinin işini kaybettiği anlamına gelmektedir. Ancak bu kadar çok robot üretimi yapılırken robot üreten ve robot\nendüstrisine girdi sağlayan endüstrilerde yeni iş ve istihdamın yaratıldığı göz ardı edilmemelidir.","Bu nedenle bilgi\nteknolojisinin iş, istihdam ve vasıf üzerinde standart bir etkisinden söz etme mümkün değildir. Aksine bu süreç son\nderece karmaşıktır. Ayrıca bilgi teknolojisi son derece esnektir."],"questions":[{"q":"“1970’li yıllardan sonra bilgi ve iletişim teknolojilerinde (BIT) meydan gelen değişimi “……………..” olarak\ngörülmektedir.” Boşluğu dolduracak ifade hangi şıkta doğru olarak verilmiştir.","options":[{"key":"A","text":"Etkileşim Devrimi”"},{"key":"B","text":"Teknoloji Devrimi”"},{"key":"C","text":"İkinci Sanayi Devrimi”"},{"key":"D","text":"Hizmet Sektörü Devrimi”"},{"key":"E","text":"Süper Sanayi Devrim"}],"answerText":"İkinci Sanayi Devrimi”","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yirminci yüzyılın son çeyreğinden itibaren robot ve bilgisayar endüstrileri âdete patlama yaşamasına hizmet eden sebep\nhangi şıkta doğru olarak verilmiştir?","options":[{"key":"A","text":"Mikro-işlemcinin yaygın bir şekilde üretim sürecinde kullanılması"},{"key":"B","text":"Bilgi teknolojilerinin gelişmesi"},{"key":"C","text":"Silikonun yaygın olarak kullanılması"},{"key":"D","text":"Micro elektroniğin üretimde kullanılması"},{"key":"E","text":"Vakum tüplerin kullanılması."}],"answerText":"Mikro-işlemcinin yaygın bir şekilde üretim sürecinde kullanılması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilgi teknolojileri temel de neden işsizliğe sebep olmaktadır?","options":[{"key":"A","text":"Emekten tasarruf sağladığı için."},{"key":"B","text":"Zamandan tasarruf sağlaması."},{"key":"C","text":"Mekândan tasarruf sağlamaması."},{"key":"D","text":"Sermayeden tasarruf sağlaması."},{"key":"E","text":"Maliyetinin ucuz olması."}],"answerText":"Emekten tasarruf sağladığı için.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Yeni teknolojilerin işsizliğe sebep olmasının aksine; insanları arzu edilmeyen rutin monoton, kirli ve pis işlerden\nözgürleştirmekte ve daha yüksek yaşam standardı sunduğunu ileri sürmektedir.” Bu düşünceyi savunan kimdir?","options":[{"key":"A","text":"H. Ford"},{"key":"B","text":"Adam Smith"},{"key":"C","text":"E. Durkheim"},{"key":"D","text":"F. Duchin"},{"key":"E","text":"F. Taylor"}],"answerText":"F. Duchin","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İyimser yaklaşıma göre bilgi teknolojisi vasıf düzeyini nasıl etkilemektedir?","options":[{"key":"A","text":"Vasıf düzeyini artırmaktadır."},{"key":"B","text":"Vasıf düzeyini azaltmaktadır."},{"key":"C","text":"Vasıf düzeyini Etki etmemektedir."},{"key":"D","text":"Vasıf düzeyini çeşitlendirmektedir"},{"key":"E","text":"Vasıfları yok etmektedir."}],"answerText":"Vasıf düzeyini artırmaktadır.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden mikro-elektronik teknolojisinin tarihsel gelişimi açısından hangisi yanlıştır?","options":[{"key":"A","text":"Mikro-elektronik endüstrisi İkinci Dünya Savaşından sonra transistor icadıyla gelişmeye başlamıştır."},{"key":"B","text":"Transistor, yarı-iletken madde olan silikonu elektrik devreleri için kullanan ilk araçtır."},{"key":"C","text":"Başlangıcından itibaren mikro-elektronik endüstrisi teknolojisini minyatürleştirmek zorundaydı."},{"key":"D","text":"Mikro-elektronik 1950 ve 1960'larda buzdolabı, televizyon vs. gibi elektrikli ev aletlerinde kullanıldı"},{"key":"E","text":"Mikro-işlemcinin icat edilmesiyle mikro-elektroniğin gelişimi açısından önemli değildir."}],"answerText":"Mikro-işlemcinin icat edilmesiyle mikro-elektroniğin gelişimi açısından önemli değildir.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilgi teknolojisi ile ilgili olarak aşağıdakilerden hangisi yanlıştır?","options":[{"key":"A","text":"Bilgi teknolojisi insanların yapmak istemediği rutin monoton, kirli ve pis işleri yok etmektedir."},{"key":"B","text":"Bilgi teknolojisinin yarattığı potansiyel olanaklar yol açtığı sorunlardan daha fazladır."},{"key":"C","text":"Bilgi teknolojisi kısmen işsizlik sorunun kaynağıdır."},{"key":"D","text":"Bilgi teknoloji ne tarafsız ne de önlenemez, aksine teknoloji işçilerle yapılan pazarlıkta işverenin elini güçlendiren\nbir baskı aracıdır."},{"key":"E","text":"Bilgi teknolojisi işçilerinin vasıflarını artırmakta ve motivasyonlarını yükseltmektedir."}],"answerText":"Bilgi teknolojisi işçilerinin vasıflarını artırmakta ve motivasyonlarını yükseltmektedir.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bilgi teknolojisinin istihdam üzerindeki olumuz etkisiyle ilgili olarak yanlıştır?","options":[{"key":"A","text":"Bilgi teknolojisi destekli makine teçhizat ve robotların üretim sürecinde kullanılmasıyla net bir iş kaybına yol\naçmıştır."},{"key":"B","text":"İş-güvencesizliği artmıştır."},{"key":"C","text":"Büro işçileri, özellikle daktilo ve stenografi kullananlar en fazla etkilenen gruptur."},{"key":"D","text":"Robotlar da imalat sektöründe pek çok işçiyi gereksiz hale getirmiştir."},{"key":"E","text":"Makine operatörleri, takım üretenler ve kalıpçılar ve metal işçileri bilgisayar destekli makine teçhizattan\netkilenmemiştir."}],"answerText":"Makine operatörleri, takım üretenler ve kalıpçılar ve metal işçileri bilgisayar destekli makine teçhizattan etkilenmemiştir.","answerKey":null,"source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Robotların üretim sürecinde kullanılması ile ilgili olarak aşağıdakilerden hangisi doğrudur?","options":[{"key":"A","text":"Robotlar işçilerle rekabet etmektedir."},{"key":"B","text":"Robotlar üretim sürecinde her zaman işçilerin yerini almaktadır."},{"key":"C","text":"Robotlar üretim sürecinde sadece kirli, pis ve tehlikeli işleri yapmak için kullanılmaktadır."},{"key":"D","text":"Robotların maliyeti işçilik maliyetinden az olması durumunda işletmeler robot kullanmayı tercih etmektedir."},{"key":"E","text":"İşletmeler genellikle robot kullanmak yerine üretimi emeğin ucuz ve bol olduğu ülkelere taşımaktadır."}],"answerText":"Robotların maliyeti işçilik maliyetinden az olması durumunda işletmeler robot kullanmayı tercih etmektedir.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yeni teknoloji ve esnek çalışma ilişkisi nasıldır?","options":[{"key":"A","text":"Esnek çalışma saatlerini zorunlu kılar"},{"key":"B","text":"Geleneksel çalışma saatlerini korur"},{"key":"C","text":"Esnek çalışma imkânı sağlar"},{"key":"D","text":"Çalışan memnuniyetini azaltır"},{"key":"E","text":"Sadece ofis çalışanlarını etkiler"}],"answerText":"Esnek çalışma imkânı sağlar","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Mikro-elektronik gelişmeler aşağıdaki alanlardan hangisinde etkili olmuştur?","options":[{"key":"A","text":"Pazarlama stratejilerinde"},{"key":"B","text":"Lojistik ve dağıtımda"},{"key":"C","text":"İnsan kaynaklarında"},{"key":"D","text":"Üretim süreçlerinde"},{"key":"E","text":"Yeni iş alanları oluşturmada"}],"answerText":"Üretim süreçlerinde","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bilgi teknolojilerinin iş ve istihdam üzerindeki etkisi nasıldır?","options":[{"key":"A","text":"İşsizlik oranını sabit tutar"},{"key":"B","text":"Yeni iş alanları oluşturur"},{"key":"C","text":"İş güvencesini artırır"},{"key":"D","text":"Çalışan memnuniyetini azaltır"},{"key":"E","text":"İş güvenliğini artırır"}],"answerText":"Yeni iş alanları oluşturur","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşin Yeniden Tasarımı ve Alternatif İş Organizasyonu","cards":["Fordist Taylorist üretim modeline özgü vasıfsız iş ve yakın kontrol, sadece işçilerin iş tatmini sağlanması imkan\nvermeyen bir iş değil aynı zamanda mali açından etkin olmayan son derece katı bir iş organizasyonu ortaya çıkarmıştır.","Emek sürecinde işçilerin vasıfsızlaştırma ve tatminsizliğe reaksiyonu işyerinde sabotaj, direniş, işi yavaşlatma, grev gibi\nendüstriyel eylemler olmuştur. Bu durum işletme yöneticileri ve bilim adamları ve danışmalık kuruluşlarını Fordist-","Taylorist üretim modelinde reform öngören Çalışma Gününün Kalitesi ve işin insanileştirmesi gibi programlar\nbaşlatmaya sevk etmiştir. Bu uygulamalar işin yeniden tasarımına yönelik teorik yaklaşımlardan çıkarılmıştır. Bu\nuygulamalar iş rotasyonu, iş genişletme ve iş zenginleştirmedir. Bunlar haricinde özerk takım çalışması da mevcuttur.","Bu, işin niteliğinde köklü bir değişime yol açmamaktır. İş tasarımından sağlanan kazançlar işçiler açısından sadece iş\ntatmini ile sınırlıdır. Bunu işçiler takdir edilebilir. Ne var ki bu alanda kazanımlar sınırlıdır. Zira iş tasarımı reformu\nişveren tarafında uygulanmakta ve bunun araçları, kârlılık ve üretim ilişkilerinde sosyal ilişkilerin yeniden üretimi gibi\nkriterler ile tanımlanmakta ve sınırlandırılmaktadır.\nUygulama Soruları\n1. İş zenginleştirme ne demektir? Bir sektör üzerinden uygulanma biçimi ve sonuçlarını tartışınız.\n 2. Özek takım çalışması ne demektir? Fordist-Taylorist üretim modeline nasıl değişiklik getirmektedir? Tartışınız."],"questions":[{"q":"Aşağıdakilerden hangisi işin yeniden tasarlanmasının amaçlarından bir değildir?","options":[{"key":"A","text":"İşyerinde çatışmayı azaltmak"},{"key":"B","text":"İşin insani olmasını sağlamak"},{"key":"C","text":"İş gücünün işyerine bağlılığını arttırmak"},{"key":"D","text":"Verimliliği artırmak"},{"key":"E","text":"Sendikayı tasfiye etmek"}],"answerText":"Sendikayı tasfiye etmek","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi iş rotasyonun amacıdır?","options":[{"key":"A","text":"İşgücünün vasfını arttırmak"},{"key":"B","text":"İşgücüne inisiyatif kullanma imkânı vermek"},{"key":"C","text":"İşgücüne bakım görevi vermek"},{"key":"D","text":"İş çeşitliliğini arttırarak işçilere farklı iş yapma imkânı vermek"},{"key":"E","text":"Emek sürecine esneklik kazandırmak"}],"answerText":"İşgücüne bakım görevi vermek","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iş genişletmenin bir hedefi değildir?","options":[{"key":"A","text":"Daha tam ve anlamlı iş yaratmaktadır"},{"key":"B","text":"İş döngüsünü (işlem süresi) arttırmak"},{"key":"C","text":"İhtisaslaşma derecesini azaltmak"},{"key":"D","text":"İşletmenin rekabet gücünü arttırmak"},{"key":"E","text":"İşçilerin otonomi ve sorumluluklarını arttırmak"}],"answerText":"İşletmenin rekabet gücünü arttırmak","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iş zenginleştirme için söylenemez?","options":[{"key":"A","text":"Dikey düzlemde değişim getirmektedir"},{"key":"B","text":"Bireysel gelişim açısından işin motivasyon içeriğini arttırmaktadır"},{"key":"C","text":"İşçilerin işle ilgili olarak karar-alma konusunda sorumluluğunu yok etmektedir."},{"key":"D","text":"İşbölümünün yarattığı sorunları çözmek için geliştirmemiştir"},{"key":"E","text":"İşçiye tam bir görev ve işin ritmi kontrol imkânı vermektedir"}],"answerText":"İşçilerin işle ilgili olarak karar-alma konusunda sorumluluğunu yok etmektedir.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi takım çalışmasıyla ilgili doğru değildir?","options":[{"key":"A","text":"Takım çalışmasının kökenlerini Taylorizm ’de bulmak mümkündür."},{"key":"B","text":"Takım çalışmasının kökenleri Hawthorne Deneylerine dayanır."},{"key":"C","text":"Takım çalışması Sosyo-Teknik Sistem yaklaşımı tarafından geliştirilmiştir."},{"key":"D","text":"Volvo’nun ve Saab’ın uygulamaları başarılı olmuştur"},{"key":"E","text":"Takım çalışması popülerliğini sürdürmektedir"}],"answerText":"Takım çalışmasının kökenlerini Taylorizm ’de bulmak mümkündür.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi takım çalışması için gerekli değildir?","options":[{"key":"A","text":"Takım üyeleri iş tahsisini ve işin nasıl yapılacağını kendileri belirler"},{"key":"B","text":"Takımın eğitimi ve yeni üyelerinin seçilmesinde takım üyelerinin katılımı vardır"},{"key":"C","text":"Takım bünyesinde, birlikte tek bir ürün veya hizmet oluşturmaktadır"},{"key":"D","text":"Takım liderini daima işletme yönetimi seçer"},{"key":"E","text":"Takım bünyesinde görevler birbirine bağımlı değildir"}],"answerText":"Takım bünyesinde görevler birbirine bağımlı değildir","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Herzberg’in İki-Faktör iş tasarım yaklaşımı için söylenemez?","options":[{"key":"A","text":"1950’li yılların sonu ve 1960’lı yılların başlarında geliştirmiştir"},{"key":"B","text":"İş tatmini ve tatminsizliğiyle ilişkili iki farklı boyutun varlığı tespit etmiştir"},{"key":"C","text":"Bu teori, tüm diğer iş tasarımı teorilerden daha fazla ampirik olarak test edilmiştir"},{"key":"D","text":"Bu teori, uygulama açısından tüm diğer iş tasarımı teorilerden daha fazla etkileyicidir"},{"key":"E","text":"Bu yaklaşımdan iş genişletme düşüncesi ortaya çıkmıştır"}],"answerText":"Bu yaklaşımdan iş genişletme düşüncesi ortaya çıkmıştır","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi İki faktör Yaklaşımı için doğru değildir?","options":[{"key":"A","text":"Bu yaklaşım, insanların işte ne ölçüde tatmin oldukları belirleyen iş faktörlerini tespit etmektedir"},{"key":"B","text":"Tanınma, başarı, takdir edilme, yapılan işin niteliği, yetki ve sorumluluk sahibi olma motivasyon faktörleridir"},{"key":"C","text":"İşletme politikası ve yönetimi, çalışma koşulları, ücret düzeyi, organizasyonda alt-üst arasındaki ilişkiler, hijyen\nfaktörleridir"},{"key":"D","text":"Araştırma sonuçları yayınlandıkça iki faktör teorisinin temel önerileri, saygınlığını artırmıştır"},{"key":"E","text":"Bir iş için motive edici faktörlerin bizzat işin bünyesinde tasarlamış olma derecesi işin motivasyon düzeyini belirlemektedir"}],"answerText":"Araştırma sonuçları yayınlandıkça iki faktör teorisinin temel önerileri, saygınlığını artırmıştır","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iş karakteristikleri yaklaşımının bir varsayımı değildir?","options":[{"key":"A","text":"İş motivasyonu ve iş doyumunu birlikte açıklamaktadır"},{"key":"B","text":"Çalışanın iş motivasyonu ve doyumuna etki eden dışsal faktörlerle açıklamaktadır."},{"key":"C","text":"İş genişletme ve iş zenginleştirme programlarının çalışanlar üzerindeki etkisini açıklamak üzere geliştirilmiştir"},{"key":"D","text":"Teorinin esasını kritik psikolojik durumlar oluşturmaktadır"},{"key":"E","text":"Güçlü kişisel gelişim ve ilerleme ihtiyacı olan insanlar, özellikle bu 5 temel iş karakteristiği etrafında motive edilecektir"}],"answerText":"Çalışanın iş motivasyonu ve doyumuna etki eden dışsal faktörlerle açıklamaktadır.","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sosyo teknik sistem yaklaşımının varsayımı değildir?","options":[{"key":"A","text":"Bu yaklaşım Tavistock Enstitüsü tarafından geliştirilmiştir."},{"key":"B","text":"Bu yaklaşıma göre işin detaylarına bölünmesi azaltılarak işçilerin tam bir iş yapması sağlanabilir."},{"key":"C","text":"Üretimde özerk takım çalışmasını tavsiye etmektedir"},{"key":"D","text":"Bu yaklaşım iş yeniden tasarlanırken hem sosyal hem de teknik ihtiyacın karışlanması gerektiğini savunmaktadır."},{"key":"E","text":"Beşeri ihtiyaçlar ve sosyoteknik tasarımın tatmini ve verimlilikte iyileşme ve çatışma davranışı arasında çok güçlü\nilişki olduğunu ileri sürmektedir."}],"answerText":"Beşeri ihtiyaçlar ve sosyoteknik tasarımın tatmini ve verimlilikte iyileşme ve çatışma davranışı arasında çok güçlü ilişki","answerKey":null,"source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşin yeniden tasarımı hangi ana amaç doğrultusunda yapılır?","options":[{"key":"A","text":"İşin verimliliğini artırmak"},{"key":"B","text":"Üretim maliyetlerini artırmak"},{"key":"C","text":"Çalışan memnuniyetini azaltmak"},{"key":"D","text":"İş yükünü artırmak"},{"key":"E","text":"İş güvenliğini azaltmak"}],"answerText":"İşin verimliliğini artırmak","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İş genişletme stratejisi hangi sonucu doğurabilir?","options":[{"key":"A","text":"İşçilerin iş tatmini azalır"},{"key":"B","text":"Üretim yavaşlar"},{"key":"C","text":"İş güvenliği riskleri artar"},{"key":"D","text":"İşçilere yeni beceriler kazandırır"},{"key":"E","text":"İş yükü artar"}],"answerText":"Üretim yavaşlar","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Fordist Kitle Üretiminin Yükselişi ve Çöküşü","cards":["Fordist-Taylorist üretim modelin çökmesi ve ardından Neo-Liberal iktisadi politikaların uygulamaya konulması ile\nekonomik ve endüstriyel yeniden yapılanma süreci başlamıştır. Bir yandan çalışma yaşamında önemli değişiklikler\nmeydan gelirken Fordizm’e alternatif üretim modelleri de önerilmeye başlamıştır. Bu süreçte birçok ideolojik ve yönetsel\naçıdan esneklik anahtar kavram haline gelirken çok sayıda farklı teorik yaklaşım geliştirilmiş ve Almanya, İsveç, İtalya\nve Japonya’nın uygulamalarının Fordizm'e alternatif Post-Fordist bir üretim modeli olduğu farklı yazarlarca ileri\nsürülmüştür.","Bu alanda en meşhur iki yaklaşım, “Neo-Fordizm ve Post-Fordisim”dir. Neo Fordizm, Fordist-Taylorist\nüretim sürecinde bilgi teknolojisi ve takım çalışması gibi yeni uygulamalar ile kısmi bir dönüşüme denk gelmektedir. Öte\nyandan Post-Fordizm ise Fordist Taylorist üretimin mantığında köklü değişikler öngörmektedir. Bu çerçevede üç\nyaklaşım ön plana çıkmaktadır. Bunlar esnek firma, esnek uzmanlaşma ve yalın üretim yaklaşımlarıdır. Bu\nyaklaşımlardan ilki, esnek firma İngiltere’de geliştirilen esnek Firma modeli daha çok talepte dalgalanmalar işgücünün\nsayısını maliyetsiz bir şeklide ayarlama stratejisidir.","Esnek uzmanlaşma yaklaşımı Post-fordizmin İtalya uygulamasını,\ndiğeri de yalın üretim olarak isimlendirdiği Japon uygulamasını Fordizm'e alternatif olarak görmektedir. Her üç\nyaklaşımın da ciddi eksikleri mevcut olup yoğun bir şeklide eleştirilmektedir. [1]Zanaat ayrımı uygulamasına göre vasıflı işçiler sadece kendi zanaat (meslek) alanlarına giren işleri yaparlar, başka\nalana giren işleri başka zanaattan işçiler yaparlar. Örneğin bir makinenin üzeride mekanik bir arıza olduğu zaman tek bir\nişçi değil bir kaç farklı zanaattan işçi bu arızayı gidermeye çalışır. Bu maliyet ve zaman açısından son derece verimsiz bir\nuygulamadır.","Oysa yeni uygulamada sadece bir işçi bir kaç farklı mesleki alan düşen işleri yapmaktadır. [2]Örneğin Toplam Kalite Kontrol (TKK), Deming, W., Juran, J. ve Feingenbaum, V. gibi İkinci dünya savaşı\nsonrası yazarlar tarafından geliştirilmiştir. [3]Kaplinsky ve Hoffman (1989) “Sistemo-Faktür”, Kenney ve Florida (1987) Fujitizm, Jürgens ve diğ. (1985)","Toyotizm, Boyer, (1989) “Esnek Kitle Üretimi” ve Womak ve diğ. (1990) \"Yalın üretim\" kavramlarını\nkullanmaktadırlar\n[4]Japonların Japonya dışında tamamen kendi sahip oldukları veya yerli şirketlerle ortak olarak kurdukları fabrikalardır.\n[5]Dohse Diğerleri (1985) Japon çalışma yöntemlerinin negatif yönlerini Japon işgücünun ikinci dünya savaşı sonrası\nmaruz kaldığı yenilgi ve basitçe \"sınırlandırılmamış Fordism\" (uninhibited Fordism) kavramalarına dayandırmaları,\nUygulama Soruları\n1. Neo-Fordizm niçin başarısız olmuştur? Tartışınız.\n2. Japon Üretim Modeli niçin Fordizme alternatiftir? Tartışınız"],"questions":[{"q":"Son yıllarda ün kazanan ve İngiltere'de Atkinson'un 1985’te geliştirdiği modelin adı nedir?","options":[{"key":"A","text":"Katı üretim"},{"key":"B","text":"Standart firma"},{"key":"C","text":"Esnek Firma"},{"key":"D","text":"Yarı -Esnek üretim"},{"key":"E","text":"Esnek üretim"}],"answerText":"Esnek Firma","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esnek uzmanlaşma, genellikle endüstrisiyle özdeşleştirilmektedir?","options":[{"key":"A","text":"Alman endüstri"},{"key":"B","text":"İngiliz endüstrisi"},{"key":"C","text":"Çin endüstrisi"},{"key":"D","text":"Japon endüstrisi"},{"key":"E","text":"Amerikan endüstrisi"}],"answerText":"Alman endüstri","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esnek uzmanlaşma temel ilkelerinden birisi değildir?","options":[{"key":"A","text":"Tam-Zamanında-Üretim (TZÜ),"},{"key":"B","text":"Toplam Kalite özelliği"},{"key":"C","text":"Kalite Çemberlerinin olması"},{"key":"D","text":"Japon üretim tekniklerine benzer olması"},{"key":"E","text":"Fason üretim tekniğinin benimsenmesi"}],"answerText":"Fason üretim tekniğinin benimsenmesi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esnek taylorizm olarak ta tanımlanan Uluslararası piyasaların düzenlenmesiyle yeniden şekillendirilen üretim sürecine\nne ad verilmektedir?","options":[{"key":"A","text":"Neo-fordist üretim"},{"key":"B","text":"Fordist üretim"},{"key":"C","text":"Post fordist üretim"},{"key":"D","text":"Fordist- Taylorist üretim"},{"key":"E","text":"Esnek üretim"}],"answerText":"Neo-fordist üretim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yüksek vasıflı işgücü, Yüksek güvene dayalı endüstri ilişkileri ve Tam İşlevsel esneklik gibi özellikleri içinde barındıran\nüretim sistemi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Post- Fordist üretim"},{"key":"B","text":"Fordist- Taylorist üretim"},{"key":"C","text":"Esnek Uzmanlaşma"},{"key":"D","text":"Neo-fordist üretim"},{"key":"E","text":"Fordist üretim"}],"answerText":"Post- Fordist üretim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"\"İşçilerin farklı üretim teknolojileri kullanabilme ve üretim ve bakım gibi görevleri birlikte yapabilme yeteneğine işaret\neden bir iş-süreç faktörüdür.\" Tırnak içerisindeki tanım hangi esneklik türünü açıklamaktadır.","options":[{"key":"A","text":"İstihdam esnekliği"},{"key":"B","text":"İşlevsel esneklik"},{"key":"C","text":"Sayısal esneklik"},{"key":"D","text":"Ücret esnekliği"},{"key":"E","text":"İçsel - dışsal esneklik"}],"answerText":"İşlevsel esneklik","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esnek firma modeli kimin tarafından ve hangi tarihte geliştirilmiştir?","options":[{"key":"A","text":"Michael J. Piore - 1980"},{"key":"B","text":"Anne Pollert -1988"},{"key":"C","text":"Richard Jenkins - 1987"},{"key":"D","text":"Esasen Atkinson - 1985"},{"key":"E","text":"Maurice Zeitlin - 1990"}],"answerText":"Esasen Atkinson - 1985","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"1970 ve 1980'li yıllarda Japonların kaliteli ve ucuz mallar üreterek, yeni ürün ve modelleri, tasarım iyileştirmeleri ve\nekstra özellikleri, yerel üreticilerin yapamadığı fiyat ve sıklıkta piyasaya getirerek dünya piyasalarını hızla kontrol altına\naldılar. Bu durum hangi ifade ile tanımlanmaktadır?","options":[{"key":"A","text":"Japon etkisi"},{"key":"B","text":"Japon üretimi"},{"key":"C","text":"Japon tehdidi"},{"key":"D","text":"Japon marjinalitesi"},{"key":"E","text":"Japon öğretisi"}],"answerText":"Japon tehdidi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Japon üretim paradigmasının temel özellikleri arasında sayılmaz?","options":[{"key":"A","text":"Üretim teknolojisini son derece esnektir"},{"key":"B","text":"İş organizasyonunu katıdır"},{"key":"C","text":"Beşeri ve maddi kaynakların maksimum düzeyde kullanımına olanak sağlar"},{"key":"D","text":"Kitle üretimi yapan sektörlerde işi ve çalışmayı insanileştirmiştir"},{"key":"E","text":"Karşılıklı işbirliği ve güven esasına dayalı yeni çalışma ilişkilerini oluşturmuştur"}],"answerText":"İş organizasyonunu katıdır","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi yalın üretimin özelliklerinden biri değildir?","options":[{"key":"A","text":"Bilgisayar-esaslı esnek otomasyon kullanımı"},{"key":"B","text":"Çoklu vasıflı işgücü kullanımı"},{"key":"C","text":"Yüksek stokla çalışma"},{"key":"D","text":"İşbirliğine dayalı alıcı-tedarikçi ilişkisi"},{"key":"E","text":"Çok sayıda ve çok çeşitli ürünlerin üretimi"}],"answerText":"Yüksek stokla çalışma","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi üretimin yeniden yapılanması sürecinde önemli olan faktörlerden biri değildir?","options":[{"key":"A","text":"Teknolojik gelişmeler"},{"key":"B","text":"İşgücü maliyetleri"},{"key":"C","text":"Küreselleşme"},{"key":"D","text":"Tüketici talepleri"},{"key":"E","text":"İşçi talepleri"}],"answerText":"İşçi talepleri","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Post Fordizm ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","options":[{"key":"A","text":"Kitle üretimi benimsenir"},{"key":"B","text":"Standart ürünler üretilir"},{"key":"C","text":"Tek tip iş gücü kullanılır"},{"key":"D","text":"Esnek üretim yöntemleri kullanılır"},{"key":"E","text":"Hiyerarşik yönetim tarzı benimsenir"}],"answerText":"Esnek üretim yöntemleri kullanılır","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Üretimin Yeniden Yapılanması ve Post-Fordizm","cards":["Esneklik, küreselleşme ile birlikte 1970'lerden itibaren yaşamın her alanında karşımıza çıkan ve gün geçtikçe önemi daha\nda artan ve çok daha fazla ülkede uygulanmaya başlayan bir olgudur. Esnekliği \"değişime ayak uydurabilme yeteneği\"\nolarak ifade etmek mümkündür. Esnekliğin amacı, değişen koşullara uyum sağlayabilmektir. Bu bağlamda, son 30-40\nyıldır \"esnek üretim\", \"esnek işletme\", \"esnek uzmanlaşma\", \"esnek çalışma\" vb. kavramlar tüm iş piyasasına hâkim\nolmuştur. Esneklik, üretimde son derece yaygın bir şekilde kullanılmaktadır.","Bilgiye dayalı yeni teknolojilerin ve son\nderece gelişmiş üretim araçlarının kullanıldığı yeni üretim ve yönetim sistemleri, esnekliğe imkân sağlayan bir zemin\noluşturmaktadır. Esneklik, çalışma yaşamını da derinden etkisi altına almış bir olgudur. Esneklik, çalışma yaşamına\n\"esnek çalışma\" olarak yansımıştır. Esnek çalışmanın ne olduğu, işletmeye, çalışana ve iş hukukuna göre değişmektedir.","İşletme açısından esneklik, işletmenin rekabet gücünü, karlılığını ve verimliliğini artırmak üzere çalışanların gerektiği\nzaman, gerektiği yerde ve gerektiği miktarda kullanılmasıdır. Çalışan açısından esneklik, çalışma süresi ve çalışma\nmekânı ile çalışanların koşulları arasında uyum sağlanarak iş-yaşam dengesinin kurulmasıdır. Devlet açısından esneklik\nise, iş piyasalarında daha fazla istihdam sağlanması ve işsizliğin azaltılması, ayrıca iş yasalarında katı hükümler yerine\ndaha esnek hükümlerin yer almasıdır.","Esnek çalışmanın ortaya çıkışıyla, Fordist üretim süreci ve çalışma ilişkileri tamamen ortadan kalkmasa da baskın\nkonumunu yitirmiştir. Bir başka deyişle, çalışanların yalnızca bir işverene bağlı olduğu, bu işverene ait işyerinde standart\nistihdam ilişkisi içinde tam gün çalıştığı, çalışma yaşamı, 1970'li yıllardan itibaren değişmeye başlamış, Fordist dönemin\nürünü olan katı iş ilişkilerinden uzaklaşılarak, esneklik ekseninde yeni iş ilişkilerinin tanımlandığı yeni bir dönem\nbaşlamıştır.\n[BA1]1990 mı yoksa 1990’ları mı kastediyorsunuz?\n[BA2]Bu cümleyi anlayamadım hocam\n[BA3]Uygulanmıştır mı yoksa uygulanmamıştır mı?"],"questions":[{"q":"Yoğun bir rekabetin karakterize ettiği küresel ekonomide işletmelerin rekabet güçlerini koruyabilmeleri açısından\nişletmelerin kısa bir süre içinde az bir maliyet ve çabayla değişebilme veya değişime uyum sağlayabilme yeteneği olarak\ntanımlanan kavram hangisidir?","options":[{"key":"A","text":"Katılık"},{"key":"B","text":"Esneklik"},{"key":"C","text":"Etkililik"},{"key":"D","text":"Korunabilirlik"},{"key":"E","text":"Etkinlik"}],"answerText":"Esneklik","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esneklik kavramı işletmeler açısından aşağıdaki kavramlardan hangisi ile ilişkilendirilmez?","options":[{"key":"A","text":"Kolay işe alma"},{"key":"B","text":"Daha az düzenleme"},{"key":"C","text":"İş güvencesi"},{"key":"D","text":"Kuralsızlaştırma"},{"key":"E","text":"Kolay işten çıkarma"}],"answerText":"İş güvencesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esnekliğin boyutları ile ilgili olarak farklı yazarlar farklı kavram ve tanımlar kullanmaktadır. Aşağıdakilerden hangisi\nEmek piyasalarında esneklik ve esnek çalışma ile kavramlardan birisi değildir?","options":[{"key":"A","text":"Standart-dışı istihdam"},{"key":"B","text":"A-tipik istihdam"},{"key":"C","text":"Durumsal iş"},{"key":"D","text":"İğreti istihdam"},{"key":"E","text":"Katı iş düzenlemeleri"}],"answerText":"Katı iş düzenlemeleri","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iş güvencesi ve sosyal korumanın yüksek olmasına rağmen aynı zamanda belirli süreli\nistihdamında oldukça yüksek olduğu ülkelerden birisi değildir?","options":[{"key":"A","text":"İspanya"},{"key":"B","text":"Portekiz"},{"key":"C","text":"İsveç"},{"key":"D","text":"Hollanda"},{"key":"E","text":"İngiltere"}],"answerText":"İngiltere","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Genellikle normalden daha az sürelerde çalışmayı gerektiren düzenli bir istihdam şeklidir. a-tipik çalışmanın en yaygın\nve önemli biçimini oluşturmaktadır. Literatürde genellikle standart uygulama, haftada ücretli bir işte 30 saatten az\nçalışanları kapsamaktadır.” Tırnak içindeki kavram esnek çalışma türlerinden hangisini karşılamaktadır?","options":[{"key":"A","text":"Kısmi zamanlı çalışma"},{"key":"B","text":"Full- time çalışma"},{"key":"C","text":"Geçici iş ilişkisi"},{"key":"D","text":"Ödünç iş ilişkisi"},{"key":"E","text":"Taşeronlaşma"}],"answerText":"Kısmi zamanlı çalışma","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“ABD’de kısmi zamanlı iş genellikle haftalık ...….saatten daha az olan işlerdir. Kanada ve İngiltere’de ise haftalık ……..\nsaatten daha az olan işler kısmi zamanlı iş olarak tanımlanmaktadır.” Boşlukları dolduracak kavramlar hangi şıkta doğru\nolarak verilmiştir?","options":[{"key":"A","text":"45 - 40"},{"key":"B","text":"40 -35"},{"key":"C","text":"35 - 30"},{"key":"D","text":"30 - 25"},{"key":"E","text":"25 - 20"}],"answerText":"35 - 30","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Kısmi zamanlı çalışma ABD’de kullanılan en yaygın atipik çalışma biçimi olup çalışanların %……….bu statüde\nistihdam edilmektedir. Öte yandan Avrupa’ya bakıldığında çalışan nüfusun yaklaşık % ……. kısmi zamanlı statüde\nistihdam edilmektedir.” Boşlukları dolduracak kavramlar hangi şıkta doğru olarak verilmiştir?","options":[{"key":"A","text":"20’si ve 22’si"},{"key":"B","text":"22’si ve 25’i"},{"key":"C","text":"25’i ve 18,2’si"},{"key":"D","text":"25’i ve 27’si"},{"key":"E","text":"27’si ve 30’u"}],"answerText":"25’i ve 18,2’si","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletmeler işçileri en düşük maliyetle işe alma ve işten çıkarma yeteneklerini artırmak için aşağıdaki esneklik türlerinden\nhangisini kullanılmaktadırlar?","options":[{"key":"A","text":"İstihdam esnekliği"},{"key":"B","text":"Emek süreci esnekliği"},{"key":"C","text":"Çalışma süresi esnekliği"},{"key":"D","text":"Esnek emeklilik"},{"key":"E","text":"İş paylaşımı"}],"answerText":"İstihdam esnekliği","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Standing’e göre, esnek çalışmanın yaygınlık kazanması için aşağıdaki yöntemlerden hangisi tercih edilmez?","options":[{"key":"A","text":"Yasal değişikliklerin iş güvencesini zayıflatması"},{"key":"B","text":"Daha fazla korumaya sahip işgücünün istihdamdaki ağırlığının artması"},{"key":"C","text":"İstihdamın, iş güvencesinin zayıf olduğu sektörlere kayması"},{"key":"D","text":"İşletmelerin daha çok esnek çalışanları tercih etmesi"},{"key":"E","text":"Esnek çalışmaya olanak tanıyacak şekilde toplu pazarlığın değişmesi"}],"answerText":"Daha fazla korumaya sahip işgücünün istihdamdaki ağırlığının artması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi standart olmayan istihdam türlerinden biri değildir?","options":[{"key":"A","text":"Belirli süreli istihdam"},{"key":"B","text":"Kısmı zamanlı istihdam"},{"key":"C","text":"Belirsiz süreli istihdam"},{"key":"D","text":"Kendi-kendine istihdam"},{"key":"E","text":"Kayıt dışı istihdam"}],"answerText":"Belirsiz süreli istihdam","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Esneklik kavramı çalışma hayatında hangi alanda kendini gösterir?","options":[{"key":"A","text":"Ücretlendirme"},{"key":"B","text":"İş güvenliği"},{"key":"C","text":"İş tanımları"},{"key":"D","text":"Çalışma saatleri"},{"key":"E","text":"Eğitim seviyesi"}],"answerText":"Çalışma saatleri","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi esnek çalışma modellerinin yaygınlaşmasının nedenlerinden biridir?","options":[{"key":"A","text":"Teknolojik gelişmeler"},{"key":"B","text":"Artan işçi hakları"},{"key":"C","text":"Düşen işsizlik oranları"},{"key":"D","text":"Küresel rekabet"},{"key":"E","text":"Artan sendikalaşma"}],"answerText":"Teknolojik gelişmeler","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Esneklik ve Esnek Çalışma","cards":["Küreselleşme son yılların en popüler kavramlarından biridir. Henüz tamamlanmamış ve oldukça karmaşık bir süreç\nolması nedeniyle tam olarak ne ifade ettiği veya hangi anlama geldiği tartışmalıdır. Ancak dünyanın ekonomik, sosyal ve\npolitik açılardan artan bütünleşmesi ile ülkelerin birbirine daha da bağımlı hale gelmesi olarak tanımlanabilir.","Küreselleşme sürecinin itici gücü tartışmasız ÇUŞ’ların dir. ÇUŞ’ların , birden fazla ülkede gelir getirici faaliyet\ngösteren ve doğrudan yabancı sermaye yatırımlarını üstlenen şirketlerdir. ÇUŞ’ların üretimlerini, dikey olarak\nparçalayıp, iletişim ve ulaşım teknolojilerinin yardımıyla bileşenlerine ayırarak, emeğin bol ve ucuz olduğu gelişen\nülkelere kaydırmaktadır. 1960’lı yılların sonlarından itibaren tekstil, hazır-giyimg ve ayakkabı gibi emek yoğun\nsektörlerde başlayan bu sürece küresel üretim denilmektedir.","Bu süreç 1980’lerde elektronik, otomobil ve beyaz eşya gibi sermaye yoğun imalat sektörlerinde, 2000'den itibaren de\nhizmet sektöründe yayılmaya başlamıştır..","Üretimin küreselleşmesi gelişmiş ülkelerde emek piyasalarını olumsuz etkilemektedir. Bu süreçten en fazla vasıfsız\nişçiler ve emek yoğun endüstrileri etkilenmektedir. Dolayısı ile gelişen ülkelerden yapılan katma değeri düşük emek\nyoğun malların ithalatının gelişmiş ülkelerde düşük vasıflı işçilerin istihdamını ve emek yoğun endüstrilerin geleceğini\ntehdit etmektedir.","Küresel üretimin ve dış tedariğin artması serbest ticaret bölgelerinin ve ter atöyelerinin sayılarını artmaktadır. Bu\nbölgelere ekseriyetle kadın ve çocuklar istihdam edilmekte, çalışma yasaları askıya alınmakta işçilerin örgütlenme\nhakları engellenmektedir. Kadınlar ve çocukar son derece kötü şartlarda istihdam edimekte ve istismara maruz\nkalmaktadır. Uygulama Soruları\n1. Çocuk emeğini çalışan çocuklara ve ailelerine zarar vermeden nasıl ortadan kaldırabiliriz? Araştırınız. 2. Üretimin küreselleşmesi şirketlerin üretim ilişkilerini ne yönde etkilemiştir? 3. Üretimin küreselleşmesi ile küresel değer zinciri arasında nasıl bir ilişki vardır?","Açıklayınız. 4. Küresel değer zinciri profesyonel işbölümü olarak tanımlayabilir miyiz? Detaylı şekilde anlatınız."],"questions":[{"q":"Aşağıdakilerden hangisi küreselleşme sürecinin nedenlerinden bir değildir?","options":[{"key":"A","text":"Brettonwood sistemimin çökmesi"},{"key":"B","text":"Keynesyen politikaların başarısızlığa uğraması"},{"key":"C","text":"Bilgi ve iletişim teknolojilerinin gelişmesi"},{"key":"D","text":"Neo-liberalizmin yükselişi"},{"key":"E","text":"Uluslararası taşeron kullanımı"}],"answerText":"Uluslararası taşeron kullanımı","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ÇUŞ’lar ile ilgili doğru bilgi değildir?","options":[{"key":"A","text":"İlk çokuluslu şirket dikiş makinesi üreten bir Amerikan şirketi olan Singer’dir"},{"key":"B","text":"Petrol, demir ve fosfat gibi madenlere yapılan yabancı yatırımlar “hammadde /kaynak arayan yatırım” denilir"},{"key":"C","text":"Yeni piyasalar temin etmeye yönelik yabancı yatırımlar “piyasa arayan” yatırım denilir."},{"key":"D","text":"1980 sonrası yatırmaların büyük bir çoğunluğu bilgi teknolojilerine yapılmıştır."},{"key":"E","text":"Son yıllarda gelişen ülkelerde kendi ÇUŞ’larını kurmuştur"}],"answerText":"1980 sonrası yatırmaların büyük bir çoğunluğu bilgi teknolojilerine yapılmıştır.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi üretimin küreselleşmesinin özelliğidir?","options":[{"key":"A","text":"Üretimde kullanılan girdiler farklı kaynaklardan temin edilmektedir"},{"key":"B","text":"Üretilen ürünlerin etiketinde “dünyada üretilmiştir” yazmaktadır"},{"key":"C","text":"Pek çokuluslu şirket ürünlerinin tamamını kendi üretmektedir"},{"key":"D","text":"Bu sürece işletmeler arası “yeni işbölümü” denilmektedir"},{"key":"E","text":"Küresel üretimde sadece kadın ve çocuklar istihdam edilmektedir"}],"answerText":"Pek çokuluslu şirket ürünlerinin tamamını kendi üretmektedir","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi küresel dış-tedarik açısından doğru değildir?","options":[{"key":"A","text":"Nakliye masraflarına karşı oldukça hassastır?"},{"key":"B","text":"Küresel dış tedarik 1960’larda tekstil ve hazır giyimde başlamıştır"},{"key":"C","text":"Küresel dış tedarik 1980’lerde otomotiv, uçak ve beyaz eşya üretiminde başlamıştır"},{"key":"D","text":"Küresel dış tedarik 1990’lerde spor elbise ve ayakkabı üretiminde başlamıştır"},{"key":"E","text":"Küresel dış tedarik 2000’lerde hizmet sektöründe başlamıştır"}],"answerText":"Küresel dış tedarik 2000’lerde hizmet sektöründe başlamıştır","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşasıdakilerinden hangisi üretimin küreselleşmesinin emek piyasaları üzerindeki etkisiyle ilgili değildir?","options":[{"key":"A","text":"Emek piyasalarında rekabetin artması"},{"key":"B","text":"Ücretlerin düşmesi"},{"key":"C","text":"Çalışma standartlarının yükselmesi"},{"key":"D","text":"İşsizliğin yaygınlaşması"},{"key":"E","text":"İstihdamın azalması"}],"answerText":"Çalışma standartlarının yükselmesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangileri serbest ticaret bölgelerinin bir özelliği değildir?","options":[{"key":"A","text":"Genellikle kadın ve çocuklar istihdam edilmektedir"},{"key":"B","text":"Sendikal örgütlenme serbesttir"},{"key":"C","text":"Ücretler son derce düşüktür"},{"key":"D","text":"Çevre ile ilgili tedbirler yeterli değildir"},{"key":"E","text":"Çalışma yasaları ya aksıya alınmıştır"}],"answerText":"Sendikal örgütlenme serbesttir","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden serbest bölge ve ter atölyelerinde çocuk emeği ile ilgili olarak doğru değildir?","options":[{"key":"A","text":"Çocuk işçilerin sayısı her geçen gün artmaktadır"},{"key":"B","text":"Çocukların okula gitmesine izin verilmektedir"},{"key":"C","text":"Ailelerin gelir düzeyi düşük olduğu için çocuklar çalışmak zorundadır"},{"key":"D","text":"Çocuklar genellikle günde 12 saatten fazla çalışmaktadır"},{"key":"E","text":"Çocuklar çalıştığı işyerlerinde iş güvenliği tedbirleri alınmamaktadır."}],"answerText":"Çocukların okula gitmesine izin verilmektedir","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi ter atölyeleri ile ilgili olarak doğru değildir?","options":[{"key":"A","text":"Ter atölyeleri serbest ticaret bölgelerinde kurulmaktadır"},{"key":"B","text":"Ter atölyelerinde zorla çalıştırma ve ayrımcılık yaygındır"},{"key":"C","text":"Gelişmiş ülkelerde ter atölyesi bulunmamaktadır"},{"key":"D","text":"Ter atölyeleri tekstil ve hazır giyim sektöründe yaygındır"},{"key":"E","text":"Sivil toplum örgütleri baskı yoluyla ter atölyelerini engellemeye çalışmaktadır"}],"answerText":"Gelişmiş ülkelerde ter atölyesi bulunmamaktadır","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşasıdakilerinden hangisi çocuk emeği ile ilgili doğru değildir?","options":[{"key":"A","text":"Çocuk emeği her yerde yasaklanmalıdır"},{"key":"B","text":"Mili gelir ile çocuk emeği arasında bir ilişki mevcuttur"},{"key":"C","text":"Çocukların hem çalışıp hem de okula da gidebilecekleri bir çözüm uygulanmalıdır"},{"key":"D","text":"Çocukların çalışması yasaklanmamalıdır"},{"key":"E","text":"Çocuk işçi istihdam eden ülkelere karşı ticari boykot uygulanmamalıdır"}],"answerText":"Çocuk emeği her yerde yasaklanmalıdır","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üretimin küreselleşmesi neyi ifade eder?","options":[{"key":"A","text":"Yerel üretimin artması"},{"key":"B","text":"Tek bir ülkeye odaklanması"},{"key":"C","text":"Sadece gelişmiş ülkelerde üretim yapılması"},{"key":"D","text":"Üretimin dünya geneline yayılması"},{"key":"E","text":"Sadece gelişmekte olan ülkelerde üretim yapılması"}],"answerText":"Üretimin dünya geneline yayılması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Çokuluslu şirketlerin yayılmasında en etkili faktör aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Yerel yönetimlerin politikaları"},{"key":"B","text":"Azalan iş gücü maliyetleri"},{"key":"C","text":"Artan vergiler"},{"key":"D","text":"Gelişen altyapı"},{"key":"E","text":"Küresel pazarların genişlemesi"}],"answerText":"Küresel pazarların genişlemesi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi çokuluslu şirketlerin başlıca avantajlarından biridir?","options":[{"key":"A","text":"Küresel kaynaklara erişim"},{"key":"B","text":"Yerel pazarlara odaklanma"},{"key":"C","text":"Üretim maliyetlerini artırma"},{"key":"D","text":"İş gücünü azaltma"},{"key":"E","text":"Teknolojiyi sınırlama"}],"answerText":"Küresel kaynaklara erişim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Üretimin Küreselleşmesi ve Çokuluslu Şirketler","cards":["İş-yaşam dengesinin, niteliğini ve kalitesini belirleyen refah devleti, 20.yüzyılda gelişen en önemli kurumsal yapılardan\nbiridir. Refah devletinin eşitlik temelinde sunduğu sosyal refah hizmetleri, kapitalizmin getirdiği toplumsal sorunları\nçözmek için belli bir yaşam standardını yakalamayı amaçlamaktadır. Bunun için farklı yaş, gelir düzeyi ve\ncinsiyettekilere para ve zaman dağıtımı, para transferleri ya da kamu hizmetleri sunulmaktadır. Bu hizmetlerle 1947-\n1974 arasındaki yıllarda bireylere refah artışı sağlanmış yaşam kalitesi artmıştır.","Bu durum, bölgesel, ulusal ve\nuluslararası düzeyde toplumsal, ekonomik ve politik ilişkileri şekillendiren değişimler LE bozulmuş, refah devletini\nçözümsüzlüğe itmiştir.","Bu değişimler, emek piyasasına, cinsiyet ile aile ilişkilerine ve iş-yaşam dengesine yansımaktadır. Cinsiyet ilişkileri ve\ncinsiyete dayalı sosyal yapıyla ilgili sosyal normları kökünden sarsmaktadır. Bu dönüşümde önemli kilit rol oynayan ise,\nailenin reisi ve geçimi sağlayan erkeğin gelirinin düşmesi ile tek bir gelirin temel yaşam standardını garantilememesi\nkarşısında evli ve çocuklu kadınların emek piyasasına girmesi olmuştur. Bunun sonucunda toplumda erkeğin ekmek\nkazandığı aile modeli baskın konumunu kaybetmeye başlayarak her iki ebeveynin çalıştığı iki gelirli aile modeli\nyükselmeye başlamıştır.","Aile kurumunun, çalışma hayatıyla beraber yürütülmesinin, iş-yaşam dengesiyle mümkün olabileceğinin kabul\ngörmesiyle sosyal politikalarda yeni bir sürece girilmiştir. Bu, erkeğin ekmek kazandığı aile modeli temelinde\noluşturulan sosyal politikaların yerine istihdam, cinsiyet ve aile ilişkilerindeki değişimlere cevap verebilecek politikalara\ngeçişin bir ihtiyaç haline geldiği anlamını taşımaktadır. Sonuçta iki gelirli aile modeli esasına dayalı olarak geliştirilen\nebeveyn izni, çocuk bakım politikaları, esnek çalışma düzenlemeleri gibi kapsamlı refah devleti politikalarının gelişimi\nönem kazanmıştır.","Bu konuda AB, oldukça çeşitli politikalar sunmasıyla ve ülke uygulamalarıyla dikkat çekmektedir. AB’nin iş-yaşam\ndengesini, toplumsal cinsiyet eşitliği stratejisinin tamamlayıcı unsuru olarak alması ve sosyal bir hak olarak, aile kurumu\naçısından da bir gereklilik olarak tanımlaması bu politikaların gelişimini sağlamıştır. Böylelikle refah devletinin\nuyguladığı ebeveyn izni, çocuk bakım hizmetleri ve esnek çalışma düzenlemeleri gibi politika ve önlemlerle, iş ve aile\nyaşamı dengesinde ebeveynin seçimleri desteklenmektedir. Ayrıca ailenin koşulları finansal olarak iyileştirilmekte,\nekonomik ve demografik büyüme için de gerekli şartlar sağlanmaktadır.\n[BA1]Eğreti?"],"questions":[{"q":"Aşağıdakilerin hangisinde 21. yüzyılda iş ve aile alanlarında kapsamı oldukça geniş olan değişimlerin temelinde yer\nalmaz?","options":[{"key":"A","text":"Erkeğin ekmek kazandığı aile modelinin toplumda baskın konuma gelmesi"},{"key":"B","text":"Hizmet sektörünün gelişmesi"},{"key":"C","text":"Kadın istihdamının yaygınlaşması"},{"key":"D","text":"İki gelirli/yetişkin işçi ailesi modelinin gelişmeye başlaması"},{"key":"E","text":"Erkeğin ekmek kazandığı aile modelinin toplumda baskın konumunu kaybetmesi"}],"answerText":"Erkeğin ekmek kazandığı aile modelinin toplumda baskın konuma gelmesi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İş-yaşam dengesi açısından refah devletinin yeniden yapılanma sürecinde önemli olan değişim aşağıdakilerden\nhangisidir?","options":[{"key":"A","text":"Rekabetin artması"},{"key":"B","text":"Erkeğin ekmek kazandığı aile modelinin gelişmesi"},{"key":"C","text":"Hizmet sektörünün gelişmesi ve erkeğin gelirinin düşmesine paralel olarak kadınların bilhassa annelerin, işgücüne\nkatılması"},{"key":"D","text":"Esnek çalışmanın yaygınlaşması"},{"key":"E","text":"Neo-liberal politikalara geçiş sürecinin başlaması"}],"answerText":"Hizmet sektörünün gelişmesi ve erkeğin gelirinin düşmesine paralel olarak kadınların bilhassa annelerin, işgücüne","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kamusal alanı erkeğe, özel alanı aileye/kadına tahsis eden aile modeli aşağıdakilerden hangisidir?","options":[{"key":"A","text":"İki gelirli aile modeli"},{"key":"B","text":"Erkeğin ekmek kazandığı aile modeli"},{"key":"C","text":"Geniş aile modeli"},{"key":"D","text":"Tek ebeveynli aile modeli"},{"key":"E","text":"Geçici geniş aile modeli"}],"answerText":"Erkeğin ekmek kazandığı aile modeli","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kadın istihdamını arttıran faktörlerden değildir?","options":[{"key":"A","text":"Ekonomik dönüşüm ve endüstriyel yeniden yapılanma"},{"key":"B","text":"Emek piyasalarının yeniden yapılanması"},{"key":"C","text":"Kadının çalışmasına yönelik tutumlarda değişim,"},{"key":"D","text":"Boşanma"},{"key":"E","text":"Artan rekabet baskısı"}],"answerText":"Artan rekabet baskısı","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"1997 Amsterdam Anlaşmasının iş-yaşam dengesi açısından önemi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"İş-yaşam dengesinin, toplumsal cinsiyet eşitliğinin anaakımsallaştırılmasının esası ve tamamlayıcı unsuru olması"},{"key":"B","text":"Avrupa Birliği İstihdam Stratejisinin ortaya çıkması"},{"key":"C","text":"Sosyal Politika Protokolünün Amsterdam Antlaşması’nın bünyesine dâhil olması"},{"key":"D","text":"AB ülkelerinde, yüksek seviyeli istihdamın temel amaç olarak belirlenmesi"},{"key":"E","text":"Nitelikli, eğitimli ve uyumlu işgücünü güçlendirerek ekonomik değişimlere uygun hale getirilmesinin kabul edilmesi"}],"answerText":"İş-yaşam dengesinin, toplumsal cinsiyet eşitliğinin anaakımsallaştırılmasının esası ve tamamlayıcı unsuru olması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İş-yaşam dengesine yönelik refah devletinin uyguladığı politika ve önlemler aşağıdakilerden hangisini\ndesteklememektedir?","options":[{"key":"A","text":"Ailenin koşulları finansal olarak iyileştirilmesini"},{"key":"B","text":"Ekonomik ve demografik büyüme için de gerekli şartların sağlanmasını"},{"key":"C","text":"Lizbon Zirvesi’nin hedeflerine ulaşılmasını"},{"key":"D","text":"Nüfusun yaşlanması, doğum oranlarının azalması, çocuk sahibi olmanın ertelenmesi gibi problemleri çözülmesini"},{"key":"E","text":"Emek piyasasında erkeklerin konumunu güçlendirilmesini"}],"answerText":"Emek piyasasında erkeklerin konumunu güçlendirilmesini","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi, AB direktifleriyle düzenlenen ebeveyn izninin uygulanma amaçlarından biri değildir?","options":[{"key":"A","text":"Kadın istihdamını arttırmak"},{"key":"B","text":"Eşit işe eşit ücret ilkesini geliştirmek"},{"key":"C","text":"Çocukların refahını sağlamak"},{"key":"D","text":"Emek piyasasında cinsiyet eşitliğini sağlamak"},{"key":"E","text":"Ebeveynler arasında çocuk bakımında eşit paylaşım teşvik etmek"}],"answerText":"Eşit işe eşit ücret ilkesini geliştirmek","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi yarı zamanlı çalışmayı yaygın hale getiren faktörlerden değildir?","options":[{"key":"A","text":"Erkeklerden daha çok kadınların yarı zamanlı çalışması"},{"key":"B","text":"Bakım sorumlulukları"},{"key":"C","text":"Eğitim sürecinin uzun olması ve işgücünün daha kısa sürelerde çalışma isteği"},{"key":"D","text":"Erkeklerin ebeveyn iznini kullanması"},{"key":"E","text":"İşgücü maliyetlerinden tasarruf etmek ve esnek bir işgücüne sahip olmak isteyen işverenlerin talepleri"}],"answerText":"Erkeklerin ebeveyn iznini kullanması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İş-Yaşam Dengesi ve AB’de İş-Yaşam Dengesi Politikaları","cards":["Vatandaşlığın 20. yüzyılda medeni ve sivil haklara ilaveten sosyal hak boyutunu kazanması vatandaşlık kavramının,\ntanım ve kapsamı genişlemiştir. Refah devleti hizmetlerinin sosyal haklarla sunulması bu genişlemede oldukça etkin\nolmuş sosyal vatandaşlık kavramı ortaya çıkmıştır. Bununla beraber Marshall'ın katkısıyla gelişen bu kavramla toplumda\nbelli standartlarla yaşayabilmenin ön şartı olarak kabul edilmiş kapitalizmin işleyişindeki toplumsal eşitsizliklerin\ngiderilmesi hedeflenmiştir. Böylelikle kamu müdahalesinin artmasıyla refah devleti genişlemiş 1945-1975 yılları\narasında altın çağını yaşamıştır.","Bu refah devleti ile vatandaşlık kavramını arasındaki ilişkiyi göstermekte ve boyutlarını\nbelirlemektedir. Ancak 1970'li yıllarda yaşanan dünya piyasalarındaki kriz ve küreselleşme ile refah devleti\npolitikalarının o kadar da başarılı olmadığını görülmüştür. Kamu müdahalesinin ve refah harcamalarının azaltılması\nyönündeki baskılarla liberal politikalara dönüş sürecine girilmiştir. Bu değişimin tetiklemesiyle, yeni bir refah rejiminin\ntemel yapısının şekillendiğini ve buna paralel olarak sosyal haklarda ve vatandaşlıkta önemli dönüşümlerin yaşandığını\nsöylemek mümkündür.","Artık tüm bireylerin vatandaş olarak eşit bir biçimde yararlandığı refah devletinden, belli düzeyde\nsosyal korumadan yararlanabilmeyi çalışma şartına bağlayan zorunlu istihdam devletine geçiş söz konusudur. Çalışma\nzorunluluğu altında sosyal yardımların sağlanması, kamu yardımına ihtiyaç duyanlar ile devlet arasında kurulan sosyal\ndevlet ilişkisini değiştirmektedir. Aynı zamanda haklar ve sosyal devlet sisteminde köklü bir farklılaşma oluşturmaktadır.","Bunun sonucunda, toplumda belirli hak ve yaşam standardında iki kutuplu bir ayrışma meydana gelmektedir. Bununla\nbirlikte bu ikili yapıda kadının da cinsiyete dayalı işbölümüyle yer alması tartışmaların yönünü, çok boyutlu ve kapsamlı\nbir yapıda artan eşitsizliğin giderilmesine yönlendirmektedir. Böylelikle bu konu, sosyal politikanın önemli bir meselesi\nhaline gelmektedir."],"questions":[{"q":"Refah devletinin tanımı aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Bir yurtta yaşayıp o topluluğun üyesi olmak ve topluluğa uyum sağlamak, sorumluluk almayı, tanımlayan devlet\ntürüdür."},{"key":"B","text":"Yaşadığı topluluğa uyum sağlayanların katkıda bulunmasını ve katkının seviyesini belirleyen bir devlet türüdür."},{"key":"C","text":"Yasal olarak üyelerinin hak-yükümlülüklerini belirleyen devlet türüdür."},{"key":"D","text":"Ulus-devletle üyeleri arasındaki ilişkileri tanımlayan normatif beklentiler ve bu beklentilerin uygulanabildiği devlet\ntürüdür."},{"key":"E","text":"Piyasanın sosyal adaleti ve insanca bir yaşamı sağlamadaki başarısızlıklarını azaltmak amacıyla bilinçli bir şekilde\nörgütlü kamu gücünün kullanıldığı bir devlet türüdür."}],"answerText":"Piyasanın sosyal adaleti ve insanca bir yaşamı sağlamadaki başarısızlıklarını azaltmak amacıyla bilinçli bir şekilde","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Refah devleti uygulamaları hangi esasta sunulmaktadır?","options":[{"key":"A","text":"Sosyal hak ilkesi esasında"},{"key":"B","text":"Sivil haklar esasında"},{"key":"C","text":"Siyasal hak esasında"},{"key":"D","text":"Gelir esasında"},{"key":"E","text":"Vergilendirme esasında"}],"answerText":"Sosyal hak ilkesi esasında","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Modern refah devletinin şekillenmesi, çeşitli alanlarda devlet müdahalesinin ve desteğinin uygulanmaya başlanması\ngerçekleşmiştir. Aşağıdakilerden hangisi bu alanlardan biri değildir?","options":[{"key":"A","text":"Sağlık"},{"key":"B","text":"İstihdam ve sosyal güvenlik"},{"key":"C","text":"Konut edindirme"},{"key":"D","text":"Eğitim"},{"key":"E","text":"Ulaşım"}],"answerText":"Ulaşım","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerde hangisi refah devletinin krizini derinleştiren nedenler biri değildir?","options":[{"key":"A","text":"Petrol krizleri"},{"key":"B","text":"Ekonomik durgunluklar"},{"key":"C","text":"Artan işsizlik"},{"key":"D","text":"Emek talebinde yükselme"},{"key":"E","text":"Fiyatlar genel düzeyinin sürekli ve hissedilir artışı"}],"answerText":"Emek talebinde yükselme","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerde hangisi refah devletinin alternatifi olarak değerlendirilen Üçüncü Yol yaklaşımının unsurlarından biri\ndeğildir?","options":[{"key":"A","text":"Pasif sosyal politikalar"},{"key":"B","text":"Demokratik devlet ve aktif sivil toplum"},{"key":"C","text":"Yeni karma ekonomi"},{"key":"D","text":"Eşitlik"},{"key":"E","text":"Sosyal yatırım devleti"}],"answerText":"Pasif sosyal politikalar","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi zorunlu istihdam devletinde öngörülen uygulamalardan biri değildir?","options":[{"key":"A","text":"Piyasaların serbestleştirilmesi"},{"key":"B","text":"Bakım harcamalarının arttırılması"},{"key":"C","text":"Özelleştirme"},{"key":"D","text":"Kuralsızlaştırma"},{"key":"E","text":"Sosyal refah harcamalarının kısılması"}],"answerText":"Bakım harcamalarının arttırılması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi refah devletinin tanımıdır?","options":[{"key":"A","text":"Sadece ekonomik kalkınmaya odaklanan devlet sistemi"},{"key":"B","text":"Yalnızca askeri harcamalara odaklanan devlet"},{"key":"C","text":"Sosyal ve ekonomik refahı sağlamak için çeşitli hizmetlerin sunulduğu devlet sistemi"},{"key":"D","text":"Vatandaşların tüm haklarını kısıtlayan devlet"},{"key":"E","text":"Ekonomik kalkınma ve askeri harcamalara odaklanan devlet sistemi"}],"answerText":"Sosyal ve ekonomik refahı sağlamak için çeşitli hizmetlerin sunulduğu devlet sistemi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Refah devleti hangi hizmetleri kapsar?","options":[{"key":"A","text":"Sadece askeri hizmetler"},{"key":"B","text":"Yalnızca ticaret ve sanayi"},{"key":"C","text":"Sadece tarım sektörü"},{"key":"D","text":"Tarım, sanayi ve hizmet sektörü"},{"key":"E","text":"Sağlık, eğitim, sosyal güvenlik"}],"answerText":"Sağlık, eğitim, sosyal güvenlik","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Vatandaşlık hakları aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Oy kullanma, çalışma, eğitim ve sosyal güvenlik hakları"},{"key":"B","text":"Sadece oy kullanma hakkı"},{"key":"C","text":"Yalnızca çalışma hakkı"},{"key":"D","text":"Sadece eğitim hakkı"},{"key":"E","text":"Eğitim ve çalışma hakkı"}],"answerText":"Oy kullanma, çalışma, eğitim ve sosyal güvenlik hakları","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Refah devletinin finansmanı nasıl sağlanır?","options":[{"key":"A","text":"Dış yardımlarla"},{"key":"B","text":"Vergiler ve kamu gelirleriyle"},{"key":"C","text":"Yalnızca zenginlerin vergileriyle"},{"key":"D","text":"Sadece doğal kaynaklarla"},{"key":"E","text":"Dış fonlarla"}],"answerText":"Vergiler ve kamu gelirleriyle","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Refah devleti ile ilgili doğru ifade hangisidir?","options":[{"key":"A","text":"Askeri faaliyetlere odaklanır"},{"key":"B","text":"Zenginlere hizmet sunar"},{"key":"C","text":"Vatandaşların özgürlüklerini kısıtlar"},{"key":"D","text":"Sosyal ve ekonomik refahı hedefler"},{"key":"E","text":"Ekonomik ve askeri faaliyetlere odaklanır"}],"answerText":"Sosyal ve ekonomik refahı hedefler","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Refah Devleti ve Vatandaşlık","cards":[],"questions":[]}]},"ikt":{"name":"Genel İktisat","code":"AIKY1002","file":"Ders _ GENEL İKTİSAT - eKitap.txt","color":"#b45309","units":["İktisat Bilimi","Talep","Arz","Piyasa Dengesi","Talep Tahlilleri","Arz Tahlilleri","Üretim Maliyetleri","Tam Rekabet Piyasaları","Eksik Rekabet Piyasaları","Milli Gelir","Enflasyon","İstihdam-İşgücü-İşsizlik","Para","Para Politikası"],"unitData":[{"title":"İktisat Bilimi","cards":["· İktisat; insanların sınırlı kaynaklarla ihtiyaçlarını en iyi şekilde karşılamak için gösterdikleri çabaları inceleyen bir\nsosyal ilimdir. Bir yandan ihtiyaçların karşılanmasıyla ilgili faaliyetlerdeki ilişkileri tespit etmek, diğer yandan bu\nilişkilerin doğrultusunda insanların ve toplumların refahının ne şekilde artırılabileceğini araştırmak amacındadır.","İhtiyaç karşılandığı zaman insanlara haz ve mutluluk veren, karşılanmadığı zaman ise üzüntü ve keder veren\nduygudur. İhtiyaçları kendi içerisinde zorunlu ve zorunlu olmaya ihtiyaçlar olarak ikiye ayırabiliriz. İhtiyaçlar sonsuzdur.","İhtiyaçlar şiddet dereceleri yönünden birbirinden farklıdırlar. İhtiyaçlarla bunları gidermekte kullanılan araçlar\narasındaki uyumsuzluk kıtlık terimi ile ifade edilmektedir. İhtiyaçları tatmine yarayan unsurlara mal denilmektedir.","İktisadi kaynaklar sınırlı olduğundan bunların yardımıyla üretilen mal ve hizmetler de sınırlı olmakta ve bunlara iktisadi\nmallar denilmektedir. Çeşitli kullanma imkânlarından en yüksek tatmini veya en büyük getiriyi yani ürünü sağlayan\nkullanma imkânının seçilmesine rasyonel davranış veya iktisadi davranış denilmektedir.","İktisadi faaliyetler kıtlığa karşı girişilen ve malların rasyonel idaresi şeklinde beliren, bilinçli, içinde\nbulunduğumuz zamana ve geleceğe ait davranışlardır. Bu faaliyetleri dört ana başlık altında gruplamak mümkündür.","Bunlar üretim, dolaşım, bölüşüm ve tüketim biçiminde ayrılmaktadır.","İktisadi faaliyetlerin analizi; büyüklükleri bakımından Mikro ve Makro, süreleri bakımından Statik,","Mukayeseli Statik ve Dinamik olarak incelenmektedir. Bir birimin iktisadi davranış ve faaliyetlerini incelemeye\n yönelik analiz tarzına mikro analiz denilmektedir. Bir toplumun iktisadi davranış ve faaliyetlerini incelemeye yönelik\nanaliz tarzına ise makro analiz denilmektedir. Statik analizde zaman unsuru ve onun getireceği değişiklikler dikkate\nalınmadan, iktisadi olay ve faaliyetlerin belli bir anı seçilmekte ve iktisadi olay ve faaliyetlerin bu andaki durumu\nincelenmektedir. Mukayeseli statik analizde bir iktisadi olayı oluşturan öğelerin iki ayrı zaman anındaki durumları\nkarşılaştırılmaktadır."],"questions":[{"q":"Aşağıdakilerden hangisi iktisadi faaliyetlerin itici gücünü ifade etmektedir?","options":[{"key":"A","text":"Talep"},{"key":"B","text":"Arz"},{"key":"C","text":"Fayda"},{"key":"D","text":"İhtiyaç"},{"key":"E","text":"Para"}],"answerText":"İhtiyaç","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ihtiyaçların tatmininde kullanılan durum için gereklidir?","options":[{"key":"A","text":"Üretim"},{"key":"B","text":"Para"},{"key":"C","text":"Fayda"},{"key":"D","text":"Kar"},{"key":"E","text":"Talep"}],"answerText":"Üretim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İhtiyaçları gidermede maddi bir özellik taşımayan unsur aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Tatmin"},{"key":"B","text":"Mal"},{"key":"C","text":"Hizmet"},{"key":"D","text":"Fayda"},{"key":"E","text":"Kıtlık"}],"answerText":"Hizmet","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iktisat biliminin cevap aradığı bir soru değildir?","options":[{"key":"A","text":"Malların üretilmesinden kim sorumlu olacak?"},{"key":"B","text":"Mallar nasıl üretilecek?"},{"key":"C","text":"Mallar kimler için üretilecek?"},{"key":"D","text":"Hangi mallar üretilecek?"},{"key":"E","text":"Ne kadar mal üretilecek?"}],"answerText":"Malların üretilmesinden kim sorumlu olacak?","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ekonomide üretim ve istihdam düzeyinin düşmesi durumu aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Enflasyon"},{"key":"B","text":"Genişleme"},{"key":"C","text":"Daralma"},{"key":"D","text":"Dış denge"},{"key":"E","text":"İç denge"}],"answerText":"Daralma","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bir ülke ekonomisinde iktisadi faaliyetlerin hüküm sürdüğü sosyal-siyasal-ekonomik\nkadrolar kast edilmektedir?","options":[{"key":"A","text":"Gayri safi milli hasıla"},{"key":"B","text":"Gayri safi yurtiçi hasıla"},{"key":"C","text":"KBMG"},{"key":"D","text":"Ekonomik Sistem"},{"key":"E","text":"Ekonomik Büyüme"}],"answerText":"Ekonomik Sistem","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iktisadın temel uğraş alanı olan sorunlardan biridir?","options":[{"key":"A","text":"Para"},{"key":"B","text":"Fiyat"},{"key":"C","text":"Fayda"},{"key":"D","text":"Enflasyon"},{"key":"E","text":"Kıtlık"}],"answerText":"Kıtlık","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Mikro analiz ile ilgili olamayan konu aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Firma arzı"},{"key":"B","text":"Fayda analizi"},{"key":"C","text":"Tüketici dengesi"},{"key":"D","text":"Üretici dengesi"},{"key":"E","text":"Büyüme"}],"answerText":"Büyüme","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi özel mülkiyet ile kamu mülkiyetini, piyasa mekanizması ile müdahaleyi, fiyat\nmekanizması ile merkezi planlamayı kabul eden iktisadi yapılanmayı ifade etmektedir?","options":[{"key":"A","text":"Kapitalist sistem"},{"key":"B","text":"Sosyalist sistem"},{"key":"C","text":"Karma ekonomik sistem"},{"key":"D","text":"Fizyokratik sistem"},{"key":"E","text":"Merkantilist sistem"}],"answerText":"Karma ekonomik sistem","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Makro analiz ile ilgili olamayan konu aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Gayri safi milli hasıla"},{"key":"B","text":"Fiyatlar Genel Düzeyi"},{"key":"C","text":"Firma arzı"},{"key":"D","text":"Toplam istihdam"},{"key":"E","text":"Toplam gelir"}],"answerText":"Firma arzı","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Talep","cards":["· Talep: belirli bir sürede bir mala ve bu malın değişik fiyatlarına karşı bir tüketicinin satın almak istediği mal\nmiktarıdır. Mal fiyatları ile miktarları arasındaki değişim ters yönde olmakta; fiyat düşükçe mal miktarı artmakta, fiyat\nyükseldikçe talep edilen mal miktarı azalmaktadır. Buna talep kanunu denilmektedir.","Talep eğrisinin negatif eğimli olmadığı istisnai durumlarda söz konusu olmaktadır. Bu istisnai durumlara düşük\n(inferior) mallar ile gösteriş amaçlı lüks tüketim mallarında rastlamak mümkündür. Talep kanuna ters düşen bu duruma","Talep değişmesi kavramından talep eğrisi üzerindeki bir değişme anlaşılmaktadır. Talep kayması ise; talep\neğrisinin bütünüyle yer değiştirmesidir. Bir malın fiyatındaki değişmeler karşısında tüketicilerin malın talebi ile ilgili\nduyarlılık dereceleri talep esnekliği kavramı ile ifade edilmektedir.","Mala ve piyasaya göre; esnekliğin rakam olarak ifadesi çok değişik olup; sonsuz ile sıfır arasında değişmekte,\nbazen negatif bile olmaktadır. Esneklik 0 ile –1 arasında ise talep esnek değildir. +1 ile ∞ arasında ise talep esnek\ndemektir.","Nokta Esnekliği talep eğrisi üzerindeki herhangi bir noktanın esnekliğidir.Yay esnekliği iki noktadan geçen\ndoğrunun orta noktasının esnekliğini belirtmektedir. Bir başka ifade ile bir önceki ve bir sonraki değerlerin basit\naritmetik ortalamasıdır denilebilir.","Bir malın fiyatındaki değişmenin diğer bir malın talep miktarında meydana getireceği değişikliğe çapraz esneklik\ndenilmektedir. X ve Y malı arasında ikâme ilişkisi varsa y malının fiyatındaki bir düşme (yükselme) x malının talebinde\nbir azalmaya (artma) neden olmaktadır. Çapraz esnekliğin sıfıra yaklaşması ikâmenin güç olduğunu, sonsuz olması ise\n ikâmenin kolay ve tam olduğunu ifade etmektedir. x ve y malı tamamlayıcı özelliği taşıyorsa y malının fiyatındaki\nyükselme (düşme), x malının talebini azaltır (yükseltir). Tamamlayıcı mallar negatif çapraz esnekliğine sahiptir.","Tüketicinin gelirindeki bir değişme sonucunda bir malın talebinde meydana gelen değişmeye talebin gelir\nesnekliği denir. Talebin gelir esnekliği katsayısı 0 ile 1 arasında bir değer alıyorsa temel ihtiyaca yönelik mallar, 1’den\nbüyük ise lüks tüketim malları tüketiliyor demektir."],"questions":[{"q":"Bir kavramı belirleyen çok sayıda değişkenden bir tanesinin değişebileceği, diğer değişkenlerin sabit kalacağı\nvarsayımına ne ad verilir?","options":[{"key":"A","text":"Homo economicus"},{"key":"B","text":"Mutadis mutandis"},{"key":"C","text":"Ceteris paribus"},{"key":"D","text":"Laissez faire"},{"key":"E","text":"Vice versa"}],"answerText":"Ceteris paribus","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ikame mala örnektir?","options":[{"key":"A","text":"Reçel - Peynir"},{"key":"B","text":"Tavuk - Koyun"},{"key":"C","text":"Araba - Benzin"},{"key":"D","text":"Çay - Şeker"},{"key":"E","text":"Bilgisayar - Masa"}],"answerText":"Tavuk - Koyun","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İlişkili mallardan birinin fiyatında meydana gelen bir artış diğer malın talep miktarında artışa neden oluyorsa bu\nmallara ne ad verilir?","options":[{"key":"A","text":"Giffen mal"},{"key":"B","text":"Düşük mal"},{"key":"C","text":"Normal mal"},{"key":"D","text":"Tamamlayıcı mal"},{"key":"E","text":"İkame mal"}],"answerText":"İkame mal","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"A malının tamamlayıcısı olan B malının fiyatı artarsa, aşağıdakilerden hangisi meydana gelir?","options":[{"key":"A","text":"A malının talebi artar"},{"key":"B","text":"A malının talebi azalır"},{"key":"C","text":"B malının talebi artar"},{"key":"D","text":"B malının talebi değişmez"},{"key":"E","text":"A malının talebi değişmez"}],"answerText":"A malının talebi azalır","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki durumlardan hangisinde talep eğrisi sola kaymaz?","options":[{"key":"A","text":"İkame malın fiyatının artması"},{"key":"B","text":"İkame malın fiyatının düşmesi"},{"key":"C","text":"Tüketicinin gelirinin düşmesi"},{"key":"D","text":"Tamamlayıcı malların fiyatının artması"},{"key":"E","text":"Nüfus miktarının azalması"}],"answerText":"İkame malın fiyatının artması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki durumlardan hangisinde talep eğrisi sola kaymaz?","options":[{"key":"A","text":"İkame malın fiyatının artması"},{"key":"B","text":"İkame malın fiyatının düşmesi"},{"key":"C","text":"Tüketicinin gelirinin düşmesi"},{"key":"D","text":"Tamamlayıcı malların fiyatının artması"},{"key":"E","text":"Nüfus miktarının azalması"}],"answerText":"İkame malın fiyatının artması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi çapraz talep esnekliği pozitif olan malları göstermektedir?","options":[{"key":"A","text":"Veblen Malı"},{"key":"B","text":"İkame Malı"},{"key":"C","text":"Tamamlayıcı Mal"},{"key":"D","text":"Giffen Malı"},{"key":"E","text":"Snop Mal"}],"answerText":"İkame Malı","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi malın talep edilen miktarının, bu malın fiyatı karşısındaki duyarlılığının ölçüsünü ifade\netmektedir?","options":[{"key":"A","text":"Talebin gelir esnekliği"},{"key":"B","text":"Talebin tercih esnekliği"},{"key":"C","text":"Çapraz talep esnekliği"},{"key":"D","text":"Talebin ikame esnekliği"},{"key":"E","text":"Talebi fiyat esnekliği"}],"answerText":"Talebi fiyat esnekliği","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Çapraz talep esnekliği negatif olan mallara ne ad verilir?","options":[{"key":"A","text":"Veblen Malı"},{"key":"B","text":"İkame Malı"},{"key":"C","text":"Tamamlayıcı Mal"},{"key":"D","text":"Giffen Malı"},{"key":"E","text":"Snop Mal"}],"answerText":"Tamamlayıcı Mal","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Negatif gelir esnekliği olan mal grubu aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Tamamlayıcı mallar"},{"key":"B","text":"İkame mallar"},{"key":"C","text":"Normal mallar"},{"key":"D","text":"Düşük mallar"},{"key":"E","text":"Serbest mallar"}],"answerText":"Düşük mallar","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Arz","cards":["· Arz; bir satıcının veya üreticinin belli bir zaman süresi içinde elinde bulundurduğu bir malın, değişik fiyatları\nkarşısında piyasada bu maldan satmaya razı olduğu miktardır. Arz bir üretim olmakla birlikte bir satış arzusudur. Bir mal\nfiyatının artması, diğer unsurlar ceteris paribus ise arzı arttırır veya fiyat azalışı arz hacmini azaltır.","Mal fiyatları ile miktarları arasındaki değişim aynı yönde olmakta; fiyat yükseldikçe mal miktarı artmakta, fiyat\ndüştükçe arz edilen mal miktarı azalmaktadır. Fiyat ile arz arasında pozitif bir ilişki olmasına arz kanunu denir.","Arz değişmesi arz eğrisi üzerindeki bir değişimi ifade etmektedir. Buna göre fiyat değişiklikleri karşısında belirli\nbir fiyat miktar bileşiminden diğer bir fiyat miktar bileşimine geçiş söz konusu olmaktadır.","Arz kayması ise; arz eğrisinin bütünüyle yer değiştirmesidir. Arzı belirleyen fonksiyonel unsurlardan bir veya\nbirkaç tanesinde meydana gelen bir değişme arz eğrisinin bütünü ile yer değiştirmesine neden olmakta sağa veya sola\ndoğru kaymaktadır.","Arz esnekliği; fiyattaki değişme yüzdesinin arzdaki değişme yüzdesine oranlanması ile ölçülmektedir. Arz\nesnekliği beş çeşit olup; sıfır ile sonsuz arasında değişmektedir. Arz esnekliğinin bilinmesi; bir malın fiyatının belirli bir\noranda değişmesi sonucu üretici veya satıcının üretim veya satış düzeyinin ne yönde değişeceğini saptamak bakımından\nönem taşımaktadır. Mala ve piyasaya göre; esnekliğin sonsuz ile sıfır arasında değişmekte, bazen negatif bile olmaktadır.","Esneklik 0 ile –1 arasında ise arz esnek değildir. +1 ile ∞ arasında ise arz esnek demektir.","Arzın fiyat esnekliği çeşitli şekillerde hesaplanmaktadır. Nokta Esnekliği arz eğrisi üzerindeki herhangi bir\nnoktanın esnekliğidir.","Arzın yay esnekliği; arz eğrisi üzerindeki iki nokta arasında kalan kısmının esnekliği olup; iki nokta için bulunan\nesnekliğin ortalaması olarak da ifade edilmektedir."],"questions":[{"q":"Arz miktarındaki yüzde değişmenin malın fiyatındaki yüzde değişme oranına ne ad verilir?","options":[{"key":"A","text":"Arz esnekliği"},{"key":"B","text":"Talep esnekliği"},{"key":"C","text":"Gelir esnekliği"},{"key":"D","text":"Geçiş esnekliği"},{"key":"E","text":"Çapraz esnekliği"}],"answerText":"Arz esnekliği","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üreticilerin arz ettikleri miktarlar fiyatın değişen yüzdesinden daha düşük düzeyde olduğunda esneklik katsayısı\nkaç olur?","options":[{"key":"A","text":"se:0"},{"key":"B","text":"se>1"},{"key":"C","text":"se<1"},{"key":"D","text":"se:1"},{"key":"E","text":"se:∞"}],"answerText":"se<1","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Arzı belirleyen öncelikli unsur hangisidir?","options":[{"key":"A","text":"Malın fiyatı"},{"key":"B","text":"Maliyetler"},{"key":"C","text":"Teknoloji"},{"key":"D","text":"Diğer mal fiyatları"},{"key":"E","text":"Zevk ve moda"}],"answerText":"Malın fiyatı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arz eğrisinin kaymasına neden olmaz?","options":[{"key":"A","text":"Diğer malın fiyatının artması"},{"key":"B","text":"İlgili malın fiyatının artması"},{"key":"C","text":"Teknolojinin gelişmesi"},{"key":"D","text":"İşçilik ücretlerinin artması"},{"key":"E","text":"Sermayeye ödenen faizin artması"}],"answerText":"İlgili malın fiyatının artması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üretim faktörlerinin fiyatlarının artışı halinde aşağıdakilerden hangisi gerçekleşir?","options":[{"key":"A","text":"Mal maliyetleri azalır"},{"key":"B","text":"Malın talebi artar"},{"key":"C","text":"Malın arz eğrisi sola kayar"},{"key":"D","text":"Malın fiyatı azalır"},{"key":"E","text":"Üretim miktarı artar"}],"answerText":"Malın arz eğrisi sola kayar","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arz kanunu anlatır?","options":[{"key":"A","text":"Arz eğrisinin pozitif eğimli olması"},{"key":"B","text":"Arz eğrisinin negatif eğimli olması"},{"key":"C","text":"Arz eğrisinin yatay olması"},{"key":"D","text":"Arz eğrisinin dikey olması"},{"key":"E","text":"Arz eğrisinin hiperbol eğri olması"}],"answerText":"Arz eğrisinin pozitif eğimli olması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İktisadi faaliyetlerde insan ihtiyaçlarını giderme amacına yönelik mal ve hizmet üretilmesine ne denir?","options":[{"key":"A","text":"Talep"},{"key":"B","text":"Arz"},{"key":"C","text":"Esneklik"},{"key":"D","text":"Fayda"},{"key":"E","text":"Tüketim"}],"answerText":"Arz","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arzı etkileyen faktörlerden değildir?","options":[{"key":"A","text":"Üretim teknolojilerinin değişmesi"},{"key":"B","text":"Maliyetlerdeki değişmeler"},{"key":"C","text":"Malın fiyatındaki değişme"},{"key":"D","text":"Diğer mal fiyatının değişmesi"},{"key":"E","text":"Hava koşulları"}],"answerText":"Hava koşulları","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yatay eksene paralel bir arz eğrisi söz konusu olduğunda esneklik derecesi kaç olur?","options":[{"key":"A","text":"Arz esnekliği sıfırdır."},{"key":"B","text":"Arz esnekliği birden küçüktür."},{"key":"C","text":"Arz esnekliği bire eşittir."},{"key":"D","text":"Arz esnekliği birden büyüktür."},{"key":"E","text":"Arz esnekliği sonsuzdur."}],"answerText":"Arz esnekliği sonsuzdur.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arz kanununu anlatır?","options":[{"key":"A","text":"Arz eğrisinin pozitif eğimli olması"},{"key":"B","text":"Arz eğrisinin negatif eğimli olması"},{"key":"C","text":"Arz eğrisinin yatay olması"},{"key":"D","text":"Arz eğrisinin düşey olması"},{"key":"E","text":"Arz eğrisinin hiperbol eğri olması"}],"answerText":"Arz eğrisinin pozitif eğimli olması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Piyasa Dengesi","cards":["· Piyasa dengesi, talep edilen miktar ile arz edilen miktarın birbirine eşit olduğu başka bir ifade ile arz ve talep\neğrilerinin kesiştiği noktada oluşur. Bu noktaya karşı gelen fiyat düzeyine denge fiyatı, bu noktaya karşı gelen mal\nmiktarına ise denge miktarı denilmektedir. Piyasa denge analizinde üç dönem söz konusu olmaktadır.","Çok kısa dönem veya piyasa dönemi: Arz edenlerin arz düzeyini arttırmalarının mümkün olamadığı dönemdir","Kısa dönem: Bu dönem arz edenlere arz miktarını arttırma olanağı veren bir dönemdir.","Uzun dönem: Arz edenlere yeni tesis kurarak arz düzeylerini arttırma imkânı veren bir dönemdir.","Belirli bir arz eğrisi karşısında talep eğrisinin artış yönünde sağa kayması sonucu yeni denge noktasında daha\nyüksek bir fiyat ve daha fazla mal miktarı söz konusudur. Yine belirli bir arz eğrisi karşısında talep eğrisinin sola\nkayması ise durumu tersine çevirmekte, daha düşük bir fiyat ve daha az mal miktarı söz konusu olmaktadır.","Belirli bir talep eğrisi karşısında arz eğrisinin artış yönünde sağa doğru kayması sonucu yeni denge noktasında\ndaha düşük bir fiyat ve daha fazla mal miktarı söz konusudur. Yine belirli bir talep eğrisi karşısında arz eğrisinin sola\nkayması ise, durumu tersine çevirmekte; daha yüksek bir fiyat daha az mal miktarı söz konusu olmaktadır.","Piyasada belirlenmiş tek bir denge fiyatında; bir malı daha yüksek fiyattan satın almaya razı tüketici ile yine\nbelirlenmiş fiyattan daha düşük fiyata satmayı kabul eden üreticiler piyasa fiyatına göre sübjektif veya psikolojik bir kâr\nelde etmektedirler. Bu durumda tüketici ve üretici için bir rant söz konusudur.","Karaborsa, piyasa koşullarının ya da yapay nedenlerin yarattığı mal darlığından yararlanarak, kanun otoritesinin\nkoyduğu ya da kontrol ettiği fiyatlardan daha yüksek fiyata satış yapılan piyasadır."],"questions":[{"q":"Talep eğrisinin esnek olması durumunda arzdaki artış ve azalışlarda aşağıdakilerden hangi durum ortaya\nçıkmaktadır?","options":[{"key":"A","text":"Arz sağa kayınca fiyat düşmekte,sola kayınca fiyat yükselmekte"},{"key":"B","text":"Fiyat düşmekte denge miktarı artmakta"},{"key":"C","text":"Fiyatta küçük miktarda büyük oranlarda değişim olur"},{"key":"D","text":"Fiyat yükselmekte denge miktarı azalmakta"},{"key":"E","text":"Arz sola kayınca fiyat düşmekte,sağa kayınca fiyat yükselmekte"}],"answerText":"Fiyatta küçük miktarda büyük oranlarda değişim olur","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Talep eğrisi sola arz eğrisi sağa kayarsa denge fiyatındaki ve miktarındaki değişme hangi yöndedir?","options":[{"key":"A","text":"Denge fiyatı düşer denge miktarı artar"},{"key":"B","text":"Denge fiyatı artar denge miktarı düşer"},{"key":"C","text":"Denge fiyatı ve denge miktarı artar"},{"key":"D","text":"Denge fiyatı ve denge miktarı azalır"},{"key":"E","text":"Denge fiyatı düşer denge miktarı değişmez"}],"answerText":"Denge fiyatı düşer denge miktarı değişmez","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Talep sabitken arzı azalan bir mal için aşağıdakilerden hangisi meydana gelir?","options":[{"key":"A","text":"Denge miktarı artar, denge fiyatı sabit kalır"},{"key":"B","text":"Hem denge fiyatı hem de denge miktarı azalır"},{"key":"C","text":"Hem denge fiyatı hem de denge miktarı artar"},{"key":"D","text":"Denge fiyatı artar, denge miktarı azalır"},{"key":"E","text":"Denge fiyatı azalır, denge miktarı sabit kalır"}],"answerText":"Denge fiyatı azalır, denge miktarı sabit kalır","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bir malın piyasa talep ve arz eğrilerinin kesişmesi durumunu ifade etmektedir?","options":[{"key":"A","text":"Denge fiyatını"},{"key":"B","text":"Denge miktarını"},{"key":"C","text":"Hem talep fazlasını hem de arz fazlasının olmadığı bir noktayı"},{"key":"D","text":"Yukarıdakilerin hepsini"},{"key":"E","text":"Hiçbiri"}],"answerText":"Yukarıdakilerin hepsini","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arz esnekliği ve dönem uzunluğu ile ilgili olarak doğru ifade değildir?","options":[{"key":"A","text":"Piyasa döneminde arz esnekliği birden büyüktür"},{"key":"B","text":"Kısa dönemde arz esnekliği birden küçüktür"},{"key":"C","text":"Uzun dönemde arz esnekliği birden büyüktür"},{"key":"D","text":"Dönem uzunluğu arttıkça arz esnekliği büyür"},{"key":"E","text":"Çok kısa dönemde arz esnekliği sıfırdır"}],"answerText":"Piyasa döneminde arz esnekliği birden büyüktür","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi talep eğrisinin esnek olması durumunda arzdaki artış ve azalışların oluştuğu durumu\nifade etmektedir?","options":[{"key":"A","text":"Arz sağa kayınca fiyat düşmekte, sola kayınca fiyat yükselmekte"},{"key":"B","text":"Fiyat düşmekte denge miktarı artmakta"},{"key":"C","text":"Fiyatta küçük miktarda büyük oranlarda değişim olur"},{"key":"D","text":"Fiyat yükselmekte denge miktarı azalmakta"},{"key":"E","text":"Arz sola kayınca fiyat düşmekte,sağa kayınca fiyat yükselmekte"}],"answerText":"Fiyatta küçük miktarda büyük oranlarda değişim olur","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki ifadelerden hangisi denge fiyatına ilişkin doğru ifade değildir?","options":[{"key":"A","text":"Arz ve talep miktarının eşitlendiği fiyattır"},{"key":"B","text":"Arz fazlalığı yoktur"},{"key":"C","text":"Talep fazlalığı yoktur"},{"key":"D","text":"Piyasada mal darlığı vardır"},{"key":"E","text":"Denge fiyatından mal satın almak isteyen herkes mal alabilir"}],"answerText":"Piyasada mal darlığı vardır","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir firmanın üretimde hiçbir şeyi değiştiremediği döneme ne ad verilir?","options":[{"key":"A","text":"Piyasa dönemi"},{"key":"B","text":"Kısa dönem"},{"key":"C","text":"Orta dönem"},{"key":"D","text":"Uzun dönem"},{"key":"E","text":"Teknolojik dönem"}],"answerText":"Piyasa dönemi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tüketici rantı kavramını ifade etmektedir?","options":[{"key":"A","text":"Tüketicinin fiili olarak ödediği miktar ile ödemeye razı olduğu miktar arasındaki fark"},{"key":"B","text":"Tüketicinin ödemeye razı olduğu miktarla fiili olarak ödediği miktar arasındaki fark"},{"key":"C","text":"Tüketicinin fiili olarak ödediği ve ödemeye razı olduğu miktarların toplamı"},{"key":"D","text":"Tüketicinin ödemeye razı olduğu miktarın fiili olarak ödediği miktara bölümü"},{"key":"E","text":"Tüketicinin fiili olarak ödediği miktar"}],"answerText":"Tüketicinin ödemeye razı olduğu miktarla fiili olarak ödediği miktar arasındaki fark","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Örümcek ağı teoremine göre piyasa dengesinin bozulması durumunda arz talep\ndengesinin kendiliğinden oluşması durumunu göstermektedir?","options":[{"key":"A","text":"Talep ve arz eğrilerinin aynı eğime sahip olması durumunda"},{"key":"B","text":"Arz eğrisinin talep eğrisinden daha yatık olması durumunda"},{"key":"C","text":"Talep eğrisinin esnekliğinin sıfır olması durumunda"},{"key":"D","text":"Talep eğrisinin arz eğrisinden daha yatık olması durumunda"},{"key":"E","text":"Arz esnekliğinin 1 olması durumunda"}],"answerText":"Talep eğrisinin arz eğrisinden daha yatık olması durumunda","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Talep Tahlilleri","cards":["· Fayda mal ve hizmetlerin insan ihtiyaçlarını tatmin etme özelliğine denilmektedir. Kardinal yaklaşım Faydanın\nölçülebileceğini, faydanın kantitatif ölçülerle ifade edileceği görüşünü savunmaktadır. Ordinal yaklaşım ise faydanın\nölçülemeyeceğini ifade etmekte; fayda subjektif bir kavramdır ve bunu sayı ile ifade etmek yani kardinal olarak ölçmek\nmümkün değildir..","Bir malın toplam tüketiminin tüketiciye sağladığı faydaya toplam fayda denir. Belirli bir malın tüketici tarafından\nkullanılan ek biriminin o malın toplam faydasında yaptığı değişiklik marjinal fayda ile ifade edilmektedir. Kullanılan\nmal miktarı arttıkça toplam fayda da artmakta ve bu durum tam doyum noktasına kadar devam etmektedir. Buna karşın\nkullanılan mal miktarları arttıkça marjinal fayda azalmaktadır. Marjinal faydanın gittikçe azalan bir durum göstermesine\nazalan marjinal fayda kanunu denilmektedir.","Birbiri ile ikame edebilen farklı mal bileşimlerinin tüketiciye aynı toplam faydayı sağladığını gösteren\neğrilere kayıtsızlık eğrileri denir. Aynı eğri üzerinde her nokta daima aynı toplam faydayı temsil etmektedir.","Kayıtsızlık eğrilerinin dört özellikliği vardır.Bunlar; negatif eğimlidir, birbirlerini kesinlikle kesmezler, orijine\ngöre dış bükeydir, orijinden uzaklaştıkça daha fazla fayda sağlamaktadır.","Tüketicinin belirli geliri ve piyasa fiyatları ile çeşitli mallardan satın alabileceği mal miktarlarının geometrik\nyerine bütçe doğrusu denilmektedir.","Tüketiciye aynı faydayı sağlayan farklı mal bileşimlerinin geometrik yeri olan kayıtsızlık eğrisi ile belirli geliri\ndoğrultusunda iki maldan satın alabileceği farklı bileşimleri gösteren bütçe doğrusunun kesiştiği nokta tüketici\ndengesini oluşturmaktadır.","Tüketicinin geliri artıp mal fiyatları sabit iken, eski bütçesine göre daha fazla mal satın alma imkânına sahip\nolacağından bütçe doğruları paralel olarak sağa doğru kaymaktadır.","Böylece gelir-tüketim eğrisi bütçe doğruları ile kayıtsızlık eğrilerinin oluşturdukları denge noktalarının\nbirleştirilmesiyle elde edilmektedir. Bu eğri X eksenine doğru bükümlü ise X malı normal mal, Y malı düşük maldır. Y\neksenine doğru bükümlü ise X malı düşük mal, Y malı normal maldır. Her iki mal da düşük mal ise gelir-tüketim eğrisi\nçizilemez."],"questions":[{"q":"Mal ve hizmetlerin insan ihtiyaçlarını tatmin kabiliyetine ne ad verilmektedir?","options":[{"key":"A","text":"Değer"},{"key":"B","text":"Fayda"},{"key":"C","text":"Tüketim"},{"key":"D","text":"Talep"},{"key":"E","text":"Harcama"}],"answerText":"Fayda","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi faydanın ölçülemeyeceğini ifade eden yaklaşımdır?","options":[{"key":"A","text":"Kardinal fayda"},{"key":"B","text":"Ordinal fayda"},{"key":"C","text":"Marjinal fayda"},{"key":"D","text":"Toplam fayda"},{"key":"E","text":"Azalan fayda"}],"answerText":"Ordinal fayda","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangisi kayıtsızlık eğrilerinin özelliklerinden biri değildir?","options":[{"key":"A","text":"Her noktada aynı eğime sahip olmaları"},{"key":"B","text":"Negatif eğimli olmaları"},{"key":"C","text":"Birbirlerini ve eksenleri kesmemeleri"},{"key":"D","text":"Genellikle orijine göre dışbükey olmaları"},{"key":"E","text":"Sağa kayan her kayıtsızlık eğrisinin bir öncekinden daha fazla fayda sağlaması"}],"answerText":"Her noktada aynı eğime sahip olmaları","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tüketicinin satın alma gücünü yansıtan kavram aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Gelir- tüketim eğrisi"},{"key":"B","text":"Fiyat-tüketim eğrisi"},{"key":"C","text":"Bütçe doğrusu"},{"key":"D","text":"Genişleme yolu"},{"key":"E","text":"Maliyet kısıtı"}],"answerText":"Bütçe doğrusu","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kayıtsızlık eğrilerinin özelliğini aşağıdakilerden hangisi göstermektedir?","options":[{"key":"A","text":"Pozitif eğimlidirler"},{"key":"B","text":"Birbirlerini keserler"},{"key":"C","text":"Üzerlerindeki her nokta farklı tatmin düzeyini gösterir"},{"key":"D","text":"Eksenleri keserler"},{"key":"E","text":"Orijine göre dışbükeydirler"}],"answerText":"Orijine göre dışbükeydirler","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir maldan bir birim daha fazla tüketilmesinin toplam faydada yarattığı değişme aşağıdakilerden hangisi ile ifade\nedilmektedir?","options":[{"key":"A","text":"Marjinal fayda"},{"key":"B","text":"Kardinal fayda"},{"key":"C","text":"Ordinal fayda"},{"key":"D","text":"Maksimum fayda"},{"key":"E","text":"Minimum fayda"}],"answerText":"Marjinal fayda","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir malın tüketilen miktarı arttırıldığında, her yeni birimin sağladığı faydanın azalacağını belirten kanun\naşağıdakilerden hangisidir?","options":[{"key":"A","text":"Azalan verimler kanunu Gresham yasası"},{"key":"B","text":"Azalan marjinal fayda yasası"},{"key":"C","text":"Talep yasası"},{"key":"D","text":"Arz yasası"},{"key":"E","text":"Azalan verimler kanunu"}],"answerText":"Azalan marjinal fayda yasası","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Marjinal faydayı gösteren durum aşağıdakilerden hangisidir?","options":[{"key":"A","text":"∆Q ∕ ∆L"},{"key":"B","text":"∆TUa ∕ Qa"},{"key":"C","text":"∆TUa ∕ ∆Qa"},{"key":"D","text":"TUa ∕ ∆Qa"},{"key":"E","text":"TUa ∕ Qa"}],"answerText":"∆TUa ∕ ∆Qa","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tüketiciye bir maldan daha fazla satın alma imkanını sağlayan eğriyi ifade etmektedir?","options":[{"key":"A","text":"Bütçe doğrusu"},{"key":"B","text":"Kayıtsızlık eğrisi"},{"key":"C","text":"Eş ürün eğrisi"},{"key":"D","text":"Gelir-tüketim eğrisi"},{"key":"E","text":"Genişleme yolu"}],"answerText":"Gelir-tüketim eğrisi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tüketicinin geliri arttığında talebinin azaldığı mal grubunu ifade etmektedir?","options":[{"key":"A","text":"Lüks mal"},{"key":"B","text":"Düşük mal"},{"key":"C","text":"Esnek mal"},{"key":"D","text":"Ekonomik mal"},{"key":"E","text":"Normal mal"}],"answerText":"Düşük mal","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Arz Tahlilleri","cards":["· Bir fayda yaratmak veya mevcut faydalara ilavelerde bulunmak amacıyla yapılan bütün faaliyetlere üretim denir.","Üretim ; şekil faydası, mekan faydası ve zaman faydası yaratan faaliyetleri içermektedir..","Üretimin meydana gelmesinde kullanılan unsurlar üretim faktörleri olarak tanımlanmaktadır. Üretim\nfaktörlerinin birleştirilmesiyle üretim gerçekleşmektedir. Üretim faktörleri; Toprak, Emek, Sermaye, Girişim olmak\nüzere dört grupta toplanmaktadır","Üretimin gerçekleşmesi sürecinde kullanılan faktörlerin miktarı ile üretilen malın miktarı arasında fonksiyonel bir\nilişkiyi üretim fonksiyonu ifade eder. Üretim fonksiyonu teknik bir zorunluluğu ifade etmektedir. Mal üretimi için\nkullanılan girdilerden birinin miktarının arttırılması ancak diğer girdilerden birinin miktarının azaltılması ile mümkün\nolmaktadır. Burada zaman ayırımı da önem kazanmaktadır. En az bir girdinin belirli zaman aralığında sabit kaldığı\ndöneme kısa dönem, yeteri kadar zaman aralığı varsayımı altında firmaların girdi miktarlarını arttırdıkları döneme de\nuzun dönem denilmektedir.","Azalan verim kanunu üretim faktörlerinden birinin miktarı değiştirilip diğer üretim faktörlerinin miktarının sabit\ntutulması durumunda miktarı artan üretim faktörünün veriminin; önce artış gösterip maksimum noktasına ulaşması, daha\nsonra da azalması durumunu ifade etmektedir.","Üreticiye aynı üretim düzeyini sağlayan iki faktörün (emek ve sermaye) farklı bileşimlerinin geometrik yeri olup,\nüreticileri ilgilendiren eğriler eş ürün eğrileridir. Eş ürün eğrilerinin de özellikleri olarak; negatif eğimli eğrilerdir,\nparalel eğriler olup; birbirlerini kesmezler, orijine göre dış bükeydirler, orijinden daha uzakolan eş ürün eğrisi\ndaha fazla üretim düzeyini göstermektedir.","Üreticinin belirli bir bütçe ve veri faktör fiyatları ile hangi faktörlerden ne kadar satın alacağını gösteren doğru eş\nmaliyet doğrusudur.","Eş-ürün eğrileri ile eş maliyet doğrularının kesiştiği nokta faktör fiyatları veri iken; üreticinin bütçe olanakları\ndoğrultusunda maksimum verimliliği sağlayabileceği faktör bileşimini göstermekte ve üretici dengesi sağlanmaktadır."],"questions":[{"q":"Aşağıdakilerden hangisi faktörlerden bazılarını değiştirme imkanını veren durumu göstermektedir?","options":[{"key":"A","text":"Kısa dönem"},{"key":"B","text":"Uzun dönem"},{"key":"C","text":"Çok uzun dönem"},{"key":"D","text":"Pazar dönemi"},{"key":"E","text":"Piyasa dönemi"}],"answerText":"Kısa dönem","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir fayda yaratmak amacılya yapılan durum aşağıdakilerden hangisi ile ifade edilmektedir?","options":[{"key":"A","text":"Talep"},{"key":"B","text":"İhtiyaç"},{"key":"C","text":"Arz"},{"key":"D","text":"Üretim"},{"key":"E","text":"Tüketim"}],"answerText":"Üretim","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Toprak, emek , sermaye ve girişimden oluşan kaynaklara ne ad verilir?","options":[{"key":"A","text":"Çıktı"},{"key":"B","text":"Üretim faktörü"},{"key":"C","text":"Ürün"},{"key":"D","text":"Doğal kaynak"},{"key":"E","text":"İmalat"}],"answerText":"Üretim faktörü","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi, farklı iki faktör bileşiminin aynı ürün miktarını verdiği geometrik durumu ifade\netmektedir?","options":[{"key":"A","text":"Farksızlık eğrisi"},{"key":"B","text":"Kayıtsızlık eğrisi"},{"key":"C","text":"Eş ürün eğrisi"},{"key":"D","text":"Anlaşma eğrisi"},{"key":"E","text":"Bağıt eğrisi"}],"answerText":"Eş ürün eğrisi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tüm girdilerinin miktarlarının değiştirilebileceği dönemdir?","options":[{"key":"A","text":"Piyasa dönemi"},{"key":"B","text":"Pazar dönemi"},{"key":"C","text":"Kısa dönem"},{"key":"D","text":"Çok kısa dönem"},{"key":"E","text":"Uzun dönem"}],"answerText":"Uzun dönem","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki hangisi üretim fonksiyonu ile ilgili doğru tanımdır?","options":[{"key":"A","text":"Fonksiyona giren üretim faktörlerinin marjinal fiziki ürünlerine ulaşmak mümkündür"},{"key":"B","text":"Yalnızca ölçeğe göre sabit getiriyi gösterir"},{"key":"C","text":"Teknolojik gelişme fonksiyonu aşağıya kaydırır"},{"key":"D","text":"Üretim faktörlerinden birisinin değişmesi ile ortaya çıkan üretimi gösterir"},{"key":"E","text":"Her zaman doğrusal bir fonksiyondur"}],"answerText":"Fonksiyona giren üretim faktörlerinin marjinal fiziki ürünlerine ulaşmak mümkündür","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üreticinin mali gücündeki iyileşme sonucu daha fazla faktör alma imkanı ve üretim artışı aşağıdakilerden hangisi\nile ifade edilir?","options":[{"key":"A","text":"Bütçe doğrusu"},{"key":"B","text":"Genişleme yolu"},{"key":"C","text":"Gelir tüketim eğrisi"},{"key":"D","text":"Eş maliyet doğrusu"},{"key":"E","text":"Eş ürün eğrisi"}],"answerText":"Genişleme yolu","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi eş maliyet doğrusunu belirtmektedir?","options":[{"key":"A","text":"Faktör bileşiminin maliyetini"},{"key":"B","text":"Eş ürün eğrileri ile teğet olma durumunu"},{"key":"C","text":"Eş ürün eğrilerinin birbirlerini kesme durumunu"},{"key":"D","text":"Faktör bileşimini"},{"key":"E","text":"Üreticinin teknik seçimlerini"}],"answerText":"Faktör bileşiminin maliyetini","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi değişken bir faktörün ister azaltılarak isterse arttırılarak kullanımı ile üretimi\narasındaki ilişkiyi yansıtmaktadır?","options":[{"key":"A","text":"Artan verim kanunu"},{"key":"B","text":"Artan marjinal fayda kanunu"},{"key":"C","text":"Azalan verim kanunu"},{"key":"D","text":"Azalan toplam fayda kanunu"},{"key":"E","text":"Değişen marjinal fayda kanunu"}],"answerText":"Azalan verim kanunu","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki hangi özellik faktörler arası ikame olduğu varsayımının sonucudur?","options":[{"key":"A","text":"Üzerindeki her noktanın eşit üretim düzeyini göstermesi"},{"key":"B","text":"Orijinden uzaklaştıkça daha yüksek üretim düzeyini göstermesi"},{"key":"C","text":"Birbirlerini ve genellikle eksenleri kesmemesi"},{"key":"D","text":"Orijine göre dışbükey olması"},{"key":"E","text":"Azalan (negatif) eğimli olması"}],"answerText":"Azalan (negatif) eğimli olması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Üretim Maliyetleri","cards":["· Üretim kapasitesinin ve teknolojinin sabit olduğu, üretimde kullanılan faktörlerin bir kısmının da sabit olduğu\nbuna karşılık sadece değişir faktörün arttırılıp azaltılmasıyla üretim düzeyinin değiştirildiği dönem kısa dönemdir. Kısa\ndönemde; sabit, değişir ve toplam maliyetler ile marjinal maliyet yer almaktadır.","Firmanın üretim Uzun dönemde de kullandığı tüm üretim faktörlerini değiştirmek için gerekli zaman süresine\nsahip olduğu dönem uzun dönemdir. Uzun dönemde tüm faktörler değişir durumdadır. Bütün maliyetler değişir olduğu\niçin firma bütün üretim faktörlerinde yapabileceği değişmelerle üretim hacmini ayarlamaktadır. Uzun dönemde de\ntoplam maliyet, ortalama toplam maliyet ve marjinal maliyet olmak üzere dört maliyet bulunmaktadır.","Ölçek ekonomileri içsel ekonomiler ve dışsal ekonomiler olarak ikiye ayrılmaktadır.Bir firmanın tesisleri\ngenişleterek, üretim hacmini veya üretim fonksiyonunu değiştirmesi, teknolojik yenilikler getirerek veya dış çevrede\nmeydana gelen maliyet düşürücü faktörlerden yararlanarak verimliliğini arttırması; diğer bir ifade ile üretim\nmaliyetlerinin düşürülmesi sonucu elde edilen avantajlar ölçek ekonomileri doğrultusunda gerçekleşmektedir.","İçsel ölçek ekonomileri firma içinde veya firmanın bulunduğu sanayi sektöründe meydana gelmektedir. İçsel\nekonomiler iki açıdan değerlendirilmektedir. Birincisi maliyet düşürücü etki sağlayan avantajlar olup, içsel ekonomiler\nolarak tanımlanmaktadır. İkincisi ise maliyet yükseltici etki sağlayan dezavantajlardır ki bunlar da içsel eksi ekonomiler\nolarak ifade edilmektedir.","Dışsal ekonomiler firma dışı fakat endüstri içi sağladığı kazanç ve kayıplar olarak tanımlanmaktadır. Dışsal ölçek\nekonomileri de iki açıdan değerlendirilmektedir. Endüstrinin genel gelişmesine bağlı olarak firma maliyetlerinde düşüş\nsağlayan dışsal ekonomiler, ile bunun sonucunda dışsal ekonomilerin yarattığı kayıplar neticesi maliyet artışları\ngörülmekte ve dışsal - eksi ekonomiler .","Piyasa, mal ve hizmet karşılığında para vermek isteyen tüketiciler ile para karşılığında mal ve hizmet sunmak\nisteyen üreticileri karşı karşıya getiren ve fiyatın oluşumunu sağlayan ortamdır. Piyasa dengesi bir malın piyasa fiyatının\noluşumunun analizi olup; piyasa fiyatından ne kadar malın piyasaya arz edileceğini ve bu fiyattan malın ne kadarının\ntalep edileceğini ifade etmektedir."],"questions":[{"q":"Üretim faktörlerinden sadece bir tanesinin değiştirilmesine olanak sağlayan döneme ne ad verilir?","options":[{"key":"A","text":"Kısa dönem"},{"key":"B","text":"Çok kısa dönem"},{"key":"C","text":"Orta dönem"},{"key":"D","text":"Uzun dönem"},{"key":"E","text":"Piyasa dönemi"}],"answerText":"Kısa dönem","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bütün girdilerinin miktarlarının değiştirilebileceği dönem aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Piyasa dönemi"},{"key":"B","text":"Kısa dönem"},{"key":"C","text":"Uzun dönem"},{"key":"D","text":"Çok kısa dönem"},{"key":"E","text":"Pazar dönemi"}],"answerText":"Uzun dönem","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Değişir maliyetler toplamının üretim miktarına bölünmesi ile elde edilen maliyet kavramı aşağıdakilerden\nhangisidir?","options":[{"key":"A","text":"Marjinal maliyet"},{"key":"B","text":"Ortalama toplam maliyet"},{"key":"C","text":"Ortalama sabit maliyet"},{"key":"D","text":"Ortalama değişir maliyet"},{"key":"E","text":"Sabit maliyet"}],"answerText":"Ortalama değişir maliyet","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi sabit maliyetlere bir örnek verilemez?","options":[{"key":"A","text":"Fabrikanın kirası"},{"key":"B","text":"İşçi ücretleri"},{"key":"C","text":"Belediye harçları"},{"key":"D","text":"Bina ve arazi vergileri"},{"key":"E","text":"Amortismanlar"}],"answerText":"İşçi ücretleri","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Firmanın birim üretim başına düşen maliyetine ne ad verilir?","options":[{"key":"A","text":"Ortalama toplam maliyet"},{"key":"B","text":"Ortalama sabit maliyet"},{"key":"C","text":"Ortalama değişken maliyet"},{"key":"D","text":"Marjinal maliyet"},{"key":"E","text":"Toplam maliyet"}],"answerText":"Ortalama toplam maliyet","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Kısa dönem ortalama maliyet eğrisinin U biçiminde olmasının nedeni aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Ölçeğe göre artan ve azalan verimler"},{"key":"B","text":"Ölçeğe göre artan ve sabit verimler"},{"key":"C","text":"Sabit marjinal verimler kanunu"},{"key":"D","text":"Sabit ve artan marjinal verimler kanunu"},{"key":"E","text":"Artan ve azalan marjinal verimler kanunu"}],"answerText":"Artan ve azalan marjinal verimler kanunu","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ölçek ekonomileri söz konusu olduğunda aşağıdakilerden hangisi söylenebilir?","options":[{"key":"A","text":"Uzun dönem ortalama maliyet düşer"},{"key":"B","text":"Uzun dönem ortalama maliyet artar"},{"key":"C","text":"Kısa dönem ortalama maliyet artar"},{"key":"D","text":"Kısa dönem ortalama maliyet düşer"},{"key":"E","text":"Kısa dönem ortalama maliyet değişmez"}],"answerText":"Uzun dönem ortalama maliyet düşer","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi firma dışı fakat endüstri içi kazanç durumunu ifade etmektedir?","options":[{"key":"A","text":"İçsel ekonomiler"},{"key":"B","text":"İçsel-eksi ekonomiler"},{"key":"C","text":"Dışşal ekonomiler"},{"key":"D","text":"Dışsal-eksi ekonomiler"},{"key":"E","text":"Artan maliyetli endüstri"}],"answerText":"Dışşal ekonomiler","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Piyasa denge koşulu hangi durumda oluşmaktadır?","options":[{"key":"A","text":"Arz ve talebin birbirine eşit olması"},{"key":"B","text":"Talebin arzdan fazla olması"},{"key":"C","text":"Arzın talepten fazla olması"},{"key":"D","text":"Arz ve talep edenlerin kararları doğrultusunda"},{"key":"E","text":"Arz ve talebin eşit olmaması"}],"answerText":"Arz ve talebin birbirine eşit olması","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Denge fiyatına ilişkin aşağıdaki ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Arz ve talep miktarının eşitlendiği fiyattır"},{"key":"B","text":"Arz fazlalığı yoktur"},{"key":"C","text":"Talep fazlalığı yoktur"},{"key":"D","text":"Piyasada mal darlığı vardır"},{"key":"E","text":"Denge fiyatından mal satın almak isteyen herkes mal alabilir"}],"answerText":"Piyasada mal darlığı vardır","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Tam Rekabet Piyasaları","cards":["· Alıcı ve satıcıların fiyatları etkileyemedikleri piyasa türüne tam rekabet piyasaları adı verilmektedir.","Alıcılar, satıcılar ve faktör sahipleri arasındaki ilişkilerde rekabetin tam olduğu ve piyasalara giriş-çıkışın\nengellenmediği piyasa türüne tam rekabet piyasaları denilmektedir. Bu piyasa türünde piyasada oluşan fiyat kişisel\netkilerden bağımsız olarak arz ve talep tarafından belirlenmektedir.","Firmanın satışa sunduğu malın miktarı ile fiyatının çarpımına firma geliri denilmektedir. Ancak firmanın gelirini\nbelirleyebilmesi için öncelikle malın fiyatını başka bir ifade ile malına olan talep miktarını bilmesi gerekmektedir. Tam\nrekabet piyasasında firma fiyatı veri olarak kabul etmek durumunda olduğundan ve üretebildiği kadar malı\nsatabileceğinden karşı karşıya olduğu talep eğrisi yatay eksene paralel bir doğru biçiminde olmaktadır.","Firma üç tür geliri elde etmektedir. Firmanın toplam geliri sattığı mala ödenen para miktarı olup; mal miktarı ile\nfiyatın çarpımına eşittir. Toplam gelirin satılan mal miktarına bölünmesi ile elde edilen ortalama gelir aynı zamanda\nfiyata eşittir. Firmanın satışında bir birimlik bir değişmenin toplam gelirde meydana getirdiği değişme oranı ise marjinal\ngeliri vermektedir.","Firma kısa dönemde üretim kapasitesini değiştirecek zaman süresine sahip değildir ve üretim faktörleri de sabit\nolduğundan, değişir faktörlerden daha az veya daha çok kullanarak üretim miktarını belirleyecektir.","Toplam gelir ve toplam maliyet yaklaşımı doğrultusunda firmanın kârını maksimum kıldığı nokta toplam gelir\nile toplam maliyet arasındaki farkın en fazla olduğu karlılığın en yüksek olduğu yerdir..","Marjinal maliyet ve marjinal gelir yaklaşımı doğrultusunda firmanın kârını maksimum kıldığı nokta ise\nmarjinal maliyetin ve marjinal gelire eşit olduğu noktada oluşmaktadır.","Bütün faktörlerin değişir olduğu uzun dönemde ise firmalar üretim tesislerinin ölçeğini değiştirebilme imkânına\nsahiptirler. Piyasada aşırı kâr eden firmaların olması bu kârdan yararlanmak isteyen yeni firmaların piyasaya girmelerine\nneden olurken; zarar eden firmaların da piyasadan çıkış yapmaları firmaların kârlılık durumlarını etkilemektedir."],"questions":[{"q":"Birbiriyle ile rekabet eden az sayıda firmanın bulunduğu ve her birinin üretimindeki değişmelerin piyasa fiyatını\netkileyebilecek durumda olduğu piyasa türü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Oligopson"},{"key":"B","text":"Monopol"},{"key":"C","text":"Oligopol"},{"key":"D","text":"Tekelci rekabet"},{"key":"E","text":"Monopson"}],"answerText":"Oligopol","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tam rekabete ait bir özellik değildir?","options":[{"key":"A","text":"Atomize"},{"key":"B","text":"Mobilite"},{"key":"C","text":"Homojenlik"},{"key":"D","text":"Şeffaflık"},{"key":"E","text":"Ürün farklılaştırması"}],"answerText":"Ürün farklılaştırması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tam rekabet piyasasında toplam gelir ile toplam maliyetin birbirine eşit olduğu üretim\ndüzeyini göstermektedir?","options":[{"key":"A","text":"Kapanma noktası"},{"key":"B","text":"Maksimum kar noktası"},{"key":"C","text":"Başa baş noktası"},{"key":"D","text":"Denge noktası"},{"key":"E","text":"Minimum zarar noktası"}],"answerText":"Başa baş noktası","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tam rekabet şartlarında kısa dönemde firmaların ortalama geliri aşağıdakilerden hangi gelir düzeyine eşit\nolmaktadır?","options":[{"key":"A","text":"Malın satış fiyatına"},{"key":"B","text":"Firmanın marjinal maliyetine"},{"key":"C","text":"Firmanın toplam maliyetine"},{"key":"D","text":"Firmanın toplam gelirine"},{"key":"E","text":"Firmanın üretim miktarına"}],"answerText":"Firmanın marjinal maliyetine","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tam rekabet piyasalarının şartlarından biri değildir?","options":[{"key":"A","text":"Alıcı ve satıcıların tam bilgiye sahip olması"},{"key":"B","text":"Çok sayıda satıcı olması"},{"key":"C","text":"Çok sayıda alıcı olması"},{"key":"D","text":"Malların homojen olması"},{"key":"E","text":"Piyasaya girişte kısıtlamalar olması"}],"answerText":"Piyasaya girişte kısıtlamalar olması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisinde tam rekabet piyasasında faaliyette bulunan bir firmanın karını maksimum kılma\nkoşuludur?","options":[{"key":"A","text":"Fiyat = Ortalama gelir"},{"key":"B","text":"Ortalama maliyet = Ortalama gelir"},{"key":"C","text":"Ortalama değişir maliyet = Marjinal gelir"},{"key":"D","text":"Marjinal maliyet = Marjinal gelir"},{"key":"E","text":"Marjinal gelir = Ortalama gelir"}],"answerText":"Marjinal maliyet = Marjinal gelir","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki hangi piyasa türünde firmalar reklam faaliyeti ile ilgili maliyetlere maruz kalmamaktadır?","options":[{"key":"A","text":"Tam rekabet"},{"key":"B","text":"Monopollü rekabet"},{"key":"C","text":"Monopol"},{"key":"D","text":"Monopson"},{"key":"E","text":"Oligopol"}],"answerText":"Tam rekabet","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tam rekabet piyasasında uzun dönem karlılıklarını normal kar olarak oluşturmaktadır?","options":[{"key":"A","text":"Alıcı ve satıcıların piyasa hakkında bilgili olması"},{"key":"B","text":"Malın homojen olması"},{"key":"C","text":"Piyasaya giriş çıkışların serbest olması"},{"key":"D","text":"Alıcıların çok olması"},{"key":"E","text":"Alıcıların fiyatı etkileyememesi"}],"answerText":"Piyasaya giriş çıkışların serbest olması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tam rekabet piyasasında zarar eden firmanın bu zararı en aza indirme durumu aşağıdakilerden hangisidir?","options":[{"key":"A","text":"P < OM ve P> ODM"},{"key":"B","text":"P > OM ve P> ODM"},{"key":"C","text":"P < OM ve P < ODM"},{"key":"D","text":"P = OM ve P> ODM"},{"key":"E","text":"P < OM ve P = ODM"}],"answerText":"P < OM ve P> ODM","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Tam rekabet piyasasında maliyet yapıları farklı firmaların kar etmesi durumunda aşağıdakilerden hangisi\ngerçekleşmektedir?","options":[{"key":"A","text":"Ortalama maliyet fiyatın üstünde olmalı"},{"key":"B","text":"Değişir maliyet fiyatın üstünde olmalı"},{"key":"C","text":"Ortalama maliyet fiyata eşit"},{"key":"D","text":"Hem ortalama maliyet hem de değişir maliyet fiyatın altında"},{"key":"E","text":"Hem ortalama maliyet hem de değişir maliyet fiyatın üstünde"}],"answerText":"Hem ortalama maliyet hem de değişir maliyet fiyatın altında","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Eksik Rekabet Piyasaları","cards":["· Monopol; çok sayıda alıcıya karşın, tek satıcının bulunduğu piyasa türüdür. Tek satıcı olması nedeniyle piyasaya\nhakim durumda olup; piyasa fiyatı üzerinde doğrudan kontrole sahiptir. Bu nedenle monopolcü firma için piyasada\nherhangi bir rekabet söz konusu değildir.","Monopolcü firma da tam rekabet piyasalarında faaliyette bulunan firmalar gibi toplam gelir, ortalama gelir ve\nmarjinal gelir olmak üzere üç gelir elde etmektedir.","Piyasada tek firma olduğundan dolayı hem üretim miktarını hem de fiyatı belirleme imkânına sahiptir. Ancak her\nikisini aynı anda belirlemek mümkün olamamaktadır. Monopolcü de rasyonel davranan her firma gibi kârını maksimuma\nçıkaracak veya zararını minimuma indirecek bir denge düzeyi sağlamak amacındadır. Bunun için firma ya fiyatı\nbelirleyip, buna göre kârı maksimum kılacak üretim düzeyini saptamakta veya üretim düzeyini belirleyip buna göre kârı\nmaksimum kılacak fiyatı bulmaktadır.","Monopolcünün karını arttırmak amacıyla aynı mal ve hizmet için farklı fiyat istemesi veya daha fazla alanlara\ndaha az alanlara oranla daha düşük fiyattan satmasına fiyat farklılaştırması denilmektedir. Fiyat farklılaştırması\nuygulaması için; piyasaların bölünebilmesi, talep esneklikleri farklı olması ve maliyetlerinde herhangi bir değişme\nolmaması gibi bazı koşulların bulunması gerekmektedir.","Belirli bir malın üretiminin sınırlı sayıda firma tarafından yapıldığı buna karşın çok sayıda alıcının bulunduğu\npiyasalara oligopol piyasaları denilmektedir. Oligopolcüler satış yapmak için birbirleri ile rekabet ederler. Firmaların her\nbiri ne kadar üretim yapacakları kararının piyasa fiyatını etkileyeceğini bilmektedirler. Her bir firma, bir dereceye kadar\nmonopolcüye benzer piyasa gücüne sahiptir. Bu nedenle bu piyasadaki rekabet “mükemmel” değildir.","Monopollü rekabet piyasaları hem tam rekabet hem de monopol piyasalarının özelliklerini yansıtan ve piyasada\nfarklılaştırılmış mal ve hizmetlerin sunulduğu, çok sayıda satıcının bulunduğu piyasalardır. Firmalar piyasaya sundukları\nmalları diğer mallardan farklı imiş gibi sunmakta; bu da firmaların her birine ayrı ayrı monopol gücü kazandırmaktadır."],"questions":[{"q":"İkamesi bulunmayan bir malın satıldığı piyasaya ne denir?","options":[{"key":"A","text":"Monopollü rekabet"},{"key":"B","text":"Tam rekabet"},{"key":"C","text":"Monopson"},{"key":"D","text":"Oligopol"},{"key":"E","text":"Monopol"}],"answerText":"Monopol","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Monopolcünün ortalama gelir eğrisini göstermektedir?","options":[{"key":"A","text":"Artan eğime sahip bir eğri"},{"key":"B","text":"Azalan eğime sahip bir eğri"},{"key":"C","text":"Yatay eksene paralel bir doğru"},{"key":"D","text":"Dikey eksene paralel bir doğru"},{"key":"E","text":"Önce artan sonra azalan bir eğri"}],"answerText":"Azalan eğime sahip bir eğri","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Monopolcünün marjinal gelir eğrisini göstermektedir?","options":[{"key":"A","text":"Talebin altında kalan negatif eğimli bir doğrudur."},{"key":"B","text":"Talebin üstünde kalan pozitif eğimli bir doğrudur."},{"key":"C","text":"Ortalama gelire eşittir."},{"key":"D","text":"Talep eğrisine eşittir"},{"key":"E","text":"Fiyata eşittir."}],"answerText":"Talebin altında kalan negatif eğimli bir doğrudur.","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Monopolcünün marjinal maliyetinin marjinal geliri aştığı durumu ifade etmektedir?","options":[{"key":"A","text":"Denge durumundakinden daha düşük marjinal maliyet ile"},{"key":"B","text":"Denge durumundakinden daha yüksek marjinal gelir ile"},{"key":"C","text":"Denge üretimden düşük üretim hacmi"},{"key":"D","text":"Denge üretimden yüksek üretim hacmi"},{"key":"E","text":"Denge üretim hacmi"}],"answerText":"Denge üretimden yüksek üretim hacmi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Monopolcünün kar ettiği durumu ifade etmektedir?","options":[{"key":"A","text":"Marjinal maliyetin minimum olması"},{"key":"B","text":"Marjinal gelirin maksimum olması"},{"key":"C","text":"Toplam gelirin maksimum olması"},{"key":"D","text":"Toplam gelir toplam maliyet eşitliği"},{"key":"E","text":"Marjinal gelir marjinal maliyet eşitliği"}],"answerText":"Marjinal gelir marjinal maliyet eşitliği","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi piyasa yapısı alış fiyatının belirlendiği piyasadır?","options":[{"key":"A","text":"Monopol"},{"key":"B","text":"Monopson"},{"key":"C","text":"Monopollü rekabet"},{"key":"D","text":"Duopol"},{"key":"E","text":"Oligopol"}],"answerText":"Monopson","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Az sayıda firmanın karı arttırmak için oluşturdukları birliktelik aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Tröst"},{"key":"B","text":"Tekel"},{"key":"C","text":"Kartel"},{"key":"D","text":"Noksan Oligopol"},{"key":"E","text":"Tam Oligopol"}],"answerText":"Kartel","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Sweezy modeline göre firma davranışını açıklamaktadır?","options":[{"key":"A","text":"Rakibin maliyeti sabittir"},{"key":"B","text":"Rakibin satış miktarı sabittir"},{"key":"C","text":"Rakibin fiyatı sabittir"},{"key":"D","text":"Fiyat artarken rakipler izlemez, düşerken izlerler"},{"key":"E","text":"Fiyat düşerken rakipler izlemez, artarken izlerler"}],"answerText":"Fiyat artarken rakipler izlemez, düşerken izlerler","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi monopollü rekabet ile monopol piyasaları arasındaki farklılığı ifade etmektedir?","options":[{"key":"A","text":"Reklam giderleri"},{"key":"B","text":"Müşteri sayısı"},{"key":"C","text":"Talebin esneklik derecesi"},{"key":"D","text":"Yüksek fiyattan mal satışı"},{"key":"E","text":"Düşük fiyattan mal satışı"}],"answerText":"Reklam giderleri","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Monopollü rekabet piysası uzun dönem firma dengesi hangi piyasa yapısı ile benzerlik göstermektedir?","options":[{"key":"A","text":"Monopol"},{"key":"B","text":"Monopson"},{"key":"C","text":"Duopol"},{"key":"D","text":"Oligopol"},{"key":"E","text":"Tam rekabet"}],"answerText":"Tam rekabet","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Milli Gelir","cards":["· Bir ekonomide belli bir dönemde (bir yılda) mal ve hizmet üretimine katılan faktörlerin, bunun karşılığında\naldıkları payların toplam değerine milli gelir denilmektedir. Milli gelir hesapları ekonomik faaliyetlerin genel bir özetini\nsunmanın yanında, ülkedeki üretim, gelirler ve harcamalar arasındaki karşılıklı ilişkileri de göstermektedir.","Gayrı Safi Milli Hasıla (GSMH): Bir ülkede belirli bir dönemde (bir yıl içinde) üretilen nihai mal ve hizmetler\ntoplamının piyasa fiyatlarına göre para ile ifadesidir. Safi Milli Hasıla gayrı safi milli hasıladan amortisman payı\ndüşüldüğü zaman safi milli hasıla elde edilmektedir.","Milli gelir çeşitli şekillerde hesaplanmaktadır. Üretim yöntemi ile milli gelir, bir ekonomide bir yılda üretilen nihai\nmal ve hizmetlerin piyasa değeri ile ifade edildiği bir hesaplama yöntemidir. Gelir yöntemi ile milli gelir, dört temel\nfaktör geliri dikkate alınmakta, bir yıl içinde elde edilen ücret, maaş, faiz, kira, kâr ve rantlar toplandığında bir ülkenin\nmilli geliri bulunmaktadır. Harcama yöntemi ile milli gelir, bir ekonomide bir yılda nihai mal ve hizmetler için yapılan\nharcamaların toplamı göz önüne alınmaktadır.","Gayrı safi yurtiçi hasıla belirli bir dönemde (bir yıl) bir ülkenin ulusal sınırları dahilinde üretim faktörlerinin\nkullanılmasıyla oluşan nihai mal ve hizmetlerin toplam değerini yansıtmaktadır. Kişisel gelir, halkın belli bir dönemde\nfiilen elde ettiği gelirdir. Elde edilen gelirin bir kısmı emekli sandığı ve sosyal sigorta kurumlarına ödenen sigorta\nprimleri, dağıtılmayan şirket kârları ve kurumlar vergisi olarak kesildiğinden milli gelirden düşülmekte, buna karşın\ndevletin kişilere verdiği sübvansiyonlar ile transfer ödemeleri ise ilave edilerek, kişisel gelire ulaşılmaktadır.","Harcanabilir\ngelir, kişinin serbestçe kullanabileceği geliri olup, kişisel gelirden doğrudan vergiler çıkarıldıktan sonra elde edilen gelire\ndenir.","İktisadi anlamda tüketim harcamaları ise; bir ekonomide belli bir dönemde tüketicilerin ihtiyaçlarını doğrudan\nkarşılayacakları mal ve hizmetlere yaptıkları harcamaların toplamını ifade etmektedir. Gelirin tüketime ayrılmayan\nkısmına tasarruf denir. Tasarrufta harcanabilir gelire bağlı olup, gelir arttıkça tasarrufta artacaktır."],"questions":[{"q":"Kişisel gelirden dolaysız vergilerin düşülmesiyle aşağıdakilerden hangisini elde ederiz?","options":[{"key":"A","text":"GSMH"},{"key":"B","text":"SMH"},{"key":"C","text":"MG"},{"key":"D","text":"Harcanabilir gelir"},{"key":"E","text":"GSYİH"}],"answerText":"Harcanabilir gelir","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Dönem üretiminin baz alınan bir yılın fiyatları ile hesaplanmasıyla bulunan gelir ölçüsüne ne denir?","options":[{"key":"A","text":"Nominal gelir"},{"key":"B","text":"Reel gelir"},{"key":"C","text":"Milli gelir"},{"key":"D","text":"Harcanabilir gelir"},{"key":"E","text":"Kişisel gelir"}],"answerText":"Reel gelir","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Harcama yönünden milli gelir hesaplanmasında aşağıdakilerden hangisi kullanılmamaktadır?","options":[{"key":"A","text":"Tüketim"},{"key":"B","text":"Yatırım"},{"key":"C","text":"Kamu harcaması"},{"key":"D","text":"Net ihracat"},{"key":"E","text":"Kar"}],"answerText":"Net ihracat","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Ücret+Rant+Faiz+Kâr+Dolaylı Vergiler+Amortismanlar = ?\nbu denklemi ifade etmektedir?","options":[{"key":"A","text":"Gelirler yöntemi ile milli gelir"},{"key":"B","text":"Harcamalar yöntemi ile milli gelir"},{"key":"C","text":"Üretim yöntemi ile milli gelir"},{"key":"D","text":"Nominal milli gelir"},{"key":"E","text":"Reel milli gelir"}],"answerText":"Gelirler yöntemi ile milli gelir","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir ekonomide bireylerin satın alma gücünü ifade eden kavram aşağıdakilerden hangisidir?","options":[{"key":"A","text":"GSMH"},{"key":"B","text":"Kişisel Gelir"},{"key":"C","text":"Safi Milli Hasıla"},{"key":"D","text":"Harcanabilir Gelir"},{"key":"E","text":"Milli Gelir"}],"answerText":"Harcanabilir Gelir","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Milli gelir hesaplamalarında katma değerlerin esas alındığı ölçme yöntemi hangisidir?","options":[{"key":"A","text":"Gelirler yöntemine göre GSYİH"},{"key":"B","text":"Harcamalar yöntemine göre GSYİH"},{"key":"C","text":"Üretim yöntemine göre GSYİH"},{"key":"D","text":"Reel Milli Gelir"},{"key":"E","text":"Hiçbiri"}],"answerText":"Üretim yöntemine göre GSYİH","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi tüketim harcamalarını etkileyen faktördür?","options":[{"key":"A","text":"Faiz oranı"},{"key":"B","text":"Servet"},{"key":"C","text":"Kapasite kullanımı"},{"key":"D","text":"Teknolojik değişme"},{"key":"E","text":"Sermaye mallarının maliyeti"}],"answerText":"Servet","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Gelirden bağımsız tüketim harcamalarına ne denir?","options":[{"key":"A","text":"Otonom Tüketim"},{"key":"B","text":"Uyarılmış Tüketim"},{"key":"C","text":"Toplam Tüketim"},{"key":"D","text":"Ortalama Tüketim"},{"key":"E","text":"Hiçbiri"}],"answerText":"Otonom Tüketim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Belli bir dönemde bir ekonomide üretilmiş bütün nihai mal ve hizmetlerin piyasa fiyatları ile hesaplanmış değeri\naşağıdakilerden hangisidir?","options":[{"key":"A","text":"GSYH"},{"key":"B","text":"SMH"},{"key":"C","text":"GSMH"},{"key":"D","text":"KG"},{"key":"E","text":"Harcanabilir Gelir"}],"answerText":"GSMH","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Harcanabilir gelir sıfır iken birey ve toplumun zorunlu ihtiyaçları için yaptığı tüketim aşağıdakilerden\nhangisidir?","options":[{"key":"A","text":"Tüketim"},{"key":"B","text":"Marjinal Tüketim Eğilimi"},{"key":"C","text":"Ortalama Tüketim Eğilimi"},{"key":"D","text":"Otonom Tüketim"},{"key":"E","text":"Lüks Tüketim"}],"answerText":"Otonom Tüketim","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Enflasyon","cards":["· Bir ekonomide toplam talebin toplam arzdan fazla olması sonucu, fiyatlar genel düzeyinin sürekli olarak\nyükselmesine enflasyon denilmektedir. Enflasyona neden olan etkenler göz önüne alındığında talep ve arz kaynaklı\noldukları görülmektedir.","Talep enflasyonu bir ülkede üretilen mal ve hizmetlerin toplam talebi karşılayamaması nedeniyle ortaya çıkan\nenflasyondur. Mal ve hizmet fiyatlarının oluşumunda maliyet koşulları esas alınıyorsa ve buna bağlı olarak fiyatlar genel\ndüzeyi yükseliyorsa arz (maliyet) enflasyonu ortaya çıkmaktadır.","Her ülkenin ekonomik yapısının farklı özellikler taşıması enflasyonun farklı şekillerde görülmesine sebep\nolmaktadır. Enflasyon çeşitleri; yapısal enflasyon, kronik enflasyon, sinsi enflasyon ve hiperenflasyondur. Yapısal","Enflasyon belirli piyasalarda ve ekonominin bazı kesimlerinde fiyatların birkaç firma tarafından belirlenmesi sonucu\nortaya çıkmaktadır. Kronik enflasyon; kamu harcamalarının sürekli artması, gelirlerin üretimdeki artışla orantısız olması,\nsürekli bütçe açıkları, yatırım finansmanlarının emisyonla karşılanması gibi nedenlere bağlı olarak fiyatlar genel\ndüzeyinin sürekli artış göstermesi sonucu görülen bir enflasyon türüdür. Sinsi Enflasyon fiyatlar genel düzeyinin yavaş\nve çok küçük oranlarda yükselme eğilimi gösterdiği dönemlerde görülen bir enflasyon çeşididir.","Fiyatlar genel düzeyinin\nçok hızlı yükselmesi ve paranın iç değerinin aşırı ve hızlı bir şekilde düşmesi sonucu enflasyon hızının çok yükselmesi\ndurumuna hiperenflasyon denilmektedir.","Deflasyon; ekonomide üretim artışlarının yavaşladığı veya durduğu, fiyatlar genel düzeyinin ise düşme eğilimi\ngösterdiği bir durumdur. Deflasyon toplam gerçek talepteki azalmanın derecesine ve devamına göre; satışların\nyavaşlaması sebebiyle stokların artmasına da sebep olmaktadır.","Devalüasyon bir ülke parasının dış değerinin yabancı paralar karşısında düşürülmesidir. Millî paranın dış değerinin\ndüşürülmesinin iki nedeni bulunmaktadır. Birinci durumda paranın iç değeri ile dış değeri arasındaki farkın uluslararası\nmal alışverişinde meydana getirdiği güçlükleri ortadan kaldırmak söz konusu olduğu hâlde; ikinci durumda millî\nmalların dış piyasalardaki rekabet gücünü arttırmak söz konusu olmaktadır.","Revalüasyon; bir ülke parasının değerini altına ve dövize göre yükselterek yeniden ayarlamaktır. Merkez"],"questions":[{"q":"Enflasyonun artışına neden olan unsur aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Faiz oranlarındaki artış"},{"key":"B","text":"Para miktarındaki artış"},{"key":"C","text":"Talep artışı"},{"key":"D","text":"Döviz kurunun yükselmesi"},{"key":"E","text":"Para miktarındaki azalış"}],"answerText":"Para miktarındaki artış","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangisi talep enflasyonuna sebep olan unsurlardan biri değildir?","options":[{"key":"A","text":"Enerji yetersizliği"},{"key":"B","text":"Döviz yetersizliği"},{"key":"C","text":"Sermaye yetersizliği"},{"key":"D","text":"İşgücü yetersizliği"},{"key":"E","text":"Yatırım yetersizliği"}],"answerText":"Sermaye yetersizliği","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi arz (maliyet) enflasyonunun en önemli nedenidir?","options":[{"key":"A","text":"Üretim maliyetlerindeki artış"},{"key":"B","text":"Enerji kıtlığı"},{"key":"C","text":"Döviz darboğazı"},{"key":"D","text":"İşgücü yetersizliği"},{"key":"E","text":"Sermaye yetersizliği"}],"answerText":"Üretim maliyetlerindeki artış","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki ifadelerden hangisi yanlıştır?","options":[{"key":"A","text":"Enflasyon fiyatlar genel düzeyinde sürekli artıştır."},{"key":"B","text":"Enflasyonun tersi deflasyondur."},{"key":"C","text":"Enflasyon ile pahalılık özdeş kavramlardır."},{"key":"D","text":"Enflasyonda bütün mal ve hizmetlerin fiyatı artar."},{"key":"E","text":"Enflasyon oranlarındaki değişiklikler fiyat endeksleri yardımıyla izlenir."}],"answerText":"Enflasyon ile pahalılık özdeş kavramlardır.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Azgelişmiş/gelişmekte olan ülkelerde tam istihdama ulaşmadan ortaya çıkan yüksek fiyat artışlarına ne denir?","options":[{"key":"A","text":"Yapısal Enflasyon"},{"key":"B","text":"Talep Enflasyonu"},{"key":"C","text":"Maliyet Enflasyonu"},{"key":"D","text":"Hiperenflasyon"},{"key":"E","text":"Hiçbiri"}],"answerText":"Yapısal Enflasyon","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"A ülkesinin devalüasyon yapması sonucunda aşağıdakilerden hangisi ortaya çıkmaktadır?","options":[{"key":"A","text":"Dış rekabet azalır"},{"key":"B","text":"İthalatı artar"},{"key":"C","text":"Uzun dönemde dış ticareti artar"},{"key":"D","text":"İhracatı artar"},{"key":"E","text":"İhracatı azalır"}],"answerText":"İhracatı artar","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi deflasyon sürecinde uygulanacak tedbirlerden birisidir?","options":[{"key":"A","text":"Kredi hacmini daraltma"},{"key":"B","text":"Harcama kısıcı politika uygulamaları"},{"key":"C","text":"Gelir ve kurumlar vergisi oranlarında artış"},{"key":"D","text":"Yüksek ücret politikası"},{"key":"E","text":"Hiçbiri"}],"answerText":"Yüksek ücret politikası","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Paranın değer ölçüsü olma özelliğini kaybetmesi en fazla hangi enflasyon türünde görülmektedir?","options":[{"key":"A","text":"Kronik enflasyon"},{"key":"B","text":"Yapısal enflasyon"},{"key":"C","text":"Hiperenflasyon"},{"key":"D","text":"Sinsi enflasyon"},{"key":"E","text":"Hiçbiri"}],"answerText":"Hiperenflasyon","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Devletin döviz kurunun değerini düşürmesi işlemine ne denir?","options":[{"key":"A","text":"Revalüasyon"},{"key":"B","text":"Resesyon"},{"key":"C","text":"Deflasyon"},{"key":"D","text":"Devalüasyon"},{"key":"E","text":"Stagflasyon"}],"answerText":"Revalüasyon","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Revalüasyonun yapılma nedeni aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Ödemeler dengesi fazlılığı"},{"key":"B","text":"Ödemeler dengesi azlığı"},{"key":"C","text":"İhracat azlığı"},{"key":"D","text":"İthalat azlığı"},{"key":"E","text":"İhracat < İthalat"}],"answerText":"Ödemeler dengesi fazlılığı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İstihdam-İşgücü-İşsizlik","cards":["· İstihdam: Çalışma gücü ve arzusunda olan kişilerin belirli bir ücret karşılığında hizmetlerinden yararlanılmasıdır.","Bir ülkenin nüfus miktarı ile istihdam arasında yakın bir ilişki vardır. Nüfus miktarının yaş, cinsiyet, göç gibi demografik\nözellikleri istihdam üzerinde etkilidir.","Bir ülkedeki nüfusun üretici durumda bulunan yani iktisadi faaliyete katılan kısmına işgücü denilmektedir. Başka\nbir tanımla; bir ülkede emek arzını insan sayısı yönünden ifade eden bir kavramdır.","İşsizlik; bir kişinin çalışma gücü ve arzusunda olup ta piyasadaki cari ücret düzeyine razı olmasına karşın iş\nbulamama durumudur. Dolayısıyla, ücret düzeyini beğenmediği için çalışmayanlar işsiz sayılmamaktadırlar. İşsizlik\nçeşitlerini; yapısal, iradî, gayri idarî, friksiyonel, konjoktürel ve gizli işsizlik olarak sınıflandırmak mümkündür.","İşsizlik çeşitleri işsizliğin hangi sebeplerden kaynaklandığı konusunda fikir vermektedir. Ekonominin talep ve\nüretim yapısında meydana gelen değişikliklere uyum sürecinin sebep olduğu işsizliğe yapısal işsizlik denilmektedir.","İnsanların cari ücret veya kanunla belirlenen ücret seviyesinde çalışma imkânına sahip olmalarına karşın; çeşitli\nnedenlerle çalışmak istemeyip, işsiz kalmak istemeleri durumunda ortaya çıkan işsizlik iradi işsizliktir.","Çalışma gücünde ve arzusunda olup; cari ücret düzeyinde ve mevcut şartlarda çalışmaya razı kişilerin iş\nbulamamaları halinde oluşan işsizliğe gayri iradi işsizlik denilmektedir.","Friksiyonel işsizlik insanların mevcut işlerini bırakıp, başka bir iş aramasına bağlı bir işsizliktir. Amaç daha iyi\nçalışma koşulları ve daha yüksek ücret elde etmektir."],"questions":[{"q":"İşgücü tanımına dahil olmayan grup aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Maaş ve ücretliler"},{"key":"B","text":"İşsizler"},{"key":"C","text":"İşverenler"},{"key":"D","text":"Çalışmak istemeyenler"},{"key":"E","text":"Emekliler"}],"answerText":"Çalışmak istemeyenler","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kişilerin belirli bir ücret karşılığında hizmetlerinden yararlanılmasını ifade etmektedir?","options":[{"key":"A","text":"İşsizlik"},{"key":"B","text":"İşgücü"},{"key":"C","text":"İstihdam"},{"key":"D","text":"İşsizlik oranı"},{"key":"E","text":"Emek"}],"answerText":"İstihdam","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi cari ücrete razı kişilerin iş bulamama durumunu ifade etmektedir?","options":[{"key":"A","text":"İradi işsizlik"},{"key":"B","text":"Yapısal işsizlik"},{"key":"C","text":"Gayrı-iradi işsizlik"},{"key":"D","text":"Friksiyonel işsizlik"},{"key":"E","text":"Konjoktürel işsizlik"}],"answerText":"Gayrı-iradi işsizlik","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Bir ekonomide emek-yoğun teknolojilerde görülen işsizlik türü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Yapısal işsizlik"},{"key":"B","text":"Gayrı-iradi işsizlik"},{"key":"C","text":"İradi işsizlik"},{"key":"D","text":"Gizli işsizlik"},{"key":"E","text":"Friksiyonel işsizlik"}],"answerText":"Gizli işsizlik","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üretim hacminde zaman zaman ortaya çıkan daralmanın yarattığı işsizlik türü hangisidir?","options":[{"key":"A","text":"Yapısal işsizlik"},{"key":"B","text":"Gizli işsizlik"},{"key":"C","text":"İradi işsizlik"},{"key":"D","text":"Konjonktürel işsizlik"},{"key":"E","text":"Friksiyonel işsizlik"}],"answerText":"Konjonktürel işsizlik","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşsizlik oranı nasıl hesaplanmaktadır ?","options":[{"key":"A","text":"İşsiz sayısı - Gizli işsiz"},{"key":"B","text":"İşsizlik oranı-Doğal işsizlik"},{"key":"C","text":"Faal nüfus / Toplam nüfus"},{"key":"D","text":"İşgücü / Toplam nüfus"},{"key":"E","text":"İşsiz sayısı / İşgücü x100"}],"answerText":"İşsiz sayısı / İşgücü x100","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ekonomi üzerinde en az olumsuz etkiye sahip olan işsizlik türü aşağıdakilerden hangisidir ?","options":[{"key":"A","text":"Konjoktürel işsizlik"},{"key":"B","text":"Friksiyonel işsizlik"},{"key":"C","text":"Mevsimlik işsizlik"},{"key":"D","text":"Teknolojik işsizlik"},{"key":"E","text":"Yapısal işsizlik"}],"answerText":"Friksiyonel işsizlik","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi talep ve üretimdeki değişikliklere uyum sağlanamadığından ortaya çıkan işsizlik\nçeşididir ?","options":[{"key":"A","text":"Friksiyonel işsizlik"},{"key":"B","text":"Yapısal işsizlik"},{"key":"C","text":"Gizli işsizlik"},{"key":"D","text":"İradi işsizlik"},{"key":"E","text":"Gayrı İradi işsizlik"}],"answerText":"Yapısal işsizlik","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Reel GSYİH’nın potansiyel GSYİH’nın gerisinde kalması sonucu oluşan işsizliğe ne denir?","options":[{"key":"A","text":"Yapısal"},{"key":"B","text":"Mevsimsel"},{"key":"C","text":"Konjonktürel"},{"key":"D","text":"Gizli"},{"key":"E","text":"Friksiyonel"}],"answerText":"Konjonktürel","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işsizlik süresini etkileyen faktörlerden biri değildir?","options":[{"key":"A","text":"Demografik yapı"},{"key":"B","text":"İş ve işçi bulma kurumu"},{"key":"C","text":"İşsizlik sigortası"},{"key":"D","text":"İşgücü mobilitesi"},{"key":"E","text":"İşçi talebi"}],"answerText":"İşçi talebi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Para","cards":["· Para, insanlar ve ülkeler arasında el değiştirerek ticari faaliyetlerin yürütülmesini sağlamaktadır. Paranın temel\nözelliklerini beş başlık altında sıralamak mümkündür. Homojen, Taşınabilir, Dayanıklı, Bölünebilir olması ve Taklit\nedilememesidir.","Paranın üç fonksiyonu vardır. Değer ölçüsü ve hesap birimi olma fonksiyonu, ortak değer ölçüsü olarak para; mal\nve hizmetin ne kadar para birimi karşılığında el değiştireceğini gösterir ki bu da o mal ve hizmetin fiyatını belirler.","Paranın mübadele aracı olma fonksiyonu, mal ve hizmetlerin el değiştirmesi sürecini kolaylaştıran ve hızlandıran\nbir işlev kazandırmaktadır.","Paranın değer olarak saklanması fonksiyonu, paranın saklanması birçok mala göre daha kolaydır. Tasarrufun para\nhalinde saklanması, tasarruf sahibine bunu istediği gibi kullanma imkânını vermektedir.","Para çeşitleri üç grupta toplanmaktadır. Birincisi madeni paralar olarak da tanımlanan mal paralar, ikincisi senetler,\nsertifikalar ve banknotları kapsayan temsili paralar, üçüncüsü ise banka parası olarak da tanımlanan kaydi paradır.","Paranın icadından önceki çağlarda, mübadelelerde aracı olarak kullanılan değerler mal para şeklindedir.","Başlangıçta bazı gıda maddeleri para yerine kullanılmıştır. Daha sonra ilk para çeşidi olarak gümüş ve altın paraların\nkullanıldığı görülmektedir.","Ekonominin gelişmesi ile altın ve gümüş paraların taşınmasının ve korunmasının güçleşmesi temsili paraların\nortaya çıkmasına sebep olmuştur. Temsili paralar dört çeşittir."],"questions":[{"q":"Mal, hizmet, borç ve alacaklarda değer ölçüsü olarak genel kabul gören araca ne denir?","options":[{"key":"A","text":"Para"},{"key":"B","text":"Çek"},{"key":"C","text":"Kredi"},{"key":"D","text":"Mevduat"},{"key":"E","text":"Likidite"}],"answerText":"Para","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi para fonksiyonu mal ve hizmetlerin el değiştirmesi sürecini kolaylaştırmaktadır?","options":[{"key":"A","text":"Hesap birimi olma"},{"key":"B","text":"Değişim aracı olma"},{"key":"C","text":"İktisat politikası aracı olma"},{"key":"D","text":"Değer muhafaza aracı olma"},{"key":"E","text":"Finansal yeniliklere olanak tanıma"}],"answerText":"Değişim aracı olma","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi özellik paranın özelliklerinden biri değildir?","options":[{"key":"A","text":"Toplum tarafından genel kabul görmesi"},{"key":"B","text":"Ağırlığına göre yüksek bir değere sahip olması"},{"key":"C","text":"Bozulmaması ve taşınmaya elverişli olması"},{"key":"D","text":"Homojen olması"},{"key":"E","text":"Hepsi"}],"answerText":"Ağırlığına göre yüksek bir değere sahip olması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangisi paranın geleneksel fonksiyonlarından biri değildir?","options":[{"key":"A","text":"Hesap birimi yani, değer ölçüsü olması"},{"key":"B","text":"Faiz oranının belirleyicisi olması"},{"key":"C","text":"Mübadele aracı olması"},{"key":"D","text":"Tasarruf yani, değer biriktirme aracı olması"},{"key":"E","text":"Hiçbiri"}],"answerText":"Faiz oranının belirleyicisi olması","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangisi paranın modern fonksiyonlarından değildir?","options":[{"key":"A","text":"Ekonomik faaliyetlerde etkin olması"},{"key":"B","text":"Gelirleri yeniden dağıtıcı olması"},{"key":"C","text":"Nüfuz aracı olması"},{"key":"D","text":"Değişim ve ödeme aracı olması"},{"key":"E","text":"Hiçbiri"}],"answerText":"Nüfuz aracı olması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Ekonomideki fiyat istikrarsızlıkları paranın hangi fonksiyonuna etki etmektedir?","options":[{"key":"A","text":"Hesap birimi olma"},{"key":"B","text":"Değer saklama aracı olma"},{"key":"C","text":"Değişim aracı olma"},{"key":"D","text":"Finansal nitelik tasıma"},{"key":"E","text":"En likit varlık olma"}],"answerText":"Değer saklama aracı olma","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Paranın tasarruf olarak saklanması sonucu kişiye bunu istediği gibi kullanma imkânını veren unsur\naşağıdakilerden hangisi değildir?","options":[{"key":"A","text":"Bankaya yatırabilir"},{"key":"B","text":"Hisse senedi alabilir"},{"key":"C","text":"Tahvil satın alabilir"},{"key":"D","text":"Taşınmaz mallar edinebilir"},{"key":"E","text":"Alış-verişte kullanabilir."}],"answerText":"Alış-verişte kullanabilir.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi altın ve gümüşe çevrilebilen para çeşididir?","options":[{"key":"A","text":"Banknot"},{"key":"B","text":"Kâğıt para"},{"key":"C","text":"Temsili para"},{"key":"D","text":"Mal para"},{"key":"E","text":"Sikke"}],"answerText":"Temsili para","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi hem mal hem de değişim aracı olarak kullanılan para çeşididir?","options":[{"key":"A","text":"Kaydi para"},{"key":"B","text":"Mal para"},{"key":"C","text":"İtibari para"},{"key":"D","text":"Asli para"},{"key":"E","text":"Bozukluk para"}],"answerText":"Mal para","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi banka parasını tanımlamaktadır?","options":[{"key":"A","text":"Mevduat"},{"key":"B","text":"Kredi"},{"key":"C","text":"Kaydi para"},{"key":"D","text":"Nakdi olmayan para"},{"key":"E","text":"Banknot"}],"answerText":"Kaydi para","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"Para Politikası","cards":["· Para politikası bir ülkede hükümetlerin belirli ekonomik amaçları gerçekleştirmek için ekonominin likiditesini\ndeğiştirmek üzere kredi, para arzı ve faiz oranları ile ilgili olarak yaptığı düzenlemelerdir. Para politikalarının\ndüzenlenmesinde Merkez Bankaları önemli rol oynamaktadır.","Para politikasının amacı, para arzını belirleyerek; fiyat istikrarını, toplam talebi, faiz oranını, milli geliri,\nistihdam düzeyi ile ödemeler bilançosu dengesini etkilemektir. Para politikasının amaçları beş başlık altında toplanabilir.","Bunlar tam istihdam, fiyat istikrarı, faiz oranı istikrarı, ekonomik büyüme ve ödemeler bilançosu dengesidir.","Para politikasını uygularken kullandıkları araçlar dört tanedir. Bunlar; açık piyasa işlemleri, reeskont oranları,\nkanuni karşılıklar ve kredi tavanıdır.","Açık piyasa işlemleri, Merkez Bankası tarafından hazine bonosu, devlet tahvili ve döviz alım satımı yaparak para\narzını belirlediği önemli araçlardan birisidir.\no Bankalar nakit ihtiyacı içinde oldukları zaman merkez bankasından borçlanabilmektedir. Buna göre merkez\nbankasının bankalara verdiği kredilere uyguladığı faiz oranına reeskont oranı adı verilmektedir.","Merkez bankası zorunlu karşılık oranını yükselttiğinde bankalar daha büyük miktarı rezerv olarak tutmak\nzorunda kalmakta, yaratacakları kaydi para azalmaktadır. Tersi durumunda ise zorunlu karşılık oranı düşürülmekte,\ndaha az rezerv tutma nedeniyle bankaların yaratacağı kaydi para miktarı artmaktadır.","Merkez Bankası ticari bankaların çeşitli ekonomik faaliyetleri ile ilgili olarak açacakları kredilere bir tavan\ngetirebilir. Böylece Merkez Bankası kredi hacmini ekonomik gelişmeler doğrultusunda ayarlama imkânına sahip\nolmaktadır.","Merkez bankalarının uyguladığı para politikasının değişen koşullar ile ekonomik aktörleri etkileme gücüne\nuyumlu olması açısından belli kurallara göre uygulanması söz konusudur. Para politikası otoritelerinin uygulayacakları\nüç temel kural bulunmaktadır. Bunlar; Para arzı hedeflemesi, nominal GSYH hedeflemesi ve enflasyon hedeflemesidir."],"questions":[{"q":"Hangisi Merkez bankasının kullandığı para politikası araçlarından biri değildir?","options":[{"key":"A","text":"Faiz oranı istikrarı"},{"key":"B","text":"Kanuni karşılık"},{"key":"C","text":"Reeskont oranı"},{"key":"D","text":"Açık piyasa işlemleri"},{"key":"E","text":"Kredi tavanı"}],"answerText":"Faiz oranı istikrarı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Para politikasının temel amacı aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Fiyat istikrarını sağlamak"},{"key":"B","text":"Tam istihdamı sağalmak"},{"key":"C","text":"Yüksek ve dengeli büyümeyi gerçekleştirmek"},{"key":"D","text":"Ödemeler dengesini sağlamak"},{"key":"E","text":"Hepsi"}],"answerText":"Fiyat istikrarını sağlamak","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi para politikasının temel amaçlarından biri değildir?","options":[{"key":"A","text":"Fiyat İstikrarı"},{"key":"B","text":"Bütçe Dengesi"},{"key":"C","text":"Tam İstihdam"},{"key":"D","text":"Faiz İstikrarı"},{"key":"E","text":"Finansal Piyasalarda İstikrar"}],"answerText":"Bütçe Dengesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Hangi para politikası aracında doğrudan alım, doğrudan satım işlemi yapılmaktadır?","options":[{"key":"A","text":"Reeskont Politikası"},{"key":"B","text":"Açık Piyasa İşlemleri"},{"key":"C","text":"Kanuni Karşılık Politikası"},{"key":"D","text":"Disponibilite Oranı"},{"key":"E","text":"Hepsi"}],"answerText":"Açık Piyasa İşlemleri","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi zorunlu karşılık oranının uygulanma amacını ifade etmektedir?","options":[{"key":"A","text":"Fiyatlar genel düzeyini kontrol etmek"},{"key":"B","text":"Ülkedeki para miktarını kontrol etmek"},{"key":"C","text":"Banka ihtiyatlarını muhafaza etmek"},{"key":"D","text":"Kaydi para yaratmak"},{"key":"E","text":"Kısmi rezerve destek olmak"}],"answerText":"Ülkedeki para miktarını kontrol etmek","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Para politikasının amaçlarından biri olmayan kavram aşağıdakilerden hangisidir ?","options":[{"key":"A","text":"Tam istihdam"},{"key":"B","text":"Fiyat istikrarı"},{"key":"C","text":"Ekonomik büyüme"},{"key":"D","text":"Kredi tavanı"},{"key":"E","text":"Tasarruf artışı"}],"answerText":"Kredi tavanı","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Para politikasının araçlarından biri olmayan kavram aşağıdakilerden hangisidir ?","options":[{"key":"A","text":"Finansal istikrar"},{"key":"B","text":"Kanuni karşılık"},{"key":"C","text":"Reeskont oranı"},{"key":"D","text":"Açık piyasa işlemleri"},{"key":"E","text":"Kredi tavanı"}],"answerText":"Finansal istikrar","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Merkez Bankası aşağıdakilerden hangisini açık piyasa işlemlerini gerçekleştirirken kullanmamaktadır?","options":[{"key":"A","text":"Hazine Bonosu"},{"key":"B","text":"B-Tipi likit fon"},{"key":"C","text":"Döviz"},{"key":"D","text":"Devlet tahvili"},{"key":"E","text":"Repo"}],"answerText":"B-Tipi likit fon","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Reeskont oranının yükseltilmesi ekonomide nasıl bir durumu ifade etmektedir?","options":[{"key":"A","text":"Stagflasyon"},{"key":"B","text":"Deflasyon"},{"key":"C","text":"Enflasyon"},{"key":"D","text":"Devalüasyon"},{"key":"E","text":"Revalüasyon"}],"answerText":"Enflasyon","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangi durum zorunlu karşılık oranlarının yükseltilmesi sonucu bankaları riskle karşı karşıya\nbırakmaktadır?","options":[{"key":"A","text":"Merkez Bankasından borçlanmasını zorlaştırmakta"},{"key":"B","text":"Kredileri arttırma zorunluluğu"},{"key":"C","text":"Faiz oranında istikrarsızlık"},{"key":"D","text":"Likidite sıkışıklığı"},{"key":"E","text":"Likidite bolluğu"}],"answerText":"Likidite sıkışıklığı","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]}]},"islet":{"name":"İşletme Yönetimi","code":"AIKY1001","file":"Ders _ İŞLETME YÖNETİMİ - eKitap.txt","color":"#1d4ed8","units":["İşletme ile İlgili Temel Kavramlar","İşletmeciliğin Tarihsel Gelişimi","İşletmecilik Bilim Dalının Diğer Bilim Dalları ile İlişkisi ve Temel İlkeleri","İşletmenin Dış Çevresi ile Ekonomik ve Sosyal Yapı İçindeki Yeri","İşletmelerin Sınıflandırılması","İşletmenin Kuruluş Çalışmaları","İşletme Fonksiyonları - 1","İşletmecilik Fonksiyonları - 2"],"unitData":[{"title":"İşletme ile İlgili Temel Kavramlar","cards":["· Kitabımızın bu bölümünde ilk önce insan ihtiyaçları tanımlanmış ve ihtiyaçlarla ilgili sınıflamalardan bahsedilmiştir. Öncelikle birincil ve ikincil ihtiyaçlar\nayrımı söz konusudur. Birincil ihtiyaçlar insanda doğuştan varolan ve yaşamsal nitelikte olan ihtiyaçları kapsamaktadır. Bu tür ihtiyaçlar insan vücudunda\ndengenin oluşturulması ve bunun korunmasına yönelik ihtiyaçlardır. Sosyal ve kişisel ihtiyaçlar adı da verilen ikincil ihtiyaçlar ise kişilerin toplumsal\nilişkilerinden ve görevlerinden veya kişisel arzularından doğan ihtiyaçlardır.","Amerikalı ünlü psikolog Abraham H. Maslow (1908 – 1970) tarafından 1943 yılında ortaya konulan “İhtiyaçlar Hiyerarşisi” psikoloji ve işletme bilim\ndallarında önemli bir yer tutmaktadır. Maslow’a göre insan ihtiyaçları en alt seviyeden en üst seviyeye doğru yükselen bir hiyerarşiye sahiptir. İlk seviyede\nfizyolojik ihtiyaçlar, ikinci seviyede güvenlik ihtiyacı, üçüncü seviyede ait olma ve sevgi ihtiyacı, dördüncü seviyede saygı ve takdir edilme ihtiyacı ve beşinci\nseviyede de kendini gerçekleştirme ihtiyacı bulunmaktadır. Maslow’a göre insan ihtiyaçları belirli bir hiyerarşik sıra izler, alt kademedeki ihtiyaçlar\ngiderilmeden, üst kademedeki ihtiyaçlar kişiyi davranışa sevk edemez.","İnsanların ihtiyaçlarını giderme niteliği ya da faydası taşıyan mal ve hizmetlere “ekonomik mal ve hizmetler” denmektedir. Ekonomik mal ve hizmetler,\ninsan ihtiyaçlarını tatmine yarayan, ancak doğrudan herkese yetecek kadar bol bulunmayan (kıt olan) ve elde edilmeleri belirli bir çaba harcanmasını gerektiren\nmaddelerdir.","Mal veya hizmetlerin insanların ihtiyaçlarını giderme niteliğine “fayda” denilmekte olup işletmeler şekil değişikliği ile, zaman değişikliği ile, yer\ndeğişikliği ile ve mülkiyet değişikliği ile olmak üzere başlıca dört şekilde fayda yaratırlar.","Üretim; “faydalı mal ve hizmetlerin oluşturulması, depolanması, taşınması ve satılması vb. faaliyetlerin tümünü kapsayan bir süreçtir. Üretilen mal\nve/veya hizmetleri talep eden ve tüketen kişilere ”tüketici” denir. Tüketiciler, bu mal ve/veya hizmetlere bir bedel (para) ödeyerek sahip olmaktadırlar.","Üretimi gerçekleştirebilmek için insanlar üretim faktörleri adı verilen birtakım faktörlere ihtiyaç duymaktadırlar. Üretim faktörleri genel olarak dörde\n(doğal kaynaklar, emek, sermaye, girişimci) ayrılmakla birlikte son yıllarda beşinci faktör olarak “bilgi” de üretim faktörleri arasında yerini almıştır.","Girişimci ya da müteşebbis denilen kişi üretim faktörlerini başkalarının ihtiyaçlarını karşılayacak mal ve/veya hizmetler üretmek üzere tedarik eden,\nuygun şekilde birleştiren ve bunların sonucundaki riske katlanan kişidir. Girişimcinin asıl amacı kar elde etmektir ve kendisi de bir üretim faktörüdür. Girişimci\niş fırsatlarını elde etmek için girişimlerde bulunur. Yönetici ise kar ve riski başkalarına ait olmak üzere, üretim faktörlerini tedarik ederek onları mal ve/veya\nhizmet üretmek için yöneten kişidir. Profesyonel yönetici de denilen yönetici, aynı faaliyeti başkaları adına belli bir maaş karşılığında yapar; yani yönetim bir\nmeslek haline gelmiştir.","Kişilerin ihtiyaçlarını karşılamak amacına dayanarak üretim faktörlerini uyumlu bir şekilde bir araya getirip ekonomik mal ve hizmet üretmek ve/veya\npazarlamak için faaliyette bulunan ekonomik birimlere “işletme” denir."],"questions":[{"q":"İnsanları tek başlarına ya da birlikte çalışmaya iten temel itici güç aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Davranış"},{"key":"B","text":"Düşünce"},{"key":"C","text":"İhtiyaç"},{"key":"D","text":"Duygu"},{"key":"E","text":"Emek"}],"answerText":"İhtiyaç","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üretilen mal ve hizmetlerin insan ihtiyaçlarını tatmin etme niteliğine ne ad verilmektedir?","options":[{"key":"A","text":"Fayda"},{"key":"B","text":"Hizmet"},{"key":"C","text":"İhtiyaç"},{"key":"D","text":"Yönetim"},{"key":"E","text":"Tüketici"}],"answerText":"Fayda","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerin hangisi işletmelerin fayda yaratma şekillerinden değildir?","options":[{"key":"A","text":"Şekil değişikliği ile fayda yaratma"},{"key":"B","text":"Zaman değişikliği ile fayda yaratma"},{"key":"C","text":"Yer değişikliği ile fayda yaratma"},{"key":"D","text":"Değer değişikliği ile fayda yaratma"},{"key":"E","text":"Mülkiyet değişikliği ile fayda yaratma"}],"answerText":"Değer değişikliği ile fayda yaratma","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Üretilen mal ve/veya hizmetleri talep eden ve tüketen kişilere ne denir?","options":[{"key":"A","text":"Tüketici"},{"key":"B","text":"Üretici"},{"key":"C","text":"Girişimci"},{"key":"D","text":"Yönetici"},{"key":"E","text":"Çalışan"}],"answerText":"Tüketici","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Malların sınırlı olduğu zamanlarda pazara sunulmak üzere depolanması ve muhafaza edilmesiyle ilgili faaliyetler” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Şekil değişikliği ile fayda yaratma"},{"key":"B","text":"Zaman değişikliği ile fayda yaratma"},{"key":"C","text":"Yer değişikliği ile fayda yaratma"},{"key":"D","text":"Değer değişikliği ile fayda yaratma"},{"key":"E","text":"Mülkiyet değişikliği ile fayda yaratma"}],"answerText":"Zaman değişikliği ile fayda yaratma","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmelerin genel amaçlarını en doğru biçimde ifade eder?","options":[{"key":"A","text":"Karlılık-Toplumsal fayda-Süreklilik"},{"key":"B","text":"Karlılık-Rekabet-Süreklilik"},{"key":"C","text":"Toplumsal fayda-Rekabet-Maliyetlerin düşürülmesi"},{"key":"D","text":"Süreklilik-Pazar payının arttırılması-Maliyetlerin düşürülmesi"},{"key":"E","text":"Kalite-Karlılık-Süreklilik"}],"answerText":"Karlılık-Toplumsal fayda-Süreklilik","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ekonomik olarak kar kavramının gösterimi olabilir?","options":[{"key":"A","text":"Ekonomik Kar = İşletme Gelirleri - İşletme Giderleri"},{"key":"B","text":"Ekonomik Kar = İşletme Giderleri - İşletme Gelirleri"},{"key":"C","text":"Ekonomik Kar = İşletme Harcamaları - İşletme Kazançları"},{"key":"D","text":"Ekonomik Kar = İşletmedeki Üretim Tutarı - İşletmedeki Satış Tutarı"},{"key":"E","text":"Ekonomik Kar = İşletme Alacakları - İşletme Borçları"}],"answerText":"Ekonomik Kar = İşletme Gelirleri - İşletme Giderleri","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi birincil ihtiyaçlara örnek olarak verilemez?","options":[{"key":"A","text":"Karnını doyurmak"},{"key":"B","text":"Su içmek"},{"key":"C","text":"Lüks bir araba satın almak"},{"key":"D","text":"Uyumak"},{"key":"E","text":"Giyinmek"}],"answerText":"Lüks bir araba satın almak","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İnsanların ihtiyaçlarını giderme niteliği ya da faydası taşıyan mal ve hizmetler”e ne ad verilir?","options":[{"key":"A","text":"Karlı mal ve hizmetler"},{"key":"B","text":"Verimli mal ve hizmetler"},{"key":"C","text":"Ekonomik mal ve hizmetler"},{"key":"D","text":"Etkin mal ve hizmetler"},{"key":"E","text":"Sürekli mal ve hizmetler"}],"answerText":"Ekonomik mal ve hizmetler","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Birincil ihtiyaçların temel özelliği nedir?","options":[{"key":"A","text":"Kişisel gelişim ile bağlantılıdır."},{"key":"B","text":"Çevreden öğrenilir."},{"key":"C","text":"Maddi olmayan araçlarla tatmin edilir."},{"key":"D","text":"Fizyolojik dengeyi korumaya yöneliktir."},{"key":"E","text":"Sosyal statüye dayanır."}],"answerText":"Fizyolojik dengeyi korumaya yöneliktir.","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Maslow’a göre bir alt seviyedeki ihtiyaç karşılanmadan bir üst seviyeye geçilememesi hangi kavramı ifade eder?","options":[{"key":"A","text":"Fayda"},{"key":"B","text":"Motivasyon"},{"key":"C","text":"Hiyerarşi"},{"key":"D","text":"Girişimcilik"},{"key":"E","text":"Arz"}],"answerText":"Hiyerarşi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Girişimcinin temel amacı nedir?","options":[{"key":"A","text":"Risk almamak"},{"key":"B","text":"Kâr elde etmek"},{"key":"C","text":"Bilgi birikimini artırmak"},{"key":"D","text":"Çalışanların ihtiyaçlarını karşılamak"},{"key":"E","text":"İş süreçlerini düzenlemek"}],"answerText":"Kâr elde etmek","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmeciliğin Tarihsel Gelişimi","cards":["· Sanayi Devrimi olarak anılan ve çeşitli icatlarla desteklenerek büyük üretim artışları sağlayan gelişmeler, el sanatları ve ev sanayisinin küçük ve dağınık\nüretim birimlerinin bir çatı altında toplanmasını ve merkezileşmesini, fabrika sisteminin oluşmasını sağlamıştır. Böylece Sanayi Devrimi’nden bu yana\nişletmelerin, sayı ve büyüklükleri artmış, bünyeleri karmaşıklaşmış ve faaliyet alanları çeşitlenmiştir.","Bilimsel Yönetim Yaklaşımının kurucusu olan Frederick Winslow Taylor (1856-1915), uzun yıllar süren çalışmalarında bilimsel metodlar uygulayan","Taylor, zamanının büyük bir kısmını imalathanedeki üretim faaliyetlerini incelemekle geçirerek işçilik, hammadde ve malzemede büyük ölçüde israf olduğunu\nsaptamış, bunu önleyerek verimliliği arttırmanın yollarını aramıştır.","Yönetim Süreci Yaklaşımının kurucusu olan Fransız maden mühendisi Jules Henri Fayol (1841 - 1925), “büyük bir işletmenin genel yönetim ilkelerini”\nsistemli bir şekilde ortaya koymuştur. Fayol bir sanayi işletmesinde bulunan fonksiyonları sınıflandırmış ve aynı zamanda yönetimi tanımlayarak çeşitli\naşamaları olan bir süreç olduğunu ortaya koymuştur.","Bürokrasi Yaklaşımı diye adlandırılan bir örgüt teorisi geliştiren Alman düşünürü Max Weber işletme yönetiminin bir bilim dalı olarak gelişmesinde büyük\nrol oynamıştır.","Davranışsal Yaklaşım, psikoloji, sosyoloji ve sosyal psikoloji alanlarındaki bulguların ve geliştirilen yöntemlerin, İşletme Yönetiminin bir parçası olan\nörgütsel davranış biçimlerinin anlaşılması için kullanılmasına dayanmaktadır. Hawthorne araştırmaları bu dönem çalışmaların en önemli örneklerinden biridir.","Modern yönetim yaklaşımları II. Dünya Savaşından sonra geliştirilmiş teoriler olup, Sistem Yaklaşımı ve Durumsallık Yaklaşımı olmak üzere iki alt\nbaşlıkta incelenmektedir. Sistem yaklaşımı işletmeyi bir açık sistem olarak tanımlayıp işletmenin girdi olarak çevreden enerji bilgi ve malzeme aldığını ve\nbunları dönüşüme uğratarak çevreye çıktı olarak verdiğini kabul eder.","Durumsallık yaklaşımı, her işletmenin ve yönetim olayının, farklı çevresel faktörler ve konumlarından dolayı birbirinden farklı olduğunu varsayar ve her\nişletme ve yönetim sorunu için “sadece bir doğru çözüm” olduğu ilkesini reddeder."],"questions":[{"q":"İnsan organizmasını basit bir makine, insanlardan oluşan geleneksel örgüt yapısını da teknik bir sistem olarak gören yaklaşım aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Toplam kalite yönetimi yaklaşımı"},{"key":"B","text":"Sistem yaklaşımı"},{"key":"C","text":"Durumsallık yaklaşımı"},{"key":"D","text":"Neoklasik yaklaşım"},{"key":"E","text":"Klasik yaklaşım"}],"answerText":"Klasik yaklaşım","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Joan Woodward 1953-1957 yılları arasında İngiltere’de yaptığı araştırmada hangi iki değişken arasındaki ilişkiyi ele almıştır?","options":[{"key":"A","text":"Organizasyon yapısı-teknoloji ilişkisi"},{"key":"B","text":"Organizasyon yapısı-iç çevre ilişkisi"},{"key":"C","text":"Organizasyon yapısı-dış çevre ilişkisi"},{"key":"D","text":"Organizasyon yapısı-hükümet ilişkisi"},{"key":"E","text":"Organizasyon yapısı-sendikalar ilişkisi"}],"answerText":"Organizasyon yapısı-teknoloji ilişkisi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Durumsallık yaklaşımı çerçevesinde aşağıdaki hangi iki araştırmacı organizasyon - çevre ilişkisini inceleyen bir çalışma yapmışlardır?","options":[{"key":"A","text":"Jeffrey Pfeffer - Gerald Salancik"},{"key":"B","text":"Henri Fayol - Frederick Taylor"},{"key":"C","text":"Tom Burns - G.M. Stalker"},{"key":"D","text":"Elton Mayo - Henri Fayol"},{"key":"E","text":"Joan Woodward - Frederick Taylor"}],"answerText":"Tom Burns - G.M. Stalker","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Popülasyon ekolojisi yaklaşımının öncüleri aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Jeffrey Pfeffer - Gerald Salancik"},{"key":"B","text":"Henri Fayol - Frederick Taylor"},{"key":"C","text":"Tom Burns - G.M. Stalker"},{"key":"D","text":"Michael Hannan - John Freeman"},{"key":"E","text":"Elton Mayo - Henri Fayol"}],"answerText":"Michael Hannan - John Freeman","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Meşruiyetini akıl ve kurallardan alan yetki türü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Klasik yetki"},{"key":"B","text":"Neoklasik yetki"},{"key":"C","text":"Geleneksel yetki"},{"key":"D","text":"Rasyonel yetki"},{"key":"E","text":"Karizmatik yetki"}],"answerText":"Rasyonel yetki","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdaki yaklaşımlardan hangisi Henri Fayol tarafından geliştirilmiştir?","options":[{"key":"A","text":"Yönetim Süreci Yaklaşımı"},{"key":"B","text":"Bürokratik Yönetim Yaklaşımı"},{"key":"C","text":"Bilimsel Yönetim Yaklaşımı"},{"key":"D","text":"Durumsallık Yaklaşımı"},{"key":"E","text":"Neoklasik Yönetim Yaklaşımı"}],"answerText":"Yönetim Süreci Yaklaşımı","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmecilikte klasik yaklaşım araştırmacılarından biridir?","options":[{"key":"A","text":"Ludwig von Bertalanfy"},{"key":"B","text":"Peter Drucker"},{"key":"C","text":"Elton Mayo"},{"key":"D","text":"Frederick Taylor"},{"key":"E","text":"Chris Argyris"}],"answerText":"Frederick Taylor","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi yönetimin fonksiyonlarından biri değildir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Örgütleme"},{"key":"C","text":"Pazarlama"},{"key":"D","text":"Koordinasyon"},{"key":"E","text":"Denetim"}],"answerText":"Pazarlama","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Henri Fayol’a göre bir sanayi işletmesinde bulunan başlıca faaliyetlerden değildir?","options":[{"key":"A","text":"Teknik Faaliyetler"},{"key":"B","text":"Ticari Faaliyetler"},{"key":"C","text":"Pazarlama Faaliyetleri"},{"key":"D","text":"Mali Faaliyetler"},{"key":"E","text":"Güvenlik Faaliyetleri"}],"answerText":"Pazarlama Faaliyetleri","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Weber’in görüşlerinden biri değildir?","options":[{"key":"A","text":"Açık - seçik belirlenmiş bir hiyerarşik yapı ve dolayısıyla her kademenin bir üst kademe tarafından kontrol edilmesi."},{"key":"B","text":"Her kademede işlerin yapılışına ilişkin pozisyonlara gelen herkesin uyacağı ilke ve yöntemler"},{"key":"C","text":"Rasyonel ve ilkeler doğrultusunda (kişisel ve duygusal olmayan) ilişkiler."},{"key":"D","text":"Teknik yeteneğe dayalı personel seçimi ve terfi sistemi."},{"key":"E","text":"Örgüt (organizasyon) birimlerinin karizmatik yetkilerle birbirine bağlanması."}],"answerText":"Örgüt (organizasyon) birimlerinin karizmatik yetkilerle birbirine bağlanması.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Henri Fayol’a göre aşağıdakilerden hangisi bir yönetim fonksiyonu değildir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Muhasebe"},{"key":"C","text":"Yürütme"},{"key":"D","text":"Örgütleme"},{"key":"E","text":"Kontrol"}],"answerText":"Muhasebe","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sanayi Devrimi’nin işletmeciliğe getirdiği en önemli sonuçlardan biri nedir?","options":[{"key":"A","text":"İnsan gücüne duyulan ihtiyacın artması"},{"key":"B","text":"Küçük ölçekli atölyelerin sayıca artması"},{"key":"C","text":"Yönetimin profesyonel yöneticilere devredilmesi"},{"key":"D","text":"Geleneksel tarım yöntemlerine dönülmesi"},{"key":"E","text":"Ticari faaliyetlerin durması"}],"answerText":"Yönetimin profesyonel yöneticilere devredilmesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmecilik Bilim Dalının Diğer Bilim Dalları ile İlişkisi ve Temel İlkeleri","cards":["· İşletme bilimi tüm çabalarında çeşitli bilim dallarının bilgi birikiminden yararlanmaktadır. İşletme disiplini aralarındaki etkileşim nedeniyle, işletmeyi\nçeşitli yönlerden inceleme konusu olarak alan iktisat, davranış bilimleri, hukuk, matematik-istatistik ve bilgi teknolojileri gibi diğer disiplinlerdeki gelişmeleri\nyakından izlemek durumundadır.","İşletme bilimi, iktisat bilim dalı ile yakın ilişki ve etkileşim içindedir. Girişimciler ve işletme yöneticileri, mal ve hizmet piyasalarında değişen arz ve talep\nilişkilerini, rekabet piyasalarında firma davranışlarını, devletin para ve maliye politikaları sonucunda değişen dengeleri, fiyat değişimlerini, dış ticaret teşvik ve\nengellerini anlayabilmek için iktisat biliminin temelleri ile ilgili bilgi sahibi olmak durumundadırlar.","Davranış bilimleri, birey veya grup halindeki insanların tutumlarını, özelliklerini ve etkileşimlerini inceleyip sonuçlara varmaya çalışan toplumsal\nbilimlerin bir alt grubunu oluşturur. İnsan unsurunu hem tek olarak, hem de belli bir topluma mensup olarak ele alıp çeşitli yönleriyle inceleyen başlıca davranış\nbilim dalları olan psikoloji, endüstriyel psikoloji, sosyoloji ve sosyal psikoloji işletme bilimine çeşitli yararlar sağlamaktadır.","İşletmeler kuruluş aşamalarını tamamlayıp üretime geçtikten sonra ekonomik sipariş miktarı, stok kontrolü, maliyet minimizasyonu ve kâr\nmaksimizasyonu gibi konularda karşılaştıkları sorunlara sağlıklı çözümler bulmak ve tüm faaliyetlerine ilişkin zamanında ve rasyonel kararlar alabilmek için\nmatematiksel ve istatiksel tekniklerden büyük ölçüde yararlanırlar.","Bir toplumda düzeni sağlamak amacıyla yürürlükte bulunan yasalar, tüzük ve yönetmeliklerle, yazılı olan ve olmayan diğer kurallar bütününe\n“hukuk” denir. Toplumun sürekli bir dinamizm içinde olan kesimini oluşturan işletmelerle hukuk kuralları arasında sürekli bir ilişki vardır.","Bilgi teknolojileri günümüzde diğer üretim faktörlerinden daha önemli bir konuma gelmiştir. Teknolojinin hayati öneme sahip bir duruma gelmesi bilgiyi\nhızlı bir şekilde edinmenin önemini artırmış, bu da işletmelerin bilgiyi edinme çabalarına yönelmesine sebep olmuştur.","İşletmeciliğin temel ilkelerinden biri olan verimlilik, “belirli bir üretim miktarı ile bu üretimi elde etmek için kullanılan faktörler arasındaki oran” olarak\ntanımlanmaktadır. Bir faaliyetin verimli sayılabilmesi için, aynı miktarda girdi ile daha fazla çıktı sağlanması, aynı miktarda çıktının daha az girdi ile elde\nedilmesi veya çıktıdaki artışın girdideki artıştan daha yüksek düzeyde olması gerekir.","“Bir işletmenin amaçlarına ulaşma derecesi” etkinlik olarak tanımlanmaktadır. Verimlilik bir işi doğru yapmak iken etkinlik doğru işi yapmak olarak ifade\nedilebilir. Etkinlik; işçilik, hammadde, malzeme ve diğer tüm girdilerin işletme içinde belirlenen amaçlar doğrultusunda ne derece etkin kullanıldığının yani\nüretim faktörleri ya da üretimin kendisi için önceden belirlediği programın gerçekleştirme derecesini gösteren bir değerlendirme ölçütüdür."],"questions":[{"q":"Aşağıdakilerden hangisi iktisat biliminin konularından biri değildir?","options":[{"key":"A","text":"Gelir dağılımı"},{"key":"B","text":"Kalkınma"},{"key":"C","text":"İşveren sağlığı"},{"key":"D","text":"Fiyatlar genel düzeyi"},{"key":"E","text":"Enflasyon"}],"answerText":"İşveren sağlığı","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi endüstriyel psikolojinin çözebileceği sorunlar kapsamına girmemektedir?","options":[{"key":"A","text":"İş şartlarından şikâyetlerin artması"},{"key":"B","text":"Çalışma hızının azalması"},{"key":"C","text":"Yönetim Kurulu üye sayısının belirlenmesi"},{"key":"D","text":"Üretimde hatalı mamul sayısının artması"},{"key":"E","text":"Çalışanın işe ilgisinin azalması"}],"answerText":"Yönetim Kurulu üye sayısının belirlenmesi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"A İşletmesi, 5.000 TL maliyetler ürettiği ürünleri 7.500 TL’ye satmıştır. Bu işletmenin ekonomik verimlilik değeri aşağıdakilerden hangisidir?","options":[{"key":"A","text":"1.5"},{"key":"B","text":"1.25"},{"key":"C","text":"0.66"},{"key":"D","text":"1"},{"key":"E","text":"0.50"}],"answerText":"1.5","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi İşletme bilimi ile ilişkili olan bilim dalları arasında yer almaz?","options":[{"key":"A","text":"İktisat"},{"key":"B","text":"Davranış Bilimleri"},{"key":"C","text":"Patoloji"},{"key":"D","text":"Matematik"},{"key":"E","text":"Hukuk"}],"answerText":"Patoloji","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmelerde Matematik biliminden yararlanılan konulardan biri değildir?","options":[{"key":"A","text":"Talep tahmini"},{"key":"B","text":"Fiyatların belirlenmesi"},{"key":"C","text":"Çalışan sayısının belirlenmesi"},{"key":"D","text":"Yasal düzenlemelerin takip edilmesi"},{"key":"E","text":"Stokların hesaplanması"}],"answerText":"Yasal düzenlemelerin takip edilmesi","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir toplumda düzeni sağlamak amacıyla yürürlükte bulunan yasalar, tüzük ve yönetmeliklerle, yazılı olan ve olmayan diğer kurallar bütünü” aşağıdakilerden\nhangisidir?","options":[{"key":"A","text":"Politika"},{"key":"B","text":"Hukuk"},{"key":"C","text":"Töre"},{"key":"D","text":"Gelenek"},{"key":"E","text":"Kural"}],"answerText":"Hukuk","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İnsanların sınırsız ihtiyaçlarına kıt (sınırlı) ekonomik kaynaklarla çözüm bulmaya çalışan bilim” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"İşletme"},{"key":"B","text":"İktisat"},{"key":"C","text":"İstatistik"},{"key":"D","text":"Psikoloji"},{"key":"E","text":"Sosyoloji"}],"answerText":"İktisat","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"X işletmesi 2021 yılında toplam 90.000 TL maliyetle 5.000 adet mal üretip her birimini 30 TL’ye satmıştır. Bu dönemde işletmenin elde ettiği kar ne kadardır?","options":[{"key":"A","text":"40.000 TL"},{"key":"B","text":"50.000 TL"},{"key":"C","text":"60.000 TL"},{"key":"D","text":"70.000 TL"},{"key":"E","text":"80.000 TL"}],"answerText":"60.000 TL","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Özsermayesi 200.000.000 TL olan bir işletme 80.000.000 TL net kar elde etmişse özsermayenin karlılık oranı yüzde kaçtır?","options":[{"key":"A","text":"% 250"},{"key":"B","text":"% 40"},{"key":"C","text":"% 25"},{"key":"D","text":"% 50"},{"key":"E","text":"% 150"}],"answerText":"% 40","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Y İşletmesi 2021 yılında 500.000 TL net kar etmiştir. İşletmenin 2021 yılı satışları 2.500.000 TL ise net kar marjı yüzde kaçtır?","options":[{"key":"A","text":"% 5"},{"key":"B","text":"% 10"},{"key":"C","text":"% 15"},{"key":"D","text":"% 20"},{"key":"E","text":"% 25"}],"answerText":"% 20","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi iktisat biliminin cevap aradığı sorulardan biri değildir?","options":[{"key":"A","text":"Hangi mal ve hizmetler üretilmelidir?"},{"key":"B","text":"İşletme türleri nasıl sınıflandırılmalıdır?"},{"key":"C","text":"Üretim faktörleri nasıl organize edilmelidir?"},{"key":"D","text":"Toplumda adil bölüşüm nasıl sağlanmalıdır?"},{"key":"E","text":"Kıt kaynaklar nasıl temin edilebilir?"}],"answerText":"İşletme türleri nasıl sınıflandırılmalıdır?","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletme biliminin davranış bilimleriyle ilişkisi neden önemlidir?","options":[{"key":"A","text":"Hukuki düzenlemeleri anlamak için"},{"key":"B","text":"Çalışanların yalnızca ekonomik ihtiyaçlarını karşılamak için"},{"key":"C","text":"Stok kontrolü ve maliyet analizleri için"},{"key":"D","text":"İnsan faktörünün işletmelerdeki işlev ve önemini anlamak için"},{"key":"E","text":"Bilgi teknolojilerinin kullanımını artırmak için"}],"answerText":"İnsan faktörünün işletmelerdeki işlev ve önemini anlamak için","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmenin Dış Çevresi ile Ekonomik ve Sosyal Yapı İçindeki Yeri","cards":["· İşletmeler, birbirleriyle ilişkili olan çok sayıda değişkenin karşılıklı etkileşim içinde olduğu bir dış çevrede faaliyet gösterirler. Çevre; bir kişi ya da\ntopluluğu etkileyen fiziksel ve sosyal şartların toplamıdır.","İşletmenin genel dış çevresi, toplumun geniş kesimlerini, ekonomide bulunan sektörleri ve her sektördeki işletmeleri dolaylı yoldan etkileyebilecek\npotansiyele sahip, fırsat ve tehditler yaratabilecek öğelerden oluşur. Bunlar, Politik ve Yasal Çevre, Ekonomik Çevre, Demografik Çevre, Sosyal ve Kültürel","Çevre, Teknolojik Çevre ve Uluslararası Çevre olarak sınıflandırılır.","Politik çevre, işletmelerin faaliyette bulundukları ülkede, merkezi ve yerel yönetsel sistemin ve bunlara bağlı kuruluşların siyasi otoritesini sağladığı ve\nkullandığı ortam olarak adlandırılabilir. Politik çevrede bulunan unsurların işletmelere etkisi yönetenlerin çıkardıkları yasalar, yönetmelikler ve kararlarla olur,\nbunların bulunduğu ortama da hukuki (yasal) çevre denilmektedir.","Ekonomik çevre olarak adlandırılan ortam, toplumun gereksinimlerini karşılayacak mal ve hizmetlerin elde bulunan sınırlı kaynaklarla üretildiği,\ntüketildiği, kaynakların, malların, hizmetlerin ve gelirin bölüşüldüğü, yani her gün milyonlarca ekonomik faaliyete sahne olan ortamdır. Demografik çevre\nfaktörleri dendiğinde ülkedeki nüfusun miktarı ve yoğunluğu, yaş yapısı, coğrafi dağılımı, gelir dağılımı, eğitim düzeyi vb. özellikler akla gelir. Demografik\nçevre faktörleri işletmeleri etkiler.","Sosyal ve kültürel çevre ya da “sosyokültürel çevre” olarak adlandırılan çevre, başta eğitim ve kültür olmak üzere toplumsal inançlar, gelenekler,\ngörenekler, değer yargıları gibi bireylerin tüketim kalıplarını, eğilimlerini, tercihlerini ve satın alma alışkanlıklarını etkileyen faktörleri kapsamaktadır. Yeni\nbilgilerin yaratıldığı ve her ortamda uygulanarak ürün ve süreçlerde gelişmelere yolaçan faaliyetlerin oluşturduğu ortam teknolojik çevre olarak tanımlanabilir.","İşletmenin faaliyette bulunduğu ülkenin dışındaki yabancı ülkelerdeki fırsat ve tehditleri barındıran politik, yasal, ekonomik ve sektörel olayların ve\naktörlerin (müşteriler, tedarikçiler, rakipler) dahil olduğu ortam uluslararası çevre olarak tanımlanabilir.","İşletmenin yakın dış çevresinde ise, tüketiciler, rakipler, tedarikçiler, kredi kuruluşları ve sendikalar yer almaktadır."],"questions":[{"q":"Aşağıdakilerden hangisi genel dış çevre faktörlerinden biri değildir?","options":[{"key":"A","text":"Yasal Çevre"},{"key":"B","text":"Sektörel Çevre"},{"key":"C","text":"Demografik Çevre"},{"key":"D","text":"Sosyal ve Kültürel Çevre"},{"key":"E","text":"Teknolojik Çevre"}],"answerText":"Sektörel Çevre","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi “çalışanların sosyal haklarını elde etmek için kurdukları ve onlar adına sözleşme yapan örgütler” dir?","options":[{"key":"A","text":"Rakip şirketler"},{"key":"B","text":"Sendikalar"},{"key":"C","text":"Bankalar"},{"key":"D","text":"Aracı kurumlar"},{"key":"E","text":"Hukuk firmaları"}],"answerText":"Sendikalar","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi ekonomik çevre unsurlarından biri değildir?","options":[{"key":"A","text":"Para arzı"},{"key":"B","text":"Nüfusun yaş dağılımı"},{"key":"C","text":"Dış ticaret açığı"},{"key":"D","text":"Bütçe açığı"},{"key":"E","text":"Enerji maliyetleri"}],"answerText":"Nüfusun yaş dağılımı","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi sosyokültürel çevrenin unsurlarından biri değildir?","options":[{"key":"A","text":"Gelenek ve görenekler"},{"key":"B","text":"Kültür"},{"key":"C","text":"Değer yargıları"},{"key":"D","text":"Nüfus yapısı"},{"key":"E","text":"Toplumsal inançlar"}],"answerText":"Nüfus yapısı","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İşletmeye hammadde, yarı mamul, insan gücü (emek), enerji vb. üretim girdilerini sağlayan kişi ya da kuruluşlar” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Rakip şirketler"},{"key":"B","text":"Sendikalar"},{"key":"C","text":"Bankalar"},{"key":"D","text":"Aracı kurumlar"},{"key":"E","text":"Tedarikçi firmalar"}],"answerText":"Tedarikçi firmalar","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Uluslararası Standartlar Örgütü (ISO) tarafından 2010 yılında yayınlanan sosyal sorumluluk standardı aşağıdakilerden hangisidir?","options":[{"key":"A","text":"ISO 9001"},{"key":"B","text":"ISO 14001"},{"key":"C","text":"IS0 18000"},{"key":"D","text":"ISO 26000"},{"key":"E","text":"ISO 10002"}],"answerText":"ISO 26000","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Carroll’un sosyal sorumluluk modelinde ele aldığı boyutlardan biri değildir?","options":[{"key":"A","text":"Ekonomik sorumluluk"},{"key":"B","text":"Hukuksal sorumluluk"},{"key":"C","text":"Çevresel sorumluluk"},{"key":"D","text":"Etik sorumluluk"},{"key":"E","text":"Gönüllü sorumluluk"}],"answerText":"Çevresel sorumluluk","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi toplumun işletmelerden beklentileri arasında sayılamaz?","options":[{"key":"A","text":"Devlete karşı yükümlülüklerini yerine getirmesi"},{"key":"B","text":"Çevresini koruması"},{"key":"C","text":"Güvenli ürünler satması"},{"key":"D","text":"Satış sonrası hizmetlerin olmaması"},{"key":"E","text":"Eğitim ve sanata destek olması"}],"answerText":"Satış sonrası hizmetlerin olmaması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"SA 8000 standardı kapsamında aşağıdaki temel ilkelerden hangisi yer almamaktadır?","options":[{"key":"A","text":"Çocuk işçi"},{"key":"B","text":"Zorla çalıştırma"},{"key":"C","text":"Üretim standartları"},{"key":"D","text":"Disiplin uygulamaları"},{"key":"E","text":"Sağlık ve güvenlik"}],"answerText":"Üretim standartları","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Toplumun işletmelerden beklediği hayırseverlik amaçlı faaliyetler işletmenin hangi sorumluluk alanı içerisinde yer almaktadır?","options":[{"key":"A","text":"Ekonomik Sorumluluk"},{"key":"B","text":"Hukuksal Sorumluluk"},{"key":"C","text":"Etik Açıdan Sorumluluk"},{"key":"D","text":"Gönüllü Sorumluluk"},{"key":"E","text":"İşletme içi Sorumluluk"}],"answerText":"Gönüllü Sorumluluk","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmenin demografik çevresi içinde değerlendirilebilecek faktörlerden biridir?","options":[{"key":"A","text":"Asgari ücret politikaları"},{"key":"B","text":"İthalat tarifeleri"},{"key":"C","text":"Araştırma ve geliştirme faaliyetleri"},{"key":"D","text":"Çevre koruma yasaları"},{"key":"E","text":"Ortanca yaş"}],"answerText":"Ortanca yaş","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi bir işletmenin sosyal sorumlu davranışına örnek olabilir?","options":[{"key":"A","text":"Çevre dostu ürünler geliştirme"},{"key":"B","text":"Çalışanlarına düşük ücret ödeme"},{"key":"C","text":"Vergi kaçırma"},{"key":"D","text":"Rekabet üstünlüğü için yanlış bilgi yayma"},{"key":"E","text":"Ürünlerinde kalite standartlarını düşük tutma"}],"answerText":"Çevre dostu ürünler geliştirme","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmelerin Sınıflandırılması","cards":["· İşletmeleri büyüklükleri bakımından sınıflandırırken araştırmacılar tarafından değişik ölçütler kullanılmaktadır. Sahip olunan sermaye, çalışanların sayısı,\nüretim kapasitesi, kullanılan hammadde, malzeme, enerji ve makine parkı, bir dönem içindeki toplam satış gibi değişik ölçütler söz konusudur. Genel olarak,\nişletmeler büyüklüklerine göre; sıfır grubu veya çok küçük işletmeler, küçük ve orta ölçekli işletmeler ve büyük işletmeler olarak incelenebilir.","İşletmeler hitap ettikleri pazar alanlarına göre sınıflandırıldığında başlıca dört grupta ele alınabilir. Ulusal işletmeler, bir ülkenin yerel pazarında faaliyette\nbulunurlar. Uluslararası işletmeler, kuruluş merkezinin bulunduğu ülke dışına yönelik olarak çalışırlar. Çokuluslu işletmeler ise çok fazla sayıda ülkeye yönelik\nolarak faaliyette bulunurlar. Küresel işletmeler ise dünya pazarına hitabeden işletmelerdir.","İşletmenin ait olduğu kişi veya kuruluşa yani sermaye sahipliğine göre bir sınıflandırma yapıldığında, özel işletmeler, kamu işletmeleri ve karma\nişletmeler söz konusu olmaktadır.","Üretilen mal veya hizmetin cinsine göre işletmeler; mal üreten işletmeler, hizmet üreten işletmeler ve malların ticaretine aracılık eden işletmeler olmak\nüzere üçe ayrılır.","Bir işletmenin kurulmasına karar verildikten sonra amaca en uygun hukuki yapıda kurulması gerekmektedir. Ülkemizde işletmelerin hukuki yapılarını\ndüzenleyen çeşitli kanunlar vardır. Bunlar arasında; Ticaret Kanunu, Borçlar Kanunu, Kooperatifler Kanunu ve Vergi Kanunları bulunmaktadır. Hukuki açıdan\nbakıldığında işletmeleri; tek kişi işletmeleri, şirketler, kooperatifler, dernek ve vakıflar olmak üzere sınıflandırmak mümkündür.","Şirketler, kendi içlerinde adi şirketler ve ticaret şirketleri olmak üzere ikiye ayrılırken, ticaret şirketleri de şahıs şirketleri ve sermaye şirketleri olmak üzere\nikiye ayrılmaktadır. Şahıs şirketlerinin kollektif ve komandit olmak üzere iki türü vardır. Sermaye şirketlerinin ise anonim şirket, limited şirket ve sermayesi\npaylara bölünmüş komandit şirket olmak üzere üç türü vardır.","İşletmelerin çeşitli düzeylerdeki anlaşma veya birleşmeleri, ortak girişim, konsorsiyum, holding ve şirket birleşmeleri olmak üzere dört grupta\ntoplanabilir. Ortak girişimler (Joint Venture), belirli bir alanda, belirli bir işi veya projeyi beraberce gerçekleştirmek için işletmelerin varlık ve yeteneklerini\nbiraraya getirerek, yeni bir işletmeyi, yeni bir ad veya kimlik ile başlatmalarıdır.","Konsorsiyum, kelime olarak “belirli bir iş için kurulan birlik veya ortaklık” anlamına gelir. İşletmeler, uluslararası finans kuruluşları veya devletler belirli\nbir amaç için biraraya gelirler. Genellikle büyük çaplı taahhüt işlerinde, aynı veya farklı ülkeden; aynı dalda veya farklı dallarda uzmanlık sahibi olan işletmeler,\nfinansal olanaklarını veya teknolojik vb. üstünlüklerini birleştirip işbirliği yaparlar."],"questions":[{"q":"Aşağıdakilerden hangisi KOBİ’lerin avantajlarından biri değildir?","options":[{"key":"A","text":"Kurulma kolaylığı"},{"key":"B","text":"Uluslararasılaşma hızı"},{"key":"C","text":"Düşük maliyetler"},{"key":"D","text":"Esneklik"},{"key":"E","text":"Girişimcilik ve yenilikçilik"}],"answerText":"Uluslararasılaşma hızı","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi çokuluslu işletmelerin özelliklerinden biri değildir?","options":[{"key":"A","text":"Sermaye payları iki veya daha çok ülkeye dağılmıştır."},{"key":"B","text":"Üst kademe yöneticileri ana merkez tarafından belirlenir, bu yöneticiler çeşitli uluslardan olabilir."},{"key":"C","text":"Her ülkedeki birim belli bir bağımsızlık içinde çalışır, ancak uzun vadeli amaç ve politikalar genel merkezde oluşturulur."},{"key":"D","text":"Üretim birden fazla ülkede yapılır ve toplam üretim içinde önemli bir oran bu dış ülkelerde gerçekleştirilir."},{"key":"E","text":"Tek bir ülke pazarına yönelik olarak çalışırlar."}],"answerText":"Tek bir ülke pazarına yönelik olarak çalışırlar.","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi hizmet sektöründe çalışan bir işletme değildir?","options":[{"key":"A","text":"Otel"},{"key":"B","text":"Emlakçı"},{"key":"C","text":"Sinema"},{"key":"D","text":"Kuaför"},{"key":"E","text":"Otomobil fabrikası"}],"answerText":"Otomobil fabrikası","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletmeler pazar alanlarına göre sınıflandırıldığında aşağıdakilerden hangisi farklıdır?","options":[{"key":"A","text":"Ulusal işletmeler"},{"key":"B","text":"Uluslararası işletmeler"},{"key":"C","text":"Büyük işletmeler"},{"key":"D","text":"Çokuluslu işletmeler"},{"key":"E","text":"Küresel işletmeler"}],"answerText":"Büyük işletmeler","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aynı sektörde faaliyet gösteren firmalar arasında gerçekleştirilen birleşmeler …………… birleşmelerdir. Bu ifadedeki boşluğu aşağıdakilerden hangisi doğru\nbiçimde tamamlar?","options":[{"key":"A","text":"Dikey"},{"key":"B","text":"Karma"},{"key":"C","text":"Aynı Merkezli"},{"key":"D","text":"Çapraz"},{"key":"E","text":"Yatay"}],"answerText":"Yatay","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Ticari bir işletmeyi, bir ticaret unvanı altında işletme maksadıyla gerçek şahıslar arasında kurulan ve ortaklarından hiçbirisinin mesuliyeti, şirket alacaklılarına\nkarşı tahdit edilmemiş olan şirket” tanımı hangi işletmeyi tanımlamaktadır?","options":[{"key":"A","text":"Kollektif"},{"key":"B","text":"Komandit"},{"key":"C","text":"Anonim"},{"key":"D","text":"Limited"},{"key":"E","text":"Sermayesi paylara bölünmüş komandit şirket"}],"answerText":"Kollektif","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"KOSGEB yönetmeliğine göre “On kişiden az yıllık çalışan istihdam eden ve yıllık net satış hasılatı veya mali bilançosundan herhangi biri beş milyon Türk\nLirasını aşmayan işletmeler” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Mikro işletmeler"},{"key":"B","text":"Çok küçük işletmeler"},{"key":"C","text":"Küçük işletmeler"},{"key":"D","text":"Orta ölçekli işletmeler"},{"key":"E","text":"Büyük işletmeler"}],"answerText":"Mikro işletmeler","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Türk Ticaret Kanunu’na göre anonim şirketin kurulabilmesi için en az sermaye tutarı ne kadardır?","options":[{"key":"A","text":"5.000"},{"key":"B","text":"10.000"},{"key":"C","text":"50.000"},{"key":"D","text":"100.000"},{"key":"E","text":"500.000"}],"answerText":"50.000","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi anonim şirketin özelliklerinden biri değildir?","options":[{"key":"A","text":"Sorumluluk sınırlıdır."},{"key":"B","text":"Yönetim bir düzene bağlıdır, çoğunlukla profesyonel yöneticiler görev alırlar."},{"key":"C","text":"Ortakların paylarını devredebilmesi oldukça zordur."},{"key":"D","text":"Büyüme imkanı çok fazladır, yeni hisselerle sermaye artırılabilir."},{"key":"E","text":"Kredi imkanları da fazladır."}],"answerText":"Ortakların paylarını devredebilmesi oldukça zordur.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Türk Ticaret Kanunu’na göre limited şirketin kurulabilmesi için gerekli en az sermaye tutarı ne kadardır?","options":[{"key":"A","text":"5.000"},{"key":"B","text":"10.000"},{"key":"C","text":"50.000"},{"key":"D","text":"100.000"},{"key":"E","text":"500.000"}],"answerText":"10.000","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Sıfır grubu ya da çok küçük işletmelere örnek olarak aşağıdakilerden hangisi verilebilir?","options":[{"key":"A","text":"Ayakkabı tamircisi"},{"key":"B","text":"Otomobil fabrikası"},{"key":"C","text":"Sinema salonu"},{"key":"D","text":"Demir-çelik fabrikası"},{"key":"E","text":"Büyük bir zincir market"}],"answerText":"Ayakkabı tamircisi","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Köprü, baraj vb. projelerde genelde hangi işletme tipi kullanılır?","options":[{"key":"A","text":"Anonim şirket"},{"key":"B","text":"Konsorsiyum"},{"key":"C","text":"Kooperatif"},{"key":"D","text":"Tek kişi işletmesi"},{"key":"E","text":"Komandit şirket"}],"answerText":"Konsorsiyum","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmenin Kuruluş Çalışmaları","cards":["· Girişimcileri işletme kurmaya yönelten nedenler şu şekilde sıralanabilir: miras, bağımsız iş yapma isteği, kazanç sağlama isteği, toplumsal itibar\nsağlamak, başka fırsatların yokluğu, bir düşünce veya misyonu gerçekleştirme isteği.","Bir işletme kurulmadan önce girişimcinin kafasında belirli bir endüstri dalında, belli bir büyüklükte ve belli bir hukuksal yapıda üretim yapma düşüncesi\noluşur. Aynı zamanda halihazırda piyasada çalışmakta olan işletmeler de, pazarda talebin artması, işletmenin büyüme isteği, teknolojik yenileme vb etkenler\ndolayısıyla yeni yatırımlara girişmek isteyebilirler.","Girişimcinin kafasında beliren proje fikrinden sonra bu düşüncenin uygulanabilir (feasible) nitelikte olup olmadığı yapılacak “fizibilite etüdü” adı verilen\nçeşitli ön araştırmalar sonucu ortaya çıkacaktır. Fizibilite Etüdü, bir projenin ekonomik potansiyelini ve pratik olarak uygulanabilirliğini belirlemek amacıyla,\nprojenin teknik, finansal ve ekonomik verilerinin araştırılmasına dayanır.","Projenin değerlendirilmesi fizibilite raporuna dayanılarak yapılmaktadır. Bu aşama tüm bilgi ve belgelerin incelenerek projenin kabulü, değiştirilmesi veya\nreddedilmesi kararının verildiği sistematik bir çalışmadır. Yapılan ön proje çalışmaları sonucunda kurulmak istenen işletmenin beklenen karlılığı sağladığı\nanlaşılırsa, yatırım kararı alınır. Bu aşamada fizibilite çalışmalarında yer alan ekonomik, finansal, teknik ve hukuki araştırmalar daha kapsamlı bir şekilde\nyapılmak üzere tekrarlanır.","Projenin uygulanması, işletmenin kurulması ve faaliyete geçmesi ile ilgili tüm planlanan çalışmaların başlatıldığı aşama olup, gerekli yasal işlemler ve\nizinler alınarak, yatırım fiziksel olarak gerçekleştirilir.","Kuruluşunu tamamlayan işletme hemen tam kapasite ile faaliyete geçmez. Üretimin, önceden plânladığı gibi gerçekleşip gerçekleşemeyeceği kesinlikle\ndenenmelidir. Deneme üretimi ile ayrıca üretilen mal ve hizmetler tüketicinin eline geçmeden bir denetimden geçirilmeli ve kalitelerinin beklenen düzeyde olup\nolmadığı saptanmalıdır. Aksi halde, piyasaya istenmeyen kalitede mal ve hizmet sunan bir işletme, açıldığı gibi kapanabilir.","İşletmenin kuruluş yeri seçimiyle yakından ilişkili olan işletme büyüklüğünün ne olması gerektiği sorunu çok yönlü olarak ele alınması gereken bir\nkonudur ve bu konunun üzerinde işletmelerin kuruluş çalışmaları çerçevesinde önemle durulmalıdır. İşletme büyüklüğünü ölçmede niceliksel veya niteliksel\nkritelerden yararlanılabilir.","İşletmenin kuruluş yeri seçimini etkileyen başlıca faktörler, pazara yakınlık, hammaddeye yakınlık, işgücüne yakınlık, taşıma olanakları ve devletin teşvik\nve sınırlamalarıdır."],"questions":[{"q":"Aşağıdakilerden hangisi işletmelerin kuruluş nedenlerinden biri değildir?","options":[{"key":"A","text":"Miras"},{"key":"B","text":"Bağımsız iş yapma isteği"},{"key":"C","text":"Zarar etme isteği"},{"key":"D","text":"Kazanç sağlama isteği"},{"key":"E","text":"Toplumsal itibar sağlamak"}],"answerText":"Zarar etme isteği","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi kuruluş yeri seçimini etkileyen faktörlerden biri değildir?","options":[{"key":"A","text":"Pazara yakınlık"},{"key":"B","text":"Hammadde"},{"key":"C","text":"Kalite"},{"key":"D","text":"İşgücü"},{"key":"E","text":"Devletin teşvik ve sınırlamaları"}],"answerText":"Kalite","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi fizibilite etüdleri kapsamında değildir?","options":[{"key":"A","text":"Ekonomik etüd"},{"key":"B","text":"Teknik etüd"},{"key":"C","text":"Finansal etüd"},{"key":"D","text":"Demografik etüd"},{"key":"E","text":"Yasal etüd"}],"answerText":"Demografik etüd","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmelerin kuruluş aşamalarından biri değildir?","options":[{"key":"A","text":"Fizibilite etüdleri"},{"key":"B","text":"Ön proje"},{"key":"C","text":"Satış sonrası hizmetlerin sağlanması"},{"key":"D","text":"Değerlendirme ve yatırım kararı"},{"key":"E","text":"Kesin Proje"}],"answerText":"Satış sonrası hizmetlerin sağlanması","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Girişimci açısından ………………., nakdi sermayenin, üretim yapacak makine ve teçhizata veya iktisadi üretim birimine dönüşmesidir. Yukarıdaki boşluğu\naşağıdakilerden hangisi tamamlar?","options":[{"key":"A","text":"Yatırım"},{"key":"B","text":"Sermaye"},{"key":"C","text":"Proje"},{"key":"D","text":"Ön Proje"},{"key":"E","text":"Fizibilite"}],"answerText":"Yatırım","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi teknik etüd kapsamına giren konulardan biri değildir?","options":[{"key":"A","text":"Üretim teknolojisi seçimi"},{"key":"B","text":"Üretilecek malların, yan ürün ve artıkların çeşitleri, nitelikleri artıkları değerlendirme olanakları"},{"key":"C","text":"Makine ve teçhizat seçimi"},{"key":"D","text":"Hukuki durum"},{"key":"E","text":"İnşaat işleri"}],"answerText":"Hukuki durum","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi finansal etüd kapsamına giren konulardan biri değildir?","options":[{"key":"A","text":"Yatırım tutarının hesaplanması"},{"key":"B","text":"İşletmenin gelir tahminlerinin yapılması"},{"key":"C","text":"Makine ve teçhizat seçimi"},{"key":"D","text":"İşletmenin kârlılık durumuyla ilgili analizler"},{"key":"E","text":"İşletmenin gider tahminlerinin yapılması"}],"answerText":"Makine ve teçhizat seçimi","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Fiili kapasitesi 50.000 ton/yıl ve normal kapasitesi 75.000 ton/yıl olan bir işletmenin kapasite kullanım oranı ne kadardır?","options":[{"key":"A","text":"%45"},{"key":"B","text":"%47"},{"key":"C","text":"%63"},{"key":"D","text":"%66"},{"key":"E","text":"%71"}],"answerText":"%66","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"X işletmesinin fiili kapasitesi 20.000 ton ve normal kapasitesi 25.000 ton ise bu işletmenin atıl kapasitesi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"5.000 ton"},{"key":"B","text":"10.000 ton"},{"key":"C","text":"15.000 ton"},{"key":"D","text":"20.000 ton"},{"key":"E","text":"25.000 ton"}],"answerText":"5.000 ton","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"............... kapasite, makine ya da teçhizatın, hiçbir bekleme, gecikme, arıza, aksama veya duraklama olmadan ulaşabileceği en yüksek üretim miktarıdır. Boşluğa\ngelecek kapasite çeşidi aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Aşırı kapasite"},{"key":"B","text":"Teorik kapasite"},{"key":"C","text":"Normal kapasite"},{"key":"D","text":"Optimum kapasite"},{"key":"E","text":"Fiili kapasite"}],"answerText":"Teorik kapasite","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletme kurma nedenlerinden biri olan “miras” ne anlama gelir?","options":[{"key":"A","text":"İşletmeyi bir başkasına satma isteği"},{"key":"B","text":"Kendi adını devam ettirecek bir işletme kurma isteği"},{"key":"C","text":"İşçi haklarını koruma isteği"},{"key":"D","text":"Sermayeyi büyütme hedefi"},{"key":"E","text":"İş gücünü artırma planı"}],"answerText":"Kendi adını devam ettirecek bir işletme kurma isteği","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Fizibilite etüdünün temel amacı nedir?","options":[{"key":"A","text":"Pazar talebini artırmak"},{"key":"B","text":"İşletmenin kuruluş yerini seçmek"},{"key":"C","text":"Yatırım tutarını hesaplamak"},{"key":"D","text":") Maliyetleri azaltmak"},{"key":"E","text":"Projenin uygulanabilirliğini değerlendirmek"}],"answerText":"Projenin uygulanabilirliğini değerlendirmek","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletme Fonksiyonları - 1","cards":["· Yönetim faaliyeti insanın varolması ile birlikte ortaya çıkan bir olgudur. İki veya daha fazla insanın ortak bir amaç etrafında çalışmalarını organize\netmesiyle yönetim söz konusu olur. Diğer bir deyişle, yönetim insanların tek başlarına gerçekleştiremeyecekleri amaçlara ulaşabilmek için yürütülen grup\nfaaliyetidir.","Yönetim bir grup insanı belirlenmiş amaçlara doğru yöneltme aralarındaki işbirliği ile koordinasyonu sağlama çabalarını bütününü içeren bir süreç\nşeklinde tanımlanabilir.","Yönetici, kar ve riski başkalarına ait olmak üzere mal ve hizmet ortaya koymak için üretim faktörlerini tedarik eden ve bunları belli bir ihtiyacı karşılama\namacına yönelten kimse olarak tanımlanır.","Henry Mintzberg’e göre yönetici, üç çeşit örgütsel rolü yerine getirmekle görevlidir. Bu roller kişilerarası rolü, bilgi rolü ve karar verme rolüdür.","Yöneticiler bu farklı rolleri yürütebilmek ve etkin olabilmek için bazı becerilere sahip olmak ve onları sürekli olarak geliştirmek zorundadır. İşletmenin\nkaynaklarını kullanarak amaçları gerçekleştirmeye çalışan yöneticiler görevlerini yerine getirirken kavramsal, insani ve teknik becerilere ihtiyaç duyarlar.","Bir işletme çatısı altında üst kademe, orta kademe ve alt kademe olmak üzere üç farklı yönetim kademesi vardır. Üst kademe yöneticiler, işletmede en\nfazla yetki ve güce sahiptirler, işletmenin amaçlarını belirler, uzun dönemli politika ve stratejileri saptarlar ve işletmeyi dışarıda en geniş yetkilerle temsil ederler.","Orta kademe yöneticilerin görevleri arasında, üst yönetimce belirlenen genel amaçları gerçekleştirmeye yönelik uygulama planları geliştirilmesi ve alt\nkademe yöneticilerin çalışmalarının koordine edilmesi, uygulamaya dönük işlerin yürütülmesi gelir.","Alt kademe yöneticiler günlük faaliyetleri gerçekleştiren işçilerin, teknik ya da ticari personeli veya büro personelinin gözetiminden sorumlu ilk düzey\nyöneticilerdir. Kim, ne, niçin, nereden, ne zaman ve nasıl sorularının ayrıntısıyla cevaplandırıldığı ve uygulandığı alandır."],"questions":[{"q":"Aşağıdakilerden hangisi yönetimin fonksiyonlarından biri değildir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Örgütleme"},{"key":"C","text":"Yürütme"},{"key":"D","text":"Koordinasyon"},{"key":"E","text":"Değerlendirme"}],"answerText":"Değerlendirme","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmede yönetim kademeleri dikkate alındığında çalışanlar kategorisi altında yer almaz?","options":[{"key":"A","text":"Operatörler"},{"key":"B","text":"Şefler"},{"key":"C","text":"El işçileri"},{"key":"D","text":"Uzmanlar"},{"key":"E","text":"Teknisyenler"}],"answerText":"Şefler","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi yürütme sürecinin başlıca faaliyetlerinden değildir?","options":[{"key":"A","text":"Yürütme, yöneticinin astlarına emir ve talimatlar vermesini kapsar."},{"key":"B","text":"Astların belirli görevleri sürdürmelerinde yol gösteren devamlı bir eğitim faaliyetlerini ifade eder."},{"key":"C","text":"Ortak amaca ulaşmak için faaliyetlerin birbiri ardına gelmesini sağlar."},{"key":"D","text":"Yöneticilerin, astların beklentilerini karşılamaları ile ilgili olarak motivasyon konusunu içerir."},{"key":"E","text":"Çalışmalarda disiplin sağlamayı ve iyi çalışanları ödüllendirmeyi içerir."}],"answerText":"Ortak amaca ulaşmak için faaliyetlerin birbiri ardına gelmesini sağlar.","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi pazarlama fonksiyonu kapsamında yer almaz?","options":[{"key":"A","text":"Tüketicilerin ihtiyaç ve eğilimlerinin belirlenmesi"},{"key":"B","text":"Mal veya hizmetlerin geliştirilmesi"},{"key":"C","text":"Reklam ve tutundurma"},{"key":"D","text":"Üretim maliyetlerinin hesaplanması"},{"key":"E","text":"Dağıtımla ilgili kararların verilmesi"}],"answerText":"Üretim maliyetlerinin hesaplanması","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi pazarlamanın 4P’sinden biri değildir?","options":[{"key":"A","text":"Mamul"},{"key":"B","text":"Fiyat"},{"key":"C","text":"Tutundurma"},{"key":"D","text":"Dağıtım"},{"key":"E","text":"Satış"}],"answerText":"Satış","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir mal veya hizmeti, üretildiği yerden, tüketileceği yere götürmek için gerekli tüm çabalar” aşağıdakilerden hangisini ifade eder?","options":[{"key":"A","text":"Pazarlama"},{"key":"B","text":"Tutundurma"},{"key":"C","text":"Denetim"},{"key":"D","text":"Dağıtım"},{"key":"E","text":"Promosyon"}],"answerText":"Dağıtım","answerKey":"D","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Görülecek işlerin belirlenmesi / İşlerin gruplara ayrılması/ Çalışanların belirlenip atanması / Yetki ve sorumlulukların belirlenmesi / Yer, araç ve yöntemlerin\nbelirlenmesi” şeklinde verilen sıralama hangi yönetim fonksiyonunun alt başlıklarını ifade etmektedir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Örgütleme"},{"key":"C","text":"Yürütme"},{"key":"D","text":"Koordinasyon"},{"key":"E","text":"Denetim"}],"answerText":"Örgütleme","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yöneticinin“spesifik iş bilgisi ve bu bilgiyi ne zaman ve nasıl kullanacağını bilme becerisi” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Kavramsal beceri"},{"key":"B","text":"Teknik beceri"},{"key":"C","text":"İnsani beceri"},{"key":"D","text":"Duygusal beceri"},{"key":"E","text":"Sosyal beceri"}],"answerText":"Teknik beceri","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi Mintzberg’in sınıflandırdığı karar verme rollerinden biri değildir?","options":[{"key":"A","text":"Girişimci"},{"key":"B","text":"Sorun çözücü"},{"key":"C","text":"Kaynak dağıtıcı"},{"key":"D","text":"Görüşmeci"},{"key":"E","text":"Bilgi dağıtıcı"}],"answerText":"Bilgi dağıtıcı","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Resmi olarak işletmeyi temsil etme, tören ve sembolik görevlerde bulunma, karşılama, yasal anlaşmaları imzalama” rolü Mintzberg’in kişilerarası rollerinden\nhangisidir?","options":[{"key":"A","text":"Liderlik"},{"key":"B","text":"Temsil"},{"key":"C","text":"İşbirliği"},{"key":"D","text":"Karar verme"},{"key":"E","text":"Bilgi dağıtma"}],"answerText":"Temsil","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Henry Mintzberg’in tanımladığı yönetici rolleri arasında aşağıdakilerden hangisi bulunmaz?","options":[{"key":"A","text":"Temsil rolü"},{"key":"B","text":"Liderlik rolü"},{"key":"C","text":"İş birliği rolü"},{"key":"D","text":"Bilgi dağıtma rolü"},{"key":"E","text":"Finans yöneticisi rolü"}],"answerText":"Finans yöneticisi rolü","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Yönetim faaliyetinin başlangıcını oluşturan en temel fonksiyon aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Denetim"},{"key":"C","text":"Örgütleme"},{"key":"D","text":"Yürütme"},{"key":"E","text":"Koordinasyon"}],"answerText":"Planlama","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]},{"title":"İşletmecilik Fonksiyonları - 2","cards":["· Üretim, genel anlamıyla, beşeri ve fiziksel faktörlerin, mal ve hizmetlere dönüştürülmesi sürecidir. Üretim faktörleri olarak adlandırılan çeşitli işletme\nkaynaklarının (işgücü, makine, hammadde, malzeme, sermaye, vb.), girdi (input) olarak katıldıkları üretim süreci sonunda, çıktıya (output) dönüşerek, ihtiyaç\nkarşılayacak mal ve hizmetler haline gelmesine “üretim” denmektedir","Üretim sistemleri çeşitli bakımlardan sınıflandırılabilir. Genel olarak kullanılan sınıflandırma bu sistemleri belirli bir sürede üretilen miktara göre\nsınıflandırmaktır. Bu kritere göre üretim sitemleri tek (birim) üretim, seri üretim ve süreç üretimi olmak üzere üçe ayrılır.","Siparişe göre üretim adı verilen üretim türünde belirli bir sürede tek mamul üretilir ve üretim işlemi bir daha tekrarlanmaz. Aynı zamanda, aynı kalitede,\naynı özelliklerde ve aynı ölçüde sadece bir mamul meydana getirildiği için, her üretilen mamul kendisinden önce ve sonra üretilenden farklı olur.","Seri üretimde, bir seferde nitelik bakımından birbirinin aynı olan, tek tip, standart, müşteri spesifikasyonlarına bağlı olmadan ürünler üretilir. İmalat\nsanayiinde yaygın olarak kullanılan bu yöntemde üretim kısa bir sürede gerçekleşir ve o seri bittiğinde başka bir serinin üretimine geçilir.","Süreç üretiminde, belirli bir sürede, seri üretimdeki miktarın çok üzerinde, aşırı sermaye yoğun üretim teknolojisi ve otomasyonun yardımı ile tamamen\nbirbirinin aynı olan mamuller üretilir.","Araştırma kavramı, bilinmeyen bir teknoloji, ürün ya da bilgiyi ortaya çıkarmak ve mümkün olan durumlarda bunları uygulamaya yöneltmek anlamına\ngelmektedir. Buna göre AR-GE daha çok üretimle ve üretim tekniğiyle ilgilidir; ancak günümüzde işletmenin etkinlik ve verimliliğini artırmaya yönelik her türlü\nekonomik faaliyet AR-GE çalışmalarına konu olabilmektedir. Üretimin yanında yönetim organizasyon, pazarlama, finansman ve personel yönetimi gibi\nfonksiyonlarda da AR-GE çalışmaları yapılmaktadır.","Finansman fonksiyonu; işletmelerin faaliyette bulunabilmeleri için ihtiyaç duyduğu mali kaynakları en uygun şartlarda sağlayarak, işletmede birikmiş olan\nfonların amaçların gerçekleştirilmesi için planlanması, örgütlenmesi, yöneltilmesi ve kontrol edilmesi faaliyetleri olarak tanımlanabilir.","İşletmelerde finansman yöntemleri “kaynağına göre” ve “süresine göre” finansman olmak üzere ikiye ayrılır. Kaynağına göre finansman yöntemleri öz\nkaynaklardan sağlanan finansman, dış kaynaklardan sağlanan finansman ve otofinansman olarak üç grupta incelenebilir. Süresine Göre Finansman"],"questions":[{"q":"İşletmelerde üretim süreci gerçekleşirken aşağıdakilerden hangisi girdi olarak kullanılmaz?","options":[{"key":"A","text":"Malzeme"},{"key":"B","text":"İnsan gücü"},{"key":"C","text":"Makine, araç ve gereçler"},{"key":"D","text":"Sermaye"},{"key":"E","text":"Mal veya hizmet"}],"answerText":"Mal veya hizmet","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi işletmecilik fonksiyonlarından biri değildir?","options":[{"key":"A","text":"Planlama"},{"key":"B","text":"Üretim"},{"key":"C","text":"Finans"},{"key":"D","text":"İnsan Kaynakları Yönetimi"},{"key":"E","text":"Muhasebe"}],"answerText":"Planlama","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Araştırma ve geliştirme, genelde bilimsel ve teknik bilgi birikimini artırmak amacıyla işletmelerin yürütmüş oldukları bir dizi sistematik çabadan oluşmaktadır.\nAşağıdakilerden hangisi bu çabalardan biri değildir?","options":[{"key":"A","text":"Pazar ve pazarlama araştırmaları"},{"key":"B","text":"Üretim süreçlerinin düzenlenmesi"},{"key":"C","text":"Yeni gelişmelerin ve buluşların üretim süreçlerine yansıtılması"},{"key":"D","text":"Finansal araştırmaların yapılması"},{"key":"E","text":"İnsan kaynaklarının işe alınması"}],"answerText":"İnsan kaynaklarının işe alınması","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"İşletmenin kendi faaliyetleri sonucunda oluşan kârın, gerek kanun tarafından, gerekse işletme yönetiminin kararıyla dağıtılmayarak işletme sermayesine\neklenmesi; yani işletmenin kendi kendine finansman sağlaması” na ne denir?","options":[{"key":"A","text":"Özkaynaklardan sağlanan finansman"},{"key":"B","text":"Dış kaynaklardan sağlanan finansman"},{"key":"C","text":"Otofinansman"},{"key":"D","text":"Kısa süreli finansman"},{"key":"E","text":"Uzun süreli finansman"}],"answerText":"Otofinansman","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi üretim planlaması yapılmasının sebeplerinden biri değildir?","options":[{"key":"A","text":"Üretim süreçlerinin karmaşık ve yoğun olması"},{"key":"B","text":"İşletme içinde faaliyetlerin koordine edilmesi gereği"},{"key":"C","text":"Tüketici istek ve ihtiyaçlarının değişmesi"},{"key":"D","text":"Fiyat ve kalitede rekabetin artması"},{"key":"E","text":"İşe alma süreçlerinin gelişmesi"}],"answerText":"İşe alma süreçlerinin gelişmesi","answerKey":"E","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir işletmenin belirli bir tarihteki finansal durumunu yansıtan bir tablo” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Gelir tablosu"},{"key":"B","text":"Nakit akım tablosu"},{"key":"C","text":"Bilanço"},{"key":"D","text":"Dağıtılmayan karlar tablosu"},{"key":"E","text":"Gider tablosu"}],"answerText":"Bilanço","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“Bir yıl ya da bir faaliyet dönemi içinde nakde dönüşen veya giderleşen varlıklar” aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Dönen varlıklar"},{"key":"B","text":"Duran varlıklar"},{"key":"C","text":"Kısa vadeli varlıklar"},{"key":"D","text":"Uzun vadeli varlıklar"},{"key":"E","text":"Özsermaye"}],"answerText":"Dönen varlıklar","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Aşağıdakilerden hangisi üretim sistemleri sınıflandırmasında yer almaz?","options":[{"key":"A","text":"Tek üretim"},{"key":"B","text":"Birim üretim"},{"key":"C","text":"Hızlı üretim"},{"key":"D","text":"Seri üretim"},{"key":"E","text":"Süreç üretimi"}],"answerText":"Hızlı üretim","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İşletmenin bir dönemde elde ettiği tüm gelirler ile aynı dönemde katlandığı bütün maliyet ve giderleri ve bunların sonucunda işletmenin elde ettiği dönem kârını\nya da zararını toplu halde gösteren tablo”ya ne denir?","options":[{"key":"A","text":"Gelir tablosu"},{"key":"B","text":"Nakit akım tablosu"},{"key":"C","text":"Bilanço"},{"key":"D","text":"Dağıtılmayan karlar tablosu"},{"key":"E","text":"Gider tablosu"}],"answerText":"Gelir tablosu","answerKey":"A","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"“İşletme faaliyetlerinde bir yıldan daha uzun bir süre şekil değiştirmeden kalan, bina, makinalar, arazi, uzun süreli alacaklar, çeşitli patentler ve haklar”dan\noluşan varlıklara ne ad verilir?","options":[{"key":"A","text":"Dönen varlıklar"},{"key":"B","text":"Duran varlıklar"},{"key":"C","text":"Kısa vadeli varlıklar"},{"key":"D","text":"Uzun vadeli varlıklar"},{"key":"E","text":"Özsermaye"}],"answerText":"Duran varlıklar","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"\"Sipariş üzerine, tek bir mamul üretilir ve bu işlem bir daha tekrarlanmaz.\" Bu üretim türü aşağıdakilerden hangisidir?","options":[{"key":"A","text":"Seri üretim"},{"key":"B","text":"Süreç üretimi"},{"key":"C","text":"Tek üretim"},{"key":"D","text":"Kitle üretimi"},{"key":"E","text":"Akıcı üretim"}],"answerText":"Tek üretim","answerKey":"C","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"},{"q":"Süreç üretiminin en belirgin özelliği nedir?","options":[{"key":"A","text":"Ürünlerin müşterilerin ihtiyaçlarına göre tasarlanması"},{"key":"B","text":"Üretim aşamalarının ara verilmeden gerçekleşmesi"},{"key":"C","text":"Üretim maliyetlerinin düşük olması"},{"key":"D","text":"Üretim programının belirsiz olması"},{"key":"E","text":"Siparişe göre üretim yapılması"}],"answerText":"Üretim aşamalarının ara verilmeden gerçekleşmesi","answerKey":"B","source":"İstanbul Üniversitesi AUZEF ders kitabı – Ünite Soruları","kind":"book"}]}]}},"examIntel":{"bat":{"status":"Güçlü arşiv","note":"İşletme–İKY etiketli vize setleri özellikle önceliklendirildi. 2023–24 ve 2024–25 İşletme–İKY vize setleri; 2025–26 ortak ve İşletme vize setleri arşivlerde listeleniyor.","patterns":["Tanımdan kavramı bulma","Yöntemleri birbirinden ayırma","I–II–III türü önerme soruları","“Hangisi değildir?” çeldiricileri"],"sources":["https://aofpusula.com/cikmis-sorular/auzef/bilimsel-arastirma-teknikleri","https://cozsen.com/courses/958"]},"sos":{"status":"Orta-güçlü arşiv","note":"2023–24, 2024–25 ve 2025–26 AUZEF vize kayıtları bulunuyor. Tekrarlanan eksenler: Sanayi Devrimi, toplumsal dönüşüm, Marx, yabancılaşma, modern yaklaşımlar.","patterns":["Düşünür → kavram","Tarihsel dönüşüm → sonuç","Paragraftan kavramı teşhis","Yanlış ifadeyi bulma"],"sources":["https://universiten.com/cikmis-sorular/auzef/calisma-sosyolojisi","https://lolonolo.com/auzef/calisma-sosyolojisi/"]},"ikt":{"status":"Güçlü arşiv","note":"2022–23, 2023–24, 2024–25 ve 2025–26 için 20 civarı soruluk vize setleri listeleniyor. 2025–26 vizesinde marjinal ürün, arz-talep kaymaları, marjinal fayda, ikame mal ve örümcek ağı gibi başlıklar görülüyor.","patterns":["Kavram tanıma","Grafik/kayma mantığı","Neden-sonuç ilişkisi","Kısa hesap ve denge yorumu"],"sources":["https://aofpusula.com/cikmis-sorular/auzef/genel-iktisat","https://lolonolo.com/auzef/genel-iktisat/"]},"islet":{"status":"Orta-güçlü arşiv","note":"2022–23, 2024–25 ve 2025–26 İşletme Yönetimi vize setleri AUZEF olarak arşivlenmiş durumda.","patterns":["Tanım → kavram","Örnek olay → işletme kavramı","Kuramcı/yaklaşım eşleştirme","Verimlilik/kârlılık gibi temel uygulamalar"],"sources":["https://cozsen.com/courses/284","https://lolonolo.com/2025/10/24/isletme-yonetimi-2024-2025-vize-sorulari-bahar/"]}},"officialExam":{"questions":20,"minutes":30,"note":"AUZEF resmî program sayfalarında sınavların genel olarak çoktan seçmeli, ders başına 20 soru ve 30 dakika olduğu belirtiliyor.","source":"https://auzef.istanbul.edu.tr/en/content/recreation/about-the-program"},"scope":{"status":"UNKNOWN","note":"2026–2027 vize için ders bazında resmî ünite kapsamı elimizde doğrulanmış değil. Uygulama hiçbir üniteyi “kesin vize kapsamı” diye etiketlemiyor."},"quality":{"status":"IN PROGRESS","bookQuestionOptionRepairs":391,"questionsNeedingManualReview":1,"scope2026":"UNKNOWN","note":"Kitap soruları ile geçmiş sınav soruları ayrı tutulur. Ayrıntılı açıklamalar kaynakla doğrulandıkça eklenir."}};
window.AUZEF_TEACHING = {
  "bat-0": {
    learn:["Bilimsel araştırmanın temel işlevlerinden biri, karar alıcının karşılaştığı belirsizliği azaltmaktır. Bu ünitede bilim felsefesi, bilgi türleri, bilimsel yöntem, tümevarım ve tümdengelim birlikte ele alınır.","Bilimsel araştırma sistematik ve nesnel bir süreçtir. Araştırma problemi ortaya konur, hipotez belirlenir, araştırma planlanır ve yürütülür; elde edilen bulgular yorumlanır."],
    confuse:["Temel araştırma ↔ uygulamalı araştırma: Temel araştırma mevcut bilgiye yeni bilgi katmayı; uygulamalı araştırma günlük/pratik problemlere çözüm üretmeyi hedefler.","Tümevarım ↔ tümdengelim: Birbirinin yerine kullanılan kavramlar değildir; bilimsel yöntem her iki akıl yürütme biçiminden yararlanabilir."],
    remember:["Araştırma = sistematik + objektif + sınanabilir süreç.","Karar verme açısından ana fikir: belirsizliği azaltmak."],
    exam:["Tanımdan kavramı bulma ve 'hangisi değildir?' sorularında tek bir aykırı ifadeye dikkat et.","Bilimsel yöntemin aşamalarında sıralama sorusu gelebilecek yapıdadır; süreç ilişkisini ezberden çok mantığıyla kur."]
  },
  "sos-0": {
    learn:["Sosyoloji, Sanayi Devrimi ve Fransız Devrimi sonrasında yaşanan büyük ekonomik, siyasal ve sosyal dönüşümleri anlamlandırma ihtiyacı içinde gelişmiştir.","Feodal düzenin çözülmesiyle fabrika sistemi, ücretli istihdam ilişkileri, yeni iş ritmi, işçi sınıfı ve sanayi burjuvazisi gibi yeni toplumsal yapılar belirginleşmiştir."],
    confuse:["Sosyolojinin ortaya çıkışı yalnızca teknoloji değişimi değildir; ekonomik, siyasal ve sosyal düzenin birlikte dönüşümüyle ilişkilidir.","Tarım toplumunun mevsimsel/statik iş ritmi ↔ fabrika sisteminin kesintisiz/dinamik iş ritmi ayrımını koru."],
    remember:["İki büyük kırılma: Sanayi Devrimi + Fransız Devrimi.","Çalışma yaşamındaki dönüşüm: feodal/tarımsal yapı → fabrika ve ücretli istihdam."],
    exam:["Bir paragraf verilip hangi tarihsel dönüşümü anlattığı sorulabilir.","Sınıf, çalışma ilişkisi ve üretim biçimi kavramlarını dönemlerle eşleştir."]
  },
  "ikt-0": {
    learn:["İktisat biliminin çıkış noktası, insan ihtiyaçlarının sınırsız; bu ihtiyaçları karşılayacak kaynakların ise sınırlı olmasıdır. Bu nedenle seçim yapmak zorunludur.","Temel ekonomik problem yalnızca ne üretileceği değildir: hangi malların, hangi yöntemlerle ve kimler için üretileceği de kıt kaynakların etkin kullanımıyla bağlantılıdır."],
    confuse:["Mikro ↔ makro analiz aynı düzey değildir. Mikro bireysel ekonomik birimleri; makro ekonominin bütününü inceler.","Kıtlık, hiçbir kaynağın bulunmaması demek değildir; sınırlı kaynakların sınırsız ihtiyaçların tamamını karşılayamamasıdır."],
    remember:["Sınırsız ihtiyaç + sınırlı kaynak = seçim zorunluluğu.","Temel sorular: Ne? Nasıl? Kim için üretilecek?"],
    exam:["Tanım sorularında 'kıtlık' ile fiziksel yokluğu karıştırma.","Neden-sonuç sorularında kaynak sınırlılığından seçim ve etkin kullanım sonucuna git."]
  },
  "islet-0": {
    learn:["İhtiyaçlar, insanların varlıklarından veya ilişkilerinden kaynaklanan eksikliklerdir. Bu ihtiyaçların giderilmesi için ekonomik faaliyetler yürütülür ve mal/hizmet üretilir.","Kitap üretim faktörlerini doğal kaynak, emek, sermaye, girişimci ve bilgi olarak ele alır. Tüketici mal veya hizmeti kullandığında fayda elde eder."],
    confuse:["Girişimci ↔ yönetici aynı rol değildir. Ünitenin öğrenme hedeflerinden biri bu farkı kurmaktır.","İhtiyaç ↔ fayda: ihtiyaç eksiklik duygusunu; fayda ise mal/hizmetin ihtiyaç giderme özelliğini ifade eder."],
    remember:["Üretim faktörleri: doğal kaynak + emek + sermaye + girişimci + bilgi.","İşletmenin amacı yalnızca kâr kavramıyla sınırlandırılarak okunmamalıdır; ünitede işletme amaçları ayrıca ele alınır."],
    exam:["Maslow, üretim faktörleri, fayda ve girişimci-yönetici ayrımı yüksek değerli kavram kümeleridir.","Benzer görünen tanımlarda sorunun 'ihtiyaç', 'fayda' veya 'üretim faktörü' istediğini ayır."]
  }
};

// Development 3 — source-grounded teaching expansion
Object.assign(window.AUZEF_TEACHING, {
"bat-4":{learn:["Kalitatif (nitel) araştırmada araştırma problemi merkezdedir ve süreç doğrusal değil, dairesel ilerleyebilir; süreçte yeni problemler ortaya çıktıkça önceki aşamalara dönülebilir.","Nitel araştırmada veri doğal ortamda elde edilir; temel araç araştırmacıdır. Veri çoğunlukla sayılardan değil sözcükler ve resimlerden oluşur; sonuç kadar süreç de önem taşır."],confuse:["Nitel süreç ↔ nicel süreç: kitap, nitel süreci dairesel; çoğunlukla nicel araştırmayı temsil eden genel süreci ise doğrusal yapı üzerinden ayırır.","Betimsel nitel veri, veriyi mutlaka sayısal ölçüye indirgemek anlamına gelmez."],remember:["Nitel = doğal ortam + araştırmacı temel araç + sözcük/resim + süreç odağı.","Ana amaç: olguyu daha derin ve bütünsel anlamak."],exam:["'Nasıl?' sorusu ve doğal ortam vurgusu nitel araştırmayı işaret edebilir.","Doğrusal/dairesel süreç ayrımı güçlü bir çeldirici alanıdır."]},
"sos-2":{learn:["İşin tarihsel dönüşümü, sosyal gelişme aşamaları ve üretim araçlarının mülkiyet kalıplarıyla birlikte ele alınır.","Avcı-toplayıcı yaşamdan yerleşik hayata geçiş; işbölümü, artık değer ve tabakalaşmayı beraberinde getirir. Tarım imparatorlukları ve feodal toplumda zanaatkâr işletmeler ve loncalar gelişir; ticari kapitalizm ve Sanayi Devrimi işin niteliğinde büyük dönüşüm yaratır."],confuse:["Tarihsel dönüşümü tek çizgili ve her toplumda aynı ilerleyen bir süreç gibi okumamak gerekir; kitap bu yaklaşımın çeşitliliği gözden kaçırabileceğini belirtir.","Lonca/zanaatkârlık sanayi fabrikasıyla aynı üretim düzeni değildir."],remember:["Yerleşik hayat → işbölümü + artık değer + tabakalaşma.","15. yüzyıldan itibaren ticari kapitalizm; ardından Sanayi Devrimi ve modern kapitalizm."],exam:["Üretim biçimi ↔ dönem ↔ çalışma ilişkisi eşleştirmelerine dikkat et.","Bir tarihsel özellik verilip hangi toplumsal aşamaya ait olduğu sorulabilir."]},
"sos-5":{learn:["Teknoloji ve emek sürecindeki otomasyon; işin parçalanması, standartlaşması, basitleşmesi, emeğin değersizleşmesi ve vasıfsızlaşması tartışmalarını yabancılaşma kavramıyla ilişkilendirir.","Kitap, Marx'ın yabancılaşmayı yalnızca bireysel tatminsizlik olarak değil toplumsal yapı ve sosyal değişmeyle ilişkili ele aldığını; çalışan deneyimlerinin nesnel faktörlerin yanında öznel faktörlerden de etkilenebileceğini vurgular."],confuse:["Yabancılaşma ↔ basit iş memnuniyetsizliği aynı şey değildir; kavramın teorik kullanımları daha geniştir.","Teknolojinin etkisi kitapta yalnızca olumsuz anlatılmaz; Robert Blauner ile ilişkilendirilen daha olumlu görüşlerin de bulunduğu belirtilir."],remember:["Otomasyon tartışması: parçalanma + standartlaşma + basitleşme + vasıfsızlaşma.","Marx: yabancılaşmayı toplumsal yapı ve değişmeyle ilişkilendirir."],exam:["Düşünür ↔ yabancılaşma yaklaşımı eşleştirmesi kritik olabilir.","Nesnel ve öznel faktörleri birbirine karıştıran seçeneklere dikkat et."]},
"ikt-2":{learn:["Arz, üreticinin belirli bir zaman içinde farklı fiyatlarda piyasada satmaya razı olduğu miktarı ifade eder. Diğer koşullar sabitken fiyat ile arz edilen miktar aynı yönde değişir.","Fiyat değişmesi arz eğrisi üzerinde harekete yol açarken; arzı belirleyen fiyat dışı unsurlardaki değişme arz eğrisinin tamamını sağa veya sola kaydırır."],confuse:["Arz miktarındaki değişme ↔ arzın değişmesi/kayması: fiyatın kendisi değişirse eğri üzerinde hareket; fiyat dışı belirleyici değişirse eğrinin bütünü kayar.","Arz kanununda ilişki pozitiftir; talepteki genel ters yönlü fiyat-miktar ilişkisiyle karıştırma."],remember:["Fiyat ↑ → ceteris paribus arz edilen miktar ↑.","Fiyat değişimi = eğri üzerinde hareket; fiyat dışı faktör = eğri kayması."],exam:["Grafik sorusunda önce değişenin malın kendi fiyatı mı, başka bir belirleyici mi olduğunu belirle.","Arz esnekliği ve arz kayması farklı kavramlardır."]},
"ikt-3":{learn:["Piyasa dengesi, talep edilen miktarla arz edilen miktarın eşit olduğu; arz ve talep eğrilerinin kesiştiği noktada oluşur. Bu noktadaki fiyat denge fiyatı, miktar denge miktarıdır.","Talep sağa kayarsa belirli arz altında denge fiyatı ve miktarı yükselir. Arz sağa kayarsa belirli talep altında fiyat düşerken denge miktarı artar."],confuse:["Talep artışı ↔ talep edilen miktar artışı aynı grafik hareketi değildir; denge analizinde eğrinin kaymasıyla eğri üzerindeki hareketi ayır.","Arz sağa kayınca fiyatın da artacağını varsayma: kitapta sonuç daha düşük fiyat + daha fazla miktardır."],remember:["Talep → sağ: P↑ Q↑. Arz → sağ: P↓ Q↑.","Piyasa dönemi: arzın artırılamadığı; kısa dönem: arzın artırılabildiği; uzun dönem: yeni tesis kurulabildiği dönem."],exam:["Denge sorularında önce hangi eğrinin kaydığını, sonra fiyat ve miktarın yönünü ayrı ayrı belirle.","Piyasa/kısa/uzun dönem ayrımı doğrudan kavram sorusuna dönüşebilir."]},
"ikt-4":{learn:["Fayda, mal ve hizmetlerin insan ihtiyaçlarını tatmin etme özelliğidir. Rasyonel tüketici geliri çerçevesinde kendisine daha fazla fayda sağlayan mal ve hizmetleri tercih eder.","Kardinal yaklaşım faydanın nicel olarak ölçülebileceğini; ordinal yaklaşım ise faydanın ölçülemeyeceğini, tercih sıralamasıyla ele alınacağını savunur."],confuse:["Kardinal ↔ ordinal: kardinal = ölçülebilir fayda; ordinal = sıralanabilir tercih. İsimleri ters eşleştirme.","Fayda kavramını malın fiyatı veya üretim maliyetiyle karıştırma; burada tüketici tatminiyle ilgilidir."],remember:["Kardinal = ölç; ordinal = sırala.","Talep tahlilleri tüketici tercihi, bütçe ve fayda ilişkisini inceler."],exam:["Tanımdan kardinal/ordinal yaklaşımı seçme soruları yüksek çeldirici potansiyeline sahiptir.","Bütçe, tercih ve fayda kavramlarını aynı soruda ilişkilendirebilirsin."]},
"islet-2":{learn:["İşletme bilimi iktisat, davranış bilimleri, hukuk, matematik-istatistik ve bilgi teknolojileri gibi disiplinlerden yararlanır.","Matematik ve istatistik; ekonomik sipariş miktarı, stok kontrolü, maliyet minimizasyonu ve kâr maksimizasyonu gibi karar alanlarında kullanılır. Hukuk ise işletmenin faaliyet gösterdiği kurallar çerçevesiyle sürekli ilişkilidir."],confuse:["İktisat ↔ işletme aynı inceleme düzeyi değildir; işletme bilimi işletme sistemindeki olay ve faaliyetleri amaçlara etkin ulaşma açısından inceler.","Etkinlik/verimlilik gibi işletme ilkelerini diğer bilim dallarının isimleriyle karıştırma."],remember:["İşletmenin komşu disiplinleri: iktisat + davranış bilimleri + hukuk + matematik/istatistik + bilgi teknolojileri.","Disiplinleri ezberlemek yerine işletmeye ne sağladıklarını eşleştir."],exam:["Bir uygulama örneği verilip hangi bilim dalından yararlanıldığı sorulabilir.","Stok/maliyet/kâr hesapları → matematik-istatistik; insan davranışı → davranış bilimleri." ]},
"islet-3":{learn:["İşletmeler çok sayıda değişkenin etkileşim içinde olduğu dış çevrede faaliyet gösterir. Genel dış çevre fırsat ve tehdit yaratabilen politik-yasal, ekonomik, demografik, sosyal-kültürel, teknolojik ve uluslararası öğelerden oluşur.","Demografik çevre nüfusun miktarı, yoğunluğu, yaş yapısı, coğrafi dağılımı, gelir dağılımı ve eğitim düzeyi gibi özellikleri; sosyokültürel çevre ise inanç, gelenek, görenek ve değer yargıları gibi tüketim davranışlarını etkileyen unsurları kapsar."],confuse:["Demografik ↔ sosyokültürel: yaş/nüfus/eğitim yapısı demografik; inanç/gelenek/değer yargıları sosyokültüreldir.","Politik çevre ile hukuki çevre ilişkilidir ama aynı tanım değildir; siyasi otoritenin kararlarının işletmeye yansıdığı kurallar hukuki çevreyi oluşturur."],remember:["Genel çevre: politik-yasal + ekonomik + demografik + sosyokültürel + teknolojik + uluslararası.","Çevre analizi = fırsat ve tehditleri görebilme."],exam:["Bir çevre unsuru örneği verilip doğru çevre kategorisi istenebilir.","Nüfus yapısını kültürel çevreye atayan çeldiricilere dikkat et."]},
"islet-4":{learn:["İşletmeler büyüklük, pazar alanı ve sermaye sahipliği gibi ölçütlerle sınıflandırılabilir. Büyüklükte sermaye, çalışan sayısı, üretim kapasitesi, enerji/makine parkı ve toplam satış gibi ölçütler kullanılabilir.","Pazar alanına göre ulusal, uluslararası, çokuluslu ve küresel işletmeler; sermaye sahipliğine göre özel, kamu ve karma işletmeler ayrılır."],confuse:["Büyük işletme bir pazar alanı sınıfı değildir; büyüklük sınıflandırmasına aittir.","Yatay birleşme aynı sektördeki firmalar; dikey birleşme üretimden satışa farklı aşamalardaki firmalar arasındadır."],remember:["Pazar alanı: ulusal → uluslararası → çokuluslu → küresel.","Sahiplik: özel + kamu + karma."],exam:["Sınıflandırma ölçütünü önce bul; seçenekleri aynı ölçüte göre karşılaştır.","Birleşme sorularında firmaların aynı aşamada mı, tedarik/satış zincirinin farklı aşamalarında mı olduğuna bak."]},
"islet-6":{learn:["Birbirine yakın görev ve faaliyetlerin gruplarına işletme fonksiyonu denir. Bu ünitede yönetim ve pazarlama; sonraki ünitede üretim, Ar-Ge, finans, muhasebe ve insan kaynakları ele alınır.","Yönetim, iki veya daha fazla insanın ortak bir amaç doğrultusunda çalışmalarını organize eden grup faaliyetidir."],confuse:["Yönetim fonksiyonları ile işletmenin tüm fonksiyonlarını aynı liste sanma.","Pazarlama yalnızca satış değildir; ünitede pazarlamanın önemi ve 4P yapısı ayrıca ele alınır."],remember:["Ünite 7 odağı: yönetim + pazarlama.","İşletme fonksiyonu = benzer görev/faaliyetlerin gruplandırılması."],exam:["Yönetim fonksiyonları ve yönetim kademeleri ayrı kavram kümeleridir.","Pazarlama karması sorularında 4P ilişkisini kur." ]}
});
