// Development 4 — high-risk concept blocks and calculation logic
Object.assign(window.AUZEF_TEACHING, {
"bat-6":{learn:["Örnekleme ünitesinin çekirdeği anakütle ile örneklem ayrımını ve örnek seçme yöntemlerini doğru sınıflandırmaktır.","Olasılıklı örneklemede birimlerin seçilme olasılığı bilinen/rastlantısal bir mekanizmaya dayanır; olasılıksız yöntemlerde bu güvence yoktur."],confuse:["Anakütle ↔ örneklem: araştırma kapsamındaki bütün birimler anakütle; bunlardan inceleme için seçilen alt küme örneklemdir.","Küme örneklemesini olasılıksız yöntem sanma; kitap sorularında bu ayrım doğrudan ölçülmektedir."],remember:["Önce evreni/anakütleyi tanı, sonra örnekleme yöntemini sınıflandır.","Örnekleme sorularında 'her birim', 'rastgele', 'kolay ulaşılabilir', 'kota' gibi ipuçlarını ara."],exam:["Yöntem adlarını tek tek ezberlemek yerine olasılıklı ↔ olasılıksız ana ayrımına yerleştir.","Tanım verilip yöntem; yöntem verilip özellik sorulabilir."]},
"bat-10":{learn:["Geçerlik ölçme işleminin 'ne ölçtüğü'; güvenirlik ise ölçmenin tutarlılığı ve 'nasıl ölçtüğü' ile ilişkilendirilir.","Kitaba göre güvenirlik geçerlik için gerekli fakat yeterli değildir: güvenilir bir araç her zaman geçerli olmayabilir."],confuse:["Güvenilir = mutlaka geçerli değildir. Aynı şeyi tutarlı biçimde yanlış ölçmek mümkündür.","Bütün hata türleri geçerliği düşürebilirken güvenirlik özellikle tesadüfi hatalardan etkilenir."],remember:["Geçerlik: doğru şeyi ölç. Güvenirlik: tutarlı ölç.","Gerekli ama yeterli değil: güvenirlik → geçerliği tek başına garanti etmez."],exam:["'Güvenilir ama geçersiz olabilir mi?' sorusunun cevabı evettir.","Geçersizlik kaynakları: geçmiş, olgunlaşma, test, araç ve seçim etkilerini ayrı tut."]},
"ikt-5":{learn:["Kısa dönemde bazı üretim faktörleri sabitken değişken faktör artırıldığında toplam ürün, ortalama ürün ve marjinal ürün birlikte incelenir.","Marjinal ürün sıfır olduğunda toplam ürün maksimumdadır; marjinal ürün negatif olduğunda toplam ürün azalmaya başlar."],confuse:["Toplam ürün maksimum ↔ marjinal ürün maksimum aynı nokta değildir. Toplam ürünün tepesinde marjinal ürün sıfırdır.","Azalan verim, toplam üretimin hemen azalması demek değildir; marjinal katkı azalırken toplam ürün bir süre daha artabilir."],remember:["MP = ek değişken faktörün üretime ek katkısı.","MP = 0 → TP maksimum; MP < 0 → TP düşer."],exam:["Grafik sorusunda önce TP/AP/MP eğrisinin hangisi olduğunu belirle.","'Diğer faktörler sabit' varsayımı azalan verim mantığının anahtarıdır."]},
"ikt-6":{learn:["Kısa dönemde toplam maliyet, sabit ve değişken maliyetlerin toplamıdır. Üretim sıfırken toplam maliyet sabit maliyete eşittir.","Marjinal maliyet, üretim miktarındaki değişmenin toplam maliyette oluşturduğu değişimdir; son birimin maliyeti olarak da okunabilir."],confuse:["Toplam maliyet ↔ ortalama toplam maliyet: ortalama toplam maliyet toplam maliyetin üretim miktarına bölünmesidir.","Kısa dönem ↔ uzun dönem: uzun dönemde sabit faktör yoktur; bütün faktörler değişebilir."],remember:["TC = FC + VC. ATC = TC/Q. MC = ΔTC/ΔQ.","MC yükselirken ortalamalar bir süre daha düşebilir; MC ortalama maliyeti minimum noktasında keser."],exam:["Hesap sorusunda önce hangi maliyetin istendiğini sembolleştir, sonra sayıları yerleştir.","Üretim sıfırken değişken maliyet sıfır olabilir ama sabit maliyet nedeniyle toplam maliyet sıfır olmak zorunda değildir."]},
"sos-3":{learn:["Çalışma sosyolojisindeki klasik teorik yaklaşımlar, modern kapitalist toplumun yükselişini ve işin dönüşümünü açıklamaya çalışır.","Durkheim'ın katkısı özellikle iş bölümü, sosyal dayanışma ve anomi tartışmalarıyla ilişkilendirilir; modern toplumdaki artan farklılaşmanın sosyal sonuçlarını inceler."],confuse:["Weber ↔ Durkheim: Weberyen çizgide bürokrasi ve rasyonelleşme; Durkheim'da iş bölümü, dayanışma ve anomi bağlantılarını ayır.","Klasik teorisyenleri yalnız isim olarak değil, açıklamaya çalıştıkları dönüşüm mekanizmasıyla eşleştir."],remember:["Durkheim → iş bölümü + dayanışma + anomi.","Klasik yaklaşımların ortak problemi: Sanayi Devrimi sonrası yeni toplum düzenini anlamak."],exam:["Düşünür → kavram ve kavram → düşünür iki yönde de çalış.","Aynı 'sanayi toplumu' bağlamında farklı teorisyenlerin açıklama mekanizmalarını karıştırma."]},
"sos-5":{learn:["Marx yabancılaşmayı kapitalist üretim tarzı ve teknolojinin kullanım biçimiyle ilişkilendirir. Blauner yabancılaşmada teknolojinin rolünü ve çalışanlara verilen karar/insiyatif alanını öne çıkarır.","Goldthorpe ve Lockwood, teknolojik determinizme karşı 'işe yönelim' yaklaşımını kullanır; iş dışındaki beklenti ve öznel hissiyatların önemini vurgular."],confuse:["Marx ↔ Blauner ↔ Goldthorpe/Lockwood: kapitalist üretim ilişkisi ↔ teknoloji/karar alanı ↔ işe yönelim/öznel beklentiler.","Yabancılaşmanın nedeni olarak kitapta sayılan otomasyon, parçalanma, standartlaşma ve vasıfsızlaşmayı ücret düşüşüyle otomatik eşitleme."],remember:["Marx = üretim tarzı; Blauner = teknoloji; Goldthorpe/Lockwood = işe yönelim.","Teknoloji → işbölümü, işin niteliği, içeriği ve ritmi üzerinde etki."],exam:["Teorisyen eşleştirmelerinde anahtar kelimeyi bul ve önce yaklaşımı belirle.","'Hangisi yabancılaşma sebebi değildir?' tipi istisna sorularında seçenekleri tek tek kaynak çerçevesiyle kontrol et."]},
"islet-5":{learn:["İşletmenin kuruluş çalışmaları, işletme kurma fikrinden kesin kuruluşun tamamlanmasına kadar yürütülen araştırma ve çalışmaları kapsar.","Kuruluş ünitesinde kuruluş nedenleri, kuruluş aşamaları, fizibilite etüdü, işletme büyüklüğü/kapasite ve kuruluş yeri seçimi birlikte ele alınır."],confuse:["Fizibilite ↔ kesin proje: fizibilite yatırım fikrinin uygulanabilirliğini inceleyen etütler bütünüdür; kesin proje daha sonraki kuruluş aşamasıdır.","Kuruluş yeri faktörü ile ürünün kalite özelliğini aynı kategoriye koyma; kitap sorularında kalite kuruluş yeri faktörü değildir."],remember:["Kurma nedenleri arasında miras, bağımsız çalışma, kazanç, toplumsal itibar, başka fırsat yokluğu ve misyon bulunur.","Fizibilite: ekonomik + teknik + finansal + yasal inceleme boyutlarını ayır."],exam:["Etüt türü verilip hangi konuyu kapsadığı sorulabilir.","Kuruluş aşamalarını satış sonrası faaliyetlerle karıştıran çeldiricilere dikkat et."]},
"islet-7":{learn:["Üretim; işgücü, makine, hammadde, malzeme ve sermaye gibi girdilerin ihtiyaç karşılayan mal ve hizmetlere dönüştürülmesidir.","Finans fonksiyonu gerekli fonların temini ve uygun değerlendirilmesiyle; muhasebe finansal tablolar için veri üretimiyle; İKY ise işe alma, performans, eğitim-geliştirme ve ücret gibi çalışan süreçleriyle ilgilenir."],confuse:["Finans ↔ muhasebe: finans fon bulma/kullanma kararları; muhasebe ekonomik işlemleri bilgiye ve finansal tablolara dönüştürme tarafıdır.","İKY yalnız işe alım değildir; çalışan yaşam döngüsündeki çok sayıda faaliyeti kapsar."],remember:["Ünite 8: üretim + Ar-Ge + finans + muhasebe + İKY.","Girdi → dönüşüm → çıktı = üretimin temel şeması."],exam:["Bir faaliyet örneği verildiğinde önce hangi işletme fonksiyonuna ait olduğunu belirle.","Fonksiyonların amaçlarını birbirine benzeyen ifadelerden ayırmaya odaklan."]}
});
