Object.assign(window.AUZEF_TEACHING, {
"bat-1":{learn:["Bilimsel araştırma süreci problem ve amaçların tanımlanmasıyla başlar; model/hipotez, yöntem, anakütle-örneklem, veri aracı, saha/veri toplama, veri hazırlama-analiz ve raporlama aşamaları birbirine bağlı ilerler.","Araştırma planı bilgiye ulaşmak için hazırlanır; istenen sonucu doğrulatmak için araştırma kurgulamak bilimsel yaklaşım değildir."],confuse:["Problem ↔ hipotez: problem araştırmanın neyi açıklayacağını; hipotez ise sınanacak ilişki/öneriyi ifade eder.","Sonucu gördükten sonra hipotezi sonuca uydurmak ile araştırma sırasında yeni bilgi nedeniyle yeni hipotez geliştirmek aynı şey değildir."],remember:["Sıra: problem/amaç → model/hipotez → yöntem → anakütle/örneklem → araç → saha → analiz → rapor.","Her aşamadaki hata sonraki aşamaları etkileyebilir."],exam:["Aşama sıralama ve 'hangisi önce gelir?' sorularında süreç zincirini kullan.","Hipotez sorularında sınanabilirlik, açıklık ve mantıksal tutarlılık ipuçlarına bak."]},
"bat-3":{learn:["Veri araştırmanın hammaddesidir. Bu ünitede veri türleri, özellikle ikincil verilerin elde edilmesi ve literatür taramasındaki kullanımı ele alınır.","Literatür taramasında kitap 4N1K düzenini kullanır: Kim? Ne zaman? Niçin? Nasıl? Ne?"],confuse:["Birincil veri ↔ ikincil veri ayrımında verinin mevcut bir kaynaktan mı alındığını yoksa araştırma için doğrudan mı üretildiğini sorgula.","Literatür taraması yalnız kaynak listesi çıkarmak değildir; amaç, yöntem, örneklem, araç, analiz ve sonuç gibi bilgileri yapılandırır."],remember:["4N1K = Kim + Ne zaman + Niçin + Nasıl + Ne.","İkincil veri ve literatür taraması bu ünitenin ana omurgasıdır."],exam:["Kaynak türü veya veri örneği verilip veri sınıfı sorulabilir.","4N1K sorularında 'Nasıl?' altında tasarım, örneklem, veri toplama aracı ve analiz gibi yöntem bilgilerini ara."]},
"bat-7":{learn:["Ölçme, araştırılan özelliğin belirli kurallarla ifade edilmesini; ölçekleme ise bu ölçümü yapacak yapı ve kategorilerin kurulmasını içerir.","Kitap sürekli, tekli ve çoklu ölçekleri; ayrıca Likert tipi ölçek ile semantik farklılıklar ölçeğini karşılaştırmalı ele alır."],confuse:["Tek sayıda kategori tarafsız/kararsız orta seçenek sağlayabilir; çift sayıda kategori cevaplayıcıyı bir tarafa yönelmeye zorlayabilir.","'Fikrim yok' seçeneğinin özellikle verilmemesi zorlanmış ölçek; verilmesi zorlanmamış ölçek mantığıdır."],remember:["Tek sayı → orta/kararsız seçenek mümkün. Çift sayı → taraf seçmeye zorlama mümkün.","Likert ve semantik farklılıklar aynı ölçek değildir; soru kökündeki cevaplama biçimine dikkat et."],exam:["Ölçek örneği verilirse önce kategori yapısını ve cevaplama biçimini belirle.","Zorlanmış/zorlanmamış ve tek/çift kategori ayrımları güçlü çeldirici alanlarıdır."]},
"islet-1":{learn:["Sanayi Devrimi ile fabrika sistemi ve büyük ölçekli üretim gelişmiş; işletmeler büyümüş, karmaşıklaşmış ve yönetim düşüncesi bilimsel yaklaşımlarla sistemleşmiştir.","Klasik çizgide Taylor Bilimsel Yönetim, Fayol Yönetim Süreci, Weber Bürokrasi yaklaşımıyla; neoklasik çizgide Hawthorne araştırmaları insan ve sosyal faktörlerle öne çıkar."],confuse:["Taylor ↔ Fayol: Taylor daha çok atölye/üretim düzeyinden verimliliğe; Fayol genel yönetim ve yönetim sürecine odaklanır.","Weber'in bürokrasisi günlük dildeki geciktirme anlamı değil, rasyonel ve etkin ideal örgüt yapısı modelidir."],remember:["Taylor = Bilimsel Yönetim; Fayol = Yönetim Süreci; Weber = Bürokrasi; Mayo/Roethlisberger = Hawthorne.","Fayol: planlama → örgütleme → yöneltme → koordinasyon → denetim."],exam:["Düşünür → yaklaşım eşleştirmesini iki yönde çalış.","Hawthorne sorularında fiziksel koşullardan sosyal/psikolojik faktörlere kayan açıklama mantığını hatırla."]},
"ikt-9":{learn:["Milli gelir, ekonomide yaratılan gelir/üretim düzeyini değerlendirmede kullanılır; kişi başına gelir refah hakkında bilgi verir ancak gelir dağılımını tek başına göstermez.","Zaman içindeki karşılaştırmalarda fiyat değişimlerini ayırmak gerekir; nominal değer fiyat etkisini içerirken reel değerlendirme üretim miktarındaki gerçek değişimi izlemeye çalışır."],confuse:["Nominal artış ↔ reel artış: parasal değerin artması tek başına gerçek üretimin aynı oranda arttığını göstermez.","Kişi başına gelirin yüksek olması sosyal refahın zorunlu koşullarından biri olabilir fakat adil gelir dağılımını garanti etmez."],remember:["Nominal = cari fiyat etkisi var; reel = fiyat etkisini ayırmaya çalış.","Gelir düzeyi ≠ gelir dağılımı."],exam:["Fiyat artışı ile üretim artışını karşılaştıran örneklerde nominal/reel ayrımını yap.","Kişi başına gelir sorularında refah ve dağılım kavramlarını birbirine eşitleme."]},
"ikt-11":{learn:["İstihdam, çalışma gücü ve arzusundaki kişilerin belirli ücret karşılığında hizmetlerinden yararlanılmasıdır; işgücü ekonomik faaliyete katılan nüfus bölümünü ifade eder.","Kitap işsizliği yapısal, iradi, gayri iradi, friksiyonel, konjonktürel ve gizli işsizlik gibi türlere ayırır."],confuse:["Friksiyonel ↔ yapısal: friksiyonel iş değiştirme/arama geçişi; yapısal işgücünün ekonomik yapıdaki değişime uyum problemiyle ilişkilidir.","Gizli işsizlikte kişi çalışıyor görünür fakat toplam üretime katkısı yoktur."],remember:["Friksiyonel = iş arama/geçiş; yapısal = yapı değişimi; konjonktürel = ekonomik dalgalanma; gizli = katkı yok.","Çalışmak istemeyen herkes kitabın tanımında işsiz sayılmaz; çalışma gücü/arzusuna ve cari ücret koşuluna bak."],exam:["Senaryodaki işsizliğin nedenini bulup türle eşleştir.","İradi ve gayri iradi ayrımında kişinin cari koşullarda çalışma isteğini kontrol et."]},
"ikt-13":{learn:["Para politikası ekonominin likiditesini, kredi, para arzı ve faiz oranları üzerinden etkileyen düzenlemeleri kapsar; Merkez Bankaları uygulamada önemli rol oynar.","Kitap para politikasının amaçlarını tam istihdam, fiyat istikrarı, faiz oranı istikrarı, ekonomik büyüme ve ödemeler bilançosu dengesi olarak toplar."],confuse:["Para politikası aracı ile para politikasının amacı aynı şey değildir: araç uygulama vasıtası, amaç ulaşılmak istenen ekonomik sonuçtur.","Enflasyon hedeflemesinde fiyat istikrarı hedefi diğer makro sonuçlarla çatışabilecek etkiler doğurabilir; tek değişkene bakma."],remember:["5 amaç: tam istihdam + fiyat istikrarı + faiz istikrarı + büyüme + ödemeler bilançosu dengesi.","Enflasyon yükselirse para arzını daraltma yönü kitapta verilen temel örnektir."],exam:["'Hangisi amaç değildir?' sorusunda araçları amaçlarla karıştırma.","Genişletici/daraltıcı yön sorularında para arzı → toplam talep bağlantısını kur."]}
});
