Object.assign(window.AUZEF_TEACHING,{
"sos-1":{learn:["Sanayi Devrimi 1780–1830 döneminde önce İngiltere'de belirginleşmiş; buhar gücü ve makineleşmeyle üretimin örgütlenmesini kökten değiştirmiştir.","Dönüşüm yalnız üretim tekniği değildir; kentleşme, çalışma koşulları, aile, toplumsal cinsiyet ve sınıf yapısı üzerinde sonuçlar doğurmuştur."],confuse:["Sanayi Devrimi = yalnız makine icadı değildir; ekonomik ve toplumsal dönüşüm birlikte düşünülür.","İlk dönem sanayileşme ile sonraki çalışma mevzuatı/iyileşmeleri aynı tarihsel aşama değildir."],remember:["İlk merkez: İngiltere. İlk güçlü alan: tekstil.","Yeni sınıfsal yapı: işçi sınıfı ve orta sınıfın yükselişi."],exam:["Bir sonuç verildiğinde bunun teknolojik mi sosyal mi olduğunu ayır.","Putting-out/ev üretimi ile fabrika sistemini karıştırma."]},
"sos-4":{learn:["Modern yaklaşımlarda yakınsama teorisi ve sanayi-ötesi toplum teorileri öne çıkar.","Daniel Bell, sanayi-ötesi toplumda imalat ve mavi yakalı emeğin ağırlığının azalırken hizmetler ile beyaz yakalı işgücünün önem kazanacağını savunur."],confuse:["Yakınsama teorisi ↔ sanayi-ötesi toplum: ilki gelişmiş toplumların benzer yapılara yönelmesini; ikincisi ekonomik/toplumsal yapıda yeni aşamayı tartışır.","Bell, Gorz ve Toffler aynı başlık altında incelense de değerlendirmeleri aynı değildir."],remember:["Bell = Sanayi-Ötesi Toplumun Gelişi.","Sanayi-öncesi → sanayi → sanayi-ötesi."],exam:["Yazar → teori → temel iddia eşleştirmesi yap.","Hizmet sektörü/beyaz yakalı vurgu Bell için güçlü ipucudur."]},
"sos-6":{learn:["Bilgi teknolojileri üretim sürecini, istihdamı, meslekleri ve vasıf yapısını birlikte etkiler.","Kitap tek yönlü 'teknoloji iş yok eder' sonucuna gitmez: bazı iş ve vasıflar ortadan kalkarken yeni işler, meslekler ve vasıflar da yaratılır."],confuse:["İş yok etme etkisi ↔ iş yaratma etkisi: ikisini birlikte değerlendir.","Teknolojik kapasite artışı ile istihdam sonucunu otomatik olarak aynı yönde kabul etme."],remember:["Mikro-işlemci/bilgi teknolojisi özellikle 1970'lerden sonra hızla gelişir.","Ana sınav mantığı: yok etme + yaratma etkisi birlikte."],exam:["Teknoloji-istihdam sorularında mutlak ifadelerden şüphe et.","Vasıf ve meslek etkilerini yalnız imalatla sınırlama; büro işleri de etkilenir."]},
"sos-7":{learn:["İşin yeniden tasarımı Fordist-Taylorist işin monotonluk, yakın kontrol ve tatminsizlik sorunlarına cevap arar.","Başlıca araçlar iş rotasyonu, iş genişletme, iş zenginleştirme ve özerk takım çalışmasıdır."],confuse:["İş genişletme ↔ iş zenginleştirme: zenginleştirme sorumluluk ve yetki boyutunu güçlendirir.","İş rotasyonu işi kalıcı olarak büyütmekten çok farklı işler arasında geçiş mantığı taşır."],remember:["Rotasyon = monotonluğu azaltabilir.","Zenginleştirme = daha fazla sorumluluk/yetki; insanileştirme = işi daha anlamlı kılma."],exam:["Tanımdan uygulama biçimini bulma soruları beklenebilir.","Özerk takım ile hiyerarşik bireysel çalışma çeldiricilerini ayır."]},
"sos-8":{learn:["Fordizm standart malların büyük ölçekte üretimi, hareketli montaj hattı ve Taylorist emek süreciyle ilişkilidir.","1929 sonrası talep yönlü politikalar Fordist genişlemeyi desteklerken 1970'lerde petrol krizleri, değişen talep ve modelin katılığı krizi derinleştirmiştir."],confuse:["Taylor ↔ Ford: Taylor işin bilimsel örgütlenmesi ve parçalanması; Ford bu mantığı kayan bant ve kitle üretimiyle birleştirir.","Fordizm'in yüksek ücret-kitle tüketimi bağlantısını 'düşük ücret' çeldiricisiyle karıştırma."],remember:["Kayan bant + standardizasyon + büyük ölçek = Fordizm.","1929 → talep sorunu; 1970'ler → Fordist krizin derinleşmesi."],exam:["Fordizm özellikleri 'hangisi değildir?' biçiminde sorulabilir.","Kriz nedenleri ile model özelliklerini ayrı tut."]},
"sos-9":{learn:["1970'lerin krizi sonrası Neo-Fordizm ve Post-Fordizm alternatifleri tartışılır.","Post-Fordist başlıklarda Esnek Firma, Esnek Uzmanlaşma ve Yalın Üretim öne çıkar; kitap Neo-Fordizmi daha sınırlı/kısmi dönüşüm olarak ele alır."],confuse:["Neo-Fordizm ↔ Post-Fordizm: Neo-Fordizm Fordist mantık içinde kısmi yenilik; Post-Fordizm daha köklü dönüşüm iddiasıdır.","İşlevsel esneklik ↔ sayısal esneklik: görev/vasıf çeşitliliği ile işgücü sayısını ayarlamayı karıştırma."],remember:["Atkinson = Esnek Firma.","Post-Fordist üçlü: Esnek Firma + Esnek Uzmanlaşma + Yalın Üretim."],exam:["Model → ülke/özellik eşleştirmelerinde kitabın verdiği bağlamı kullan.","Esneklik türünü senaryodaki değişenin görev mi çalışan sayısı mı olduğuna göre seç."]},
"sos-10":{learn:["Esneklik değişen koşullara uyum sağlayabilme yeteneği olarak ele alınır ve üretim ile çalışma yaşamına farklı biçimlerde yansır.","İşletme, çalışan ve devlet açısından esnekliğin anlamı aynı değildir; rekabet/verimlilik, iş-yaşam uyumu ve istihdam düzenlemeleri gibi farklı odaklar vardır."],confuse:["Esnek üretim ↔ esnek çalışma aynı kavram değildir.","Çalışan açısından esneklik ile işletmenin işgücünü gerektiği miktarda kullanma hedefini birbirine karıştırma."],remember:["Esneklik = değişime uyum.","Bakış açısını sor: işletme mi, çalışan mı, devlet mi?"],exam:["Tanım sorularında öznenin kim olduğuna dikkat et.","Esneklik türlerini örnek olay üzerinden ayır."]},
"sos-11":{learn:["Küreselleşme ekonomik, sosyal ve politik bütünleşme ile karşılıklı bağımlılığın artması olarak ele alınır.","Çokuluslu şirketler birden fazla ülkede gelir getirici faaliyet yürütür ve doğrudan yabancı yatırımlarla küresel üretimin önemli aktörleridir."],confuse:["Küreselleşme ↔ küresel üretim: ilki daha geniş süreç; ikincisi üretimin ülkeler arasında parçalanıp örgütlenmesidir.","ÇUŞ ile yalnız ihracat yapan işletmeyi aynı kabul etme."],remember:["ÇUŞ = birden fazla ülkede faaliyet + doğrudan yabancı yatırım bağlantısı.","Üretimin parçalanması iletişim/ulaşım teknolojileriyle kolaylaşır."],exam:["Küresel üretimin emek piyasası sonuçlarında özellikle düşük vasıflı emek ve emek yoğun sektörlere dikkat et.","Şirket tanımında faaliyet coğrafyası ve yatırım biçimini ara."]},
"sos-12":{learn:["İş-yaşam dengesi iş ve aile yaşamındaki çoklu roller arasındaki gerilimi azaltmaya yönelik politika ve düzenlemeleri ele alır.","İki gelirli aile modelinin yaygınlaşmasıyla ebeveyn izni, çocuk bakım politikaları ve esnek çalışma düzenlemeleri daha görünür hale gelmiştir."],confuse:["İş-yaşam dengesi yalnız bireysel zaman yönetimi değildir; refah rejimi, cinsiyet ilişkileri ve sosyal politika boyutu vardır.","Esnek çalışma her durumda otomatik olarak iş-yaşam dengesi sağlamaz; kitap bunu politika araçlarından biri olarak ele alır."],remember:["Politika üçlüsü: ebeveyn izni + çocuk bakımı + esnek çalışma.","AB bağlamında cinsiyet eşitliği ve eşit fırsatlar önemli eksendir."],exam:["Politika örneği verildiğinde iş-yaşam dengesi bağlantısını kur.","Erkek ekmek kazanan model ↔ iki gelirli aile dönüşümünü ayır."]},
"sos-13":{learn:["20. yüzyılda vatandaşlık medeni ve siyasi haklara ek olarak sosyal hak boyutu kazanmış; refah devleti hizmetleri sosyal vatandaşlığın gelişiminde önemli olmuştur.","T.H. Marshall vatandaşlığın medeni, siyasi ve sosyal bileşenlerini ele alır; sosyal vatandaşlık belirli yaşam standartlarına erişimde sosyal hakların rolünü vurgular."],confuse:["Sosyal vatandaşlık ↔ yalnız hukuki vatandaşlık: sosyal vatandaşlık sağlık, eğitim ve refah hizmetleri gibi sosyal hak boyutunu içerir.","Refah devletinin 1945–1975 genişleme dönemi ile 1970'ler sonrası kriz/dönüşüm aynı aşama değildir."],remember:["Marshall = medeni + siyasi + sosyal haklar.","1945–1975 = refah devletinin kitapta 'altın çağ' olarak anlatılan dönemi."],exam:["Hak türü → vatandaşlık boyutu eşleştirmesi yap.","1970 sonrası kriz/küreselleşme sorularında refah devletinin dönüşümünü takip et."]}
});
