Object.assign(window.AUZEF_TEACHING, {
"bat-2":{learn:["Araştırma tasarımı, araştırma problemini cevaplamak için izlenecek genel yaklaşımı belirler. Kitap keşfedici, tanımlayıcı ve nedensel araştırmaları ayrı amaçlarla ele alır.","Problem hakkında bilgi azsa keşfedici araştırma uygun olabilir; araştırma keşfedici başlayıp tanımlayıcı veya nedensel aşamaya ilerleyebilir, ancak her araştırmanın zorunlu olarak keşfedici başlaması gerekmez."],confuse:["Keşfedici ↔ tanımlayıcı: keşfedici problemi ve olası açıklamaları anlamaya; tanımlayıcı mevcut durumu/özellikleri betimlemeye yönelir.","Tanımlayıcı ↔ nedensel: birlikte değişimi göstermek tek başına neden-sonuç kanıtı değildir; nedensel tasarım neden-sonuç ilişkisine odaklanır."],remember:["Az bilgi → keşfedici düşün.","Betimleme → tanımlayıcı; neden-sonuç → nedensel."],exam:["Soru kökündeki araştırma amacını bulup tasarımı eşleştir.","'Her araştırma keşfedici başlar' gibi mutlak ifadeleri kitaptaki esnek süreç anlayışıyla kontrol et."]},
"bat-5":{learn:["Kantitatif araştırma sayısal hale dönüştürülmüş değişkenleri inceler; ilişkileri ve neden-sonuçları ortaya koymaya, istatistiksel sonuç ve genellemelere ulaşmaya yönelir.","Kitap nicel araştırmada anket ve deney tasarımını; ön test-son test gibi deneysel düzenlemeleri de ele alır."],confuse:["Nicel ↔ nitel: nicelde sayısal değişkenler, istatistiksel analiz ve genelleme; nitelde derinlemesine anlam ve bağlam öne çıkar.","Anket ↔ deney: anket cevaplayıcıdan yapılandırılmış bilgi toplar; deney neden-sonuç ilişkisini sınamak için değişkenlerin düzenlenmesine dayanır."],remember:["Nicel = sayısal veri + istatistiksel analiz.","Deney sorularında ön test/son test ve neden-sonuç mantığını ara."],exam:["Araştırma örneğinin sayısal/genellenebilir sonuç mu yoksa derinlemesine anlam mı hedeflediğini belirle.","Veri toplama yöntemi ile araştırmanın genel tasarımını birbirine eşitleme."]},
"bat-8":{learn:["Anket, cevaplayıcılardan bilgi almak için formüle edilmiş soru kümelerini içeren bir veri toplama formudur.","İyi anket tasarımı gerekli bilgiyi yanıtlanabilir sorulara dönüştürmeli, cevaplayıcıyı katılıma teşvik etmeli ve yanıtlama hatasını azaltmalıdır."],confuse:["Araştırma sorusu ↔ anket sorusu: araştırma problemi bilimsel olarak neyi öğrenmek istediğimizi; anket sorusu cevaplayıcıdan hangi bilgiyi nasıl alacağımızı ifade eder.","Ön test, nihai veri toplama değildir; anketin anlaşılabilirliği ve işleyişindeki sorunları uygulama öncesi görmek için kullanılır."],remember:["Anketin üç hedefi: bilgiyi soruya çevir + katılımı destekle + yanıtlama hatasını azalt.","Soru biçimi kadar sıralama ve ifade biçimi de veri kalitesini etkiler."],exam:["Yönlendirici, belirsiz veya cevaplanması zor soru örneklerini ayırt et.","Anket tasarım aşamalarında ön testin yerini ve amacını karıştırma."]},
"bat-9":{learn:["Araştırmanın her aşaması hata kaynağı olabilir. Kitap hataların tamamen yok edilemeyebileceğini, fakat ölçülüp azaltılması gerektiğini vurgular.","Gerçek değer ile kaydedilen değer arasındaki fark örnekleme dışı hatayı ifade edebilir; yanıtlayıcı, anketör, etkileşim ve anket formu hata kaynakları arasında sayılır."],confuse:["Örnekleme hatası ↔ örnekleme dışı hata aynı değildir; ikinci grupta ölçme/veri toplama sürecindeki kaynaklar öne çıkar.","Güvenirlik ↔ geçerlik: tutarlı ölçüm yapmak ile ölçülmek isteneni doğru ölçmek aynı özellik değildir."],remember:["Açık/anlaşılır sorular, uygun içerik, daha büyük örneklem ve yeterli madde sayısı güvenirliği yükseltebilir.","Hata azaltma araştırma kalitesinin parçasıdır; hata yok varsayılmaz."],exam:["Senaryodaki hatanın kaynağını önce belirle: yanıtlayıcı mı, anketör mü, araç mı?","Güvenirlik sorularında ölçümün tutarlılığına; geçerlik sorularında doğru özelliği ölçmeye odaklan."]},
"bat-11":{learn:["Veri analizi; toplanan verilerin sınıflanması, kodlanması, çizelge veya grafiklerle gösterilmesi ve istatistiksel verilere dayanarak hipotezin sınanmasını içeren süreçtir.","İstatistiksel yöntem seçimi araştırmanın amacı ve veri setinin özellikleriyle uyumlu olmalıdır; kitap parametrik/nonparametrik ile tek/çok değişkenli analiz ayrımlarını ele alır."],confuse:["Veri hazırlama ↔ veri analizi: veriyi kontrol etme/düzenleme/kodlama analize hazırlıktır; istatistiksel çözümleme bunun devamıdır.","Analiz tekniğini alışkanlığa göre değil veri ve araştırma amacına göre seçmek gerekir."],remember:["Sınıflandır → kodla → göster/özetle → uygun analiz → hipotezi değerlendir.","Median dağılımı ikiye böler; korelasyon değişkenler arası ilişkiyi inceleyen tekniklerden biridir."],exam:["'Hangisi veri hazırlama aşaması değildir?' sorusunda analiz işlemlerini hazırlık adımlarından ayır.","Değişken ve ölçek yapısı verildiğinde uygun analiz mantığını sorgula."]},
"bat-12":{learn:["Araştırma sürecinin son aşamasında analizden elde edilen bulgular yorumlanır, sonuçlar düzenlenir ve araştırma raporu hazırlanır.","Kitap kaynak kullanımını ve kaynak göstermeyi raporlamanın temel parçalarından biri olarak ele alır; yorumlanmayan veri araştırma problemine tek başına çözüm sunmaz."],confuse:["Bulgu ↔ yorum: bulgu analizden çıkan sonuçtır; yorum bu sonucun araştırma problemi açısından ne ifade ettiğini açıklar.","Kaynak göstermek ile kaynakçayı yalnızca sona eklemek aynı şey değildir; kullanılan kaynağın metin içinde de uygun biçimde belirtilmesi gerekir."],remember:["Analiz → bulgu → yorum → sonuç → rapor/sunum.","Kitap sorularında işlenmiş/analiz edilmiş verinin sonucu = bulgu; özet sayfası = öz."],exam:["Rapor bölümlerinin işlevlerini eşleştir; araştırma problemi girişte tanımlanır.","Bilimsel raporda araştırmacının kişisel duygularını katması uygun bir yazım ilkesi değildir."]},
"bat-13":{learn:["Bilimsel etik araştırmanın yalnız sonuç aşamasını değil planlama, veri toplama, analiz ve yayınlama dahil bütün sürecini kapsar.","Kitap akademik etik kapsamında bilimsel yanıltma, özensiz/disiplinsiz araştırma, bilimsel sahtekârlık, yayın intihali, çıkar çatışması ve yazarlık sorunlarını ele alır."],confuse:["Özensiz/disiplinsiz araştırma ↔ bilerek yapılan sahtekârlık: kitap kötü niyet olmadan metodolojiye uymama ile kasıtlı yanıltmayı ayırır.","Alıntı yapmak ↔ intihal aynı şey değildir; kaynağın uygun biçimde gösterilmemesi etik soruna dönüşür."],remember:["Etik = süreç boyunca doğruluk, dürüstlük ve uygun bilimsel davranış.","İntihal + çıkar çatışması + ikram yazarlığı/yazarlık sırası = kitapta geçen etik başlıklar."],exam:["Etik dışı davranış örneği verildiğinde kasıt, kaynak gösterme ve yazarlık boyutlarını ayır.","'Sadece araştırmacı sorumludur' gibi dar ifadelerden kaçın; kitap süreçteki farklı kişilerin etik sorumluluğunu vurgular."]},
"ikt-1":{learn:["Talep, belirli bir sürede bir malın farklı fiyatlarında tüketicinin satın almak istediği miktardır. Ceteris paribus altında fiyat ile talep edilen miktar ters yönlüdür.","Malın kendi fiyatı değişirse talep eğrisi üzerinde hareket olur; fiyat dışındaki talep belirleyicileri değişirse talep eğrisi bütünüyle sağa veya sola kayar."],confuse:["Talep ↔ talep edilen miktar: fiyat değişimi eğri üzerinde hareket; gelir, zevkler veya ilgili mal fiyatları gibi başka belirleyiciler eğriyi kaydırabilir.","Talep artışı ↔ fiyat düşünce miktar artışı aynı grafik olayı değildir."],remember:["Fiyat ↑ → talep edilen miktar ↓; fiyat ↓ → miktar ↑, ceteris paribus.","Sağa kayma = talep artışı; sola kayma = talep azalışı."],exam:["Önce değişenin malın kendi fiyatı mı başka bir belirleyici mi olduğunu bul.","Grafik sorusunda eksenleri unutma: dikey fiyat, yatay miktar."]},
"ikt-7":{learn:["Tam rekabet piyasasında çok sayıda alıcı ve satıcı bulunur; tek bir ekonomik birim piyasa fiyatını etkileyemez ve firmalar fiyat kabul edicidir.","Kitap tam rekabette homojen mal ve piyasaya giriş-çıkışın engellenmemesi gibi koşulları vurgular; fiyat arz ve talep tarafından belirlenir."],confuse:["Fiyat kabul edici ↔ fiyat belirleyici: tam rekabet firması piyasa fiyatını veri alır; monopolde firma piyasa gücüne sahiptir.","Çok sayıda firma tek başına yeterli değildir; homojenlik ve giriş-çıkış koşulları da piyasa yapısının parçasıdır."],remember:["Çok alıcı-satıcı + homojen mal + serbest giriş/çıkış + fiyat kabulü.","Tam rekabette reklamın anlamı olmadığı kitap özetinde özellikle belirtilir."],exam:["Bir koşul bozulduğunda bunun tam rekabet varsayımıyla uyumunu sorgula.","Firma ile piyasanın fiyat belirleme rolünü karıştırma."]},
"ikt-8":{learn:["Eksik rekabet piyasaları tam rekabet koşullarının aksadığı yapılardır. Kitap monopol, düopol, oligopol ve monopollü rekabet biçimlerini ayırır.","Monopolde tek satıcı ve çok alıcı vardır; oligopolde sınırlı sayıda firma birbirinin kararlarını dikkate alır; monopollü rekabette çok sayıda satıcı farklılaştırılmış mal/hizmet sunar."],confuse:["Monopol ↔ monopollü rekabet: monopol tek satıcı; monopollü rekabet çok satıcı + ürün farklılaştırmasıdır.","Oligopolde firmalar bağımsızmış gibi davranamaz; bir firmanın üretim/fiyat kararı diğerlerinin davranışlarıyla ilişkilidir."],remember:["1 satıcı = monopol; az satıcı = oligopol; çok satıcı + farklılaştırılmış ürün = monopollü rekabet.","Monopol fiyatı veya üretimi seçebilir; ikisini birbirinden bağımsız aynı anda belirleyemez."],exam:["Satıcı sayısı ve ürün farklılaştırması verilen senaryoda piyasa türünü seç.","Fiyat farklılaştırması sorularında piyasaların bölünebilmesi ve talep esnekliklerinin farklılığı gibi koşullara dikkat et."]},
"ikt-10":{learn:["Enflasyon, fiyatlar genel düzeyinin sürekli yükselmesidir; tek bir malın fiyat artışı veya geçici fiyat artışı enflasyon olarak tanımlanmaz.","Kitap nedenleri talep ve arz/maliyet kaynaklı olarak ayırır; ayrıca yapısal, kronik, sinsi ve hiperenflasyon türlerini ele alır."],confuse:["Talep enflasyonu ↔ maliyet enflasyonu: ilkinde toplam talep mal-hizmet arzını aşar; ikincisinde maliyet koşulları fiyatlar genel düzeyini yukarı iter.","Enflasyon ↔ devalüasyon: fiyatlar genel düzeyindeki sürekli artış ile ulusal paranın dış değerinin resmi olarak düşürülmesi aynı kavram değildir."],remember:["Genel + sürekli fiyat artışı = enflasyon.","Sinsi/sürünen enflasyonda fiyat artışları yavaş ve düşük oranlıdır."],exam:["Soru tek fiyat artışı veriyorsa hemen enflasyon deme; genellik ve süreklilik koşullarını kontrol et.","Nedeni soruluyorsa talep tarafı mı maliyet/arz tarafı mı olduğunu ayır."]},
"ikt-12":{learn:["Para, değişimi kolaylaştıran genel değer ölçüsü ve değişim aracıdır. Kitap paranın homojen, taşınabilir, dayanıklı, bölünebilir ve taklit edilemez olması gibi temel özelliklerini sıralar.","Paranın geleneksel üç fonksiyonu değer ölçüsü/hesap birimi, mübadele aracı ve değer saklama aracıdır."],confuse:["Para ↔ ödeme aracı: çekin kendisi kaydi para değildir; kitap kaydi parayı bankadaki vadesiz mevduat hesabıyla ilişkilendirir.","Değer ölçüsü ↔ değer saklama: ilki malları ortak birimle fiyatlandırmayı, ikincisi satın alma gücünü zamana taşımayı ifade eder."],remember:["3 fonksiyon: hesap birimi + mübadele aracı + değer saklama.","Kaydi/banka parası = vadesiz mevduat; çek aktarım aracıdır."],exam:["Bir örnekte paranın hangi fonksiyonunun kullanıldığını belirle.","Kâğıt/bozuk para ile kaydi parayı maddi varlık ve hesap transferi açısından ayır."]}
});
